{"command":"mkdir -p /workspace/src/lang && cat > /workspace/src/tree.rs <<'EOF'
// Generic concrete syntax tree used by all language parsers.

#[derive(Clone, Debug)]
pub struct RawNode {
    pub kind: &'static str,
    pub named: bool,
    pub extra: bool,
    pub hidden: bool,
    pub missing: bool,
    pub field: Option<&'static str>,
    pub start: usize,
    pub end: usize,
    pub children: Vec<u32>,
}

/// Builder used by recursive descent parsers. Children are pushed on a stack
/// and wrapped into nodes. Extras (comments) at the borders of a wrapped range
/// are kept outside the new node, emulating tree-sitter.
pub struct Builder {
    pub nodes: Vec<RawNode>,
    pub stack: Vec<u32>,
}

#[derive(Clone, Copy)]
pub struct Checkpoint {
    nodes: usize,
    stack: usize,
}

impl Builder {
    pub fn new() -> Self {
        Builder { nodes: Vec::with_capacity(1024), stack: Vec::with_capacity(256) }
    }
    #[inline]
    pub fn mark(&self) -> usize {
        self.stack.len()
    }
    pub fn checkpoint(&self) -> Checkpoint {
        Checkpoint { nodes: self.nodes.len(), stack: self.stack.len() }
    }
    pub fn restore(&mut self, c: Checkpoint) {
        // nodes created after checkpoint are dropped; stack restored.
        // Note: wraps may have consumed stack entries below the checkpoint;
        // callers must ensure wraps only happen above checkpoint mark.
        self.nodes.truncate(c.nodes);
        self.stack.truncate(c.stack);
    }
    pub fn leaf(&mut self, kind: &'static str, named: bool, start: usize, end: usize) -> u32 {
        let id = self.nodes.len() as u32;
        self.nodes.push(RawNode {
            kind,
            named,
            extra: false,
            hidden: false,
            missing: false,
            field: None,
            start,
            end,
            children: Vec::new(),
        });
        self.stack.push(id);
        id
    }
    pub fn extra(&mut self, kind: &'static str, start: usize, end: usize) -> u32 {
        let id = self.leaf(kind, true, start, end);
        self.nodes[id as usize].extra = true;
        id
    }
    pub fn hidden(&mut self, start: usize, end: usize) -> u32 {
        let id = self.leaf("_hidden", false, start, end);
        self.nodes[id as usize].hidden = true;
        id
    }
    pub fn missing(&mut self, kind: &'static str, named: bool, pos: usize) -> u32 {
        let id = self.leaf(kind, named, pos, pos);
        self.nodes[id as usize].missing = true;
        id
    }
    /// Wrap all stack entries from mark into a node.
    pub fn wrap(&mut self, mark: usize, kind: &'static str, named: bool) -> u32 {
        self.wrap_at(mark, kind, named, usize::MAX)
    }
    /// Wrap; if no non-extra children, the node is zero width at `pos`.
    pub fn wrap_at(&mut self, mark: usize, kind: &'static str, named: bool, pos: usize) -> u32 {
        let mark = mark.min(self.stack.len());
        let children: Vec<u32> = self.stack.drain(mark..).collect();
        let n = children.len();
        let mut lead = 0;
        while lead < n && self.nodes[children[lead] as usize].extra {
            lead += 1;
        }
        let mut trail = n;
        while trail > lead && self.nodes[children[trail - 1] as usize].extra {
            trail -= 1;
        }
        let inner: Vec<u32> = children[lead..trail].to_vec();
        let (start, end) = if inner.is_empty() {
            let p = if pos == usize::MAX {
                if n > 0 { self.nodes[children[n - 1] as usize].end } else { 0 }
            } else {
                pos
            };
            (p, p)
        } else {
            (self.nodes[inner[0] as usize].start, self.nodes[*inner.last().unwrap() as usize].end)
        };
        for &c in &children[..lead] {
            self.stack.push(c);
        }
        let id = self.nodes.len() as u32;
        self.nodes.push(RawNode {
            kind,
            named,
            extra: false,
            hidden: false,
            missing: false,
            field: None,
            start,
            end,
            children: inner,
        });
        self.stack.push(id);
        for &c in &children[trail..] {
            self.stack.push(c);
        }
        id
    }
    /// Wrap including leading and trailing extras (used for the root).
    pub fn wrap_all(&mut self, mark: usize, kind: &'static str, start: usize, end: usize) -> u32 {
        let children: Vec<u32> = self.stack.drain(mark..).collect();
        let id = self.nodes.len() as u32;
        self.nodes.push(RawNode {
            kind,
            named: true,
            extra: false,
            hidden: false,
            missing: false,
            field: None,
            start,
            end,
            children,
        });
        self.stack.push(id);
        id
    }
    /// Set field on the last non-extra stack entry.
    pub fn field_last(&mut self, f: &'static str) {
        for i in (0..self.stack.len()).rev() {
            let id = self.stack[i] as usize;
            if !self.nodes[id].extra {
                self.nodes[id].field = Some(f);
                return;
            }
        }
    }
    /// Set field on all non-extra stack entries from mark.
    pub fn field_from(&mut self, mark: usize, f: &'static str) {
        for i in mark..self.stack.len() {
            let id = self.stack[i] as usize;
            if !self.nodes[id].extra && !self.nodes[id].hidden {
                self.nodes[id].field = Some(f);
            }
        }
    }
    pub fn set_field(&mut self, id: u32, f: &'static str) {
        self.nodes[id as usize].field = Some(f);
    }
    pub fn last(&self) -> Option<u32> {
        for i in (0..self.stack.len()).rev() {
            let id = self.stack[i];
            if !self.nodes[id as usize].extra {
                return Some(id);
            }
        }
        None
    }
    pub fn last_kind(&self) -> Option<&'static str> {
        self.last().map(|i| self.nodes[i as usize].kind)
    }
    /// Change the kind of a node.
    pub fn rename(&mut self, id: u32, kind: &'static str) {
        self.nodes[id as usize].kind = kind;
    }
    pub fn finish(self, root: u32, src: &str) -> Tree {
        Tree::from_raw(self.nodes, root, src)
    }
}

#[derive(Clone, Debug)]
pub struct Node {
    pub kind: &'static str,
    pub named: bool,
    pub extra: bool,
    pub missing: bool,
    pub error: bool,
    pub field: Option<&'static str>,
    pub start: usize,
    pub end: usize,
    pub sp: (usize, usize),
    pub ep: (usize, usize),
    pub parent: Option<u32>,
    pub children: Vec<u32>,
    pub index: u32, // index among parent's children
}

pub struct Tree {
    pub src: String,
    pub nodes: Vec<Node>,
    pub root: u32,
    pub line_starts: Vec<usize>,
}

impl Tree {
    pub fn from_raw(raw: Vec<RawNode>, root: u32, src: &str) -> Tree {
        let mut line_starts = vec![0usize];
        for (i, b) in src.bytes().enumerate() {
            if b == b'\n' {
                line_starts.push(i + 1);
            }
        }
        let mut t = Tree { src: src.to_string(), nodes: Vec::with_capacity(raw.len()), root: 0, line_starts };
        // DFS copy
        fn copy(t: &mut Tree, raw: &Vec<RawNode>, id: u32, parent: Option<u32>, index: u32) -> u32 {
            let r = &raw[id as usize];
            let nid = t.nodes.len() as u32;
            let sp = t.point(r.start);
            let ep = t.point(r.end);
            t.nodes.push(Node {
                kind: r.kind,
                named: r.named,
                extra: r.extra,
                missing: r.missing,
                error: r.kind == "ERROR",
                field: r.field,
                start: r.start,
                end: r.end,
                sp,
                ep,
                parent,
                children: Vec::new(),
                index,
            });
            let mut kids = Vec::with_capacity(r.children.len());
            let mut idx = 0u32;
            for &c in &r.children {
                if raw[c as usize].hidden {
                    continue;
                }
                let k = copy(t, raw, c, Some(nid), idx);
                idx += 1;
                kids.push(k);
            }
            t.nodes[nid as usize].children = kids;
            nid
        }
        let r = copy(&mut t, &raw, root, None, 0);
        t.root = r;
        t
    }
    pub fn point(&self, byte: usize) -> (usize, usize) {
        let line = match self.line_starts.binary_search(&byte) {
            Ok(i) => i,
            Err(i) => i - 1,
        };
        (line, byte - self.line_starts[line])
    }
    #[inline]
    pub fn n(&self, id: u32) -> &Node {
        &self.nodes[id as usize]
    }
    pub fn text(&self, id: u32) -> &str {
        let n = &self.nodes[id as usize];
        &self.src[n.start..n.end]
    }
    pub fn has_error(&self, id: u32) -> bool {
        let n = self.n(id);
        if n.error || n.missing {
            return true;
        }
        n.children.iter().any(|&c| self.has_error(c))
    }
    pub fn next_sibling(&self, id: u32) -> Option<u32> {
        let n = self.n(id);
        let p = n.parent?;
        self.n(p).children.get(n.index as usize + 1).copied()
    }
    pub fn prev_sibling(&self, id: u32) -> Option<u32> {
        let n = self.n(id);
        let p = n.parent?;
        if n.index == 0 {
            None
        } else {
            self.n(p).children.get(n.index as usize - 1).copied()
        }
    }
    /// pre-order traversal of all nodes under id (inclusive)
    pub fn preorder(&self, id: u32, out: &mut Vec<u32>) {
        let mut stack = vec![id];
        while let Some(x) = stack.pop() {
            out.push(x);
            let ch = &self.n(x).children;
            for &c in ch.iter().rev() {
                stack.push(c);
            }
        }
    }
    pub fn dump(&self, id: u32, cst: bool, out: &mut String, depth: usize) {
        let n = self.n(id);
        if !cst && !n.named {
            return;
        }
        for _ in 0..depth {
            out.push_str("  ");
        }
        if let Some(f) = n.field {
            out.push_str(f);
            out.push_str(": ");
        }
        if n.missing {
            out.push_str("MISSING ");
        }
        out.push_str(n.kind);
        out.push_str(&format!(" ({},{})-({},{})\n", n.sp.0, n.sp.1, n.ep.0, n.ep.1));
        for &c in &n.children {
            self.dump(c, cst, out, depth + 1);
        }
    }
    pub fn sexp(&self, id: u32, out: &mut String) {
        let n = self.n(id);
        if n.missing {
            out.push_str("(MISSING ");
            if n.named {
                out.push_str(n.kind);
            } else {
                out.push('"');
                out.push_str(n.kind);
                out.push('"');
            }
            out.push(')');
            return;
        }
        out.push('(');
        out.push_str(n.kind);
        for &c in &n.children {
            let cn = self.n(c);
            if !cn.named {
                continue;
            }
            out.push(' ');
            if let Some(f) = cn.field {
                out.push_str(f);
                out.push_str(": ");
            }
            self.sexp(c, out);
        }
        out.push(')');
    }
}
EOF
echo ok"}

