#[derive(Clone, Debug)]
pub struct Node {
    pub kind: &'static str,
    pub named: bool,
    pub extra: bool,
    pub missing: bool,
    pub error: bool,
    pub field: Option<&'static str>,
    pub start: usize,
    pub end: usize,
    pub sp: (usize, usize),
    pub ep: (usize, usize),
    pub parent: Option<u32>,
    pub children: Vec<u32>,
    pub index: u32, // index among parent's children
}

pub struct Tree {
    pub src: String,
    pub nodes: Vec<Node>,
    pub root: u32,
    pub line_starts: Vec<usize>,
}

impl Tree {
    pub fn from_raw(raw: Vec<RawNode>, root: u32, src: &str) -> Tree {
        let mut line_starts = vec![0usize];
        for (i, b) in src.bytes().enumerate() {
            if b == b'\n' {
                line_starts.push(i + 1);
            }
        }
        let mut t = Tree { src: src.to_string(), nodes: Vec::with_capacity(raw.len()), root: 0, line_starts };
        // DFS copy
        fn copy(t: &mut Tree, raw: &Vec<RawNode>, id: u32, parent: Option<u32>, index: u32) -> u32 {
            let r = &raw[id as usize];
            let nid = t.nodes.len() as u32;
            let sp = t.point(r.start);
            let ep = t.point(r.end);
            t.nodes.push(Node {
                kind: r.kind,
                named: r.named,
                extra: r.extra,
                missing: r.missing,
                error: r.kind == "ERROR",
                field: r.field,
                start: r.start,
                end: r.end,
                sp,
                ep,
                parent,
                children: Vec::new(),
                index,
            });
            let mut kids = Vec::with_capacity(r.children.len());
            let mut idx = 0u32;
            for &c in &r.children {
                if raw[c as usize].hidden {
                    continue;
                }
                let k = copy(t, raw, c, Some(nid), idx);
                idx += 1;
                kids.push(k);
            }
            t.nodes[nid as usize].children = kids;
            nid
        }
        let r = copy(&mut t, &raw, root, None, 0);
        t.root = r;
        t
    }
    pub fn point(&self, byte: usize) -> (usize, usize) {
        let line = match self.line_starts.binary_search(&byte) {
            Ok(i) => i,
            Err(i) => i - 1,
        };
        (line, byte - self.line_starts[line])
    }
    #[inline]
    pub fn n(&self, id: u32) -> &Node {
        &self.nodes[id as usize]
    }
    pub fn text(&self, id: u32) -> &str {
        let n = &self.nodes[id as usize];
        &self.src[n.start..n.end]
    }
    pub fn has_error(&self, id: u32) -> bool {
        let n = self.n(id);
        if n.error || n.missing {
            return true;
        }
        n.children.iter().any(|&c| self.has_error(c))
    }
    pub fn next_sibling(&self, id: u32) -> Option<u32> {
        let n = self.n(id);
        let p = n.parent?;
        self.n(p).children.get(n.index as usize + 1).copied()
    }
    pub fn prev_sibling(&self, id: u32) -> Option<u32> {
        let n = self.n(id);
        let p = n.parent?;
        if n.index == 0 {
            None
        } else {
            self.n(p).children.get(n.index as usize - 1).copied()
        }
    }
    /// pre-order traversal of all nodes under id (inclusive)
    pub fn preorder(&self, id: u32, out: &mut Vec<u32>) {
        let mut stack = vec![id];
        while let Some(x) = stack.pop() {
            out.push(x);
            let ch = &self.n(x).children;
            for &c in ch.iter().rev() {
                stack.push(c);
            }
        }
    }
    pub fn dump(&self, id: u32, cst: bool, out: &mut String, depth: usize) {
        let n = self.n(id);
        if !cst && !n.named {
            return;
        }
        for _ in 0..depth {
            out.push_str("  ");
        }
        if let Some(f) = n.field {
            out.push_str(f);
            out.push_str(": ");
        }
        if n.missing {
            out.push_str("MISSING ");
        }
        out.push_str(n.kind);
        out.push_str(&format!(" ({},{})-({},{})\n", n.sp.0, n.sp.1, n.ep.0, n.ep.1));
        for &c in &n.children {
            self.dump(c, cst, out, depth + 1);
        }
    }
    pub fn sexp(&self, id: u32, out: &mut String) {
        let n = self.n(id);
        if n.missing {
            out.push_str("(MISSING ");
            if n.named {
                out.push_str(n.kind);
            } else {
                out.push('"');
                out.push_str(n.kind);
                out.push('"');
            }
            out.push(')');
            return;
        }
        out.push('(');
        out.push_str(n.kind);
        for &c in &n.children {
            let cn = self.n(c);
            if !cn.named {
                continue;
            }
            out.push(' ');
            if let Some(f) = cn.field {
                out.push_str(f);
                out.push_str(": ");
            }
            self.sexp(c, out);
        }
        out.push(')');
    }
}
