// JavaScript / TypeScript / TSX parser producing tree-sitter compatible CSTs.
use super::jslex::*;
use crate::tree::{Builder, Tree};

pub struct P<'a> {
    pub src: &'a str,
    pub b: Builder,
    pub pos: usize,
    pub ts: bool,
    pub jsx: bool,
    cm: Vec<(usize, usize)>,
    pub depth: usize,
    pub no_in: bool,
    pub in_type: bool,
}

const KW_NOT_ID: &[&str] = &[
    "break", "case", "catch", "class", "const", "continue", "debugger", "default", "delete", "do", "else", "export",
    "extends", "finally", "for", "function", "if", "import", "in", "instanceof", "new", "return", "super", "switch",
    "this", "throw", "try", "typeof", "var", "void", "while", "with", "null", "true", "false", "enum",
];

pub fn parse(src: &str, ts: bool, jsx: bool) -> Tree {
    let mut p = P { src, b: Builder::new(), pos: 0, ts, jsx, cm: Vec::new(), depth: 0, no_in: false, in_type: false };
    let m = p.b.mark();
    // hash bang
    if src.starts_with("#!") {
        let e = src.find('\n').unwrap_or(src.len());
        p.b.leaf("hash_bang_line", true, 0, e);
        p.pos = e;
    }
    loop {
        let t = p.peek();
        if t.t == T::Eof {
            break;
        }
        let before = p.pos;
        p.statement();
        if p.pos == before {
            // no progress: error token
            p.error_token();
        }
    }
    p.flush_comments_to(src.len());
    // root range: first child start .. end of source
    let start = p.b.stack[m..].first().map(|&c| p.b.nodes[c as usize].start).unwrap_or_else(|| {
        let mut cm = Vec::new();
        skip_trivia(src, 0, &mut cm).0
    });
    let root = p.b.wrap_all(m, "program", start, src.len());
    p.b.finish(root, src)
}

impl<'a> P<'a> {
    // ---------- token helpers ----------
    pub fn peek_at(&self, pos: usize, re: bool) -> Tok {
        let mut cm = Vec::new();
        let (s, nl) = skip_trivia(self.src, pos, &mut cm);
        let (t, e) = lex(self.src, s, re);
        Tok { t, s, e, nl }
    }
    pub fn peek(&self) -> Tok {
        self.peek_at(self.pos, false)
    }
    pub fn peek_re(&self) -> Tok {
        self.peek_at(self.pos, true)
    }
    pub fn peek2(&self) -> Tok {
        let t = self.peek();
        self.peek_at(t.e, false)
    }
    pub fn peek_n(&self, n: usize) -> Tok {
        let mut t = self.peek();
        for _ in 0..n {
            t = self.peek_at(t.e, false);
        }
        t
    }
    pub fn tx(&self, t: Tok) -> &'a str {
        &self.src[t.s..t.e]
    }
    pub fn at(&self, s: &str) -> bool {
        let t = self.peek();
        t.t != T::Str && t.t != T::Eof && self.tx(t) == s
    }
    pub fn at_id(&self, s: &str) -> bool {
        let t = self.peek();
        t.t == T::Ident && self.tx(t) == s
    }
    pub fn flush_comments_to(&mut self, upto: usize) {
        let mut cm = std::mem::take(&mut self.cm);
        cm.clear();
        let (s, _) = skip_trivia(self.src, self.pos, &mut cm);
        let _ = s;
        for &(a, e) in &cm {
            if e <= upto {
                self.b.extra("comment", a, e);
                self.pos = e;
            }
        }
        self.cm = cm;
    }
    /// consume token t, push leaf
    pub fn bump_tok(&mut self, t: Tok, kind: &'static str, named: bool) -> u32 {
        self.flush_comments_to(t.s);
        self.pos = t.e;
        self.b.leaf(kind, named, t.s, t.e)
    }
    /// consume next token as anonymous token with kind = its text
    pub fn bump(&mut self) -> u32 {
        let t = self.peek();
        let k = intern(self.tx(t));
        self.bump_tok(t, k, false)
    }
    pub fn bump_named(&mut self, kind: &'static str) -> u32 {
        let t = self.peek();
        self.bump_tok(t, kind, true)
    }
    /// consume a token of given length at the current lookahead start (for splitting tokens like >>)
    pub fn bump_partial(&mut self, len: usize) -> u32 {
        let t = self.peek();
        let t2 = Tok { t: T::Punct, s: t.s, e: t.s + len, nl: t.nl };
        let k = intern(self.tx(t2));
        self.bump_tok(t2, k, false)
    }
    pub fn expect(&mut self, s: &str) -> bool {
        if self.at(s) {
            self.bump();
            true
        } else if s.len() == 1 && self.peek().t == T::Punct && self.tx(self.peek()).starts_with(s) {
            self.bump_partial(1);
            true
        } else {
            let p = self.pos;
            self.b.missing(intern(s), false, p);
            false
        }
    }
    pub fn eat(&mut self, s: &str) -> bool {
        if self.at(s) {
            self.bump();
            true
        } else {
            false
        }
    }
    pub fn error_token(&mut self) {
        let t = self.peek_re();
        if t.t == T::Eof {
            return;
        }
        let m = self.b.mark();
        let k = intern(self.tx(t));
        let named = matches!(t.t, T::Ident | T::Num | T::Str | T::Regex);
        let kind = if named {
            match t.t {
                T::Ident => "identifier",
                T::Num => "number",
                T::Str => "string",
                _ => "regex",
            }
        } else {
            k
        };
        self.bump_tok(t, kind, named);
        self.b.wrap(m, "ERROR", true);
    }

    /// automatic semicolon / semicolon
    pub fn semicolon(&mut self) {
        if self.at(";") {
            self.bump();
            return;
        }
        self.asi();
    }
    /// Insert an automatic semicolon (hidden). Handles same-line line comments.
    pub fn asi(&mut self) {
        let b = self.src.as_bytes();
        let mut i = self.pos;
        let mut asi_pos = self.pos;
        loop {
            if i >= b.len() {
                break;
            }
            let c = b[i];
            if c == b' ' || c == b'\t' || c == b'\r' {
                i += 1;
            } else if c == b'/' && i + 1 < b.len() && b[i + 1] == b'*' {
                // skip block comment
                let mut j = i + 2;
                while j + 1 < b.len() && !(b[j] == b'*' && b[j + 1] == b'/') {
                    j += 1;
                }
                i = (j + 2).min(b.len());
            } else if c == b'/' && i + 1 < b.len() && b[i + 1] == b'/' {
                // line comment: the comment becomes an extra before the ASI
                let mut j = i;
                while j < b.len() && b[j] != b'\n' {
                    j += 1;
                }
                let mut e = j;
                if e > i && b[e - 1] == b'\r' {
                    e -= 1;
                }
                asi_pos = e;
                self.flush_comments_to(e);
                break;
            } else {
                break;
            }
        }
        self.b.hidden(asi_pos, asi_pos);
    }
    /// optional automatic semicolon after a block-like construct: absorbs a
    /// same-line trailing line comment.
    pub fn opt_asi_line_comment(&mut self) {
        let b = self.src.as_bytes();
        let mut i = self.pos;
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t') {
            i += 1;
        }
        if i + 1 < b.len() && b[i] == b'/' && b[i + 1] == b'/' {
            let mut j = i;
            while j < b.len() && b[j] != b'\n' {
                j += 1;
            }
            let mut e = j;
            if e > i && b[e - 1] == b'\r' {
                e -= 1;
            }
            // only when followed by newline + something that allows ASI
            self.flush_comments_to(e);
            self.b.hidden(e, e);
        }
    }

    // ---------- statements ----------
    pub fn statement(&mut self) {
        let t = self.peek_re();
        let tx = self.tx(t);
        if t.t == T::Punct {
            match tx {
                "{" => {
                    self.statement_block();
                    return;
                }
                ";" => {
                    let m = self.b.mark();
                    self.bump();
                    self.b.wrap(m, "empty_statement", true);
                    return;
                }
                "@" => {
                    // decorators then class / export
                    let m = self.b.mark();
                    while self.at("@") {
                        self.decorator();
                        self.b.field_last("decorator");
                    }
                    if self.at_id("export") {
                        self.export_statement(m);
                    } else {
                        self.class_like(m, true);
                    }
                    return;
                }
                _ => {}
            }
        }
        if t.t == T::Ident {
            let t2 = self.peek_at(t.e, true);
            let tx2 = if t2.t == T::Eof { "" } else { self.tx(t2) };
            match tx {
                "var" => {
                    self.variable_declaration("var", "variable_declaration");
                    return;
                }
                "let" if t2.t == T::Ident || tx2 == "[" || tx2 == "{" => {
                    if !(t2.t == T::Ident && (tx2 == "in" || tx2 == "instanceof" || tx2 == "of") ) || tx2 == "of" && false {
                        self.variable_declaration("let", "lexical_declaration");
                        return;
                    }
                }
                "const" => {
                    if self.ts && tx2 == "enum" {
                        let m = self.b.mark();
                        self.bump();
                        self.ts_enum(m);
                        return;
                    }
                    self.variable_declaration("const", "lexical_declaration");
                    return;
                }
                "function" => {
                    let m = self.b.mark();
                    self.function_like(m, true);
                    return;
                }
                "async" if tx2 == "function" && !t2.nl => {
                    let m = self.b.mark();
                    self.function_like(m, true);
                    return;
                }
                "class" => {
                    let m = self.b.mark();
                    self.class_like(m, true);
                    return;
                }
                "if" => return self.if_statement(),
                "for" => return self.for_statement(),
                "while" => return self.while_statement(),
                "do" => return self.do_statement(),
                "try" => return self.try_statement(),
                "switch" => return self.switch_statement(),
                "return" => return self.return_like("return", "return_statement"),
                "throw" => return self.return_like("throw", "throw_statement"),
                "break" => return self.break_like("break_statement"),
                "continue" => return self.break_like("continue_statement"),
                "debugger" => {
                    let m = self.b.mark();
                    self.bump();
                    self.semicolon();
                    self.b.wrap(m, "debugger_statement", true);
                    return;
                }
                "with" => {
                    let m = self.b.mark();
                    self.bump();
                    self.parenthesized_expression();
                    self.b.field_last("object");
                    self.statement();
                    self.b.field_last("body");
                    self.b.wrap(m, "with_statement", true);
                    return;
                }
                "import" if tx2 != "(" && tx2 != "." => {
                    self.import_statement();
                    return;
                }
                "export" => {
                    let m = self.b.mark();
                    self.export_statement(m);
                    return;
                }
                _ => {}
            }
            if self.ts {
                if self.ts_statement(t, t2) {
                    return;
                }
            }
            // labeled statement
            if tx2 == ":" && !KW_NOT_ID.contains(&tx) {
                let m = self.b.mark();
                self.bump_named("statement_identifier");
                self.b.field_last("label");
                self.bump();
                self.statement();
                self.b.field_last("body");
                self.b.wrap(m, "labeled_statement", true);
                return;
            }
        }
        self.expression_statement();
    }

    pub fn expression_statement(&mut self) {
        let m = self.b.mark();
        self.expressions();
        self.semicolon();
        self.b.wrap(m, "expression_statement", true);
    }

    pub fn statement_block(&mut self) {
        self.statement_block_ex(false);
    }
    pub fn statement_block_ex(&mut self, absorb: bool) {
        let m = self.b.mark();
        self.bump(); // {
        self.statements_until_brace();
        self.expect("}");
        if absorb {
            self.opt_asi_line_comment();
        }
        self.b.wrap(m, "statement_block", true);
    }
    pub fn statements_until_brace(&mut self) {
        loop {
            let t = self.peek();
            if t.t == T::Eof || (t.t == T::Punct && self.tx(t) == "}") {
                break;
            }
            let before = self.pos;
            self.statement();
            if self.pos == before {
                self.error_token();
            }
        }
    }

    fn variable_declaration(&mut self, kw: &str, kind: &'static str) {
        let m = self.b.mark();
        let _ = kw;
        self.bump();
        if kind == "lexical_declaration" {
            self.b.field_last("kind");
        }
        loop {
            self.variable_declarator();
            if !self.eat(",") {
                break;
            }
        }
        self.semicolon();
        self.b.wrap(m, kind, true);
    }

    pub fn variable_declarator(&mut self) {
        let m = self.b.mark();
        self.binding_pattern();
        self.b.field_last("name");
        if self.ts && self.at("!") {
            self.bump();
        }
        if self.ts && self.at(":") {
            self.type_annotation();
            self.b.field_last("type");
        }
        if self.at("=") {
            self.bump();
            self.assign_expr();
            self.b.field_last("value");
        }
        self.b.wrap(m, "variable_declarator", true);
    }

    fn if_statement(&mut self) {
        let m = self.b.mark();
        self.bump();
        self.parenthesized_expression();
        self.b.field_last("condition");
        self.statement();
        self.b.field_last("consequence");
        if self.at_id("else") {
            let m2 = self.b.mark();
            self.bump();
            self.statement();
            self.b.wrap(m2, "else_clause", true);
            self.b.field_last("alternative");
        }
        self.b.wrap(m, "if_statement", true);
    }

    fn body_statement(&mut self) {
        if self.at("{") {
            self.statement_block_ex(true);
        } else {
            self.statement();
        }
    }

    fn while_statement(&mut self) {
        let m = self.b.mark();
        self.bump();
        self.parenthesized_expression();
        self.b.field_last("condition");
        self.body_statement();
        self.b.field_last("body");
        self.b.wrap(m, "while_statement", true);
    }

    fn do_statement(&mut self) {
        let m = self.b.mark();
        self.bump();
        self.statement();
        self.b.field_last("body");
        self.expect("while");
        self.parenthesized_expression();
        self.b.field_last("condition");
        if self.at(";") {
            self.bump();
        } else {
            let t = self.peek();
            if t.nl || t.t == T::Eof || self.tx(t) == "}" {
                self.asi();
            }
        }
        self.b.wrap(m, "do_statement", true);
    }

    fn try_statement(&mut self) {
        let m = self.b.mark();
        self.bump();
        if self.at("{") {
            self.statement_block();
        }
        self.b.field_last("body");
        if self.at_id("catch") {
            let m2 = self.b.mark();
            self.bump();
            if self.at("(") {
                self.bump();
                self.binding_pattern();
                self.b.field_last("parameter");
                if self.ts && self.at(":") {
                    self.type_annotation();
                    self.b.field_last("type");
                }
                self.expect(")");
            }
            if self.at("{") {
                self.statement_block();
            }
            self.b.field_last("body");
            self.b.wrap(m2, "catch_clause", true);
            self.b.field_last("handler");
        }
        if self.at_id("finally") {
            let m2 = self.b.mark();
            self.bump();
            if self.at("{") {
                self.statement_block();
            }
            self.b.field_last("body");
            self.b.wrap(m2, "finally_clause", true);
            self.b.field_last("finalizer");
        }
        self.b.wrap(m, "try_statement", true);
    }

    fn switch_statement(&mut self) {
        let m = self.b.mark();
        self.bump();
        self.parenthesized_expression();
        self.b.field_last("value");
        let mb = self.b.mark();
        self.expect("{");
        loop {
            let t = self.peek();
            if t.t == T::Eof || self.at("}") {
                break;
            }
            if self.at_id("case") || self.at_id("default") {
                let mc = self.b.mark();
                let is_case = self.at_id("case");
                self.bump();
                if is_case {
                    self.expressions();
                    self.b.field_last("value");
                }
                self.expect(":");
                loop {
                    let t = self.peek();
                    if t.t == T::Eof || self.at("}") || self.at_id("case") || self.at_id("default") {
                        break;
                    }
                    let before = self.pos;
                    self.statement();
                    if self.pos == before {
                        self.error_token();
                        continue;
                    }
                    self.b.field_last("body");
                }
                self.b.wrap(mc, if is_case { "switch_case" } else { "switch_default" }, true);
            } else {
                let before = self.pos;
                self.statement();
                if self.pos == before {
                    self.error_token();
                }
            }
        }
        self.expect("}");
        self.b.wrap(mb, "switch_body", true);
        self.b.field_last("body");
        self.b.wrap(m, "switch_statement", true);
    }

    fn return_like(&mut self, _kw: &str, kind: &'static str) {
        let m = self.b.mark();
        self.bump();
        let t = self.peek_re();
        let tx = self.tx(t);
        if !(t.t == T::Eof || t.nl || (t.t == T::Punct && (tx == ";" || tx == "}"))) {
            self.expressions();
        }
        self.semicolon();
        self.b.wrap(m, kind, true);
    }

    fn break_like(&mut self, kind: &'static str) {
        let m = self.b.mark();
        self.bump();
        let t = self.peek();
        if t.t == T::Ident && !t.nl {
            self.bump_named("statement_identifier");
            self.b.field_last("label");
        }
        self.semicolon();
        self.b.wrap(m, kind, true);
    }

    fn for_statement(&mut self) {
        let m = self.b.mark();
        self.bump(); // for
        let mut is_await = false;
        if self.at_id("await") {
            self.bump();
            is_await = true;
        }
        // determine for-in/of vs classic: scan
        let cp = self.b.checkpoint();
        let save = self.pos;
        self.expect("(");
        // try for-in/of
        if !is_await || true {
            if let Some(()) = self.try_for_in_header() {
                self.expect(")");
                self.body_statement();
                self.b.field_last("body");
                self.b.wrap(m, "for_in_statement", true);
                return;
            }
        }
        self.b.restore(cp);
        self.pos = save;
        self.expect("(");
        // classic for
        let t = self.peek_re();
        let tx = self.tx(t);
        if tx == "var" {
            self.variable_declaration("var", "variable_declaration");
            self.b.field_last("initializer");
        } else if (tx == "let" || tx == "const") && t.t == T::Ident {
            self.variable_declaration(tx, "lexical_declaration");
            self.b.field_last("initializer");
        } else if tx == ";" {
            let me = self.b.mark();
            self.bump();
            self.b.wrap(me, "empty_statement", true);
            self.b.field_last("initializer");
        } else {
            let mi = self.b.mark();
            self.no_in = true;
            self.expressions();
            self.no_in = false;
            self.expect(";");
            self.b.field_from(mi, "initializer");
        }
        // condition
        if self.at(";") {
            let me = self.b.mark();
            self.bump();
            self.b.wrap(me, "empty_statement", true);
            self.b.field_last("condition");
        } else {
            let mc = self.b.mark();
            self.expressions();
            self.expect(";");
            self.b.field_from(mc, "condition");
        }
        if !self.at(")") {
            self.expressions();
            self.b.field_last("increment");
        }
        self.expect(")");
        self.body_statement();
        self.b.field_last("body");
        self.b.wrap(m, "for_statement", true);
    }

    fn try_for_in_header(&mut self) -> Option<()> {
        let t = self.peek_re();
        let tx = self.tx(t);
        let t2 = self.peek_at(t.e, false);
        let tx2 = self.tx(t2);
        if (tx == "var" || tx == "let" || tx == "const") && t.t == T::Ident && !(tx2 == "in" || tx2 == "of") || (tx == "let" && (tx2=="of"||tx2=="in") && false) {
            self.bump();
            self.b.field_last("kind");
            self.binding_pattern();
            self.b.field_last("left");
            if self.ts && self.at(":") {
                self.type_annotation();
            }
            if tx == "var" && self.at("=") {
                self.bump();
                self.no_in = true;
                self.assign_expr();
                self.no_in = false;
                self.b.field_last("value");
            }
        } else {
            self.no_in = true;
            let ml = self.b.mark();
            self.lhs_expression();
            self.no_in = false;
            if self.b.stack.len() != ml + 1 && self.b.stack[ml..].iter().filter(|&&c| !self.b.nodes[c as usize].extra).count() != 1 {
                return None;
            }
            let id = self.b.last()?;
            self.to_pattern(id);
            self.b.field_last("left");
        }
        if self.at_id("in") || self.at_id("of") {
            self.bump();
            self.b.field_last("operator");
        } else {
            return None;
        }
        self.expressions();
        self.b.field_last("right");
        if !self.at(")") {
            return None;
        }
        Some(())
    }

    pub fn parenthesized_expression(&mut self) {
        let m = self.b.mark();
        self.expect("(");
        self.expressions();
        self.expect(")");
        self.b.wrap(m, "parenthesized_expression", true);
    }

    // ---------- import / export ----------
    fn import_statement(&mut self) {
        let m = self.b.mark();
        self.bump(); // import
        if self.ts && self.at_id("type") {
            let t2 = self.peek2();
            let tx2 = self.tx(t2);
            if tx2 != "from" && tx2 != "," && tx2 != "=" || (tx2 == "from" && self.tx(self.peek_n(2)) == "from") {
                self.bump();
            }
        }
        let t = self.peek();
        if t.t == T::Str {
            self.string_lit();
            self.b.field_last("source");
        } else {
            // TS: import x = require('y')
            if self.ts && t.t == T::Ident && self.tx(self.peek2()) == "=" {
                let mi = self.b.mark();
                let _ = mi;
                self.bump_named("identifier");
                self.bump();
                if self.at_id("require") {
                    let mr = self.b.mark();
                    self.bump();
                    self.expect("(");
                    self.string_lit();
                    self.expect(")");
                    self.b.wrap(mr, "import_require_clause", true);
                } else {
                    self.ts_entity_name();
                }
                self.semicolon();
                self.b.wrap(m, "import_statement", true);
                return;
            }
            let mc = self.b.mark();
            if self.at("*") {
                self.namespace_import();
            } else if self.at("{") {
                self.named_imports();
            } else {
                self.bump_named("identifier");
                if self.eat(",") {
                    if self.at("*") {
                        self.namespace_import();
                    } else {
                        self.named_imports();
                    }
                }
            }
            self.b.wrap(mc, "import_clause", true);
            self.from_clause();
        }
        if self.at_id("with") || self.at_id("assert") {
            let ma = self.b.mark();
            self.bump();
            self.object();
            self.b.wrap(ma, "import_attribute", true);
        }
        self.semicolon();
        self.b.wrap(m, "import_statement", true);
    }
    fn from_clause(&mut self) {
        if self.at_id("from") {
            self.bump();
            self.string_lit();
            self.b.field_last("source");
        }
    }
    fn namespace_import(&mut self) {
        let m = self.b.mark();
        self.bump();
        self.expect("as");
        self.bump_named("identifier");
        self.b.wrap(m, "namespace_import", true);
    }
    fn named_imports(&mut self) {
        let m = self.b.mark();
        self.expect("{");
        while !self.at("}") && self.peek().t != T::Eof {
            let ms = self.b.mark();
            if self.ts && self.at_id("type") {
                let t2 = self.peek2();
                if t2.t == T::Ident || t2.t == T::Str {
                    if self.tx(t2) != "as" || self.tx(self.peek_n(2)) == "as" {
                        self.bump();
                    }
                }
            }
            self.module_export_name();
            self.b.field_last("name");
            if self.at_id("as") {
                self.bump();
                self.bump_named("identifier");
                self.b.field_last("alias");
            }
            self.b.wrap(ms, "import_specifier", true);
            if !self.eat(",") {
                break;
            }
        }
        self.expect("}");
        self.b.wrap(m, "named_imports", true);
    }
    fn module_export_name(&mut self) {
        let t = self.peek();
        if t.t == T::Str {
            self.string_lit();
        } else {
            self.bump_named("identifier");
        }
    }
    fn export_statement(&mut self, m: usize) {
        self.bump(); // export
        if self.ts && self.at("=") {
            self.bump();
            self.expression();
            self.semicolon();
            self.b.wrap(m, "export_statement", true);
            return;
        }
        if self.ts && self.at_id("as") {
            self.bump();
            self.expect("namespace");
            self.bump_named("identifier");
            self.semicolon();
            self.b.wrap(m, "export_statement", true);
            return;
        }
        if self.ts && self.at_id("type") && (self.tx(self.peek2()) == "{" || self.tx(self.peek2()) == "*") {
            self.bump();
        }
        if self.at("*") {
            let t2 = self.peek2();
            if self.tx(t2) == "as" {
                let mn = self.b.mark();
                self.bump();
                self.bump();
                self.module_export_name();
                self.b.wrap(mn, "namespace_export", true);
            } else {
                self.bump();
            }
            self.from_clause();
            self.semicolon();
        } else if self.at("{") {
            let mc = self.b.mark();
            self.bump();
            while !self.at("}") && self.peek().t != T::Eof {
                let ms = self.b.mark();
                if self.ts && self.at_id("type") {
                    let t2 = self.peek2();
                    if (t2.t == T::Ident || t2.t == T::Str) && self.tx(t2) != "as" {
                        self.bump();
                    }
                }
                self.module_export_name();
                self.b.field_last("name");
                if self.at_id("as") {
                    self.bump();
                    self.module_export_name();
                    self.b.field_last("alias");
                }
                self.b.wrap(ms, "export_specifier", true);
                if !self.eat(",") {
                    break;
                }
            }
            self.expect("}");
            self.b.wrap(mc, "export_clause", true);
            self.from_clause();
            self.semicolon();
        } else if self.at_id("default") {
            self.bump();
            let t = self.peek();
            let tx = self.tx(t);
            let t2 = self.peek2();
            if tx == "function" || (tx == "async" && self.tx(t2) == "function") {
                let md = self.b.mark();
                self.function_like(md, true);
                self.b.field_last("declaration");
            } else if tx == "class" || tx == "@" {
                let md = self.b.mark();
                while self.at("@") {
                    self.decorator();
                    self.b.field_last("decorator");
                }
                self.class_like(md, true);
                self.b.field_last("declaration");
            } else if self.ts && tx == "interface" {
                let md = self.b.mark();
                self.ts_statement(t, t2);
                let _ = md;
                self.b.field_last("declaration");
            } else {
                self.expression();
                self.b.field_last("value");
                self.semicolon();
            }
        } else {
            let md = self.b.mark();
            let _ = md;
            self.statement();
            self.b.field_last("declaration");
        }
        self.b.wrap(m, "export_statement", true);
    }

    // ---------- functions & classes ----------
    /// function declaration or expression. `m` mark before (async). decl: statement-level
    pub fn function_like(&mut self, m: usize, decl: bool) {
        if self.at_id("async") {
            self.bump();
        }
        self.bump(); // function
        let mut gen = false;
        if self.at("*") {
            self.bump();
            gen = true;
        }
        let t = self.peek();
        if t.t == T::Ident && self.tx(t) != "(" {
            self.bump_named("identifier");
            self.b.field_last("name");
        }
        self.call_signature();
        if self.at("{") {
            self.statement_block_ex(decl);
            self.b.field_last("body");
        } else if self.ts {
            // overload signature
            self.semicolon();
            let kind = if decl { "function_signature" } else { "function_expression" };
            self.b.wrap(m, kind, true);
            return;
        }
        let kind = match (decl, gen) {
            (true, false) => "function_declaration",
            (true, true) => "generator_function_declaration",
            (false, false) => "function_expression",
            (false, true) => "generator_function",
        };
        self.b.wrap(m, kind, true);
    }

    pub fn call_signature(&mut self) {
        if self.ts && self.at("<") {
            self.type_parameters();
            self.b.field_last("type_parameters");
        }
        self.formal_parameters();
        self.b.field_last("parameters");
        if self.ts && self.at(":") {
            self.return_type_annotation();
            self.b.field_last("return_type");
        }
    }

    pub fn formal_parameters(&mut self) {
        let m = self.b.mark();
        self.expect("(");
        while !self.at(")") && self.peek().t != T::Eof {
            self.formal_parameter();
            if !self.eat(",") {
                break;
            }
        }
        self.expect(")");
        self.b.wrap(m, "formal_parameters", true);
    }

    pub fn formal_parameter(&mut self) {
        if self.ts {
            self.ts_formal_parameter();
            return;
        }
        while self.at("@") {
            self.decorator();
            self.b.field_last("decorator");
        }
        let m = self.b.mark();
        if self.at("...") {
            self.rest_pattern();
            return;
        }
        self.binding_pattern();
        if self.at("=") {
            self.b.field_last("left");
            self.bump();
            self.assign_expr();
            self.b.field_last("right");
            self.b.wrap(m, "assignment_pattern", true);
        }
    }

    pub fn rest_pattern(&mut self) {
        let m = self.b.mark();
        self.bump(); // ...
        self.binding_pattern();
        self.b.wrap(m, "rest_pattern", true);
    }

    /// identifier | array_pattern | object_pattern (binding context)
    pub fn binding_pattern(&mut self) {
        let t = self.peek();
        let tx = self.tx(t);
        if tx == "[" {
            let m = self.b.mark();
            self.bump();
            loop {
                if self.at("]") || self.peek().t == T::Eof {
                    break;
                }
                if self.at(",") {
                    self.bump();
                    continue;
                }
                if self.at("...") {
                    self.rest_pattern();
                } else {
                    let me = self.b.mark();
                    self.binding_pattern();
                    if self.at("=") {
                        self.b.field_last("left");
                        self.bump();
                        self.assign_expr();
                        self.b.field_last("right");
                        self.b.wrap(me, "assignment_pattern", true);
                    }
                }
                if !self.at("]") {
                    self.expect(",");
                }
            }
            self.expect("]");
            self.b.wrap(m, "array_pattern", true);
        } else if tx == "{" {
            let m = self.b.mark();
            self.bump();
            loop {
                if self.at("}") || self.peek().t == T::Eof {
                    break;
                }
                if self.at(",") {
                    self.bump();
                    continue;
                }
                if self.at("...") {
                    self.rest_pattern();
                } else {
                    let mp = self.b.mark();
                    let t = self.peek();
                    let t2 = self.peek2();
                    let tx2 = self.tx(t2);
                    if t.t == T::Ident && tx2 != ":" && tx2 != "(" {
                        self.bump_named("shorthand_property_identifier_pattern");
                        if self.at("=") {
                            self.b.field_last("left");
                            self.bump();
                            self.assign_expr();
                            self.b.field_last("right");
                            self.b.wrap(mp, "object_assignment_pattern", true);
                        }
                    } else {
                        self.property_name();
                        self.b.field_last("key");
                        self.expect(":");
                        let mv = self.b.mark();
                        self.binding_pattern();
                        if self.at("=") {
                            self.b.field_last("left");
                            self.bump();
                            self.assign_expr();
                            self.b.field_last("right");
                            self.b.wrap(mv, "assignment_pattern", true);
                        }
                        self.b.field_last("value");
                        self.b.wrap(mp, "pair_pattern", true);
                    }
                }
                if !self.at("}") {
                    self.expect(",");
                }
            }
            self.expect("}");
            self.b.wrap(m, "object_pattern", true);
        } else if t.t == T::Ident {
            let k = if tx == "undefined" { "undefined" } else if self.ts && tx == "this" { "this" } else { "identifier" };
            self.bump_named(k);
        } else {
            // member expressions in for-in, etc.
            self.lhs_expression();
        }
    }

    pub fn decorator(&mut self) {
        let m = self.b.mark();
        self.bump(); // @
        if self.at("(") {
            self.parenthesized_expression();
        } else {
            let mm = self.b.mark();
            self.bump_named("identifier");
            while self.at(".") {
                self.bump();
                self.bump_named("property_identifier");
                self.b.field_last("property");
                // object field on first child
                let first = self.b.stack[mm];
                if self.b.nodes[first as usize].field.is_none() {
                    self.b.set_field(first, "object");
                }
                self.b.wrap(mm, "member_expression", true);
            }
            if self.ts && self.at("<") {
                let cp = self.b.checkpoint();
                let sp = self.pos;
                if !self.try_type_arguments() {
                    self.b.restore(cp);
                    self.pos = sp;
                } else {
                    self.b.field_last("type_arguments");
                }
            }
            if self.at("(") {
                if let Some(&f) = self.b.stack.get(mm) {
                    self.b.set_field(f, "function");
                }
                self.arguments();
                self.b.field_last("arguments");
                self.b.wrap(mm, "call_expression", true);
            }
        }
        self.b.wrap(m, "decorator", true);
    }

    pub fn class_like(&mut self, m: usize, decl: bool) {
        if self.ts && self.at_id("abstract") {
            self.bump();
        }
        let is_abstract = self.b.stack[m..].iter().any(|&c| self.b.nodes[c as usize].kind == "abstract");
        self.bump(); // class
        let t = self.peek();
        let tx = self.tx(t);
        if t.t == T::Ident && tx != "extends" && tx != "implements" && tx != "{" {
            let k = if self.ts { "type_identifier" } else { "identifier" };
            self.bump_named(k);
            self.b.field_last("name");
        } else if t.t == T::Ident && self.ts && tx == "implements" && false {
        }
        if self.ts && self.at("<") {
            self.type_parameters();
            self.b.field_last("type_parameters");
        }
        if self.at_id("extends") || self.at_id("implements") {
            let mh = self.b.mark();
            if self.ts {
                if self.at_id("extends") {
                    let me = self.b.mark();
                    self.bump();
                    loop {
                        let mx = self.b.mark();
                        self.lhs_expression_no_call();
                        if self.at("(") {
                            // call in heritage
                            self.call_chain_from(mx);
                        }
                        if self.at("<") {
                            self.type_arguments();
                            self.b.field_last("type_arguments");
                        }
                        if !self.eat(",") {
                            break;
                        }
                    }
                    self.b.wrap(me, "extends_clause", true);
                }
                if self.at_id("implements") {
                    let mi = self.b.mark();
                    self.bump();
                    loop {
                        self.ts_type();
                        if !self.eat(",") {
                            break;
                        }
                    }
                    self.b.wrap(mi, "implements_clause", true);
                }
            } else {
                self.bump();
                self.lhs_expression();
            }
            self.b.wrap(mh, "class_heritage", true);
        }
        self.class_body();
        self.b.field_last("body");
        if decl {
            self.opt_asi_line_comment();
        }
        let kind = if decl {
            if is_abstract { "abstract_class_declaration" } else { "class_declaration" }
        } else {
            "class"
        };
        self.b.wrap(m, kind, true);
    }

    fn class_body(&mut self) {
        let m = self.b.mark();
        self.expect("{");
        loop {
            let t = self.peek();
            if t.t == T::Eof || self.at("}") {
                break;
            }
            if self.at(";") {
                self.bump();
                continue;
            }
            let before = self.pos;
            self.class_member();
            if self.pos == before {
                self.error_token();
            }
        }
        self.expect("}");
        self.b.wrap(m, "class_body", true);
    }

    fn is_modifier_here(&self, word: &str) -> bool {
        // word followed by a property name on the same line (not ( = ; : etc.)
        let t = self.peek();
        if t.t != T::Ident || self.tx(t) != word {
            return false;
        }
        let t2 = self.peek2();
        let tx2 = self.tx(t2);
        if t2.t == T::Eof {
            return false;
        }
        if matches!(tx2, "(" | "=" | ";" | ":" | "}" | "?" | "!" | "<" | ",") && t2.t == T::Punct {
            return false;
        }
        if word == "async" && t2.nl {
            return false;
        }
        true
    }

    fn class_member(&mut self) {
        let m = self.b.mark();
        while self.at("@") {
            self.decorator();
            self.b.field_last("decorator");
        }
        // static block
        if self.at_id("static") && self.tx(self.peek2()) == "{" {
            self.bump();
            self.statement_block();
            self.b.field_last("body");
            self.b.wrap(m, "class_static_block", true);
            return;
        }
        if self.ts {
            if self.ts_class_member(m) {
                return;
            }
        }
        if self.is_modifier_here("static") {
            self.bump();
        }
        self.method_or_field(m, true);
    }

    /// method definition or field definition. in_class: true for class bodies.
    pub fn method_or_field(&mut self, m: usize, in_class: bool) {
        let mut is_method = false;
        if self.is_modifier_here("async") {
            self.bump();
            is_method = true;
        }
        if self.at("*") {
            self.bump();
            is_method = true;
        }
        if (self.is_modifier_here("get") || self.is_modifier_here("set")) && !self.at("*") {
            self.bump();
            is_method = true;
        }
        self.property_name();
        let name_field = if in_class && !is_method && !self.at("(") && !self.at("<") { "property" } else { "name" };
        self.b.field_last(name_field);
        if self.ts && (self.at("?") || self.at("!")) {
            self.bump();
        }
        if self.at("(") || (self.ts && self.at("<")) {
            self.call_signature();
            if self.at("{") {
                self.statement_block();
                self.b.field_last("body");
                self.b.wrap(m, "method_definition", true);
            } else {
                self.semicolon();
                self.b.wrap(m, "method_signature", true);
            }
            if in_class && self.at(";") {
                // optional ; after method belongs to class body
            }
            return;
        }
        // field
        if self.ts && self.at(":") {
            self.type_annotation();
            self.b.field_last("type");
        }
        if self.at("=") {
            self.bump();
            self.assign_expr();
            self.b.field_last("value");
        }
        self.semicolon();
        let kind = if self.ts { "public_field_definition" } else { "field_definition" };
        self.b.wrap(m, kind, true);
    }

    pub fn property_name(&mut self) {
        let t = self.peek();
        match t.t {
            T::Str => self.string_lit(),
            T::Num => {
                self.bump_named("number");
            }
            T::Private => {
                self.bump_named("private_property_identifier");
            }
            T::Ident => {
                self.bump_named("property_identifier");
            }
            _ => {
                if self.tx(t) == "[" {
                    let m = self.b.mark();
                    self.bump();
                    self.assign_expr();
                    self.expect("]");
                    self.b.wrap(m, "computed_property_name", true);
                } else {
                    self.error_token();
                }
            }
        }
    }

    // ---------- expressions ----------
    pub fn expressions(&mut self) {
        let m = self.b.mark();
        self.assign_expr();
        if self.at(",") {
            while self.at(",") {
                self.bump();
                self.assign_expr();
            }
            self.b.wrap(m, "sequence_expression", true);
        }
    }

    pub fn expression(&mut self) {
        self.assign_expr();
    }

    fn is_arrow_ahead(&self) -> bool {
        // at "(" : find matching ")" and check "=>" (or ":" for TS return type)
        let t = self.peek();
        let mut depth = 0i32;
        let mut pos = t.s;
        let mut first = true;
        loop {
            let tk = if first { t } else { self.peek_at(pos, true) };
            first = false;
            if tk.t == T::Eof {
                return false;
            }
            let tx = self.tx(tk);
            if tk.t == T::Punct {
                match tx {
                    "(" | "[" | "{" | "${" => depth += 1,
                    ")" | "]" | "}" => {
                        depth -= 1;
                        if depth == 0 {
                            let n = self.peek_at(tk.e, false);
                            let ntx = self.tx(n);
                            return ntx == "=>" || (self.ts && ntx == ":");
                        }
                    }
                    "`" => {
                        pos = self.skip_template(tk.s);
                        continue;
                    }
                    _ => {}
                }
            }
            pos = tk.e;
        }
    }

    fn skip_template(&self, start: usize) -> usize {
        // start at backtick; return position after closing backtick
        let b = self.src.as_bytes();
        let mut i = start + 1;
        while i < b.len() {
            match b[i] {
                b'\\' => i += 2,
                b'`' => return i + 1,
                b'$' if i + 1 < b.len() && b[i + 1] == b'{' => {
                    // skip balanced
                    let mut depth = 1;
                    let mut j = i + 2;
                    while j < b.len() && depth > 0 {
                        let tk = self.peek_at(j, true);
                        if tk.t == T::Eof {
                            return b.len();
                        }
                        let tx = self.tx(tk);
                        if tx == "{" || tx == "${" {
                            depth += 1;
                        } else if tx == "}" {
                            depth -= 1;
                        } else if tx == "`" {
                            j = self.skip_template(tk.s);
                            continue;
                        }
                        j = tk.e;
                    }
                    i = j;
                }
                _ => i += 1,
            }
        }
        b.len()
    }

    pub fn assign_expr(&mut self) {
        self.depth += 1;
        if self.depth > 400 {
            self.error_token();
            self.depth -= 1;
            return;
        }
        self.assign_expr_inner();
        self.depth -= 1;
    }

    fn assign_expr_inner(&mut self) {
        let t = self.peek_re();
        let tx = self.tx(t);
        let m = self.b.mark();
        // arrow functions
        if t.t == T::Ident {
            let t2 = self.peek_at(t.e, false);
            let tx2 = self.tx(t2);
            if tx2 == "=>" && !KW_NOT_ID.contains(&tx) {
                self.bump_named("identifier");
                self.b.field_last("parameter");
                self.arrow_rest(m);
                return;
            }
            if tx == "async" && !t2.nl {
                if t2.t == T::Ident && self.tx(self.peek_at(t2.e, false)) == "=>" {
                    self.bump();
                    self.bump_named("identifier");
                    self.b.field_last("parameter");
                    self.arrow_rest(m);
                    return;
                }
                if tx2 == "(" || (self.ts && tx2 == "<") {
                    // async (..) =>
                    let cp = self.b.checkpoint();
                    let sp = self.pos;
                    self.bump();
                    if self.try_arrow_params() && self.at("=>") {
                        self.arrow_rest(m);
                        return;
                    }
                    self.b.restore(cp);
                    self.pos = sp;
                }
            }
            if tx == "yield" && !self.in_type {
                let t2s = self.tx(t2);
                if !(t2.t == T::Punct && matches!(t2s, ")" | "]" | "}" | "," | ";" | ":" | "=" | "==" | "===" | "." ) ) || t2s == "*" {
                    self.bump();
                    if self.at("*") {
                        self.bump();
                        self.assign_expr();
                    } else {
                        let n = self.peek_re();
                        let ntx = self.tx(n);
                        if !(n.t == T::Eof || n.nl || (n.t == T::Punct && matches!(ntx, ")" | "]" | "}" | "," | ";" | ":"))) {
                            self.assign_expr();
                        }
                    }
                    self.b.wrap(m, "yield_expression", true);
                    return;
                }
            }
        }
        if t.t == T::Punct && (tx == "(" || (self.ts && tx == "<" && !self.jsx)) {
            if tx == "(" && self.is_arrow_ahead() || (tx == "<" ) {
                let cp = self.b.checkpoint();
                let sp = self.pos;
                if self.try_arrow_params() && self.at("=>") {
                    self.arrow_rest(m);
                    return;
                }
                self.b.restore(cp);
                self.pos = sp;
            }
        }
        if self.ts && self.jsx && t.t == T::Punct && tx == "<" {
            // tsx generic arrow: <T,>(x) => ...
            let t2 = self.peek_at(t.e, false);
            let t3 = self.peek_at(t2.e, false);
            if t2.t == T::Ident && (self.tx(t3) == "," || self.tx(t3) == "extends") {
                let cp = self.b.checkpoint();
                let sp = self.pos;
                if self.try_arrow_params() && self.at("=>") {
                    self.arrow_rest(m);
                    return;
                }
                self.b.restore(cp);
                self.pos = sp;
            }
        }
        self.ternary();
        // assignment
        let t = self.peek();
        if t.t == T::Punct {
            let op = self.tx(t);
            match op {
                "=" => {
                    if let Some(id) = self.b.last() {
                        let k = self.b.nodes[id as usize].kind;
                        if k == "array" || k == "object" {
                            self.to_pattern(id);
                        }
                    }
                    self.b.field_last("left");
                    self.bump();
                    self.assign_expr();
                    self.b.field_last("right");
                    self.b.wrap(m, "assignment_expression", true);
                }
                "+=" | "-=" | "*=" | "/=" | "%=" | "^=" | "&=" | "|=" | ">>=" | ">>>=" | "<<=" | "**=" | "&&=" | "||="
                | "??=" => {
                    self.b.field_last("left");
                    self.bump();
                    self.b.field_last("operator");
                    self.assign_expr();
                    self.b.field_last("right");
                    self.b.wrap(m, "augmented_assignment_expression", true);
                }
                _ => {}
            }
        }
    }

    /// parse arrow function parameters (call signature); returns false if not possible
    fn try_arrow_params(&mut self) -> bool {
        if self.ts && self.at("<") {
            if !self.try_type_parameters() {
                return false;
            }
            self.b.field_last("type_parameters");
        }
        if !self.at("(") {
            return false;
        }
        let m = self.b.mark();
        self.bump();
        while !self.at(")") {
            let t = self.peek();
            if t.t == T::Eof {
                return false;
            }
            let before = self.pos;
            let mstack = self.b.mark();
            self.formal_parameter();
            if self.pos == before || self.has_missing_from(mstack) {
                return false;
            }
            if !self.eat(",") {
                break;
            }
        }
        if !self.at(")") {
            return false;
        }
        self.bump();
        self.b.wrap(m, "formal_parameters", true);
        self.b.field_last("parameters");
        if self.ts && self.at(":") {
            let ms = self.b.mark();
            if !self.try_return_type() {
                return false;
            }
            let _ = ms;
            self.b.field_last("return_type");
        }
        true
    }

    pub fn has_missing_from(&self, mark: usize) -> bool {
        fn rec(b: &Builder, id: u32) -> bool {
            let n = &b.nodes[id as usize];
            if n.missing || n.kind == "ERROR" {
                return true;
            }
            n.children.iter().any(|&c| rec(b, c))
        }
        self.b.stack[mark.min(self.b.stack.len())..].iter().any(|&c| rec(&self.b, c))
    }

    fn arrow_rest(&mut self, m: usize) {
        self.expect("=>");
        if self.at("{") {
            self.statement_block_ex(true);
        } else {
            self.assign_expr();
        }
        self.b.field_last("body");
        self.b.wrap(m, "arrow_function", true);
    }

    fn ternary(&mut self) {
        let m = self.b.mark();
        self.binary(0);
        if self.at("?") {
            self.b.field_last("condition");
            self.bump();
            let save = self.no_in;
            self.no_in = false;
            self.assign_expr();
            self.no_in = save;
            self.b.field_last("consequence");
            self.expect(":");
            self.assign_expr();
            self.b.field_last("alternative");
            self.b.wrap(m, "ternary_expression", true);
        }
    }

    fn binop_prec(&self, t: Tok) -> Option<(u8, bool)> {
        // returns (precedence, right_assoc)
        let tx = self.tx(t);
        if t.t == T::Ident {
            return match tx {
                "instanceof" => Some((7, false)),
                "in" if !self.no_in => Some((7, false)),
                "as" | "satisfies" if self.ts && !t.nl => Some((7, false)),
                _ => None,
            };
        }
        if t.t != T::Punct {
            return None;
        }
        Some(match tx {
            "??" => (1, false),
            "||" => (2, false),
            "&&" => (3, false),
            "|" => (4, false),
            "^" => (5, false),
            "&" => (6, false),
            "==" | "!=" | "===" | "!==" => (6, false).max((6, false)).min((6, false)).clone_with(65),
            "<" | ">" | "<=" | ">=" => (7, false),
            "<<" | ">>" | ">>>" => (8, false),
            "+" | "-" => (9, false),
            "*" | "/" | "%" => (10, false),
            "**" => (11, true),
            _ => return None,
        })
    }

    fn binary(&mut self, min: u8) {
        let m = self.b.mark();
        self.unary();
        self.binary_rest(m, min);
    }

    fn binary_rest(&mut self, m: usize, min: u8) {
        loop {
            let mut t = self.peek();
            // ">" may have been lexed as ">>" etc; fine
            if t.t == T::Punct && self.tx(t) == "<" && self.ts {
                // could be type arguments call handled in postfix
            }
            let Some((p, right)) = self.binop_prec(t) else { break };
            // encode equality as level 6.5 => use 65 scaling
            let p = scale(p, self.tx(t));
            if p < min {
                break;
            }
            let tx = self.tx(t);
            if self.ts && (tx == "as" || tx == "satisfies") {
                self.b.field_last("");
                self.unset_last_field();
                self.bump();
                if self.at_id("const") {
                    self.bump();
                } else {
                    self.ts_type();
                }
                let k = if tx == "as" { "as_expression" } else { "satisfies_expression" };
                self.b.wrap(m, k, true);
                continue;
            }
            self.b.field_last("left");
            t = self.peek();
            let _ = t;
            self.bump();
            self.b.field_last("operator");
            let next_min = if right { p } else { p + 1 };
            self.binary(next_min);
            self.b.field_last("right");
            self.b.wrap(m, "binary_expression", true);
        }
    }

    pub fn unset_last_field(&mut self) {
        if let Some(id) = self.b.last() {
            self.b.nodes[id as usize].field = None;
        }
    }

    fn unary(&mut self) {
        let t = self.peek_re();
        let tx = self.tx(t);
        let m = self.b.mark();
        if t.t == T::Punct {
            match tx {
                "!" | "~" | "-" | "+" => {
                    self.bump();
                    self.b.field_last("operator");
                    self.unary();
                    self.b.field_last("argument");
                    self.b.wrap(m, "unary_expression", true);
                    return;
                }
                "++" | "--" => {
                    self.bump();
                    self.b.field_last("operator");
                    self.unary();
                    self.b.field_last("argument");
                    self.b.wrap(m, "update_expression", true);
                    return;
                }
                "<" if self.ts && !self.jsx => {
                    // type assertion <T>x
                    let cp = self.b.checkpoint();
                    let sp = self.pos;
                    if self.try_type_arguments() {
                        self.unary();
                        self.b.wrap(m, "type_assertion", true);
                        return;
                    }
                    self.b.restore(cp);
                    self.pos = sp;
                }
                _ => {}
            }
        }
        if t.t == T::Ident {
            let t2 = self.peek_at(t.e, true);
            let tx2 = self.tx(t2);
            let operand_follows = !(t2.t == T::Eof
                || (t2.t == T::Punct && matches!(tx2, ")" | "]" | "}" | "," | ";" | ":" | "=" | "." | "?." | "=>" | "==" | "===" | "!=" | "!==" ))
                || (t2.t == T::Ident && matches!(tx2, "in" | "instanceof" | "of" | "as")));
            match tx {
                "typeof" | "void" | "delete" if operand_follows => {
                    self.bump();
                    self.b.field_last("operator");
                    self.unary();
                    self.b.field_last("argument");
                    self.b.wrap(m, "unary_expression", true);
                    return;
                }
                "await" if operand_follows => {
                    self.bump();
                    self.unary();
                    self.b.wrap(m, "await_expression", true);
                    return;
                }
                _ => {}
            }
        }
        self.postfix();
    }

    fn postfix(&mut self) {
        let m = self.b.mark();
        self.lhs_expression();
        let t = self.peek();
        if t.t == T::Punct && (self.tx(t) == "++" || self.tx(t) == "--") && !t.nl {
            self.b.field_last("argument");
            self.bump();
            self.b.field_last("operator");
            self.b.wrap(m, "update_expression", true);
        }
    }

    /// primary followed by member/call/subscript chain
    pub fn lhs_expression(&mut self) {
        let m = self.b.mark();
        self.primary();
        self.call_chain_from(m);
    }

    pub fn lhs_expression_no_call(&mut self) {
        let m = self.b.mark();
        self.primary();
        self.member_chain_from(m, false);
    }

    pub fn call_chain_from(&mut self, m: usize) {
        self.member_chain_from(m, true);
    }

    fn set_first_field(&mut self, m: usize, f: &'static str) {
        for i in m..self.b.stack.len() {
            let id = self.b.stack[i];
            if !self.b.nodes[id as usize].extra {
                self.b.nodes[id as usize].field = Some(f);
                return;
            }
        }
    }

    fn member_chain_from(&mut self, m: usize, calls: bool) {
        loop {
            let t = self.peek();
            let tx = self.tx(t);
            if t.t == T::Punct {
                match tx {
                    "." => {
                        self.set_first_field(m, "object");
                        self.bump();
                        self.member_property();
                        self.b.wrap(m, "member_expression", true);
                        continue;
                    }
                    "?." => {
                        self.set_first_field(m, "object");
                        let t2 = self.peek2();
                        let tx2 = self.tx(t2);
                        if tx2 == "(" {
                            if !calls {
                                break;
                            }
                            self.set_first_field(m, "function");
                            self.bump_named("optional_chain");
                            self.b.field_last("optional_chain");
                            self.arguments();
                            self.b.field_last("arguments");
                            self.b.wrap(m, "call_expression", true);
                        } else if tx2 == "[" {
                            self.bump_named("optional_chain");
                            self.b.field_last("optional_chain");
                            self.bump();
                            self.expressions();
                            self.b.field_last("index");
                            self.expect("]");
                            self.b.wrap(m, "subscript_expression", true);
                        } else {
                            self.bump_named("optional_chain");
                            self.b.field_last("optional_chain");
                            self.member_property();
                            self.b.wrap(m, "member_expression", true);
                        }
                        continue;
                    }
                    "[" => {
                        self.set_first_field(m, "object");
                        self.bump();
                        self.expressions();
                        self.b.field_last("index");
                        self.expect("]");
                        self.b.wrap(m, "subscript_expression", true);
                        continue;
                    }
                    "(" if calls => {
                        self.set_first_field(m, "function");
                        self.arguments();
                        self.b.field_last("arguments");
                        self.b.wrap(m, "call_expression", true);
                        continue;
                    }
                    "`" if !t.nl || true => {
                        if !calls {
                            break;
                        }
                        self.set_first_field(m, "function");
                        self.template_string();
                        self.b.field_last("arguments");
                        self.b.wrap(m, "call_expression", true);
                        continue;
                    }
                    "!" if self.ts && !t.nl => {
                        let t2 = self.peek2();
                        if self.tx(t2) == "=" && t2.s == t.e {
                            break;
                        }
                        self.bump();
                        self.b.wrap(m, "non_null_expression", true);
                        continue;
                    }
                    "<" if self.ts => {
                        // generic call: f<T>(x)
                        let cp = self.b.checkpoint();
                        let sp = self.pos;
                        if self.try_type_arguments() {
                            let n = self.peek();
                            let ntx = self.tx(n);
                            if ntx == "(" && calls {
                                self.b.field_last("type_arguments");
                                self.set_first_field(m, "function");
                                self.arguments();
                                self.b.field_last("arguments");
                                self.b.wrap(m, "call_expression", true);
                                continue;
                            } else if ntx == "`" && calls {
                                self.b.field_last("type_arguments");
                                self.set_first_field(m, "function");
                                self.template_string();
                                self.b.field_last("arguments");
                                self.b.wrap(m, "call_expression", true);
                                continue;
                            } else if !(n.t == T::Ident || n.t == T::Num || n.t == T::Str || matches!(ntx, "(" | "[" | "{" | "-" | "+" | "<" | "!" | "~")) {
                                self.b.field_last("type_arguments");
                                self.b.wrap(m, "instantiation_expression", true);
                                continue;
                            }
                        }
                        self.b.restore(cp);
                        self.pos = sp;
                        break;
                    }
                    _ => {}
                }
            }
            break;
        }
    }

    fn member_property(&mut self) {
        let t = self.peek();
        if t.t == T::Private {
            self.bump_named("private_property_identifier");
        } else if t.t == T::Ident {
            self.bump_named("property_identifier");
        } else {
            let p = self.pos;
            self.b.missing("property_identifier", true, p);
        }
        self.b.field_last("property");
    }

    pub fn arguments(&mut self) {
        let m = self.b.mark();
        self.expect("(");
        let save = self.no_in;
        self.no_in = false;
        while !self.at(")") && self.peek().t != T::Eof {
            if self.at(",") {
                self.bump();
                continue;
            }
            if self.at("...") {
                let ms = self.b.mark();
                self.bump();
                self.assign_expr();
                self.b.wrap(ms, "spread_element", true);
            } else {
                let before = self.pos;
                self.assign_expr();
                if self.pos == before {
                    break;
                }
            }
            if !self.at(")") {
                if !self.at(",") {
                    break;
                }
            }
        }
        self.no_in = save;
        self.expect(")");
        self.b.wrap(m, "arguments", true);
    }

    fn primary(&mut self) {
        let t = self.peek_re();
        let tx = self.tx(t);
        let m = self.b.mark();
        match t.t {
            T::Num => {
                self.bump_tok(t, "number", true);
            }
            T::Str => self.string_lit(),
            T::Regex => self.regex(t),
            T::Private => {
                self.bump_tok(t, "private_property_identifier", true);
            }
            T::Ident => match tx {
                "this" => {
                    self.bump_tok(t, "this", true);
                }
                "super" => {
                    self.bump_tok(t, "super", true);
                }
                "true" => {
                    self.bump_tok(t, "true", true);
                }
                "false" => {
                    self.bump_tok(t, "false", true);
                }
                "null" => {
                    self.bump_tok(t, "null", true);
                }
                "undefined" => {
                    self.bump_tok(t, "undefined", true);
                }
                "function" => self.function_like(m, false),
                "async" if self.tx(self.peek2()) == "function" && !self.peek2().nl => self.function_like(m, false),
                "class" => self.class_like(m, false),
                "new" => self.new_expression(),
                "import" => {
                    let t2 = self.peek2();
                    if self.tx(t2) == "." {
                        self.bump();
                        self.bump();
                        self.bump_named("property_identifier");
                        self.b.field_last("property");
                        self.b.wrap(m, "meta_property", true);
                    } else {
                        self.bump_tok(t, "import", true);
                    }
                }
                _ => {
                    self.bump_tok(t, "identifier", true);
                }
            },
            T::Punct => match tx {
                "(" => {
                    self.parenthesized_expression();
                }
                "[" => self.array(),
                "{" => self.object(),
                "`" => self.template_string(),
                "<" if self.jsx => self.jsx_element(),
                "@" => {
                    while self.at("@") {
                        self.decorator();
                        self.b.field_last("decorator");
                    }
                    if self.at_id("class") {
                        self.class_like(m, false);
                    }
                }
                _ => {
                    self.error_token();
                }
            },
            T::Eof => {
                let p = self.pos;
                self.b.missing("identifier", true, p);
            }
            T::Err => self.error_token(),
        }
    }

    fn new_expression(&mut self) {
        let m = self.b.mark();
        self.bump(); // new
        if self.at(".") {
            self.bump();
            self.bump_named("property_identifier");
            self.b.field_last("property");
            self.b.wrap(m, "meta_property", true);
            return;
        }
        let mc = self.b.mark();
        if self.at_id("new") {
            self.new_expression();
        } else {
            self.primary();
            self.member_chain_from(mc, false);
        }
        self.b.field_last("constructor");
        if self.ts && self.at("<") {
            let cp = self.b.checkpoint();
            let sp = self.pos;
            if self.try_type_arguments() {
                self.b.field_last("type_arguments");
            } else {
                self.b.restore(cp);
                self.pos = sp;
            }
        }
        if self.at("(") {
            self.arguments();
            self.b.field_last("arguments");
        }
        self.b.wrap(m, "new_expression", true);
    }

    fn array(&mut self) {
        let m = self.b.mark();
        self.bump();
        let save = self.no_in;
        self.no_in = false;
        loop {
            if self.at("]") || self.peek().t == T::Eof {
                break;
            }
            if self.at(",") {
                self.bump();
                continue;
            }
            if self.at("...") {
                let ms = self.b.mark();
                self.bump();
                self.assign_expr();
                self.b.wrap(ms, "spread_element", true);
            } else {
                let before = self.pos;
                self.assign_expr();
                if self.pos == before {
                    break;
                }
            }
            if !self.at("]") && !self.at(",") {
                break;
            }
        }
        self.no_in = save;
        self.expect("]");
        self.b.wrap(m, "array", true);
    }

    pub fn object(&mut self) {
        let m = self.b.mark();
        self.expect("{");
        let save = self.no_in;
        self.no_in = false;
        loop {
            if self.at("}") || self.peek().t == T::Eof {
                break;
            }
            if self.at(",") {
                self.bump();
                continue;
            }
            let before = self.pos;
            self.object_member();
            if self.pos == before {
                self.error_token();
            }
            if !self.at("}") && !self.at(",") {
                break;
            }
        }
        self.no_in = save;
        self.expect("}");
        self.b.wrap(m, "object", true);
    }

    fn object_member(&mut self) {
        let m = self.b.mark();
        if self.at("...") {
            self.bump();
            self.assign_expr();
            self.b.wrap(m, "spread_element", true);
            return;
        }
        let t = self.peek();
        let t2 = self.peek2();
        let tx2 = self.tx(t2);
        if t.t == T::Ident && (tx2 == "," || tx2 == "}" || t2.t == T::Eof) {
            self.bump_named("shorthand_property_identifier");
            return;
        }
        if t.t == T::Ident && tx2 == "=" {
            // shorthand with initializer (only valid in patterns)
            self.bump_named("shorthand_property_identifier_pattern");
            self.b.field_last("left");
            self.bump();
            self.assign_expr();
            self.b.field_last("right");
            self.b.wrap(m, "object_assignment_pattern", true);
            return;
        }
        // method or pair
        let is_method_start = {
            let tx = self.tx(t);
            tx == "*"
                || ((tx == "async" || tx == "get" || tx == "set") && t2.t != T::Eof && !matches!(tx2, ":" | "(" | "," | "}" | "<"))
        };
        if is_method_start {
            self.method_or_field(m, false);
            return;
        }
        self.property_name();
        if self.at(":") {
            self.b.field_last("key");
            self.bump();
            self.assign_expr();
            self.b.field_last("value");
            self.b.wrap(m, "pair", true);
        } else if self.at("(") || self.at("<") {
            self.b.field_last("name");
            self.call_signature();
            if self.at("{") {
                self.statement_block();
                self.b.field_last("body");
            }
            self.b.wrap(m, "method_definition", true);
        }
    }

    /// Convert an expression subtree into a pattern (for destructuring assignment).
    pub fn to_pattern(&mut self, id: u32) {
        let kind = self.b.nodes[id as usize].kind;
        let new_kind = match kind {
            "array" => "array_pattern",
            "object" => "object_pattern",
            "pair" => "pair_pattern",
            "shorthand_property_identifier" => "shorthand_property_identifier_pattern",
            "spread_element" => "rest_pattern",
            "assignment_expression" => "assignment_pattern",
            _ => return,
        };
        self.b.nodes[id as usize].kind = new_kind;
        let children = self.b.nodes[id as usize].children.clone();
        match new_kind {
            "array_pattern" | "object_pattern" | "rest_pattern" => {
                for c in children {
                    self.to_pattern(c);
                }
            }
            "pair_pattern" => {
                for c in children {
                    if self.b.nodes[c as usize].field == Some("value") {
                        self.to_pattern(c);
                    }
                }
            }
            "assignment_pattern" => {
                for c in children {
                    if self.b.nodes[c as usize].field == Some("left") {
                        self.to_pattern(c);
                    }
                }
            }
            _ => {}
        }
    }

    // ---------- literals ----------
    pub fn string_lit(&mut self) {
        let t = self.peek();
        if t.t != T::Str {
            let p = self.pos;
            self.b.missing("string", true, p);
            return;
        }
        self.flush_comments_to(t.s);
        let m = self.b.mark();
        let b = self.src.as_bytes();
        let q = b[t.s];
        let qk = if q == b'"' { "\"" } else { "'" };
        self.b.leaf(qk, false, t.s, t.s + 1);
        let mut i = t.s + 1;
        let end = t.e;
        let close = end > t.s + 1 && b[end - 1] == q;
        let inner_end = if close { end - 1 } else { end };
        let mut frag_start = i;
        while i < inner_end {
            if b[i] == b'\\' {
                if frag_start < i {
                    self.b.leaf("string_fragment", true, frag_start, i);
                }
                let e = escape_end(self.src, i);
                self.b.leaf("escape_sequence", true, i, e.min(inner_end));
                i = e;
                frag_start = i;
            } else {
                i += 1;
            }
        }
        if frag_start < inner_end {
            self.b.leaf("string_fragment", true, frag_start, inner_end);
        }
        if close {
            self.b.leaf(qk, false, end - 1, end);
        } else {
            self.b.missing(qk, false, end);
        }
        self.pos = end;
        self.b.wrap(m, "string", true);
    }

    fn regex(&mut self, t: Tok) {
        self.flush_comments_to(t.s);
        let m = self.b.mark();
        let b = self.src.as_bytes();
        // t.e is after closing '/'
        let close = t.e - 1;
        self.b.leaf("/", false, t.s, t.s + 1);
        self.b.leaf("regex_pattern", true, t.s + 1, close);
        self.b.field_last("pattern");
        self.b.leaf("/", false, close, close + 1);
        let mut e = close + 1;
        while e < b.len() && (b[e].is_ascii_alphabetic()) {
            e += 1;
        }
        if e > close + 1 {
            self.b.leaf("regex_flags", true, close + 1, e);
            self.b.field_last("flags");
        }
        self.pos = e;
        self.b.wrap(m, "regex", true);
    }

    pub fn template_string(&mut self) {
        let t = self.peek();
        self.flush_comments_to(t.s);
        let m = self.b.mark();
        let b = self.src.as_bytes();
        self.b.leaf("`", false, t.s, t.s + 1);
        let mut i = t.s + 1;
        let mut frag = i;
        loop {
            if i >= b.len() {
                if frag < i {
                    self.b.leaf("string_fragment", true, frag, i);
                }
                self.pos = i;
                self.b.missing("`", false, i);
                break;
            }
            match b[i] {
                b'`' => {
                    if frag < i {
                        self.b.leaf("string_fragment", true, frag, i);
                    }
                    self.b.leaf("`", false, i, i + 1);
                    self.pos = i + 1;
                    break;
                }
                b'\\' => {
                    if frag < i {
                        self.b.leaf("string_fragment", true, frag, i);
                    }
                    let e = escape_end(self.src, i);
                    self.b.leaf("escape_sequence", true, i, e);
                    i = e;
                    frag = i;
                }
                b'$' if i + 1 < b.len() && b[i + 1] == b'{' => {
                    if frag < i {
                        self.b.leaf("string_fragment", true, frag, i);
                    }
                    let ms = self.b.mark();
                    self.b.leaf("${", false, i, i + 2);
                    self.pos = i + 2;
                    let save = self.no_in;
                    self.no_in = false;
                    self.expressions();
                    self.no_in = save;
                    self.expect("}");
                    self.b.wrap(ms, "template_substitution", true);
                    i = self.pos;
                    frag = i;
                }
                _ => i += 1,
            }
        }
        self.b.wrap(m, "template_string", true);
    }

    // ---------- JSX ----------
    fn jsx_element(&mut self) {
        let m = self.b.mark();
        // opening
        let mo = self.b.mark();
        self.bump(); // <
        if self.at(">") {
            // fragment
            self.bump();
            self.b.wrap(mo, "jsx_opening_element", true);
            self.b.field_last("open_tag");
            self.jsx_children();
            let mc = self.b.mark();
            self.jsx_close_start();
            self.expect(">");
            self.b.wrap(mc, "jsx_closing_element", true);
            self.b.field_last("close_tag");
            self.b.wrap(m, "jsx_element", true);
            return;
        }
        self.jsx_element_name();
        self.b.field_last("name");
        if self.ts && self.at("<") {
            self.type_arguments();
            self.b.field_last("type_arguments");
        }
        loop {
            let t = self.peek();
            let tx = self.tx(t);
            if t.t == T::Eof || tx == ">" || tx == "/" || tx == "/>" || tx == ">>" || tx == ">=" {
                break;
            }
            let before = self.pos;
            self.jsx_attribute();
            self.b.field_last("attribute");
            if self.pos == before {
                break;
            }
        }
        if self.at("/") {
            // self closing "/>"
            let t = self.peek();
            let t2 = self.peek_at(t.e, false);
            self.flush_comments_to(t.s);
            self.pos = t2.e;
            self.b.leaf("/>", false, t.s, t2.e);
            self.b.wrap(mo, "jsx_self_closing_element", true);
            return;
        }
        if self.peek().t == T::Punct && self.tx(self.peek()).starts_with('>') {
            self.bump_partial(1);
        } else {
            self.expect(">");
        }
        self.b.wrap(mo, "jsx_opening_element", true);
        self.b.field_last("open_tag");
        self.jsx_children();
        let mc = self.b.mark();
        self.jsx_close_start();
        if !self.at(">") {
            self.jsx_element_name();
            self.b.field_last("name");
        }
        if self.peek().t == T::Punct && self.tx(self.peek()).starts_with('>') {
            self.bump_partial(1);
        } else {
            self.expect(">");
        }
        self.b.wrap(mc, "jsx_closing_element", true);
        self.b.field_last("close_tag");
        self.b.wrap(m, "jsx_element", true);
    }

    fn jsx_close_start(&mut self) {
        // expects "</"
        let t = self.peek();
        if self.tx(t) == "<" {
            let t2 = self.peek_at(t.e, false);
            if self.tx(t2).starts_with('/') {
                self.flush_comments_to(t.s);
                self.pos = t2.s + 1;
                self.b.leaf("</", false, t.s, t2.s + 1);
                return;
            }
        }
        let p = self.pos;
        self.b.missing("</", false, p);
    }

    fn jsx_children(&mut self) {
        let b = self.src.as_bytes();
        loop {
            let i = self.pos;
            if i >= b.len() {
                return;
            }
            // scan text
            let mut j = i;
            while j < b.len() && !matches!(b[j], b'{' | b'<' | b'}' | b'>' | b'&') {
                j += 1;
            }
            if j > i {
                // emit jsx_text: split into trimmed lines segments per tree-sitter
                self.jsx_text(i, j);
                self.pos = j;
                continue;
            }
            if j >= b.len() {
                return;
            }
            match b[j] {
                b'{' => {
                    self.jsx_expression();
                }
                b'<' => {
                    // closing tag?
                    let mut k = j + 1;
                    while k < b.len() && (b[k] == b' ' || b[k] == b'\n' || b[k] == b'\t' || b[k] == b'\r') {
                        k += 1;
                    }
                    if k < b.len() && b[k] == b'/' {
                        return;
                    }
                    self.jsx_element();
                }
                b'&' => {
                    let mut k = j + 1;
                    while k < b.len() && k - j < 12 && (b[k].is_ascii_alphanumeric() || b[k] == b'#') {
                        k += 1;
                    }
                    if k < b.len() && b[k] == b';' && k > j + 1 {
                        self.b.leaf("html_character_reference", true, j, k + 1);
                        self.pos = k + 1;
                    } else {
                        self.b.leaf("jsx_text", true, j, j + 1);
                        self.pos = j + 1;
                    }
                }
                _ => {
                    // stray } or >
                    let m = self.b.mark();
                    self.b.leaf(intern(&self.src[j..j + 1]), false, j, j + 1);
                    self.pos = j + 1;
                    self.b.wrap(m, "ERROR", true);
                }
            }
        }
    }

    fn jsx_text(&mut self, s: usize, e: usize) {
        // tree-sitter jsx_text: whitespace-only text between tags is not a node;
        // otherwise text excludes leading whitespace that contains a newline.
        let txt = &self.src[s..e];
        if txt.trim().is_empty() {
            return;
        }
        let b = self.src.as_bytes();
        let mut a = s;
        // leading whitespace containing newline is trimmed
        let lead_ws: usize = txt.len() - txt.trim_start().len();
        if txt[..lead_ws].contains('\n') {
            a = s + lead_ws;
        }
        let mut z = e;
        let trail_ws = txt.len() - txt.trim_end().len();
        if txt[txt.len() - trail_ws..].contains('\n') {
            z = e - trail_ws;
        }
        let _ = b;
        self.b.leaf("jsx_text", true, a, z);
    }

    fn jsx_expression(&mut self) {
        let m = self.b.mark();
        self.bump(); // {
        if self.at("...") {
            let ms = self.b.mark();
            self.bump();
            self.assign_expr();
            self.b.wrap(ms, "spread_element", true);
        } else if !self.at("}") {
            self.expressions();
        }
        self.expect("}");
        self.b.wrap(m, "jsx_expression", true);
    }

    fn jsx_identifier_tok(&mut self, kind: &'static str) {
        // identifiers allowing '-'
        let t = self.peek();
        self.flush_comments_to(t.s);
        let b = self.src.as_bytes();
        let mut e = t.e;
        let mut has_dash = false;
        while e < b.len() && (b[e] == b'-' || b[e].is_ascii_alphanumeric() || b[e] == b'_' || b[e] == b'$') {
            if b[e] == b'-' {
                has_dash = true;
            }
            e += 1;
        }
        let _ = has_dash;
        self.pos = e;
        self.b.leaf(kind, true, t.s, e);
    }

    fn jsx_element_name(&mut self) {
        let m = self.b.mark();
        self.jsx_identifier_tok("identifier");
        if self.at(":") {
            self.bump();
            self.jsx_identifier_tok("identifier");
            self.b.wrap(m, "jsx_namespace_name", true);
            return;
        }
        while self.at(".") {
            self.set_first_field(m, "object");
            self.bump();
            self.jsx_identifier_tok("property_identifier");
            self.b.field_last("property");
            self.b.wrap(m, "member_expression", true);
        }
    }

    fn jsx_attribute(&mut self) {
        if self.at("{") {
            self.jsx_expression();
            return;
        }
        let m = self.b.mark();
        let mn = self.b.mark();
        self.jsx_identifier_tok("property_identifier");
        if self.at(":") {
            self.bump();
            self.jsx_identifier_tok("identifier");
            self.b.rename(self.b.stack[mn], "identifier");
            self.b.wrap(mn, "jsx_namespace_name", true);
        }
        if self.at("=") {
            self.bump();
            let t = self.peek();
            if t.t == T::Str {
                self.jsx_string();
            } else if self.at("{") {
                self.jsx_expression();
            } else if self.at("<") {
                self.jsx_element();
            }
        }
        self.b.wrap(m, "jsx_attribute", true);
    }

    fn jsx_string(&mut self) {
        let t = self.peek();
        self.flush_comments_to(t.s);
        let m = self.b.mark();
        let b = self.src.as_bytes();
        let q = b[t.s];
        let qk = if q == b'"' { "\"" } else { "'" };
        self.b.leaf(qk, false, t.s, t.s + 1);
        let mut i = t.s + 1;
        let mut frag = i;
        while i < b.len() && b[i] != q {
            if b[i] == b'&' {
                let mut k = i + 1;
                while k < b.len() && k - i < 12 && (b[k].is_ascii_alphanumeric() || b[k] == b'#') {
                    k += 1;
                }
                if k < b.len() && b[k] == b';' && k > i + 1 {
                    if frag < i {
                        self.b.leaf("string_fragment", true, frag, i);
                    }
                    self.b.leaf("html_character_reference", true, i, k + 1);
                    i = k + 1;
                    frag = i;
                    continue;
                }
            }
            i += 1;
        }
        if frag < i {
            self.b.leaf("string_fragment", true, frag, i);
        }
        if i < b.len() {
            self.b.leaf(qk, false, i, i + 1);
            i += 1;
        }
        self.pos = i;
        self.b.wrap(m, "string", true);
    }
}

trait CloneWith {
    fn clone_with(self, _x: u8) -> Self;
}
impl CloneWith for (u8, bool) {
    fn clone_with(self, _x: u8) -> Self {
        self
    }
}

/// scale precedence: higher number binds tighter. Equality sits between & and relational.
fn scale(p: u8, op: &str) -> u8 {
    let base = p * 10;
    match op {
        "==" | "!=" | "===" | "!==" => 65,
        _ => {
            if p >= 7 {
                base
            } else {
                base
            }
        }
    }
}

pub fn escape_end(src: &str, i: usize) -> usize {
    // i at backslash
    let b = src.as_bytes();
    let n = b.len();
    if i + 1 >= n {
        return n;
    }
    let c = b[i + 1];
    match c {
        b'x' => {
            let mut j = i + 2;
            while j < n && j < i + 4 && b[j].is_ascii_hexdigit() {
                j += 1;
            }
            j
        }
        b'u' => {
            if i + 2 < n && b[i + 2] == b'{' {
                let mut j = i + 3;
                while j < n && b[j] != b'}' {
                    j += 1;
                }
                (j + 1).min(n)
            } else {
                let mut j = i + 2;
                while j < n && j < i + 6 && b[j].is_ascii_hexdigit() {
                    j += 1;
                }
                j
            }
        }
        b'0'..=b'7' => {
            let mut j = i + 1;
            while j < n && j < i + 4 && (b'0'..=b'7').contains(&b[j]) {
                j += 1;
            }
            j
        }
        b'\r' => {
            if i + 2 < n && b[i + 2] == b'\n' {
                i + 3
            } else {
                i + 2
            }
        }
        _ => {
            let ch = src[i + 1..].chars().next().unwrap();
            i + 1 + ch.len_utf8()
        }
    }
}

pub fn intern(s: &str) -> &'static str {
    use std::collections::HashSet;
    use std::sync::Mutex;
    static POOL: Mutex<Option<HashSet<&'static str>>> = Mutex::new(None);
    let mut g = POOL.lock().unwrap();
    let set = g.get_or_insert_with(HashSet::new);
    if let Some(&x) = set.get(s) {
        return x;
    }
    let l: &'static str = Box::leak(s.to_string().into_boxed_str());
    set.insert(l);
    l
}
