            Lang::Tsx => "Tsx",
            Lang::TypeScript => "TypeScript",
            Lang::Yaml => "Yaml",
        }
    }
    pub fn extensions(&self) -> &'static [&'static str] {
        match self {
            Lang::Bash => &["bash", "bats", "cgi", "command", "env", "fcgi", "ksh", "sh", "tmux", "tool", "zsh"],
            Lang::C => &["c", "h"],
            Lang::Cpp => &["cc", "hpp", "cpp", "c++", "hh", "cxx", "cu", "ino"],
            Lang::CSharp => &["cs"],
            Lang::Css => &["css", "scss"],
            Lang::Dart => &["dart"],
            Lang::Elixir => &["ex", "exs"],
