            Lang::Html => &["html", "htm", "xhtml"],
            Lang::Java => &["java"],
            Lang::JavaScript => &["cjs", "js", "mjs", "jsx"],
            Lang::Json => &["json"],
            Lang::Kotlin => &["kt", "ktm", "kts"],
            Lang::Lua => &["lua"],
            Lang::Nix => &["nix"],
            Lang::Php => &["php"],
            Lang::Python => &["py", "py3", "pyi", "bzl"],
            Lang::Ruby => &["rb", "rbw", "gemspec"],
            Lang::Rust => &["rs"],
            Lang::Scala => &["scala", "sc", "sbt"],
            Lang::Solidity => &["sol"],
            Lang::Swift => &["swift"],
            Lang::Tsx => &["tsx"],
            Lang::TypeScript => &["ts", "cts", "mts"],
            Lang::Yaml => &["yaml", "yml"],
        }
    }
    pub fn from_path(p: &std::path::Path) -> Option<Lang> {
        let ext = p.extension()?.to_str()?;
        for l in ALL_LANGS {
            if l.extensions().contains(&ext) {
                return Some(*l);
            }
        }
        None
    }
    /// character used to replace `$` in patterns
    pub fn expando(&self) -> char {
        match self {
            Lang::CSharp | Lang::Elixir | Lang::Go | Lang::Haskell | Lang::Kotlin | Lang::Php | Lang::Python
            | Lang::Ruby | Lang::Rust | Lang::Swift | Lang::Hcl => 'µ',
            Lang::Css | Lang::Nix => '_',
            Lang::Html => 'z',
            _ => '$',
        }
    }
    pub fn parse(&self, src: &str) -> Tree {
        match self {
            Lang::JavaScript => js::parse(src, false, true),
            Lang::TypeScript => js::parse(src, true, false),
            Lang::Tsx => js::parse(src, true, true),
            _ => js::parse(src, false, true),
        }
    }
}
