// Pattern compilation and tree matching (ast-grep semantics)
use crate::lang::Lang;
use crate::tree::Tree;
use std::collections::BTreeMap;

#[derive(Clone, Debug, PartialEq)]
pub enum MetaVar {
    Capture(String, bool),
    Dropped(bool),
    Multiple,
    MultiCapture(String),
}

#[derive(Clone, Debug)]
pub enum PNode {
    MetaVar(MetaVar),
    Terminal { text: String, kind: &'static str, named: bool },
    Internal { kind: &'static str, named: bool, children: Vec<PNode> },
}

impl PNode {
    fn is_named(&self) -> bool {
        match self {
            PNode::MetaVar(_) => true,
            PNode::Terminal { named, .. } => *named,
            PNode::Internal { named, .. } => *named,
        }
    }
    fn ellipsis(&self) -> Option<Option<&str>> {
        match self {
            PNode::MetaVar(MetaVar::Multiple) => Some(None),
            PNode::MetaVar(MetaVar::MultiCapture(n)) => Some(Some(n.as_str())),
            _ => None,
        }
    }
    pub fn dump(&self, out: &mut String, depth: usize) {
        for _ in 0..depth {
            out.push_str("  ");
        }
        match self {
            PNode::MetaVar(m) => {
                out.push_str("MetaVar ");
                match m {
                    MetaVar::Capture(n, _) => {
                        out.push('$');
                        out.push_str(n);
                    }
                    MetaVar::Dropped(_) => out.push_str("$_"),
                    MetaVar::Multiple => out.push_str("$$$"),
                    MetaVar::MultiCapture(n) => {
                        out.push_str("$$$");
                        out.push_str(n);
                    }
                }
                out.push('\n');
            }
            PNode::Terminal { text, kind, named } => {
                if *named {
                    out.push_str(kind);
                    out.push(' ');
                    out.push_str(text);
                } else {
                    out.push_str(kind);
                }
                out.push('\n');
            }
            PNode::Internal { kind, children, .. } => {
                out.push_str(kind);
                out.push('\n');
                for c in children {
                    c.dump(out, depth + 1);
                }
            }
        }
    }
    pub fn root_kind(&self) -> Option<&'static str> {
        match self {
            PNode::Terminal { kind, .. } | PNode::Internal { kind, .. } => Some(kind),
            _ => None,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Strictness {
    Cst,
    Smart,
    Ast,
    Relaxed,
    Signature,
    Template,
}

impl Strictness {
    pub fn from_str(s: &str) -> Option<Strictness> {
        Some(match s {
            "cst" => Strictness::Cst,
            "smart" => Strictness::Smart,
            "ast" => Strictness::Ast,
            "relaxed" => Strictness::Relaxed,
            "signature" => Strictness::Signature,
            "template" => Strictness::Template,
            _ => return None,
        })
    }
}

fn is_valid_first(c: char) -> bool {
    c.is_ascii_uppercase() || c == '_'
}
fn is_valid_char(c: char) -> bool {
    is_valid_first(c) || c.is_ascii_digit()
}

pub fn extract_meta_var(src: &str, mc: char) -> Option<MetaVar> {
    let ell: String = std::iter::repeat(mc).take(3).collect();
    if src == ell {
        return Some(MetaVar::Multiple);
    }
    if let Some(t) = src.strip_prefix(ell.as_str()) {
        if t.is_empty() || !t.chars().all(is_valid_char) || !t.starts_with(is_valid_first) {
            return None;
        }
        if t.starts_with('_') {
            return Some(MetaVar::Multiple);
        }
        return Some(MetaVar::MultiCapture(t.to_string()));
    }
    let t = src.strip_prefix(mc)?;
    let (t, named) = match t.strip_prefix(mc) {
        Some(x) => (x, false),
        None => (t, true),
    };
    if t.is_empty() || !t.starts_with(is_valid_first) || !t.chars().all(is_valid_char) {
        return None;
    }
    if t.starts_with('_') {
        Some(MetaVar::Dropped(named))
    } else {
        Some(MetaVar::Capture(t.to_string(), named))
    }
}

pub fn pre_process(pattern: &str, expando: char) -> String {
    if expando == '$' {
        return pattern.to_string();
    }
    let mut out = String::with_capacity(pattern.len());
    let mut dollars = 0;
    for c in pattern.chars() {
        if c == '$' {
            dollars += 1;
            continue;
        }
        let need = is_valid_first(c) || dollars == 3;
        let sigil = if need { expando } else { '$' };
        for _ in 0..dollars {
            out.push(sigil);
        }
        dollars = 0;
        out.push(c);
    }
    let sigil = if dollars == 3 { expando } else { '$' };
    for _ in 0..dollars {
        out.push(sigil);
    }
    out
}

#[derive(Debug, Clone)]
pub enum PatternError {
    NoContent(String),
    MultipleNode(String),
    NoSelector(String),
}

impl PatternError {
    pub fn message(&self) -> String {
        match self {
            PatternError::NoContent(s) => format!("No AST root is detected. Please check the pattern source `{}`.", s),
            PatternError::MultipleNode(s) => {
                format!("Multiple AST nodes are detected. Please check the pattern source `{}`.", s)
            }
            PatternError::NoSelector(k) => format!("`selector` kind `{}` is not found in the pattern.", k),
        }
    }
}

#[derive(Clone, Debug)]
pub struct Pattern {
    pub root: PNode,
    pub strictness: Strictness,
    pub has_error: bool,
    pub source: String,
}

fn convert(tree: &Tree, id: u32, mc: char) -> PNode {
    let n = tree.n(id);
    let text = tree.text(id);
    if let Some(mv) = extract_meta_var(text, mc) {
        return PNode::MetaVar(mv);
    }
    if n.children.is_empty() {
        return PNode::Terminal { text: text.to_string(), kind: n.kind, named: n.named };
    }
    let children = n
        .children
        .iter()
        .filter(|&&c| !tree.n(c).missing)
        .map(|&c| convert(tree, c, mc))
        .collect();
    PNode::Internal { kind: n.kind, named: n.named, children }
}

impl Pattern {
    pub fn new(src: &str, lang: Lang, strictness: Strictness) -> Result<Pattern, PatternError> {
        let processed = pre_process(src, lang.expando());
        let tree = lang.parse(&processed);
        let root = tree.root;
        let rn = tree.n(root);
        if rn.children.is_empty() {
            return Err(PatternError::NoContent(src.to_string()));
        }
        if rn.children.len() > 1 {
            return Err(PatternError::MultipleNode(src.to_string()));
        }
        let mut node = root;
        while tree.n(node).children.len() == 1 {
            node = tree.n(node).children[0];
        }
        let has_error = tree.has_error(root);
        let pn = convert(&tree, node, lang.expando());
        Ok(Pattern { root: pn, strictness, has_error, source: src.to_string() })
    }
    pub fn with_selector(
        src: &str,
        selector: &str,
        lang: Lang,
        strictness: Strictness,
    ) -> Result<Pattern, PatternError> {
        let processed = pre_process(src, lang.expando());
        let tree = lang.parse(&processed);
        let mut order = Vec::new();
        tree.preorder(tree.root, &mut order);
        for id in order {
            if tree.n(id).kind == selector {
                let has_error = tree.has_error(tree.root);
                let pn = convert(&tree, id, lang.expando());
                return Ok(Pattern { root: pn, strictness, has_error, source: src.to_string() });
            }
        }
        Err(PatternError::NoSelector(selector.to_string()))
    }
    pub fn debug(&self) -> String {
        let mut s = String::new();
        self.root.dump(&mut s, 0);
        s
    }
}

// ---------- environment ----------
#[derive(Clone, Debug, Default)]
pub struct Env {
    pub single: BTreeMap<String, u32>,
    pub multi: BTreeMap<String, Vec<u32>>,
    pub transformed: BTreeMap<String, String>,
    pub order: Vec<String>,
}

impl Env {
    pub fn insert(&mut self, tree: &Tree, name: &str, node: u32) -> bool {
        if let Some(&old) = self.single.get(name) {
            return node_eq(tree, old, node);
        }
        self.single.insert(name.to_string(), node);
        self.order.push(name.to_string());
        true
    }
    pub fn insert_multi(&mut self, tree: &Tree, name: &str, nodes: Vec<u32>) -> bool {
        if let Some(old) = self.multi.get(name) {
            if old.len() != nodes.len() {
                return false;
            }
            return old.iter().zip(nodes.iter()).all(|(&a, &b)| node_eq(tree, a, b));
        }
        self.multi.insert(name.to_string(), nodes);
        self.order.push(name.to_string());
        true
    }
    pub fn get_text(&self, tree: &Tree, name: &str) -> Option<String> {
        if let Some(t) = self.transformed.get(name) {
            return Some(t.clone());
        }
        if let Some(&n) = self.single.get(name) {
            return Some(tree.text(n).to_string());
        }
        if let Some(ns) = self.multi.get(name) {
            if ns.is_empty() {
                return Some(String::new());
            }
            let s = tree.n(ns[0]).start;
            let e = tree.n(*ns.last().unwrap()).end;
            return Some(tree.src[s..e].to_string());
        }
        None
    }
}

fn node_eq(tree: &Tree, a: u32, b: u32) -> bool {
    if a == b {
        return true;
    }
    tree.text(a) == tree.text(b)
}

#[derive(PartialEq, Debug)]
enum One {
    Both,
    SkipGoal,
    SkipCand,
    SkipBoth,
    No,
}

fn skip_comment_or_unnamed(tree: &Tree, c: u32) -> bool {
    let n = tree.n(c);
    if !n.named {
        return true;
    }
    n.extra || n.kind.contains("comment")
}

impl Strictness {
    fn match_terminal(&self, named: bool, text: &str, kind: &'static str, tree: &Tree, c: u32) -> One {
        let n = tree.n(c);
        let kind_eq = n.kind == kind && n.named == named;
        if kind_eq && tree.text(c) == text {
            return One::Both;
        }
        let (sg, sc) = match self {
            Strictness::Cst => (false, false),
            Strictness::Smart => (false, !n.named),
            Strictness::Ast => (!named, !n.named),
            Strictness::Relaxed => (!named, skip_comment_or_unnamed(tree, c)),
            Strictness::Signature => {
                if kind_eq {
                    return One::Both;
                }
                (!named, skip_comment_or_unnamed(tree, c))
            }
            Strictness::Template => {
                if tree.text(c) == text {
                    return One::Both;
                }
                (false, !n.named)
            }
        };
        match (sg, sc) {
            (true, true) => One::SkipBoth,
            (true, false) => One::SkipGoal,
            (false, true) => One::SkipCand,
            (false, false) => One::No,
        }
    }
    fn should_skip_cand(&self, tree: &Tree, c: u32) -> bool {
        let n = tree.n(c);
        match self {
            Strictness::Cst => false,
            Strictness::Smart | Strictness::Ast | Strictness::Template => !n.named,
            Strictness::Relaxed | Strictness::Signature => skip_comment_or_unnamed(tree, c),
        }
    }
    fn should_skip_trailing(&self, tree: &Tree, c: u32) -> bool {
        match self {
            Strictness::Cst => false,
            Strictness::Smart | Strictness::Ast | Strictness::Template => true,
            Strictness::Relaxed | Strictness::Signature => skip_comment_or_unnamed(tree, c),
        }
    }
    fn should_skip_goal(&self, g: &PNode) -> bool {
        match self {
            Strictness::Cst | Strictness::Smart => false,
            _ => !g.is_named(),
        }
    }
}

pub struct Matcher<'t> {
    pub tree: &'t Tree,
    pub strictness: Strictness,
}

impl<'t> Matcher<'t> {
    fn match_one(&self, goal: &PNode, c: u32, env: &mut Env) -> One {
        let tree = self.tree;
        match goal {
            PNode::Terminal { text, kind, named } => self.strictness.match_terminal(*named, text, kind, tree, c),
            PNode::MetaVar(mv) => {
                let n = tree.n(c);
                let ok = match mv {
                    MetaVar::Capture(name, named) => {
                        if *named && !n.named {
                            false
                        } else {
                            env.insert(tree, name, c)
                        }
                    }
                    MetaVar::Dropped(named) => !(*named && !n.named),
                    MetaVar::Multiple => true,
                    MetaVar::MultiCapture(name) => env.insert(tree, name, c),
                };
                if ok {
                    One::Both
                } else if self.strictness.should_skip_cand(tree, c) {
                    One::SkipCand
                } else {
                    One::No
                }
            }
            PNode::Internal { kind, named, children } => {
                let n = tree.n(c);
                let kind_ok = (n.kind == *kind && n.named == *named) || self.strictness == Strictness::Template;
                if !kind_ok {
                    return if self.strictness.should_skip_cand(tree, c) { One::SkipCand } else { One::No };
                }
                let mut env2 = env.clone();
                if self.match_seq(children, &n.children, &mut env2) {
                    *env = env2;
                    One::Both
                } else if self.strictness.should_skip_cand(tree, c) {
                    One::SkipCand
                } else {
                    One::No
                }
            }
        }
    }

    pub fn match_node(&self, goal: &PNode, c: u32, env: &mut Env) -> bool {
        let mut e = env.clone();
        if self.match_one(goal, c, &mut e) == One::Both {
            *env = e;
            true
        } else {
            false
        }
    }

    fn match_seq(&self, goals: &[PNode], cands: &[u32], env: &mut Env) -> bool {
        let tree = self.tree;
        let mut gi = 0usize;
        let mut ci = 0usize;
        if cands.is_empty() {
            // all goals must be skippable / ellipsis
            return goals.iter().all(|g| g.ellipsis().is_some() || self.strictness.should_skip_goal(g)) && {
                for g in goals {
                    if let Some(Some(name)) = g.ellipsis() {
                        if !env.insert_multi(tree, name, vec![]) {
                            return false;
                        }
                    }
                }
                true
            };
        }
        loop {
            // ---- ellipsis ----
            if gi < goals.len() {
                if let Some(name) = goals[gi].ellipsis() {
                    let mut matched: Vec<u32> = Vec::new();
                    gi += 1;
                    if gi >= goals.len() {
                        let rest: Vec<u32> = cands[ci..].to_vec();
                        if let Some(n) = name {
                            if !env.insert_multi(tree, n, rest) {
                                return false;
                            }
                        }
                        return true;
                    }
                    let mut skipped_anon = 0usize;
                    while !goals[gi].is_named() {
                        gi += 1;
                        skipped_anon += 1;
                        if gi >= goals.len() {
                            let mut rest: Vec<u32> = cands[ci..].to_vec();
                            let l = rest.len().saturating_sub(skipped_anon);
                            rest.truncate(l);
                            if let Some(n) = name {
                                if !env.insert_multi(tree, n, rest) {
                                    return false;
                                }
                            }
                            return true;
                        }
                    }
                    if goals[gi].ellipsis().is_some() {
                        matched.push(cands[ci]);
                        ci += 1;
                        if ci >= cands.len() {
                            return false;
                        }
                        if let Some(n) = name {
                            let l = matched.len().saturating_sub(skipped_anon);
                            matched.truncate(l);
                            if !env.insert_multi(tree, n, matched) {
                                return false;
                            }
                        }
                        continue;
                    }
                    loop {
                        let mut e2 = env.clone();
                        if self.match_one(&goals[gi], cands[ci], &mut e2) == One::Both {
                            if let Some(n) = name {
                                let l = matched.len().saturating_sub(skipped_anon);
                                matched.truncate(l);
                                if !env.insert_multi(tree, n, matched) {
                                    return false;
                                }
                            }
                            break;
                        }
                        matched.push(cands[ci]);
                        ci += 1;
                        if ci >= cands.len() {
                            return false;
                        }
                    }
                }
            }
            // ---- single node, skipping trivial ----
            loop {
                if ci >= cands.len() {
                    return false;
                }
                if gi >= goals.len() {
                    return cands[ci..].iter().all(|&c| self.strictness.should_skip_trailing(tree, c));
                }
                let r = self.match_one(&goals[gi], cands[ci], env);
                match r {
                    One::Both => break,
                    One::SkipGoal => {
                        gi += 1;
                        if gi >= goals.len() {
                            return cands[ci..].iter().all(|&c| self.strictness.should_skip_trailing(tree, c));
                        }
                        if goals[gi].ellipsis().is_some() {
                            break;
                        }
                    }
                    One::SkipBoth => {
                        gi += 1;
                        ci += 1;
                        if gi >= goals.len() {
                            return cands[ci..].iter().all(|&c| self.strictness.should_skip_trailing(tree, c));
                        }
                        if ci >= cands.len() {
                            return goals[gi..].iter().all(|g| g.ellipsis().is_some() || self.strictness.should_skip_goal(g));
                        }
                        if goals[gi].ellipsis().is_some() {
                            break;
                        }
                    }
                    One::SkipCand => {
                        ci += 1;
                    }
                    One::No => return false,
                }
            }
            if gi < goals.len() && goals[gi].ellipsis().is_some() {
                continue;
            }
            gi += 1;
            ci += 1;
            if gi >= goals.len() {
                return cands[ci..].iter().all(|&c| self.strictness.should_skip_trailing(tree, c));
            }
            if ci >= cands.len() {
                // remaining goals must be skippable or ellipsis (zero match)
                for g in &goals[gi..] {
                    if let Some(n) = g.ellipsis() {
                        if let Some(n) = n {
                            if !env.insert_multi(tree, n, vec![]) {
                                return false;
                            }
                        }
                        continue;
                    }
                    if !self.strictness.should_skip_goal(g) {
                        return false;
                    }
                }
                return true;
            }
        }
    }
}
