// Rule compilation & matching
use crate::config::*;
use crate::lang::Lang;
use crate::matcher::{Env, Matcher, Pattern, Strictness};
use crate::tree::Tree;
use std::collections::BTreeMap;
use std::sync::Arc;

#[derive(Debug, Clone)]
pub struct ErrChain(pub Vec<String>);

impl ErrChain {
    pub fn new(s: impl Into<String>) -> Self {
        ErrChain(vec![s.into()])
    }
    pub fn wrap(mut self, s: impl Into<String>) -> Self {
        self.0.insert(0, s.into());
        self
    }
}

#[derive(Clone, Debug)]
pub enum NthPos {
    Exact(usize),
    Func(i64, i64), // a*n + b
}

#[derive(Clone, Debug)]
pub struct NthChild {
    pub pos: NthPos,
    pub of_rule: Option<Box<Rule>>,
    pub reverse: bool,
}

#[derive(Clone, Debug)]
pub enum StopBy {
    Neighbor,
    End,
    Rule(Box<Rule>),
}

#[derive(Clone, Debug)]
pub struct Relation {
    pub rule: Rule,
    pub stop_by: StopBy,
    pub field: Option<String>,
}

#[derive(Clone, Debug)]
pub enum Rule {
    Pattern(Arc<Pattern>),
    Kind(String),
    Regex(regex::Regex),
    NthChild(Box<NthChild>),
    Range((usize, Option<usize>, usize, Option<usize>)),
    Inside(Box<Relation>),
    Has(Box<Relation>),
    Precedes(Box<Relation>),
    Follows(Box<Relation>),
    All(Vec<Rule>),
    Any(Vec<Rule>),
    Not(Box<Rule>),
    Matches(String),
}

pub struct CompileEnv<'a> {
    pub lang: Lang,
    pub util_names: &'a dyn Fn(&str) -> bool,
}

fn parse_nth(s: &NthChildSimple) -> Result<NthPos, ErrChain> {
    match s {
        NthChildSimple::Numeric(n) => Ok(NthPos::Exact(*n)),
        NthChildSimple::Functional(f) => {
            let t: String = f.chars().filter(|c| !c.is_whitespace()).collect();
            let t = t.to_ascii_lowercase();
            if let Ok(n) = t.parse::<usize>() {
                return Ok(NthPos::Exact(n));
            }
            if t == "odd" {
                return Ok(NthPos::Func(2, 1));
            }
            if t == "even" {
                return Ok(NthPos::Func(2, 0));
            }
            if let Some(idx) = t.find('n') {
                let a_s = &t[..idx];
                let b_s = &t[idx + 1..];
                let a = match a_s {
                    "" | "+" => 1,
                    "-" => -1,
                    x => x.parse::<i64>().map_err(|_| ErrChain::new(format!("Invalid nthChild syntax: {}", f)))?,
                };
                let b = if b_s.is_empty() {
                    0
                } else {
                    b_s.parse::<i64>().map_err(|_| ErrChain::new(format!("Invalid nthChild syntax: {}", f)))?
                };
                return Ok(NthPos::Func(a, b));
            }
            Err(ErrChain::new(format!("Invalid nthChild syntax: {}", f)))
        }
    }
}

pub fn compile_pattern(p: &PatternStyle, lang: Lang) -> Result<Pattern, ErrChain> {
    let r = match p {
        PatternStyle::Str(s) => Pattern::new(s, lang, Strictness::Smart),
        PatternStyle::Contextual { context, selector, strictness } => {
            let st = strictness.map(conv_strictness).unwrap_or(Strictness::Smart);
            match selector {
                Some(sel) => Pattern::with_selector(context, sel, lang, st),
                None => Pattern::new(context, lang, st),
            }
        }
    };
    r.map_err(|e| ErrChain::new(e.message()))
}

pub fn conv_strictness(s: StrictnessSer) -> Strictness {
    match s {
        StrictnessSer::Cst => Strictness::Cst,
        StrictnessSer::Smart => Strictness::Smart,
        StrictnessSer::Ast => Strictness::Ast,
        StrictnessSer::Relaxed => Strictness::Relaxed,
        StrictnessSer::Signature => Strictness::Signature,
        StrictnessSer::Template => Strictness::Template,
    }
}

pub fn compile_rule(r: &SerRule, env: &CompileEnv) -> Result<Rule, ErrChain> {
    let mut rules = Vec::new();
    if let Some(p) = r.pattern.as_ref() {
        let pat = compile_pattern(p, env.lang).map_err(|e| e.wrap("Rule contains invalid pattern matcher."))?;
        rules.push(Rule::Pattern(Arc::new(pat)));
    }
    if let Some(k) = r.kind.as_ref() {
        if !crate::lang::kinds::is_valid_kind(env.lang, k) {
            return Err(ErrChain(vec![
                "Rule contains invalid kind matcher.".into(),
                "Invalid Kind".into(),
                format!("Kind `{}` is invalid.", k),
            ]));
        }
        rules.push(Rule::Kind(k.clone()));
    }
    if let Some(re) = r.regex.as_ref() {
        match regex::Regex::new(re) {
            Ok(x) => rules.push(Rule::Regex(x)),
            Err(e) => {
                return Err(ErrChain(vec!["Rule contains invalid regex matcher.".into(), e.to_string()]));
            }
        }
    }
    if let Some(n) = r.nth_child.as_ref() {
        let nth = match n {
            SerNthChild::Simple(s) => NthChild { pos: parse_nth(s)?, of_rule: None, reverse: false },
            SerNthChild::Complex { position, of_rule, reverse } => NthChild {
                pos: parse_nth(position)?,
                of_rule: match of_rule {
                    Some(r) => Some(Box::new(compile_rule(r, env)?)),
                    None => None,
                },
                reverse: *reverse,
            },
        };
        rules.push(Rule::NthChild(Box::new(nth)));
    }
    if let Some(rg) = r.range.as_ref() {
        rules.push(Rule::Range((rg.start.line, rg.start.column, rg.end.line, rg.end.column)));
    }
    // composite
    if let Some(all) = r.all.as_ref() {
        let mut v = Vec::new();
        for x in all {
            v.push(compile_rule(x, env)?);
        }
        rules.push(Rule::All(v));
    }
    if let Some(any) = r.any.as_ref() {
        let mut v = Vec::new();
        for x in any {
            v.push(compile_rule(x, env)?);
        }
        rules.push(Rule::Any(v));
    }
    if let Some(not) = r.not.as_ref() {
        rules.push(Rule::Not(Box::new(compile_rule(not, env)?)));
    }
    if let Some(m) = r.matches.as_ref() {
        if !(env.util_names)(m) {
            return Err(ErrChain(vec![
                "Rule contains invalid matches reference.".into(),
                format!("Rule `{}` is not defined.", m),
            ]));
        }
        rules.push(Rule::Matches(m.clone()));
    }
    // relational
    let rel = |x: &SerRelation| -> Result<Box<Relation>, ErrChain> {
        let rule = compile_rule(&x.rule, env)?;
        let stop_by = match &x.stop_by {
            SerStopBy::Neighbor => StopBy::Neighbor,
            SerStopBy::End => StopBy::End,
            SerStopBy::Rule(r) => StopBy::Rule(Box::new(compile_rule(r, env)?)),
        };
        Ok(Box::new(Relation { rule, stop_by, field: x.field.clone() }))
    };
    if let Some(x) = r.inside.as_ref() {
        rules.push(Rule::Inside(rel(x)?));
    }
    if let Some(x) = r.has.as_ref() {
        rules.push(Rule::Has(rel(x)?));
    }
    if let Some(x) = r.precedes.as_ref() {
        rules.push(Rule::Precedes(rel(x)?));
    }
    if let Some(x) = r.follows.as_ref() {
        rules.push(Rule::Follows(rel(x)?));
    }
    if rules.is_empty() {
        return Err(ErrChain::new("Rule must have one positive matcher."));
    }
    if rules.len() == 1 {
        Ok(rules.pop().unwrap())
    } else {
        Ok(Rule::All(rules))
    }
}

/// Registry of utility rules available while matching
#[derive(Default, Clone)]
pub struct Utils {
    pub local: BTreeMap<String, Rule>,
    pub global: Arc<BTreeMap<String, Rule>>,
}

pub struct Ctx<'t> {
    pub tree: &'t Tree,
    pub utils: &'t Utils,
    pub depth: std::cell::Cell<usize>,
}

impl<'t> Ctx<'t> {
    pub fn new(tree: &'t Tree, utils: &'t Utils) -> Self {
        Ctx { tree, utils, depth: std::cell::Cell::new(0) }
    }
}

impl Rule {
    pub fn potential_kinds(&self) -> Option<Vec<&'static str>> {
        None
    }

    pub fn match_node(&self, ctx: &Ctx, node: u32, env: &mut Env) -> bool {
        let tree = ctx.tree;
        match self {
            Rule::Pattern(p) => {
                let m = Matcher { tree, strictness: p.strictness };
                m.match_node(&p.root, node, env)
            }
            Rule::Kind(k) => {
                let n = tree.n(node);
                n.named && n.kind == k.as_str()
            }
            Rule::Regex(re) => re.is_match(tree.text(node)),
            Rule::NthChild(nth) => self.match_nth(nth, ctx, node, env),
            Rule::Range((sl, sc, el, ec)) => {
                let n = tree.n(node);
                let (nsl, nsc) = char_point(tree, n.start);
                let (nel, nec) = char_point(tree, n.end);
                nsl == *sl && sc.map_or(true, |c| c == nsc) && nel == *el && ec.map_or(true, |c| c == nec)
            }
            Rule::All(rs) => {
                let mut e = env.clone();
                for r in rs {
                    if !r.match_node(ctx, node, &mut e) {
                        return false;
                    }
                }
                *env = e;
                true
            }
            Rule::Any(rs) => {
                for r in rs {
                    let mut e = env.clone();
                    if r.match_node(ctx, node, &mut e) {
                        *env = e;
                        return true;
                    }
                }
                false
            }
            Rule::Not(r) => {
                let mut e = env.clone();
                !r.match_node(ctx, node, &mut e)
            }
            Rule::Matches(name) => {
                let d = ctx.depth.get();
                if d > 200 {
                    return false;
                }
                ctx.depth.set(d + 1);
                let r = if let Some(r) = ctx.utils.local.get(name) {
                    r.match_node(ctx, node, env)
                } else if let Some(r) = ctx.utils.global.get(name) {
                    r.match_node(ctx, node, env)
                } else {
                    false
                };
                ctx.depth.set(d);
                r
            }
            Rule::Inside(rel) => {
                let t = tree;
                let field_ok = |child: u32| -> bool {
                    match &rel.field {
                        Some(f) => t.n(child).field == Some(f.as_str()),
                        None => true,
                    }
                };
                match &rel.stop_by {
                    StopBy::Neighbor => {
                        let Some(p) = t.n(node).parent else { return false };
                        if !field_ok(node) {
                            return false;
                        }
                        try_match(&rel.rule, ctx, p, env)
                    }
                    StopBy::End => {
                        let mut child = node;
                        while let Some(p) = t.n(child).parent {
                            if field_ok(child) && try_match(&rel.rule, ctx, p, env) {
                                return true;
                            }
                            child = p;
                        }
                        false
                    }
                    StopBy::Rule(stop) => {
                        let mut child = node;
                        while let Some(p) = t.n(child).parent {
                            if field_ok(child) && try_match(&rel.rule, ctx, p, env) {
                                return true;
                            }
                            let mut e2 = env.clone();
                            if stop.match_node(ctx, p, &mut e2) {
                                return false;
                            }
                            child = p;
                        }
                        false
                    }
                }
            }
            Rule::Has(rel) => {
                let t = tree;
                let field_ok = |child: u32| -> bool {
                    match &rel.field {
                        Some(f) => t.n(child).field == Some(f.as_str()),
                        None => true,
                    }
                };
                match &rel.stop_by {
                    StopBy::Neighbor => {
                        for &c in &t.n(node).children {
                            if field_ok(c) && try_match(&rel.rule, ctx, c, env) {
                                return true;
                            }
                        }
                        false
                    }
                    StopBy::End => {
                        // field applies to the direct children
                        for &c in &t.n(node).children {
                            if !field_ok(c) {
                                continue;
                            }
                            let mut order = Vec::new();
                            t.preorder(c, &mut order);
                            for d in order {
                                if try_match(&rel.rule, ctx, d, env) {
                                    return true;
                                }
                            }
                        }
                        false
                    }
                    StopBy::Rule(stop) => {
                        fn rec(rel: &Relation, stop: &Rule, ctx: &Ctx, n: u32, env: &mut Env) -> bool {
                            if try_match(&rel.rule, ctx, n, env) {
                                return true;
                            }
                            let mut e2 = env.clone();
                            if stop.match_node(ctx, n, &mut e2) {
                                return false;
                            }
                            for &c in &ctx.tree.n(n).children {
                                if rec(rel, stop, ctx, c, env) {
                                    return true;
                                }
                            }
                            false
                        }
                        for &c in &t.n(node).children {
                            if field_ok(c) && rec(rel, stop, ctx, c, env) {
                                return true;
                            }
                        }
                        false
                    }
                }
            }
            Rule::Precedes(rel) | Rule::Follows(rel) => {
                let t = tree;
                let forward = matches!(self, Rule::Precedes(_));
                let step = |x: u32| if forward { t.next_sibling(x) } else { t.prev_sibling(x) };
                match &rel.stop_by {
                    StopBy::Neighbor => match step(node) {
                        Some(s) => try_match(&rel.rule, ctx, s, env),
                        None => false,
                    },
                    StopBy::End => {
                        let mut cur = step(node);
                        while let Some(s) = cur {
                            if try_match(&rel.rule, ctx, s, env) {
                                return true;
                            }
                            cur = step(s);
                        }
                        false
                    }
                    StopBy::Rule(stop) => {
                        let mut cur = step(node);
                        while let Some(s) = cur {
                            if try_match(&rel.rule, ctx, s, env) {
                                return true;
                            }
                            let mut e2 = env.clone();
                            if stop.match_node(ctx, s, &mut e2) {
                                return false;
                            }
                            cur = step(s);
                        }
                        false
                    }
                }
            }
        }
    }

    fn match_nth(&self, nth: &NthChild, ctx: &Ctx, node: u32, env: &mut Env) -> bool {
        let t = ctx.tree;
        let Some(p) = t.n(node).parent else { return false };
        let mut siblings: Vec<u32> = t.n(p).children.iter().copied().filter(|&c| t.n(c).named).collect();
        if let Some(r) = &nth.of_rule {
            siblings = siblings
                .into_iter()
                .filter(|&c| {
                    let mut e = env.clone();
                    r.match_node(ctx, c, &mut e)
                })
                .collect();
        }
        if nth.reverse {
            siblings.reverse();
        }
        let Some(idx) = siblings.iter().position(|&c| c == node) else { return false };
        let pos = idx as i64 + 1;
        match nth.pos {
            NthPos::Exact(n) => pos == n as i64,
            NthPos::Func(a, b) => {
                if a == 0 {
                    pos == b
                } else {
                    let d = pos - b;
                    d % a == 0 && d / a >= 0
                }
            }
        }
    }
}

fn try_match(r: &Rule, ctx: &Ctx, node: u32, env: &mut Env) -> bool {
    let mut e = env.clone();
    if r.match_node(ctx, node, &mut e) {
        *env = e;
        true
    } else {
        false
    }
}

