// Fix templates, transformations and indentation handling
use crate::config::*;
use crate::matcher::Env;
use crate::tree::Tree;

#[derive(Clone, Debug)]
pub enum TVar {
    Single(String),
    Multi(String),
}

#[derive(Clone, Debug)]
pub struct Template {
    pub frags: Vec<String>,
    pub vars: Vec<(TVar, usize)>, // var + indent
}

fn is_var_char(c: char) -> bool {
    c.is_ascii_uppercase() || c == '_' || c.is_ascii_digit()
}

pub fn indent_at(src: &str) -> usize {
    // number of spaces immediately before offset on the same line, resetting on other chars
    let bytes = src.as_bytes();
    let look = bytes.len().saturating_sub(512);
    let mut indent = 0;
    for &c in bytes[look..].iter().rev() {
        if c == b'\n' {
            return indent;
        }
        if c == b' ' {
            indent += 1;
        } else {
            indent = 0;
        }
    }
    if look == 0 && indent != 0 {
        indent
    } else {
        0
    }
}

impl Template {
    pub fn parse(t: &str) -> Template {
        let mut frags = Vec::new();
        let mut vars = Vec::new();
        let mut cur = String::new();
        let chars: Vec<(usize, char)> = t.char_indices().collect();
        let mut i = 0;
        while i < chars.len() {
            let (off, c) = chars[i];
            if c == '$' {
                // count dollars
                let mut j = i;
                while j < chars.len() && chars[j].1 == '$' {
                    j += 1;
                }
                let nd = j - i;
                let mut k = j;
                while k < chars.len() && is_var_char(chars[k].1) {
                    k += 1;
                }
                let name: String = chars[j..k].iter().map(|x| x.1).collect();
                let valid = !name.is_empty() && (name.starts_with(|c: char| c.is_ascii_uppercase() || c == '_'));
                if valid && (nd == 1 || nd == 3 || nd == 2) {
                    let indent = indent_at(&t[..off]);
                    frags.push(std::mem::take(&mut cur));
                    let v = if nd == 3 { TVar::Multi(name) } else { TVar::Single(name) };
                    vars.push((v, indent));
                    i = k;
                    continue;
                }
                for x in &chars[i..j] {
                    cur.push(x.1);
                }
                i = j;
                continue;
            }
            cur.push(c);
            i += 1;
        }
        frags.push(cur);
        Template { frags, vars }
    }

    pub fn generate(&self, tree: &Tree, env: &Env) -> String {
        let mut out = String::new();
        out.push_str(&self.frags[0]);
        for (idx, (v, indent)) in self.vars.iter().enumerate() {
            let name = match v {
                TVar::Single(n) | TVar::Multi(n) => n,
            };
            if let Some(t) = env.transformed.get(name) {
                out.push_str(&indent_text(t, 0, *indent));
            } else if let Some(&n) = env.single.get(name) {
                let node = tree.n(n);
                let text = tree.text(n);
                let orig = indent_at(&tree.src[..node.start]);
                out.push_str(&indent_text(text, orig, *indent));
            } else if let Some(ns) = env.multi.get(name) {
                if !ns.is_empty() {
                    let s = tree.n(ns[0]).start;
                    let e = tree.n(*ns.last().unwrap()).end;
                    let text = &tree.src[s..e];
                    let orig = indent_at(&tree.src[..s]);
                    out.push_str(&indent_text(text, orig, *indent));
                }
            }
            out.push_str(&self.frags[idx + 1]);
        }
        out
    }
}

/// re-indent multi-line text from `orig` indentation to `new` indentation
pub fn indent_text(text: &str, orig: usize, new: usize) -> String {
    if !text.contains('\n') {
        return text.to_string();
    }
    use std::cmp::Ordering;
    match orig.cmp(&new) {
        Ordering::Equal => text.to_string(),
        Ordering::Greater => {
            let pre = " ".repeat(orig - new);
            text.split('\n').map(|l| l.strip_prefix(pre.as_str()).unwrap_or(l)).collect::<Vec<_>>().join("\n")
        }
        Ordering::Less => {
            let pre = " ".repeat(new - orig);
            let mut out = String::new();
            for (i, l) in text.split('\n').enumerate() {
                if i > 0 {
                    out.push('\n');
                    out.push_str(&pre);
                }
                out.push_str(l);
            }
            out
        }
    }
}

// ------------- transformations ---------------
#[derive(Clone, Debug)]
pub enum Transform {
    Substring { source: String, start: Option<i32>, end: Option<i32> },
    Replace { source: String, re: regex::Regex, by: String },
    Convert { source: String, case: StringCase, seps: Option<Vec<Separator>> },
    Rewrite { source: String, rewriters: Vec<String>, join_by: Option<String> },
}

impl Transform {
    pub fn source(&self) -> &str {
        match self {
            Transform::Substring { source, .. }
            | Transform::Replace { source, .. }
            | Transform::Convert { source, .. }
            | Transform::Rewrite { source, .. } => source,
        }
    }
}

fn strip_var(s: &str) -> Result<String, String> {
    let t = s.trim();
    let t = t.trim_start_matches('$');
    Ok(t.to_string())
}

pub fn compile_transform(t: &Transformation) -> Result<Transform, String> {
    match t {
        Transformation::Object(o) => match o {
            Trans::Substring(s) => Ok(Transform::Substring { source: strip_var(&s.source)?, start: s.start_char, end: s.end_char }),
            Trans::Replace(r) => {
                let re = regex::Regex::new(&r.replace).map_err(|e| e.to_string())?;
                Ok(Transform::Replace { source: strip_var(&r.source)?, re, by: r.by.clone() })
            }
            Trans::Convert(c) => Ok(Transform::Convert { source: strip_var(&c.source)?, case: c.to_case, seps: c.separated_by.clone() }),
            Trans::Rewrite(r) => Ok(Transform::Rewrite { source: strip_var(&r.source)?, rewriters: r.rewriters.clone(), join_by: r.join_by.clone() }),
        },
        Transformation::Simple(s) => parse_string_transform(s),
    }
}

#[derive(Debug, Clone)]
enum SVal {
    Str(String),
    List(Vec<String>),
}

fn parse_string_transform(s: &str) -> Result<Transform, String> {
    let s = s.trim();
    let open = s.find('(').ok_or_else(|| format!("Invalid transform syntax: {}", s))?;
    let name = s[..open].trim();
    if !s.ends_with(')') {
        return Err(format!("Invalid transform syntax: {}", s));
    }
    let inner = &s[open + 1..s.len() - 1];
    // split args respecting quotes and brackets
    let mut args: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut quote: Option<char> = None;
    let mut depth = 0;
    for c in inner.chars() {
        if let Some(q) = quote {
            cur.push(c);
            if c == q {
                quote = None;
            }
            continue;
        }
        match c {
            '\'' | '"' => {
                quote = Some(c);
                cur.push(c);
            }
            '[' => {
                depth += 1;
                cur.push(c);
            }
            ']' => {
                depth -= 1;
                cur.push(c);
            }
            ',' if depth == 0 => {
                args.push(std::mem::take(&mut cur));
            }
            _ => cur.push(c),
        }
    }
    if !cur.trim().is_empty() {
        args.push(cur);
    }
    if args.is_empty() {
        return Err(format!("Invalid transform syntax: {}", s));
    }
    let source = strip_var(&args[0])?;
    let mut kv: std::collections::HashMap<String, SVal> = std::collections::HashMap::new();
    fn unq(v: &str) -> String {
        let v = v.trim();
        if v.len() >= 2 && ((v.starts_with('\'') && v.ends_with('\'')) || (v.starts_with('"') && v.ends_with('"'))) {
            v[1..v.len() - 1].to_string()
        } else {
            v.to_string()
        }
    }
    for a in &args[1..] {
        let Some(eq) = a.find('=') else { return Err(format!("Invalid transform syntax: {}", s)) };
        let k = a[..eq].trim().to_string();
        let v = a[eq + 1..].trim();
        if v.starts_with('[') && v.ends_with(']') {
            let items = v[1..v.len() - 1].split(',').map(unq).filter(|x| !x.is_empty()).collect();
            kv.insert(k, SVal::List(items));
        } else {
            kv.insert(k, SVal::Str(unq(v)));
        }
    }
    let gets = |k: &str| -> Option<String> {
        match kv.get(k) {
            Some(SVal::Str(s)) => Some(s.clone()),
            _ => None,
        }
    };
    match name {
        "substring" => Ok(Transform::Substring {
            source,
            start: gets("startChar").and_then(|x| x.parse().ok()),
            end: gets("endChar").and_then(|x| x.parse().ok()),
        }),
        "replace" => {
            let re = regex::Regex::new(&gets("replace").unwrap_or_default()).map_err(|e| e.to_string())?;
            Ok(Transform::Replace { source, re, by: gets("by").unwrap_or_default() })
        }
        "convert" => {
            let case = match gets("toCase").as_deref() {
                Some("lowerCase") => StringCase::LowerCase,
                Some("upperCase") => StringCase::UpperCase,
                Some("capitalize") => StringCase::Capitalize,
                Some("camelCase") => StringCase::CamelCase,
                Some("snakeCase") => StringCase::SnakeCase,
                Some("kebabCase") => StringCase::KebabCase,
                Some("pascalCase") => StringCase::PascalCase,
                _ => return Err(format!("Invalid transform syntax: {}", s)),
            };
            let seps = match kv.get("separatedBy") {
                Some(SVal::List(l)) => Some(
                    l.iter()
                        .filter_map(|x| match x.as_str() {
                            "caseChange" => Some(Separator::CaseChange),
                            "dash" => Some(Separator::Dash),
                            "dot" => Some(Separator::Dot),
                            "slash" => Some(Separator::Slash),
                            "space" => Some(Separator::Space),
                            "underscore" => Some(Separator::Underscore),
                            _ => None,
                        })
                        .collect(),
                ),
                _ => None,
            };
            Ok(Transform::Convert { source, case, seps })
        }
        "rewrite" => {
            let rewriters = match kv.get("rewriters") {
                Some(SVal::List(l)) => l.clone(),
                Some(SVal::Str(s)) => vec![s.clone()],
                None => vec![],
            };
            Ok(Transform::Rewrite { source, rewriters, join_by: gets("joinBy") })
        }
        _ => Err(format!("Invalid transform syntax: {}", s)),
    }
}

pub fn substring(text: &str, start: Option<i32>, end: Option<i32>) -> String {
    let chars: Vec<char> = text.chars().collect();
    let len = chars.len() as i32;
    let norm = |x: i32| -> i32 {
        if x < 0 {
            (len + x).max(0)
        } else {
            x.min(len)
        }
    };
    let s = norm(start.unwrap_or(0));
    let e = norm(end.unwrap_or(len));
    if s >= e {
        return String::new();
    }
    chars[s as usize..e as usize].iter().collect()
}

fn split_words(s: &str, seps: &Option<Vec<Separator>>) -> Vec<String> {
    let all = vec![
        Separator::CaseChange,
        Separator::Dash,
        Separator::Dot,
        Separator::Slash,
        Separator::Space,
        Separator::Underscore,
    ];
    let seps = seps.clone().unwrap_or(all);
    let is_sep = |c: char| -> bool {
        (c == '-' && seps.contains(&Separator::Dash))
            || (c == '.' && seps.contains(&Separator::Dot))
            || (c == '/' && seps.contains(&Separator::Slash))
            || (c == ' ' && seps.contains(&Separator::Space))
            || (c == '_' && seps.contains(&Separator::Underscore))
    };
    let case_change = seps.contains(&Separator::CaseChange);
    let mut words = Vec::new();
    let mut cur = String::new();
    let chars: Vec<char> = s.chars().collect();
    for (i, &c) in chars.iter().enumerate() {
        if is_sep(c) {
            if !cur.is_empty() {
                words.push(std::mem::take(&mut cur));
            }
            continue;
        }
        if case_change && !cur.is_empty() {
            let prev = chars[i - 1];
            let next = chars.get(i + 1).copied();
            // lower->Upper boundary, or Upper followed by lower after Upper run (e.g. HTTPServer)
            if (prev.is_lowercase() || prev.is_ascii_digit()) && c.is_uppercase() {
                words.push(std::mem::take(&mut cur));
            } else if prev.is_uppercase() && c.is_uppercase() && next.map_or(false, |n| n.is_lowercase()) {
                words.push(std::mem::take(&mut cur));
            }
        }
        cur.push(c);
    }
    if !cur.is_empty() {
        words.push(cur);
    }
    words
}

fn capitalize(w: &str) -> String {
    let mut c = w.chars();
    match c.next() {
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
        None => String::new(),
    }
}

pub fn convert_case(text: &str, case: StringCase, seps: &Option<Vec<Separator>>) -> String {
    match case {
        StringCase::LowerCase => text.to_lowercase(),
        StringCase::UpperCase => text.to_uppercase(),
        StringCase::Capitalize => capitalize(text),
        StringCase::CamelCase => {
            let ws = split_words(text, seps);
            let mut out = String::new();
            for (i, w) in ws.iter().enumerate() {
                let lw = w.to_lowercase();
                if i == 0 {
                    out.push_str(&lw);
                } else {
                    out.push_str(&capitalize(&lw));
                }
            }
            out
        }
        StringCase::PascalCase => split_words(text, seps).iter().map(|w| capitalize(&w.to_lowercase())).collect(),
        StringCase::SnakeCase => split_words(text, seps).iter().map(|w| w.to_lowercase()).collect::<Vec<_>>().join("_"),
        StringCase::KebabCase => split_words(text, seps).iter().map(|w| w.to_lowercase()).collect::<Vec<_>>().join("-"),
    }
}

/// Replace with regex, supporting $1 / ${name} references like Rust regex
pub fn regex_replace(text: &str, re: &regex::Regex, by: &str) -> String {
    re.replace_all(text, by).into_owned()
}
