// Fix templates, transformations and indentation handling
use crate::config::*;
use crate::matcher::Env;
use crate::tree::Tree;

#[derive(Clone, Debug)]
pub enum TVar {
    Single(String),
    Multi(String),
}

#[derive(Clone, Debug)]
pub struct Template {
    pub frags: Vec<String>,
    pub vars: Vec<(TVar, usize)>, // var + indent
}

fn is_var_char(c: char) -> bool {
    c.is_ascii_uppercase() || c == '_' || c.is_ascii_digit()
}

pub fn indent_at(src: &str) -> usize {
    // number of spaces immediately before offset on the same line, resetting on other chars
    let bytes = src.as_bytes();
    let look = bytes.len().saturating_sub(512);
    let mut indent = 0;
    for &c in bytes[look..].iter().rev() {
        if c == b'\n' {
            return indent;
        }
        if c == b' ' {
            indent += 1;
        } else {
            indent = 0;
        }
    }
    if look == 0 && indent != 0 {
        indent
    } else {
        0
    }
}

impl Template {
    pub fn parse(t: &str) -> Template {
        let mut frags = Vec::new();
        let mut vars = Vec::new();
        let mut cur = String::new();
        let chars: Vec<(usize, char)> = t.char_indices().collect();
        let mut i = 0;
        while i < chars.len() {
            let (off, c) = chars[i];
            if c == '$' {
                // count dollars
                let mut j = i;
                while j < chars.len() && chars[j].1 == '$' {
                    j += 1;
                }
                let nd = j - i;
                let mut k = j;
                while k < chars.len() && is_var_char(chars[k].1) {
                    k += 1;
                }
                let name: String = chars[j..k].iter().map(|x| x.1).collect();
                let valid = !name.is_empty() && (name.starts_with(|c: char| c.is_ascii_uppercase() || c == '_'));
                if valid && (nd == 1 || nd == 3 || nd == 2) {
                    let indent = indent_at(&t[..off]);
                    frags.push(std::mem::take(&mut cur));
                    let v = if nd == 3 { TVar::Multi(name) } else { TVar::Single(name) };
                    vars.push((v, indent));
                    i = k;
                    continue;
                }
                for x in &chars[i..j] {
                    cur.push(x.1);
                }
                i = j;
                continue;
            }
            cur.push(c);
            i += 1;
        }
        frags.push(cur);
        Template { frags, vars }
    }

    pub fn generate(&self, tree: &Tree, env: &Env) -> String {
        let mut out = String::new();
        out.push_str(&self.frags[0]);
        for (idx, (v, indent)) in self.vars.iter().enumerate() {
            let name = match v {
                TVar::Single(n) | TVar::Multi(n) => n,
            };
            if let Some(t) = env.transformed.get(name) {
                out.push_str(&indent_text(t, 0, *indent));
            } else if let Some(&n) = env.single.get(name) {
                let node = tree.n(n);
                let text = tree.text(n);
                let orig = indent_at(&tree.src[..node.start]);
                out.push_str(&indent_text(text, orig, *indent));
            } else if let Some(ns) = env.multi.get(name) {
                if !ns.is_empty() {
                    let s = tree.n(ns[0]).start;
                    let e = tree.n(*ns.last().unwrap()).end;
                    let text = &tree.src[s..e];
                    let orig = indent_at(&tree.src[..s]);
                    out.push_str(&indent_text(text, orig, *indent));
                }
            }
            out.push_str(&self.frags[idx + 1]);
        }
        out
    }
}

/// re-indent multi-line text from `orig` indentation to `new` indentation
pub fn indent_text(text: &str, orig: usize, new: usize) -> String {
    if !text.contains('\n') {
        return text.to_string();
    }
    use std::cmp::Ordering;
    match orig.cmp(&new) {
        Ordering::Equal => text.to_string(),
        Ordering::Greater => {
            let pre = " ".repeat(orig - new);
            text.split('\n').map(|l| l.strip_prefix(pre.as_str()).unwrap_or(l)).collect::<Vec<_>>().join("\n")
        }
        Ordering::Less => {
            let pre = " ".repeat(new - orig);
            let mut out = String::new();
            for (i, l) in text.split('\n').enumerate() {
                if i > 0 {
                    out.push('\n');
                    out.push_str(&pre);
                }
                out.push_str(l);
            }
            out
        }
    }
}

// ------------- transformations ---------------
#[derive(Clone, Debug)]
pub enum Transform {
    Substring { source: String, start: Option<i32>, end: Option<i32> },
    Replace { source: String, re: regex::Regex, by: String },
    Convert { source: String, case: StringCase, seps: Option<Vec<Separator>> },
    Rewrite { source: String, rewriters: Vec<String>, join_by: Option<String> },
}

impl Transform {
    pub fn source(&self) -> &str {
        match self {
            Transform::Substring { source, .. }
            | Transform::Replace { source, .. }
            | Transform::Convert { source, .. }
            | Transform::Rewrite { source, .. } => source,
        }
    }
}

fn strip_var(s: &str) -> Result<String, String> {
    let t = s.trim();
    let t = t.trim_start_matches('$');
    Ok(t.to_string())
}

pub fn compile_transform(t: &Transformation) -> Result<Transform, String> {
    match t {
        Transformation::Object(o) => match o {
