            Trans::Rewrite(r) => Ok(Transform::Rewrite { source: strip_var(&r.source)?, rewriters: r.rewriters.clone(), join_by: r.join_by.clone() }),
        },
        Transformation::Simple(s) => parse_string_transform(s),
    }
}

#[derive(Debug, Clone)]
enum SVal {
    Str(String),
    List(Vec<String>),
}

fn parse_string_transform(s: &str) -> Result<Transform, String> {
    let s = s.trim();
    let open = s.find('(').ok_or_else(|| format!("Invalid transform syntax: {}", s))?;
    let name = s[..open].trim();
    if !s.ends_with(')') {
        return Err(format!("Invalid transform syntax: {}", s));
    }
    let inner = &s[open + 1..s.len() - 1];
    // split args respecting quotes and brackets
    let mut args: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut quote: Option<char> = None;
    let mut depth = 0;
    for c in inner.chars() {
        if let Some(q) = quote {
            cur.push(c);
            if c == q {
                quote = None;
            }
            continue;
        }
        match c {
            '\'' | '"' => {
                quote = Some(c);
                cur.push(c);
            }
            '[' => {
                depth += 1;
                cur.push(c);
            }
            ']' => {
                depth -= 1;
                cur.push(c);
            }
            ',' if depth == 0 => {
                args.push(std::mem::take(&mut cur));
            }
            _ => cur.push(c),
        }
    }
