pub fn substring(text: &str, start: Option<i32>, end: Option<i32>) -> String {
    let chars: Vec<char> = text.chars().collect();
    let len = chars.len() as i32;
    let norm = |x: i32| -> i32 {
        if x < 0 {
            (len + x).max(0)
        } else {
            x.min(len)
        }
    };
    let s = norm(start.unwrap_or(0));
    let e = norm(end.unwrap_or(len));
    if s >= e {
        return String::new();
    }
    chars[s as usize..e as usize].iter().collect()
}

