            } else if prev.is_uppercase() && c.is_uppercase() && next.map_or(false, |n| n.is_lowercase()) {
                words.push(std::mem::take(&mut cur));
            }
        }
        cur.push(c);
    }
    if !cur.is_empty() {
        words.push(cur);
    }
    words
}

fn capitalize(w: &str) -> String {
    let mut c = w.chars();
    match c.next() {
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
        None => String::new(),
    }
}

pub fn convert_case(text: &str, case: StringCase, seps: &Option<Vec<Separator>>) -> String {
    match case {
        StringCase::LowerCase => text.to_lowercase(),
        StringCase::UpperCase => text.to_uppercase(),
