        StringCase::SnakeCase => split_words(text, seps).iter().map(|w| w.to_lowercase()).collect::<Vec<_>>().join("_"),
        StringCase::KebabCase => split_words(text, seps).iter().map(|w| w.to_lowercase()).collect::<Vec<_>>().join("-"),
    }
}

