use crate::lang::Lang;
use crate::matcher::Env;
use crate::rule::*;
use crate::tree::Tree;
use std::collections::BTreeMap;
use std::sync::Arc;

#[derive(Clone, Debug)]
pub struct Fixer {
    pub template: Template,
    pub expand_start: Option<Box<Relation>>,
    pub expand_end: Option<Box<Relation>>,
    pub title: Option<String>,
}

#[derive(Clone)]
pub struct RuleCore {
    pub lang: Lang,
    pub rule: Rule,
    pub constraints: Vec<(String, Rule)>,
    pub transforms: Vec<(String, Transform)>,
    pub fixers: Vec<Fixer>,
    pub utils: Utils,
    pub rewriters: Arc<BTreeMap<String, RuleCore>>,
}

#[derive(Clone, Debug)]
pub struct Match {
    pub node: u32,
    pub env: Env,
}

pub fn relation_from_ser(x: &SerRelation, env: &CompileEnv) -> Result<Box<Relation>, ErrChain> {
    let rule = compile_rule(&x.rule, env)?;
    let stop_by = match &x.stop_by {
        SerStopBy::Neighbor => StopBy::Neighbor,
        SerStopBy::End => StopBy::End,
        SerStopBy::Rule(r) => StopBy::Rule(Box::new(compile_rule(r, env)?)),
    };
    Ok(Box::new(Relation { rule, stop_by, field: x.field.clone() }))
}

pub fn compile_fixer(f: &Option<SerFixer>, env: &CompileEnv) -> Result<Vec<Fixer>, ErrChain> {
    let Some(f) = f else { return Ok(vec![]) };
    let conv = |c: &SerFixConfig| -> Result<Fixer, ErrChain> {
        Ok(Fixer {
            template: Template::parse(&c.template),
            expand_start: match c.expand_start.as_ref() {
                Some(r) => Some(relation_from_ser(r, env)?),
                None => None,
            },
            expand_end: match c.expand_end.as_ref() {
                Some(r) => Some(relation_from_ser(r, env)?),
                None => None,
            },
            title: c.title.clone(),
        })
    };
    match f {
        SerFixer::Str(s) => Ok(vec![Fixer { template: Template::parse(s), expand_start: None, expand_end: None, title: None }]),
        SerFixer::Config(c) => Ok(vec![conv(c)?]),
        SerFixer::List(l) => l.iter().map(conv).collect(),
    }
}

impl RuleCore {
    pub fn from_pattern(pattern: crate::matcher::Pattern, lang: Lang, fix: Option<&str>) -> RuleCore {
        RuleCore {
            lang,
            rule: Rule::Pattern(Arc::new(pattern)),
            constraints: vec![],
            transforms: vec![],
            fixers: fix
                .map(|f| vec![Fixer { template: Template::parse(f), expand_start: None, expand_end: None, title: None }])
                .unwrap_or_default(),
            utils: Utils::default(),
            rewriters: Arc::new(BTreeMap::new()),
        }
    }

    /// Compile a rule core from serialized parts
    pub fn compile(
        core: &SerRuleCore,
        lang: Lang,
        global_utils: Arc<BTreeMap<String, Rule>>,
        rewriters: Option<&Vec<SerRewriter>>,
    ) -> Result<RuleCore, ErrChain> {
        // local utils
        let local_names: Vec<String> = core.utils.as_ref().map(|u| u.keys().cloned().collect()).unwrap_or_default();
        let gl = global_utils.clone();
        let names = move |n: &str| local_names.iter().any(|x| x == n) || gl.contains_key(n);
        let cenv = CompileEnv { lang, util_names: &names };
        let mut local = BTreeMap::new();
        if let Some(u) = &core.utils {
            for (k, v) in u {
                let r = compile_rule(v, &cenv).map_err(|e| e.wrap("`utils` is not configured correctly."))?;
                local.insert(k.clone(), r);
            }
        }
        let rule = compile_rule(&core.rule, &cenv).map_err(|e| e.wrap("`rule` is not configured correctly."))?;
        let mut constraints = Vec::new();
        if let Some(c) = &core.constraints {
            for (k, v) in c {
                let r = compile_rule(v, &cenv).map_err(|e| e.wrap("`constraints` is not configured correctly."))?;
                constraints.push((k.clone(), r));
            }
        }
        let mut transforms = Vec::new();
        if let Some(t) = &core.transform {
            for (k, v) in t {
                let key = k.as_str().unwrap_or_default().to_string();
                let tr: Transformation = serde_yaml::from_value(v.clone()).map_err(|e| {
                    ErrChain(vec!["`transform` is not configured correctly.".into(), e.to_string()])
                })?;
                let ct = compile_transform(&tr)
                    .map_err(|e| ErrChain(vec!["`transform` is not configured correctly.".into(), e]))?;
                transforms.push((key, ct));
            }
        }
        // order transforms by dependency
        let transforms = order_transforms(transforms);
        let fixers = compile_fixer(&core.fix, &cenv).map_err(|e| e.wrap("`fix` is not configured correctly."))?;
        let mut rw = BTreeMap::new();
        if let Some(list) = rewriters {
            for r in list {
                let c = RuleCore::compile(&r.core, lang, global_utils.clone(), None)?;
                rw.insert(r.id.clone(), c);
            }
            let shared = Arc::new(rw.clone());
            for v in rw.values_mut() {
                v.rewriters = shared.clone();
            }
        }
        Ok(RuleCore {
            lang,
            rule,
            constraints,
            transforms,
            fixers,
            utils: Utils { local, global: global_utils },
            rewriters: Arc::new(rw),
        })
    }

    pub fn match_node(&self, tree: &Tree, node: u32) -> Option<Env> {
        let ctx = Ctx::new(tree, &self.utils);
        let mut env = Env::default();
        if !self.rule.match_node(&ctx, node, &mut env) {
            return None;
        }
        for (var, r) in &self.constraints {
            if let Some(&n) = env.single.get(var) {
                let mut e2 = env.clone();
                if !r.match_node(&ctx, n, &mut e2) {
                    return None;
                }
            }
        }
        self.apply_transforms(tree, &mut env);
        Some(env)
    }

    pub fn apply_transforms(&self, tree: &Tree, env: &mut Env) {
        for (name, t) in &self.transforms {
            let src = t.source();
            let Some(text) = env.get_text(tree, src) else { continue };
            let val = match t {
                Transform::Substring { start, end, .. } => substring(&text, *start, *end),
                Transform::Replace { re, by, .. } => regex_replace(&text, re, by),
                Transform::Convert { case, seps, .. } => convert_case(&text, *case, seps),
                Transform::Rewrite { rewriters, join_by, .. } => self.rewrite(tree, env, src, rewriters, join_by),
            };
            env.transformed.insert(name.clone(), val);
        }
    }

    fn rewrite(&self, tree: &Tree, env: &Env, src: &str, rewriters: &[String], join_by: &Option<String>) -> String {
        let nodes: Vec<u32> = if let Some(&n) = env.single.get(src) {
            vec![n]
        } else if let Some(ns) = env.multi.get(src) {
            ns.clone()
        } else {
            return String::new();
        };
        let mut parts = Vec::new();
        for n in nodes {
            parts.push(self.rewrite_node(tree, n, rewriters));
        }
        parts.join(join_by.as_deref().unwrap_or(""))
    }

    fn rewrite_node(&self, tree: &Tree, node: u32, rewriters: &[String]) -> String {
        // find non-overlapping matches of rewriters in pre-order
        let mut edits: Vec<(usize, usize, String)> = Vec::new();
        let mut stack = vec![node];
        while let Some(x) = stack.pop() {
            let mut matched = false;
            for id in rewriters {
                if let Some(rc) = self.rewriters.get(id) {
                    if let Some(env) = rc.match_node(tree, x) {
                        if let Some(f) = rc.fixers.first() {
                            let n = tree.n(x);
                            let rep = f.template.generate(tree, &env);
                            let indent = indent_at(&tree.src[..n.start]);
                            let rep = indent_text(&rep, 0, indent);
                            edits.push((n.start, n.end, rep));
                            matched = true;
                            break;
                        }
                    }
                }
            }
            if !matched {
                for &c in tree.n(x).children.iter().rev() {
                    stack.push(c);
                }
            }
        }
        let n = tree.n(node);
        let mut out = String::new();
        let mut pos = n.start;
        edits.sort_by_key(|e| e.0);
        for (s, e, r) in edits {
            if s < pos {
                continue;
            }
            out.push_str(&tree.src[pos..s]);
            out.push_str(&r);
            pos = e;
        }
        out.push_str(&tree.src[pos..n.end]);
        // re-indent relative to node indentation
        let orig = indent_at(&tree.src[..n.start]);
        indent_text(&out, orig, 0)
    }

    pub fn find_all(&self, tree: &Tree) -> Vec<Match> {
        let mut order = Vec::new();
        tree.preorder(tree.root, &mut order);
        let mut out = Vec::new();
        for n in order {
            if let Some(env) = self.match_node(tree, n) {
                out.push(Match { node: n, env });
            }
        }
        out
    }

    /// compute replacement text and range for a match using the first fixer
    pub fn replacement(&self, tree: &Tree, m: &Match, fixer_idx: usize) -> Option<(usize, usize, String)> {
        let f = self.fixers.get(fixer_idx)?;
        let n = tree.n(m.node);
        let mut start = n.start;
        let mut end = n.end;
        let ctx = Ctx::new(tree, &self.utils);
        if let Some(rel) = &f.expand_end {
            let mut cur = tree.next_sibling(m.node);
            while let Some(s) = cur {
                let mut e = m.env.clone();
                if rel.rule.match_node(&ctx, s, &mut e) {
                    end = tree.n(s).end;
                    cur = tree.next_sibling(s);
                    if matches!(rel.stop_by, StopBy::Neighbor) {
                        continue;
                    }
                } else {
                    break;
                }
            }
        }
        if let Some(rel) = &f.expand_start {
            let mut cur = tree.prev_sibling(m.node);
            while let Some(s) = cur {
                let mut e = m.env.clone();
                if rel.rule.match_node(&ctx, s, &mut e) {
                    start = tree.n(s).start;
                    cur = tree.prev_sibling(s);
                } else {
                    break;
                }
            }
        }
        let rep = f.template.generate(tree, &m.env);
        let indent = indent_at(&tree.src[..n.start]);
        let rep = indent_text(&rep, 0, indent);
        Some((start, end, rep))
    }
}

fn order_transforms(ts: Vec<(String, Transform)>) -> Vec<(String, Transform)> {
    // simple topological order: a transform depending on another transformed var goes after it
    let names: Vec<String> = ts.iter().map(|t| t.0.clone()).collect();
    let mut done: Vec<bool> = vec![false; ts.len()];
    let mut out = Vec::new();
    let mut progress = true;
    while out.len() < ts.len() && progress {
        progress = false;
        for i in 0..ts.len() {
            if done[i] {
                continue;
            }
            let src = ts[i].1.source();
            let dep = names.iter().position(|n| n == src);
            if let Some(d) = dep {
                if d != i && !done[d] {
                    continue;
                }
            }
            done[i] = true;
            out.push(ts[i].clone());
            progress = true;
        }
    }
    for i in 0..ts.len() {
        if !done[i] {
            out.push(ts[i].clone());
        }
    }
    out
}

/// Apply edits (start, end, replacement) to source; overlapping edits are dropped.
pub fn apply_edits(src: &str, edits: &mut Vec<(usize, usize, String)>) -> String {
    edits.sort_by_key(|e| e.0);
    let mut out = String::new();
    let mut pos = 0;
    for (s, e, r) in edits.iter() {
        if *s < pos {
            continue;
        }
        out.push_str(&src[pos..*s]);
        out.push_str(r);
        pos = *e;
    }
    out.push_str(&src[pos..]);
    out
}
