            Op::Delete { n, .. } => (n, n),
            Op::Insert { n, nlen, .. } => (n, n + nlen),
            Op::Replace { n, nlen, .. } => (n, n + nlen),
        }
    }
}

struct Hook {
    ops: Vec<Op>,
    eq: Option<(usize, usize, usize)>,
    del: Option<(usize, usize, usize)>,
    ins: Option<(usize, usize, usize)>,
}

impl Hook {
    fn flush_eq(&mut self) {
        if let Some((o, n, len)) = self.eq.take() {
            self.ops.push(Op::Equal { o, n, len });
        }
    }
    fn flush_del_ins(&mut self) {
        match (self.del.take(), self.ins.take()) {
            (Some((o, olen, _)), Some((_, n, nlen))) => self.ops.push(Op::Replace { o, olen, n, nlen }),
            (Some((o, olen, n)), None) => self.ops.push(Op::Delete { o, olen, n }),
            (None, Some((o, n, nlen))) => self.ops.push(Op::Insert { o, n, nlen }),
            (None, None) => {}
        }
    }
    fn equal(&mut self, o: usize, n: usize, len: usize) {
        self.flush_del_ins();
        self.eq = match self.eq.take() {
            Some((eo, en, el)) => Some((eo, en, el + len)),
            None => Some((o, n, len)),
        };
    }
    fn delete(&mut self, o: usize, olen: usize, n: usize) {
        self.flush_eq();
        self.del = match self.del.take() {
            Some((d_o, dl, dn)) => Some((d_o, dl + olen, dn)),
            None => Some((o, olen, n)),
        };
    }
    fn insert(&mut self, o: usize, n: usize, nlen: usize) {
        self.flush_eq();
        self.ins = match self.ins.take() {
            Some((io, i_n, il)) => Some((io, i_n, il + nlen)),
            None => Some((o, n, nlen)),
        };
    }
    fn finish(&mut self) {
        self.flush_eq();
