    off: isize,
    v: Vec<usize>,
}
impl V {
    fn new(max_d: usize) -> V {
        V { off: max_d as isize, v: vec![0; 2 * max_d] }
    }
    fn get(&self, k: isize) -> usize {
        self.v[(k + self.off) as usize]
    }
    fn set(&mut self, k: isize, x: usize) {
        let i = (k + self.off) as usize;
        self.v[i] = x;
    }
}

fn max_d(l1: usize, l2: usize) -> usize {
    (l1 + l2 + 1) / 2 + 1
}

fn prefix_len<T: PartialEq>(a: &[T], ar: (usize, usize), b: &[T], br: (usize, usize)) -> usize {
    let mut i = 0;
    while ar.0 + i < ar.1 && br.0 + i < br.1 && a[ar.0 + i] == b[br.0 + i] {
        i += 1;
    }
    i
}
fn suffix_len<T: PartialEq>(a: &[T], ar: (usize, usize), b: &[T], br: (usize, usize)) -> usize {
    let mut i = 0;
    while ar.1 > ar.0 + i && br.1 > br.0 + i && a[ar.1 - 1 - i] == b[br.1 - 1 - i] {
        i += 1;
    }
    i
}

