            }
            vb.set(k, x);
            if !odd && (k - delta).abs() <= d && vb.get(k) + vf.get(-(k - delta)) >= n {
                return Some((n - x + ar.0, m - y + br.0));
            }
            k -= 2;
        }
    }
    None
}

fn conquer<T: PartialEq>(h: &mut Hook, a: &[T], mut ar: (usize, usize), b: &[T], mut br: (usize, usize), vf: &mut V, vb: &mut V) {
    let p = prefix_len(a, ar, b, br);
    if p > 0 {
        h.equal(ar.0, br.0, p);
    }
    ar.0 += p;
    br.0 += p;
