    let md = max_d(a.len(), b.len());
    let mut vf = V::new(md);
    let mut vb = V::new(md);
    let mut h = Hook { ops: vec![], eq: None, del: None, ins: None };
    conquer(&mut h, a, (0, a.len()), b, (0, b.len()), &mut vf, &mut vb);
