            }
        }
        pending.push(op);
    }
    let only_eq = pending.len() == 1 && matches!(pending[0], Op::Equal { .. });
    if !pending.is_empty() && !only_eq {
        rv.push(pending);
    }
    rv
}

/// split into lines keeping line terminators
pub fn split_lines(s: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let mut start = 0;
    let b = s.as_bytes();
    for i in 0..b.len() {
        if b[i] == b'\n' {
            out.push(&s[start..i + 1]);
            start = i + 1;
        }
    }
    if start < s.len() {
        out.push(&s[start..]);
    }
    out
}
