/// print diff hunks between old and new text
pub fn print_diff(out: &mut String, old: &str, new: &str, context: usize, color: bool) {
    let a = diff::split_lines(old);
    let b = diff::split_lines(new);
    let ops = diff::diff(&a, &b);
    let groups = diff::group_ops(ops, context);
    for g in groups {
        let first = g.first().unwrap();
        let last = g.last().unwrap();
        let (os, _) = first.old_range();
        let (ns, _) = first.new_range();
        let (_, oe) = last.old_range();
        let (_, ne) = last.new_range();
        let header = format!("@@ -{},{} +{},{} @@", os, oe - os, ns, ne - ns);
        if color {
            out.push_str(&format!("\x1b[34m{}{}\n", header, RESET));
        } else {
            out.push_str(&header);
            out.push('\n');
        }
        let w = oe.max(ne).to_string().len();
        for op in &g {
            let mut lines: Vec<(char, Option<usize>, Option<usize>, &str)> = Vec::new();
            match *op {
                diff::Op::Equal { o, n, len } => {
                    for i in 0..len {
                        lines.push((' ', Some(o + i + 1), Some(n + i + 1), a[o + i]));
                    }
                }
                diff::Op::Delete { o, olen, .. } => {
                    for i in 0..olen {
                        lines.push(('-', Some(o + i + 1), None, a[o + i]));
                    }
                }
                diff::Op::Insert { n, nlen, .. } => {
                    for i in 0..nlen {
                        lines.push(('+', None, Some(n + i + 1), b[n + i]));
                    }
                }
                diff::Op::Replace { o, olen, n, nlen } => {
                    for i in 0..olen {
                        lines.push(('-', Some(o + i + 1), None, a[o + i]));
                    }
                    for i in 0..nlen {
                        lines.push(('+', None, Some(n + i + 1), b[n + i]));
                    }
                }
            }
            for (sign, on, nn, text) in lines {
                let text = text.strip_suffix('\n').unwrap_or(text);
                if color {
                    match sign {
                        ' ' => out.push_str(&format!(
                            "\x1b[2m{}{} \x1b[2m{}{}\u{2502} {}\n",
                            pad(on, w),
                            RESET,
                            pad(nn, w),
                            RESET,
                            text
                        )),
                        '-' => out.push_str(&format!(
                            "\x1b[38;5;161m{}{} \x1b[38;5;161m{}{}\u{2502}\x1b[38;5;161m-{}\x1b[1;48;5;225;38;5;161m{}{}\x1b[38;5;161m\n{}",
                            pad(on, w),
                            RESET,
                            pad(nn, w),
                            RESET,
                            RESET,
                            text,
                            RESET,
                            RESET
                        )),
                        _ => out.push_str(&format!(
                            "\x1b[38;5;35m{}{} \x1b[38;5;35m{}{}\u{2502}\x1b[38;5;35m+{}\x1b[1;48;5;158;38;5;35m{}{}\x1b[38;5;35m\n{}",
                            pad(on, w),
                            RESET,
                            pad(nn, w),
                            RESET,
                            RESET,
                            text,
                            RESET,
                            RESET
                        )),
                    }
                } else {
                    out.push_str(&format!("{} {}\u{2502}{}{}\n", pad(on, w), pad(nn, w), sign, text));
                }
            }
        }
    }
}
