// Output printers
use crate::diff;
use crate::tree::Tree;
use serde_json::{json, Map, Value};
use std::io::Write;

pub const RESET: &str = "\x1b[0m";

pub fn line_range_of(tree: &Tree, start: usize, end: usize) -> (usize, usize) {
    let (sl, _) = tree.point(start);
    let (el, _) = tree.point(end);
    (sl, el)
}

pub fn line_text<'a>(src: &'a str, line_starts: &[usize], line: usize) -> &'a str {
    let s = line_starts[line];
    let e = if line + 1 < line_starts.len() { line_starts[line + 1] - 1 } else { src.len() };
    let e = e.max(s);
    let t = &src[s..e];
    t.strip_suffix('\r').unwrap_or(t)
}

pub struct TextOpts {
    pub color: bool,
    pub heading: bool,
    pub before: usize,
    pub after: usize,
}

fn highlight_line(out: &mut String, src: &str, ls: usize, le: usize, ranges: &[(usize, usize)], color: bool) {
    let text = &src[ls..le];
    if !color {
        out.push_str(text);
        return;
    }
    // collect segments
    let mut pos = ls;
    for &(s, e) in ranges {
        let s2 = s.max(ls);
        let e2 = e.min(le);
        if s2 >= e2 && !(s == e && s >= ls && s <= le) {
            continue;
        }
        if s2 < pos {
            continue;
        }
        out.push_str(&src[pos..s2]);
        out.push_str("\x1b[1;31m");
        out.push_str(&src[s2..e2]);
        out.push_str(RESET);
        pos = e2;
    }
    out.push_str(&src[pos..le]);
}

/// Print matches (byte ranges, sorted by start) of a file in grep-like format.
pub fn print_matches(out: &mut String, path: &str, tree: &Tree, matches: &[(usize, usize)], o: &TextOpts) {
    if matches.is_empty() {
        return;
    }
    let src = &tree.src;
    let nlines = tree.line_starts.len();
    // chunks: (display_start_line, display_end_line, ranges)
    let mut chunks: Vec<(usize, usize, Vec<(usize, usize)>)> = Vec::new();
    let mut first_end_line = 0usize;
    for &(s, e) in matches {
        let (sl, el) = line_range_of(tree, s, e);
        if let Some(last) = chunks.last_mut() {
            if sl <= first_end_line + o.before + o.after + 1 {
                let de = (el + o.after).min(nlines - 1);
                if de > last.1 {
                    last.1 = de;
                }
                last.2.push((s, e));
                continue;
            }
        }
        first_end_line = el;
        let ds = sl.saturating_sub(o.before);
        let de = (el + o.after).min(nlines - 1);
        chunks.push((ds, de, vec![(s, e)]));
    }
    // last line: if file ends with newline, the final empty line is not displayable by context
    let max_line = if src.ends_with('\n') && nlines > 1 { nlines - 2 } else { nlines - 1 };
    if o.heading {
        if o.color {
            out.push_str(&format!("\x1b[3;36m{}{}\n", path, RESET));
        } else {
            out.push_str(path);
            out.push('\n');
        }
    }
    for (ci, (ds, de, ranges)) in chunks.iter().enumerate() {
        let mut ranges = ranges.clone();
        ranges.sort();
        // merge overlapping
        let mut merged: Vec<(usize, usize)> = Vec::new();
        for r in ranges {
            if let Some(l) = merged.last_mut() {
                if r.0 < l.1 {
                    if r.1 > l.1 {
                        l.1 = r.1;
                    }
                    continue;
                }
            }
            merged.push(r);
        }
        if ci > 0 && (o.before > 0 || o.after > 0) {
            if o.heading {
                out.push_str("\u{2574}\u{2524}\n");
            } else {
                out.push_str("--\n");
            }
        }
        let match_end_line = line_range_of(tree, merged.last().unwrap().0, merged.last().unwrap().1).1;
        let de = (*de).min(max_line.max(match_end_line));
        for line in *ds..=de {
            let ls = tree.line_starts[line];
            let mut le = if line + 1 < nlines { tree.line_starts[line + 1] - 1 } else { src.len() };
            if le > ls && src.as_bytes()[le - 1] == b'\r' {
                le -= 1;
            }
            if o.heading {
                if o.color {
                    out.push_str(&format!("\x1b[2m{}{}\u{2502}", line + 1, RESET));
                } else {
                    out.push_str(&format!("{}\u{2502}", line + 1));
                }
            } else {
                out.push_str(&format!("{}:{}:", path, line + 1));
            }
            highlight_line(out, src, ls, le, &merged, o.color);
            out.push('\n');
        }
    }
    if o.heading {
        out.push('\n');
    }
}

