/// Walk paths, calling f for each file. Errors printed to stderr.
pub fn walk(paths: &[String], o: &WalkOpts, mut f: impl FnMut(&Path)) {
    if paths.is_empty() {
        return;
    }
    let mut wb = ignore::WalkBuilder::new(&paths[0]);
    for p in &paths[1..] {
        wb.add(p);
    }
