pub fn run_cmd(m: &ArgMatches) -> i32 {
    let pattern_src = m.get_one::<String>("pattern").unwrap().clone();
    let lang = m.get_one::<String>("lang").and_then(|s| Lang::from_name(s));
    let strictness = m.get_one::<String>("strictness").and_then(|s| Strictness::from_str(s)).unwrap_or(Strictness::Smart);
    let selector = m.get_one::<String>("selector").cloned();
    let rewrite = m.get_one::<String>("rewrite").cloned();
    let color = use_color(m);
    let heading = match m.get_one::<String>("heading").map(|s| s.as_str()).unwrap_or("auto") {
        "always" => true,
        "never" => false,
        _ => std::io::stdout().is_terminal(),
    };
    let (before, after) = context_of(m);
    let json = json_style(m);
    let update_all = m.get_flag("update-all");
    let files_with_matches = m.get_flag("files-with-matches");

    let build = |l: Lang| -> Result<Pattern, crate::matcher::PatternError> {
        match &selector {
            Some(sel) => Pattern::with_selector(&pattern_src, sel, l, strictness),
            None => Pattern::new(&pattern_src, l, strictness),
        }
    };

    // debug query
    if let Some(fmt) = m.get_one::<String>("debug-query") {
