        no_ignore: m.get_many::<String>("no-ignore").map(|v| v.cloned().collect()).unwrap_or_default(),
        follow: m.get_flag("follow"),
        globs: m.get_many::<String>("globs").map(|v| v.cloned().collect()).unwrap_or_default(),
    }
}

pub fn file_lang(path: &std::path::Path, want: Option<Lang>) -> Option<Lang> {
    let l = Lang::from_path(path)?;
    match want {
        Some(w) => {
            if l == w || (w == Lang::TypeScript && l == Lang::TypeScript) {
                Some(w)
            } else {
                None
            }
        }
        None => Some(l),
    }
}

pub fn run_cmd(m: &ArgMatches) -> i32 {
    let pattern_src = m.get_one::<String>("pattern").unwrap().clone();
    let lang = m.get_one::<String>("lang").and_then(|s| Lang::from_name(s));
    let strictness = m.get_one::<String>("strictness").and_then(|s| Strictness::from_str(s)).unwrap_or(Strictness::Smart);
    let selector = m.get_one::<String>("selector").cloned();
    let rewrite = m.get_one::<String>("rewrite").cloned();
    let color = use_color(m);
    let heading = match m.get_one::<String>("heading").map(|s| s.as_str()).unwrap_or("auto") {
        "always" => true,
        "never" => false,
        _ => std::io::stdout().is_terminal(),
    };
    let (before, after) = context_of(m);
    let json = json_style(m);
    let update_all = m.get_flag("update-all");
    let files_with_matches = m.get_flag("files-with-matches");

    let build = |l: Lang| -> Result<Pattern, crate::matcher::PatternError> {
        match &selector {
            Some(sel) => Pattern::with_selector(&pattern_src, sel, l, strictness),
            None => Pattern::new(&pattern_src, l, strictness),
        }
    };

    // debug query
    if let Some(fmt) = m.get_one::<String>("debug-query") {
        let l = lang.unwrap();
        match fmt.as_str() {
            "pattern" => match build(l) {
                Ok(p) => eprint!("Debug Pattern:\n{}\n", p.debug()),
                Err(e) => {
                    pattern_error(vec![e.message()]).print();
                    return 8;
                }
            },
            f => {
                let t = l.parse(&pattern_src);
                let mut s = String::new();
                match f {
                    "ast" => {
                        t.dump(t.root, false, &mut s, 0);
                        eprint!("Debug AST:\n{}\n", s);
                    }
                    "cst" => {
                        t.dump(t.root, true, &mut s, 0);
                        eprint!("Debug CST:\n{}\n", s);
                    }
                    _ => {
                        t.sexp(t.root, &mut s);
                        eprint!("Debug Sexp:\n{}\n", s);
                    }
                }
            }
        }
    }

    let mut cores: HashMap<Lang, Option<(RuleCore, bool)>> = HashMap::new();
    if let Some(l) = lang {
        match build(l) {
            Ok(p) => {
                let he = p.has_error;
                cores.insert(l, Some((RuleCore::from_pattern(p, l, rewrite.as_deref()), he)));
            }
            Err(e) => {
                pattern_error(vec![e.message()]).print();
                return 8;
            }
        }
    }
    let stdin_mode = m.get_flag("stdin");
    if stdin_mode && lang.is_none() {
        CliError::new("Language must be specified for code from StdIn.", 3)
            .help("Please use `--lang` to specify the code language.")
            .url("https://ast-grep.github.io/guide/tooling-overview.html#parse-code-from-stdin")
            .print();
        return 3;
    }

    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    let mut jp = json.map(JsonPrinter::new);
    let mut matched_any = false;
    let mut any_error_pattern = false;
    let mut applied = 0usize;
    let opts = TextOpts { color, heading, before, after };

    let mut process = |path_disp: &str, src: String, l: Lang, file_path: Option<&std::path::Path>, out: &mut std::io::StdoutLock| {
        let entry = cores.entry(l).or_insert_with(|| match build(l) {
            Ok(p) => {
                let he = p.has_error;
                Some((RuleCore::from_pattern(p, l, rewrite.as_deref()), he))
            }
            Err(_) => None,
        });
        let Some((core, has_err)) = entry.as_ref() else { return };
        if *has_err {
            any_error_pattern = true;
        }
        let tree = l.parse(&src);
        let matches = core.find_all(&tree);
        if matches.is_empty() {
            return;
        }
        matched_any = true;
        if let Some(jp) = jp.as_mut() {
            for mt in &matches {
                let rep = if rewrite.is_some() { core.replacement(&tree, mt, 0) } else { None };
                let v = match_json(&tree, mt.node, &mt.env, path_disp, l.name(), rep);
                jp.item(out, &serde_json::Value::Object(v));
            }
            return;
        }
        if files_with_matches {
            let _ = writeln!(out, "{}", path_disp);
            return;
        }
        if rewrite.is_some() {
            let mut edits: Vec<(usize, usize, String)> =
                matches.iter().filter_map(|mt| core.replacement(&tree, mt, 0)).collect();
            if update_all {
                let n = {
                    let mut e2 = edits.clone();
                    e2.sort_by_key(|e| e.0);
                    let mut pos = 0;
                    let mut c = 0;
                    for (s, e, _) in &e2 {
                        if *s >= pos {
                            c += 1;
                            pos = *e;
                        }
                    }
                    c
                };
                let new = apply_edits(&src, &mut edits);
                if let Some(fp) = file_path {
                    let _ = std::fs::write(fp, new);
                }
                applied += n;
                return;
            }
            let new = apply_edits(&src, &mut edits);
            let mut s = String::new();
            if color {
                s.push_str(&format!("\x1b[3;36m{}{}\n", path_disp, RESET));
            } else {
                s.push_str(path_disp);
                s.push('\n');
            }
            let ctx = if before > 0 || after > 0 { before.max(after) } else { 3 };
            print_diff(&mut s, &src, &new, ctx, color);
            let _ = out.write_all(s.as_bytes());
            return;
        }
        let ranges: Vec<(usize, usize)> = matches.iter().map(|mt| (tree.n(mt.node).start, tree.n(mt.node).end)).collect();
        let mut s = String::new();
        print_matches(&mut s, path_disp, &tree, &ranges, &opts);
        let _ = out.write_all(s.as_bytes());
    };

    if stdin_mode {
        let mut src = String::new();
        let _ = std::io::stdin().read_to_string(&mut src);
        process("STDIN", src, lang.unwrap(), None, &mut out);
    } else {
        let paths: Vec<String> = m.get_many::<String>("paths").map(|v| v.cloned().collect()).unwrap_or_else(|| vec![".".into()]);
        let wo = walk_opts(m);
        let files = collect(&paths, &wo);
        for f in files {
            let Some(l) = file_lang(&f, lang) else { continue };
            let Ok(bytes) = std::fs::read(&f) else { continue };
            let Ok(src) = String::from_utf8(bytes) else { continue };
            let disp = display_path(&f);
            process(&disp, src, l, Some(&f), &mut out);
        }
    }
    if let Some(jp) = jp.as_mut() {
        jp.end(&mut out);
    }
    if update_all && rewrite.is_some() && json.is_none() && applied > 0 {
        let _ = writeln!(out, "Applied {} changes", applied);
    }
    let _ = out.flush();
    if !matched_any && any_error_pattern {
        eprint!("Warning: Pattern contains an ERROR node and may cause unexpected results.\nHelp: ast-grep parsed the pattern but it matched nothing in this run. Try using playground to refine the pattern.\nSee also: https://ast-grep.github.io/playground.html\n\n");
        return 0;
    }
    if matched_any {
        0
    } else {
        1
    }
}
