// valid node kinds per language (from bundled schema)
use super::Lang;
use std::collections::{HashMap, HashSet};
use std::sync::OnceLock;

static SCHEMA: &str = include_str!("../../schemas/languages.json");

fn table() -> &'static HashMap<String, HashSet<String>> {
    static T: OnceLock<HashMap<String, HashSet<String>>> = OnceLock::new();
    T.get_or_init(|| {
        let mut m = HashMap::new();
        if let Ok(v) = serde_json::from_str::<serde_json::Value>(SCHEMA) {
            if let Some(defs) = v.get("definitions").and_then(|d| d.as_object()) {
                for (k, v) in defs {
                    if let Some(l) = k.strip_suffix("Nodes") {
                        let set: HashSet<String> = v
                            .get("enum")
                            .and_then(|e| e.as_array())
                            .map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect())
                            .unwrap_or_default();
                        m.insert(l.to_string(), set);
                    }
                }
            }
        }
        m
    })
}

fn schema_key(l: Lang) -> Option<&'static str> {
    Some(match l {
        Lang::Bash => "bash",
        Lang::C => "c",
        Lang::Cpp => "cpp",
        Lang::CSharp => "csharp",
        Lang::Css => "css",
        Lang::Elixir => "elixir",
        Lang::Go => "go",
        Lang::Haskell => "haskell",
        Lang::Html => "html",
        Lang::Java => "java",
        Lang::JavaScript => "javascript",
        Lang::Json => "json",
        Lang::Kotlin => "kotlin",
        Lang::Lua => "lua",
        Lang::Php => "php",
        Lang::Python => "python",
        Lang::Ruby => "ruby",
        Lang::Rust => "rust",
        Lang::Scala => "scala",
        Lang::Swift => "swift",
        Lang::Tsx => "tsx",
        Lang::TypeScript => "typescript",
        Lang::Yaml => "yaml",
        _ => return None,
    })
}

const SUPERTYPES: &[&str] = &[
    "expression", "statement", "declaration", "pattern", "primary_expression", "type", "primary_type", "literal",
    "declaration_statement", "simple_type", "simple_statement", "compound_statement", "parameter", "lhs_expression",
    "top_level_item", "type_specifier", "declarator", "field_declarator", "type_declarator", "abstract_declarator",
    "simple_expression", "unannotated_type", "module_directive", "literal_pattern", "arg", "lhs", "primary",
    "method_name", "variable", "nonterminal", "type_query", "constant", "expression_statement", "_expression",
    "value", "selector", "selectors", "quantifier", "statement_list",
];

pub fn is_valid_kind(l: Lang, kind: &str) -> bool {
    let Some(k) = schema_key(l) else { return true };
    let t = table();
    let Some(set) = t.get(k) else { return true };
    set.contains(kind) || SUPERTYPES.contains(&kind) || kind == "ERROR"
}
