    notes: &[String],
) {
    let src = &tree.src;
    out.push_str(&format!("{}[{}]: {}\n", severity, code, message));
    if labels.is_empty() {
        for n in notes {
            out.push_str(&format!(" = {}\n", n));
        }
        out.push('\n');
        return;
    }
    // locus: first primary label
    let primary = labels.iter().find(|l| l.primary).unwrap_or(&labels[0]);
    let (pl, _) = tree.point(primary.start);
    let pc = src[tree.line_starts[pl]..primary.start].chars().count() + 1;
    // collect lines
    let line_of = |b: usize| tree.point(b).0;
    let mut line_nos: Vec<usize> = Vec::new();
    let mut multi_label: Option<&Label> = None;
    for l in labels {
        let sl = line_of(l.start);
        let mut el = line_of(l.end);
        if l.end > l.start && el > sl && tree.line_starts[el] == l.end {
            // label ending exactly at line start belongs to previous line
            el -= 1;
        }
        line_nos.push(sl);
        if el != sl {
            line_nos.push(el);
            if multi_label.is_none() {
                multi_label = Some(l);
            }
        }
    }
    line_nos.sort();
    line_nos.dedup();
    let num_multi = if multi_label.is_some() { 1 } else { 0 };
    let line_text = |ln: usize| -> &str {
        let s = tree.line_starts[ln];
        let e = if ln + 1 < tree.line_starts.len() { tree.line_starts[ln + 1] } else { src.len() };
        let t = &src[s..e];
        let t = t.strip_suffix('\n').unwrap_or(t);
        t.strip_suffix('\r').unwrap_or(t)
    };
    let mut lines: Vec<Line> = Vec::new();
    for &ln in &line_nos {
        let ls = tree.line_starts[ln];
        let text = line_text(ln);
        let mut singles = Vec::new();
        let mut multi = None;
        for l in labels {
            let sl = line_of(l.start);
            let mut el = line_of(l.end);
            if l.end > l.start && el > sl && tree.line_starts[el] == l.end {
                el -= 1;
            }
            if sl == el {
                if sl == ln {
                    singles.push((l.primary, l.start - ls, (l.end - ls).min(text.len()).max(l.start - ls), l.message.clone()));
                }
            } else if let Some(m) = multi_label {
                if std::ptr::eq(m, l) {
                    if ln == sl {
                        let st = l.start - ls;
                        let top_left = text[..st].trim().is_empty();
                        multi = Some(MultiOnLine::Top(st, top_left));
                    } else if ln == el {
                        let en = (l.end - ls).min(text.len());
                        multi = Some(MultiOnLine::Bottom(en, l.message.clone(), l.primary));
                    } else if ln > sl && ln < el {
                        multi = Some(MultiOnLine::Middle);
                    }
                }
            }
        }
        lines.push(Line { no: ln, text, singles, multi });
    }
    let max_no = lines.iter().map(|l| l.no + 1).max().unwrap_or(1);
    let gw = max_no.to_string().len();
    let pad = " ".repeat(gw);
    out.push_str(&format!("{} \u{250c}\u{2500} {}:{}:{}\n", pad, path, pl + 1, pc));
    // empty snippet line
    let empty_inner = if num_multi > 0 { "  " } else { "" };
    out.push_str(&format!("{} \u{2502}{}\n", pad, empty_inner));
    let mut i = 0;
    while i < lines.len() {
        let line = &lines[i];
        render_line(out, &pad, gw, line, num_multi);
        if i + 1 < lines.len() {
            let next = lines[i + 1].no;
            let gap = next - line.no;
            let in_multi = multi_label.map_or(false, |m| {
                let sl = line_of(m.start);
                let el = line_of(m.end);
                line.no >= sl && line.no < el
            });
            if gap == 2 {
                let mid_no = line.no + 1;
                let mid = Line {
                    no: mid_no,
                    text: line_text(mid_no),
                    singles: vec![],
                    multi: if in_multi { Some(MultiOnLine::Middle) } else { None },
                };
                render_line(out, &pad, gw, &mid, num_multi);
            } else if gap > 2 {
                let inner = if num_multi > 0 { if in_multi { " \u{2502}" } else { "  " } } else { "" };
                out.push_str(&format!("{} \u{b7}{}\n", pad, inner));
            }
        }
        i += 1;
    }
    if !notes.is_empty() {
        out.push_str(&format!("{} \u{2502}{}\n", pad, empty_inner));
        for n in notes {
            let mut first = true;
            for nl in n.split('\n') {
                if first {
                    out.push_str(&format!("{} = {}\n", pad, nl));
                    first = false;
                } else {
                    out.push_str(&format!("{}   {}\n", pad, nl));
                }
            }
        }
    }
    out.push('\n');
