fn render_line(out: &mut String, pad: &str, gw: usize, line: &Line, num_multi: usize) {
    let text = line.text;
    // source line
    let inner_src = if num_multi == 0 {
        String::new()
    } else {
        match &line.multi {
            Some(MultiOnLine::Top(_, true)) => " \u{256d}".to_string(),
            Some(MultiOnLine::Middle) | Some(MultiOnLine::Bottom(..)) => " \u{2502}".to_string(),
            _ => "  ".to_string(),
        }
    };
    out.push_str(&format!("{:>w$} \u{2502}{} {}\n", line.no + 1, inner_src, text, w = gw));
    // inner gutter for annotation lines (label continues below this line?)
    let inner_ann = if num_multi == 0 {
        String::new()
    } else {
        match &line.multi {
            Some(MultiOnLine::Top(_, true)) | Some(MultiOnLine::Middle) | Some(MultiOnLine::Bottom(..)) => " \u{2502}".to_string(),
            _ => "  ".to_string(),
        }
    };
    // single labels
    if !line.singles.is_empty() {
        let singles = &line.singles;
        let mut num_messages = 0;
        let mut max_start = 0;
        let mut max_end = 0;
        let mut trailing: Option<usize> = None;
        for (i, (_, s, e, m)) in singles.iter().enumerate() {
            if !m.is_empty() {
                num_messages += 1;
            }
            max_start = max_start.max(*s);
            max_end = max_end.max(*e);
            if *e == max_end {
                trailing = if m.is_empty() { None } else { Some(i) };
            }
        }
        if let Some(t) = trailing {
            let (_, ts, te, _) = &singles[t];
            let overl = singles.iter().enumerate().any(|(i, (_, s, e, _))| i != t && overlaps((*ts, *te), (*s, *e)));
            if overl {
                trailing = None;
            }
        }
        let mut l = format!("{} \u{2502}{} ", pad, inner_ann);
        let chars: Vec<(usize, char)> = text.char_indices().collect();
        let mut iter: Vec<(usize, char, usize)> = chars.iter().map(|&(b, c)| (b, c, cwidth(c))).collect();
        iter.push((text.len(), '\0', 1));
        for (b, c, w) in &iter {
            let cr = (*b, *b + c.len_utf8());
            let style = singles
                .iter()
                .filter(|(_, s, e, _)| overlaps((*s, *e), cr) || (s == e && *s == *b))
                .map(|(p, _, _, _)| *p)
                .max();
            let ch = match style {
                Some(true) => Some('^'),
                Some(false) => Some('-'),
                None if *b < max_end => Some(' '),
                None => None,
            };
            if let Some(ch) = ch {
                for _ in 0..*w {
                    l.push(ch);
                }
            }
        }
        if let Some(t) = trailing {
            l.push(' ');
            l.push_str(&singles[t].3);
        }
        out.push_str(&l);
        out.push('\n');
        let hanging: Vec<usize> = (0..singles.len()).filter(|&i| !singles[i].3.is_empty() && Some(i) != trailing).collect();
        if num_messages > trailing.iter().count() {
            let pointers = |limit: usize| -> String {
                let mut s = String::new();
                for (b, c, w) in iter.iter().take(chars.len()) {
                    if *b >= limit {
                        break;
                    }
                    let cr = (*b, *b + c.len_utf8());
                    let has = hanging.iter().any(|&i| singles[i].1 >= cr.0 && singles[i].1 < cr.1);
                    let mut spaces = *w;
                    if has {
                        s.push('\u{2502}');
                        spaces = w.saturating_sub(1);
                    }
                    if *b <= max_start {
                        for _ in 0..spaces {
                            s.push(' ');
                        }
                    }
                }
                s
            };
            out.push_str(&format!("{} \u{2502}{} {}\n", pad, inner_ann, pointers(usize::MAX)));
            for &h in hanging.iter().rev() {
                out.push_str(&format!("{} \u{2502}{} {}{}\n", pad, inner_ann, pointers(singles[h].1), singles[h].3));
            }
        }
    }
    // multi-line label top (not top-left) / bottom
    match &line.multi {
        Some(MultiOnLine::Top(st, false)) => {
            let mut s = format!("{} \u{2502} \u{256d}", pad);
            let n: usize = text.char_indices().take_while(|(b, _)| *b < st + 1).map(|(_, c)| cwidth(c)).sum();
            for _ in 0..n {
                s.push('\u{2500}');
            }
            s.push('^');
            out.push_str(&s);
            out.push('\n');
        }
        Some(MultiOnLine::Bottom(en, msg, primary)) => {
            let mut s = format!("{} \u{2502} \u{2570}", pad);
            let n: usize = text.char_indices().take_while(|(b, _)| *b < *en).map(|(_, c)| cwidth(c)).sum();
            for _ in 0..n {
                s.push('\u{2500}');
            }
            s.push(if *primary { '^' } else { '\'' });
            if !msg.is_empty() {
                s.push(' ');
                s.push_str(msg);
            }
            out.push_str(&s);
            out.push('\n');
        }
        _ => {}
    }
    let _ = gw;
    let _ = width;
}

fn overlaps(a: (usize, usize), b: (usize, usize)) -> bool {
    a.0 < b.1 && b.0 < a.1
}
