                }
                let cand2 = dir.join("sgconfig.yaml");
                if cand2.exists() {
                    break cand2;
                }
                if !dir.pop() {
                    return Ok(None);
                }
            }
        }
    };
    let text = std::fs::read_to_string(&path).map_err(|e| {
        CliError::new("Cannot read configuration.", 5)
            .help("Please add an sgconfig.yml configuration file in the project root to run the scan command.")
            .url("https://ast-grep.github.io/guide/project/project-config.html")
            .causes(vec![e.to_string()])
    })?;
    let cfg: ProjectConfigSer = serde_yaml::from_str(&text).map_err(|e| {
        CliError::new("Cannot parse configuration", 8)
            .help("The config file is not a valid ast-grep configuration. Please refer to doc and fix the error.")
            .url("https://ast-grep.github.io/guide/project/project-config.html")
            .causes(vec![e.to_string()])
    })?;
    let abs = if path.is_absolute() { path.clone() } else { std::env::current_dir().unwrap().join(&path) };
    let dir = abs.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from("."));
    Ok(Some(Project { dir, config_path: path, cfg }))
}

pub fn yaml_files(dir: &Path) -> Vec<PathBuf> {
    let mut v = Vec::new();
    let mut wb = ignore::WalkBuilder::new(dir);
    wb.sort_by_file_path(|a, b| a.cmp(b));
    for e in wb.build().flatten() {
        let p = e.path();
        if p.is_file() {
            if let Some(ext) = p.extension().and_then(|e| e.to_str()) {
                if ext == "yml" || ext == "yaml" {
                    v.push(p.to_path_buf());
                }
            }
        }
    }
    v
}

fn build_globs(gs: &Option<Vec<SerGlob>>) -> Result<Option<globset::GlobSet>, String> {
    let Some(gs) = gs else { return Ok(None) };
    let mut b = globset::GlobSetBuilder::new();
    for g in gs {
        let (pat, ci) = match g {
            SerGlob::Str(s) => (s.clone(), false),
            SerGlob::Obj { glob, case_insensitive } => (glob.clone(), *case_insensitive),
        };
        let gl = globset::GlobBuilder::new(&pat).case_insensitive(ci).literal_separator(true).build().map_err(|e| e.to_string())?;
        b.add(gl);
    }
    b.build().map(Some).map_err(|e| e.to_string())
}

/// Load global utils from utilDirs
pub fn load_global_utils(proj: Option<&Project>) -> Result<Arc<BTreeMap<String, Rule>>, CliError> {
    let mut map = BTreeMap::new();
    let Some(p) = proj else { return Ok(Arc::new(map)) };
    let Some(dirs) = &p.cfg.util_dirs else { return Ok(Arc::new(map)) };
    let mut sers: Vec<(PathBuf, SerUtilConfig)> = Vec::new();
    for d in dirs {
        let dir = p.dir.join(d);
        for f in yaml_files(&dir) {
            let text = std::fs::read_to_string(&f).unwrap_or_default();
            for doc in serde_yaml::Deserializer::from_str(&text) {
                match SerUtilConfig::deserialize(doc) {
                    Ok(u) => sers.push((f.clone(), u)),
                    Err(e) => {
                        return Err(CliError::new(format!("Cannot parse rule {}", f.display()), 8)
                            .help("The file is not a valid ast-grep rule. Please refer to doc and fix the error.")
                            .url("https://ast-grep.github.io/guide/rule-config.html")
                            .causes(vec!["Fail to parse yaml as RuleConfig".into(), e.to_string()]));
                    }
                }
            }
        }
    }
    let names: Vec<String> = sers.iter().map(|s| s.1.id.clone()).collect();
    for (f, u) in &sers {
        let lang = Lang::from_name(&u.language.0).unwrap();
        let mut local_names: Vec<String> = u.utils.as_ref().map(|x| x.keys().cloned().collect()).unwrap_or_default();
        local_names.extend(names.iter().cloned());
        let nf = |n: &str| local_names.iter().any(|x| x == n);
        let env = CompileEnv { lang, util_names: &nf };
        let r = compile_rule(&u.rule, &env).map_err(|e| {
            CliError::new(format!("Cannot parse rule {}", f.display()), 8)
                .help("The file is not a valid ast-grep rule. Please refer to doc and fix the error.")
                .url("https://ast-grep.github.io/guide/rule-config.html")
                .causes({
                    let mut c = vec!["Fail to parse yaml as Rule.".to_string(), "`rule` is not configured correctly.".to_string()];
                    c.extend(e.0);
                    c
                })
        })?;
        map.insert(u.id.clone(), r);
    }
    Ok(Arc::new(map))
}

/// parse rule configs from YAML text
pub fn parse_rules(text: &str, name: &str, utils: Arc<BTreeMap<String, Rule>>) -> Result<Vec<RuleConfig>, CliError> {
    let mut out = Vec::new();
    for doc in serde_yaml::Deserializer::from_str(text) {
        let v = serde_yaml::Value::deserialize(doc);
        let v = match v {
            Ok(v) => v,
            Err(e) => return Err(parse_rule_error(name, vec!["Fail to parse yaml as RuleConfig".into(), e.to_string()])),
        };
        if v.is_null() {
            continue;
        }
        let ser: SerRuleConfig = match serde_yaml::from_value(v) {
            Ok(s) => s,
            Err(e) => return Err(parse_rule_error(name, vec!["Fail to parse yaml as RuleConfig".into(), e.to_string()])),
        };
        let lang = Lang::from_name(&ser.language.0).unwrap();
        let core = RuleCore::compile(&ser.core, lang, utils.clone(), ser.rewriters.as_ref()).map_err(|e| {
            let mut c = vec!["Fail to parse yaml as Rule.".to_string()];
            c.extend(e.0);
            parse_rule_error(name, c)
        })?;
        let files = build_globs(&ser.files).map_err(|e| parse_rule_error(name, vec![e]))?;
        let ignores = build_globs(&ser.ignores).map_err(|e| parse_rule_error(name, vec![e]))?;
        let has_fix = ser.core.fix.is_some();
        out.push(RuleConfig {
            id: ser.id,
            lang,
            core,
            severity: ser.severity,
            message: ser.message,
            note: ser.note,
            labels: ser.labels,
            files,
            ignores,
            url: ser.url,
            metadata: ser.metadata,
            has_fix,
        });
    }
    Ok(out)
}

pub fn load_project_rules(p: &Project, utils: Arc<BTreeMap<String, Rule>>) -> Result<Vec<RuleConfig>, CliError> {
    let mut rules = Vec::new();
    for d in &p.cfg.rule_dirs {
        let dir = p.dir.join(d);
        for f in yaml_files(&dir) {
            let text = std::fs::read_to_string(&f).map_err(|e| {
                CliError::new(format!("Cannot read rule {}", f.display()), 5).causes(vec![e.to_string()])
            })?;
            let disp = f.strip_prefix(std::env::current_dir().unwrap_or_default()).map(|x| x.to_path_buf()).unwrap_or(f.clone());
            let mut rs = parse_rules(&text, &disp.display().to_string(), utils.clone())?;
            rules.append(&mut rs);
        }
    }
    Ok(rules)
}

impl RuleConfig {
    pub fn applies_to(&self, rel_path: &str) -> bool {
        let p = rel_path.strip_prefix("./").unwrap_or(rel_path);
        if let Some(f) = &self.files {
            if !f.is_match(p) {
                return false;
            }
        }
        if let Some(ig) = &self.ignores {
            if ig.is_match(p) {
                return false;
            }
        }
        true
    }
}
