pub fn sev_display(s: Severity) -> &'static str {
    match s {
        Severity::Hint => "help",
        Severity::Info => "note",
        Severity::Warning => "warning",
        Severity::Error => "error",
        Severity::Off => "off",
    }
}

fn override_values(m: &ArgMatches, name: &str) -> Option<Vec<String>> {
    if m.value_source(name) != Some(clap::parser::ValueSource::CommandLine) {
        return None;
    }
    Some(m.get_many::<String>(name).map(|v| v.cloned().collect()).unwrap_or_default())
}

pub fn load_rules_for(m: &ArgMatches, top_config: Option<&str>) -> Result<(Vec<RuleConfig>, Option<Project>), CliError> {
    let config = m.get_one::<String>("config").map(|s| s.as_str()).or(top_config);
    if let Some(text) = m.get_one::<String>("inline-rules") {
        let proj = find_project(config).ok().flatten();
        let utils = load_global_utils(proj.as_ref())?;
        let rules = parse_rules(text, "INLINE_RULES", utils)?;
        return Ok((rules, proj));
    }
    if let Some(file) = m.get_one::<String>("rule") {
        let proj = find_project(config).ok().flatten();
        let utils = load_global_utils(proj.as_ref())?;
        let text = std::fs::read_to_string(file).map_err(|e| {
            CliError::new(format!("Cannot read rule {}", file), 5)
                .help("The rule file either does not exist or cannot be opened.")
                .url("https://ast-grep.github.io/guide/rule-config.html")
                .causes(vec![e.to_string()])
        })?;
        let rules = parse_rules(&text, file, utils)?;
        return Ok((rules, proj));
    }
    let proj = find_project(config)?;
    let Some(proj) = proj else { return Err(project_not_exist()) };
    let utils = load_global_utils(Some(&proj))?;
    let rules = load_project_rules(&proj, utils)?;
    Ok((rules, Some(proj)))
}

pub struct Diagnostic<'a> {
    pub rule: &'a RuleConfig,
    pub m: Match,
    pub severity: Severity,
}

pub fn labels_for(rule: &RuleConfig, tree: &Tree, m: &Match) -> Vec<Label> {
    let n = tree.n(m.node);
    if let Some(lc) = &rule.labels {
        let mut v = Vec::new();
        for (var, cfg) in lc {
            let range = if let Some(&id) = m.env.single.get(var) {
                Some((tree.n(id).start, tree.n(id).end))
            } else if let Some(ns) = m.env.multi.get(var) {
                if ns.is_empty() {
                    None
                } else {
                    Some((tree.n(ns[0]).start, tree.n(*ns.last().unwrap()).end))
                }
            } else {
                None
            };
            if let Some((s, e)) = range {
                v.push(Label {
                    primary: cfg.style == LabelStyle::Primary,
                    start: s,
                    end: e,
                    message: cfg.message.clone().unwrap_or_default(),
                });
            }
        }
        if !v.is_empty() {
            v.sort_by_key(|l| (l.start, l.end));
            return v;
        }
    }
    vec![Label { primary: true, start: n.start, end: n.end, message: String::new() }]
}

pub fn format_message(rule: &RuleConfig, tree: &Tree, m: &Match) -> String {
    let t = crate::fixer::Template::parse(&rule.message);
    let s = t.generate(tree, &m.env);
    let n = tree.n(m.node);
    let indent = crate::fixer::indent_at(&tree.src[..n.start]);
    crate::fixer::indent_text(&s, 0, indent)
}

fn yaml_to_json(v: &serde_yaml::Value) -> Value {
    serde_json::to_value(v).unwrap_or(Value::Null)
}

pub fn scan_cmd(m: &ArgMatches, top_config: Option<&str>) -> i32 {
    let (mut rules, _proj) = match load_rules_for(m, top_config) {
        Ok(x) => x,
        Err(e) => {
            e.print();
            return e.code;
        }
    };
    // severity overrides
    let all_ids: Vec<String> = rules.iter().map(|r| r.id.clone()).collect();
    let _ = all_ids;
    for (name, sev) in [
        ("error", Severity::Error),
        ("warning", Severity::Warning),
        ("info", Severity::Info),
        ("hint", Severity::Hint),
        ("off", Severity::Off),
    ] {
        if let Some(ids) = override_values(m, name) {
            for r in rules.iter_mut() {
                if ids.is_empty() || ids.contains(&r.id) {
                    r.severity = sev;
                }
            }
        }
    }
    if let Some(f) = m.get_one::<String>("filter") {
        if let Ok(re) = regex::Regex::new(f) {
            rules.retain(|r| re.is_match(&r.id));
        }
    }
    let rules: Vec<RuleConfig> = rules.into_iter().filter(|r| r.severity != Severity::Off).collect();
    let color = use_color(m);
    let json = json_style(m);
    let format = m.get_one::<String>("format").cloned();
    let style = m.get_one::<String>("report-style").cloned().unwrap_or_else(|| "rich".into());
    let include_meta = m.get_flag("include-metadata");
    let update_all = m.get_flag("update-all");
    let max_results = m.get_one::<std::num::NonZeroUsize>("max-results").map(|x| x.get());
    let (before, after) = context_of(m);
    let _ = (before, after);
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    let mut jp = json.map(JsonPrinter::new);
    let mut error_count = 0usize;
    let mut sarif_results: Vec<Value> = Vec::new();
    let mut applied = 0usize;
    let mut total = 0usize;
    let mut files_with_matches = Vec::new();
    let fwm = m.get_flag("files-with-matches");

    let mut process = |disp: &str, src: String, flang: Lang, file_path: Option<&std::path::Path>, out: &mut std::io::StdoutLock| -> bool {
        let applicable: Vec<&RuleConfig> = rules.iter().filter(|r| r.lang == flang && r.applies_to(disp)).collect();
        if applicable.is_empty() {
            return true;
        }
        let tree = flang.parse(&src);
        let mut edits: Vec<(usize, usize, String)> = Vec::new();
        let mut file_matched = false;
        for r in applicable {
            let ms = r.core.find_all(&tree);
            for mt in ms {
                if let Some(mx) = max_results {
                    if total >= mx {
                        return false;
                    }
                }
                total += 1;
                file_matched = true;
                if r.severity == Severity::Error {
                    error_count += 1;
                }
                let msg = format_message(r, &tree, &mt);
                let labels = labels_for(r, &tree, &mt);
                let rep = if r.has_fix { r.core.replacement(&tree, &mt, 0) } else { None };
                if fwm {
                    continue;
                }
                if let Some(jp) = jp.as_mut() {
                    let mut obj = match_json(&tree, mt.node, &mt.env, disp, flang.name(), rep.clone());
                    obj.insert("ruleId".into(), Value::String(r.id.clone()));
                    obj.insert("severity".into(), Value::String(r.severity.as_str().into()));
                    obj.insert("note".into(), r.note.clone().map(Value::String).unwrap_or(Value::Null));
                    obj.insert("message".into(), Value::String(msg.clone()));
                    let lj: Vec<Value> = labels
                        .iter()
                        .map(|l| {
                            let mut lm = Map::new();
                            lm.insert("text".into(), Value::String(tree.src[l.start..l.end].to_string()));
                            lm.insert("range".into(), range_json(&tree, l.start, l.end));
                            if !l.message.is_empty() {
                                lm.insert("message".into(), Value::String(l.message.clone()));
                            }
                            lm.insert("style".into(), Value::String(if l.primary { "primary" } else { "secondary" }.into()));
                            Value::Object(lm)
                        })
                        .collect();
                    obj.insert("labels".into(), Value::Array(lj));
                    if include_meta {
                        if let Some(md) = &r.metadata {
                            obj.insert("metadata".into(), yaml_to_json(&serde_yaml::Value::Mapping(md.clone())));
                        }
                    }
                    jp.item(out, &Value::Object(obj));
                    continue;
                }
                if update_all {
                    if let Some(rp) = rep {
                        edits.push(rp);
                    }
                    continue;
                }
                let n = tree.n(mt.node);
                match format.as_deref() {
                    Some("github") => {
                        let (sl, _) = tree.point(n.start);
                        let (el, _) = tree.point(n.end);
                        let level = match r.severity {
                            Severity::Error => "error",
                            Severity::Warning => "warning",
                            _ => "notice",
                        };
                        let _ = writeln!(out, "::{} file={},line={},endLine={},title={}::{}", level, disp, sl + 1, el + 1, r.id, msg);
                        continue;
                    }
                    Some("sarif") => {
                        let region = |s: usize, e: usize, snippet: bool| -> Value {
                            let (sl, _) = crate::rule::char_point(&tree, s);
                            let (el, _) = crate::rule::char_point(&tree, e);
                            let sc = crate::rule::char_point(&tree, s).1;
                            let ec = crate::rule::char_point(&tree, e).1;
                            let mut m = Map::new();
                            m.insert("byteLength".into(), json!(e - s));
                            m.insert("byteOffset".into(), json!(s));
                            m.insert("endColumn".into(), json!(ec + 1));
                            m.insert("endLine".into(), json!(el + 1));
                            if snippet {
                                m.insert("snippet".into(), json!({"text": &tree.src[s..e]}));
                            }
                            m.insert("startColumn".into(), json!(sc + 1));
                            m.insert("startLine".into(), json!(sl + 1));
                            Value::Object(m)
                        };
                        let mut res = Map::new();
                        if let Some((s, e, text)) = &rep {
                            res.insert(
                                "fixes".into(),
                                json!([{
                                    "artifactChanges": [{
                                        "artifactLocation": {"uri": disp},
                                        "replacements": [{
                                            "deletedRegion": region(*s, *e, false),
                                            "insertedContent": {"text": text}
                                        }]
                                    }],
                                    "description": {"text": "Apply suggested fix"}
                                }]),
                            );
                        }
                        let level = match r.severity {
                            Severity::Error => "error",
                            Severity::Warning => "warning",
                            _ => "note",
                        };
                        res.insert("level".into(), json!(level));
                        res.insert(
                            "locations".into(),
                            json!([{"physicalLocation": {"artifactLocation": {"uri": disp}, "region": region(n.start, n.end, true)}}]),
                        );
                        res.insert("message".into(), json!({"text": msg}));
                        res.insert("ruleId".into(), json!(r.id));
                        sarif_results.push(Value::Object(res));
                        continue;
                    }
                    _ => {}
                }
                let sev = sev_display(r.severity);
                let mut s = String::new();
                match style.as_str() {
                    "short" => {
                        let (l, _) = tree.point(n.start);
                        let c = tree.src[tree.line_starts[l]..n.start].chars().count() + 1;
                        let lab = labels.iter().find(|x| x.primary).cloned().unwrap_or(labels[0].clone());
                        let (l2, _) = tree.point(lab.start);
                        let c2 = tree.src[tree.line_starts[l2]..lab.start].chars().count() + 1;
                        let _ = (l, c);
                        s.push_str(&format!("{}:{}:{}: {}[{}]: {}\n", disp, l2 + 1, c2, sev, r.id, msg));
                    }
                    "medium" => {
                        let lab = labels.iter().find(|x| x.primary).cloned().unwrap_or(labels[0].clone());
                        let (l2, _) = tree.point(lab.start);
                        let c2 = tree.src[tree.line_starts[l2]..lab.start].chars().count() + 1;
                        s.push_str(&format!("{}:{}:{}: {}[{}]: {}\n", disp, l2 + 1, c2, sev, r.id, msg));
                        if let Some(note) = &r.note {
                            if rep.is_some() {
                                s.push_str(&format!("Note:\n{}\n\n", note));
                            } else {
                                s.push_str(&format!(" = {}\n", note));
                            }
                        }
                    }
                    _ => {
                        if let Some((rs, re, rtext)) = &rep {
                            if color {
                                s.push_str(&format!("\x1b[3;36m{}{}\n", disp, RESET));
                            } else {
                                s.push_str(disp);
                                s.push('\n');
                            }
                            s.push_str(&format!("{}[{}]: {}\n", sev, r.id, msg));
                            let mut e1 = vec![(*rs, *re, rtext.clone())];
                            let new = apply_edits(&src, &mut e1);
                            print_diff(&mut s, &src, &new, 3, color);
                            if let Some(note) = &r.note {
                                s.push_str(&format!("Note:\n{}\n\n", note));
                            }
                        } else {
                            let notes: Vec<String> = r.note.iter().cloned().collect();
                            render_rich(&mut s, sev, &r.id, &msg, disp, &tree, &labels, &notes);
                        }
                    }
                }
                let _ = out.write_all(s.as_bytes());
            }
        }
        if fwm && file_matched {
            files_with_matches.push(disp.to_string());
            let _ = writeln!(out, "{}", disp);
        }
        if update_all && !edits.is_empty() {
            let mut e2 = edits.clone();
            e2.sort_by_key(|e| e.0);
            let mut pos = 0;
            for (s, e, _) in &e2 {
                if *s >= pos {
                    applied += 1;
                    pos = *e;
                }
            }
            let new = apply_edits(&src, &mut edits);
            if let Some(fp) = file_path {
                let _ = std::fs::write(fp, new);
            }
        }
        true
    };

    if m.get_flag("stdin") {
        let mut src = String::new();
        let _ = std::io::stdin().read_to_string(&mut src);
        let langs: Vec<Lang> = rules.iter().map(|r| r.lang).collect();
        if let Some(&l) = langs.first() {
            process("STDIN", src, l, None, &mut out);
        }
    } else {
        let paths: Vec<String> = m.get_many::<String>("paths").map(|v| v.cloned().collect()).unwrap_or_else(|| vec![".".into()]);
        let wo = walk_opts(m);
        let files = collect(&paths, &wo);
        for f in files {
            let Some(l) = Lang::from_path(&f) else { continue };
            let Ok(bytes) = std::fs::read(&f) else { continue };
            let Ok(src) = String::from_utf8(bytes) else { continue };
            let disp = display_path(&f);
            if !process(&disp, src, l, Some(&f), &mut out) {
                break;
            }
        }
    }
    if let Some(jp) = jp.as_mut() {
        jp.end(&mut out);
    }
    if format.as_deref() == Some("sarif") {
        let doc = json!({
            "runs": [{
                "results": sarif_results,
                "tool": {"driver": {"name": "ast-grep"}}
            }],
            "version": "0.42.1"
        });
        let _ = writeln!(out, "{}", serde_json::to_string_pretty(&doc).unwrap());
    }
    if update_all && applied > 0 && json.is_none() {
        let _ = writeln!(out, "Applied {} changes", applied);
    }
    let _ = out.flush();
    let _ = BTreeMap::<u8, u8>::new();
    let _ = Arc::new(0);
    if error_count > 0 {
        CliError::new(format!("{} error(s) found in code.", error_count), 1)
            .help("Scan succeeded and found error level diagnostics in the codebase.")
            .print();
        return 1;
    }
    0
}
