pub fn test_cmd(m: &ArgMatches, top_config: Option<&str>) -> i32 {
    let config = m.get_one::<String>("config").map(|s| s.as_str()).or(top_config);
    let proj = match find_project(config) {
        Ok(Some(p)) => p,
        Ok(None) => {
            let e = project_not_exist();
            e.print();
            return e.code;
        }
        Err(e) => {
            e.print();
            return e.code;
        }
    };
    let utils = match load_global_utils(Some(&proj)) {
        Ok(u) => u,
        Err(e) => {
            e.print();
            return e.code;
        }
    };
    let rules = match load_project_rules(&proj, utils) {
        Ok(r) => r,
        Err(e) => {
            e.print();
            return e.code;
        }
    };
    let include_off = m.get_flag("include-off");
    let update_all = m.get_flag("update-all");
    let skip_snapshot = m.get_flag("skip-snapshot-tests");
    let filter = m.get_one::<String>("filter").and_then(|f| regex::Regex::new(f).ok());
    // test dirs
    let mut test_dirs: Vec<(PathBuf, Option<PathBuf>)> = Vec::new();
    if let Some(td) = m.get_one::<String>("test-dir") {
        test_dirs.push((PathBuf::from(td), None));
    } else if let Some(tc) = &proj.cfg.test_configs {
        for t in tc {
            test_dirs.push((proj.dir.join(&t.test_dir), t.snapshot_dir.clone()));
        }
    }
    let snap_override = m.get_one::<String>("snapshot-dir").map(PathBuf::from);
    // collect cases
    let mut cases: Vec<(TestCaseSer, PathBuf)> = Vec::new();
    for (dir, sd) in &test_dirs {
        let snap_dir = dir.join(snap_override.clone().or(sd.clone()).unwrap_or_else(|| PathBuf::from("__snapshots__")));
        for f in yaml_files(dir) {
            if f.starts_with(&snap_dir) {
                continue;
            }
            let text = std::fs::read_to_string(&f).unwrap_or_default();
            for doc in serde_yaml::Deserializer::from_str(&text) {
                match TestCaseSer::deserialize(doc) {
                    Ok(tc) => cases.push((tc, snap_dir.clone())),
                    Err(e) => {
                        let err = CliError::new(format!("Cannot parse test case {}", f.display()), 8)
                            .help("The file is not a valid ast-grep test case. Please refer to doc and fix the error.")
                            .url("https://ast-grep.github.io/guide/test-rule.html")
                            .causes(vec![e.to_string()]);
                        err.print();
                        return err.code;
                    }
                }
            }
        }
    }
    if let Some(re) = &filter {
        cases.retain(|c| re.is_match(&c.0.id));
    }
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    let _ = writeln!(out, "Running {} tests", cases.len());
    let mut details = String::new();
    let mut summary = String::new();
    let mut passed = 0;
    let mut failed = 0;
    let mut any_nm = false;
    for (tc, snap_dir) in &cases {
        let Some(rule) = rules.iter().find(|r| r.id == tc.id && (include_off || r.severity != Severity::Off)) else {
            let _ = writeln!(out, "Configuration not found! {}", tc.id);
            continue;
        };
        let snap_path = snap_dir.join(format!("{}-snapshot.yml", tc.id));
        let existing: Option<SnapshotFile> =
            std::fs::read_to_string(&snap_path).ok().and_then(|t| serde_yaml::from_str(&t).ok());
        let mut new_snaps: BTreeMap<String, TestSnapshot> = BTreeMap::new();
        let mut chars = String::new();
        let mut ok = true;
        let mut updated = false;
        for code in &tc.valid {
            let tree = rule.lang.parse(code);
            let ms = rule.core.find_all(&tree);
            if ms.is_empty() {
                chars.push('.');
            } else {
                chars.push('N');
                ok = false;
                any_nm = true;
                details.push_str(&format!(
                    "[Noisy] Expect {} to report no issue, but some issues found in:\n\n{}\n",
                    tc.id,
                    indent2(code)
                ));
            }
        }
        for code in &tc.invalid {
            let tree = rule.lang.parse(code);
            let ms = rule.core.find_all(&tree);
            let Some(first) = ms.first() else {
                chars.push('M');
                ok = false;
                any_nm = true;
                details.push_str(&format!(
                    "[Missing] Expect rule {} to report issues, but none found in:\n\n{}\n",
                    tc.id,
                    indent2(code)
                ));
                continue;
            };
            if skip_snapshot {
                chars.push('.');
                continue;
            }
            let labels = labels_for(rule, &tree, first);
            let fixed = if rule.has_fix {
                rule.core.replacement(&tree, first, 0).map(|(s, e, r)| {
                    let mut t = code.clone();
                    t.replace_range(s..e, &r);
                    t
                })
            } else {
                None
            };
            let snap = TestSnapshot {
                fixed,
                labels: labels
                    .iter()
                    .map(|l| LabelSnap {
                        source: code[l.start..l.end].to_string(),
                        message: if l.message.is_empty() { None } else { Some(l.message.clone()) },
                        style: if l.primary { "primary".into() } else { "secondary".into() },
                        start: l.start,
                        end: l.end,
                    })
                    .collect(),
            };
            let old = existing.as_ref().and_then(|e| e.snapshots.get(code));
            new_snaps.insert(code.clone(), snap.clone());
            match old {
                Some(o) if *o == snap => chars.push('.'),
                _ => {
                    if update_all {
                        chars.push('U');
                        updated = true;
                        details.push_str(&format!(
                            "[Updated] Rule {}'s snapshot baseline has been updated.\n\n{}\n",
                            tc.id,
                            indent2(code)
                        ));
                    } else {
                        chars.push('W');
                        ok = false;
                        let new_yaml = serde_yaml::to_string(&snap).unwrap_or_default();
                        match old {
                            None => {
                                details.push_str(&format!(
                                    "[Wrong] No {} baseline found.\nGenerated Snapshot:\n{}For Code:\n{}\n",
                                    tc.id,
                                    indent2(&new_yaml),
                                    indent2(code)
                                ));
                            }
                            Some(o) => {
                                let old_yaml = serde_yaml::to_string(o).unwrap_or_default();
                                let mut d = String::new();
                                print_diff(&mut d, &old_yaml, &new_yaml, 3, false);
                                details.push_str(&format!(
                                    "[Wrong] {} snapshot is different from baseline.\nDiff:\n{}For Code:\n{}\n",
                                    tc.id,
                                    d,
                                    indent2(code)
                                ));
                            }
                        }
                    }
                }
            }
        }
        if updated {
            let mut snaps = existing.map(|e| e.snapshots).unwrap_or_default();
            for (k, v) in new_snaps {
                snaps.insert(k, v);
            }
            let file = SnapshotFile { id: tc.id.clone(), snapshots: snaps };
            let _ = std::fs::create_dir_all(snap_dir);
            let _ = std::fs::write(&snap_path, serde_yaml::to_string(&file).unwrap_or_default());
        }
        if ok {
            passed += 1;
            summary.push_str(&format!("PASS {}  {}\n", tc.id, chars));
        } else {
            failed += 1;
            summary.push_str(&format!("FAIL {}  {}\n", tc.id, chars));
        }
    }
    let _ = write!(out, "\n----------- Case Details -----------\n{}{}\n", details, summary);
    if failed == 0 {
        let _ = writeln!(out, "test result: ok. {} passed; {} failed;", passed, failed);
        let _ = out.flush();
        0
    } else {
        let _ = out.flush();
        let e = if any_nm {
            CliError::new(format!("test failed. {} passed; {} failed;", passed, failed), 4)
                .help("You can use ast-grep playground to debug your rules and test cases.")
                .url("https://ast-grep.github.io/playground.html")
        } else {
            CliError::new(format!("test failed. {} passed; {} failed;", passed, failed), 4)
                .help("Test failed due to mismatching snapshots. Run with `--update-all` to update all snapshots, or `--interactive` to update selectively.")
                .url("https://ast-grep.github.io/guide/test-rule.html")
        };
        e.print();
        e.code
    }
}
