// `new` command
use crate::errors::*;
use crate::lang::Lang;
use crate::project::*;
use clap::ArgMatches;
use std::io::IsTerminal;
use std::path::PathBuf;

fn insufficient(what: &str) -> CliError {
    CliError::new("Insufficient command line argument provided to use `--yes` option.", 22)
        .help(format!("You need to provide `{}` in command line to use non-interactive `new`.", what))
}

fn not_tty() -> i32 {
    eprintln!("Error: The input device is not a TTY");
    1
}

fn already_exists(p: &std::path::Path) -> CliError {
    CliError::new(format!("File `{}` already exists.", p.display()), 17)
        .help("The item you want to create already exists. Try editing the existing file or create a new one with a different name?")
}

fn write_new(p: &std::path::Path, content: &str) -> Result<(), CliError> {
    if p.exists() {
        return Err(already_exists(p));
    }
    if let Some(d) = p.parent() {
        let _ = std::fs::create_dir_all(d);
    }
    std::fs::write(p, content).map_err(|e| CliError::new(format!("Cannot write file {}", p.display()), 5).causes(vec![e.to_string()]))
}

pub fn new_cmd(m: &ArgMatches, top_config: Option<&str>) -> i32 {
    let (sub, sm) = match m.subcommand() {
        Some((s, sm)) => (Some(s.to_string()), sm.clone()),
        None => (None, m.clone()),
    };
    let yes = sm.get_flag("yes") || m.get_flag("yes");
    let name = sm.get_one::<String>("name").cloned().or_else(|| if sub.is_some() { m.get_one::<String>("name").cloned() } else { None });
    let lang = sm.get_one::<String>("lang").cloned().or_else(|| m.get_one::<String>("lang").cloned());
    let config = sm.get_one::<String>("config").cloned().or_else(|| m.get_one::<String>("config").cloned()).or(top_config.map(|s| s.to_string()));
    let r = match sub.as_deref() {
        None => {
            if yes {
                Err(insufficient("entity"))
            } else {
                return not_tty();
            }
        }
        Some("project") => new_project(yes),
        Some(kind) => {
            if !yes && !std::io::stdin().is_terminal() {
                return not_tty();
            }
            new_item(kind, name, lang, config.as_deref())
        }
    };
    match r {
        Ok(()) => 0,
        Err(e) => {
            e.print();
            e.code
        }
    }
}

fn new_project(yes: bool) -> Result<(), CliError> {
    if let Ok(Some(_)) = find_project(None) {
        return Err(CliError::new("ast-grep project already exists.", 17)
            .help("You are already inside a sub-folder of an ast-grep project. Try finding sgconfig.yml in ancestor directory?")
            .url("https://ast-grep.github.io/guide/scan-project.html"));
    }
    if !yes && !std::io::stdin().is_terminal() {
        eprintln!("Error: The input device is not a TTY");
        std::process::exit(1);
    }
    println!("Creating a new ast-grep project...");
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let rules = cwd.join("rules");
    let tests = cwd.join("rule-tests");
    let utils = cwd.join("utils");
    for d in [&rules, &tests, &utils] {
        let _ = std::fs::create_dir_all(d);
        let _ = std::fs::write(d.join(".gitkeep"), "");
    }
    let content = format!(
        "ruleDirs:\n- {}\ntestConfigs:\n- testDir: {}\nutilDirs:\n- {}\n",
        rules.display(),
        tests.display(),
        utils.display()
    );
    let _ = std::fs::write(cwd.join("sgconfig.yml"), content);
    println!("Your new ast-grep project has been created!");
    Ok(())
}

fn new_item(kind: &str, name: Option<String>, lang: Option<String>, config: Option<&str>) -> Result<(), CliError> {
    let proj = find_project(config)?.ok_or_else(project_not_exist)?;
    let Some(name) = name else { return Err(insufficient("name")) };
    let lang_name = |l: &Option<String>| -> Result<&'static str, CliError> {
        match l.as_deref().and_then(Lang::from_name) {
            Some(l) => Ok(l.name()),
            None => Err(insufficient("lang")),
        }
    };
    match kind {
        "rule" => {
            let ln = lang_name(&lang)?;
            let dir = proj.cfg.rule_dirs.first().map(|d| proj.dir.join(d)).unwrap_or_else(|| proj.dir.join("rules"));
            let path = dir.join(format!("{}.yml", name));
            let content = format!(
                "# yaml-language-server: $schema=https://raw.githubusercontent.com/ast-grep/ast-grep/main/schemas/rule.json\n\nid: {}\nmessage: Add your rule message here....\nseverity: error # error, warning, info, hint\nlanguage: {}\nrule:\n  pattern: Your Rule Pattern here...\n# utils: Extract repeated rule as local utility here.\n# note: Add detailed explanation for the rule.",
                name, ln
            );
            write_new(&path, &content)?;
            println!("Created rules at {}", path.display());
            if let Some(tc) = proj.cfg.test_configs.as_ref().and_then(|t| t.first()) {
                let tdir = proj.dir.join(&tc.test_dir);
                let tpath = tdir.join(format!("{}-test.yml", name));
                write_new(&tpath, &test_content(&name))?;
                println!("Created test at {}", tpath.display());
            }
            Ok(())
        }
        "test" => {
            let Some(tc) = proj.cfg.test_configs.as_ref().and_then(|t| t.first()) else {
                return Err(CliError::new("No test file directory is configured.", 2)
                    .help("Please add a test directory in sgconfig.yml.")
                    .url("https://ast-grep.github.io/reference/sgconfig.html"));
            };
            let tdir = proj.dir.join(&tc.test_dir);
            let tpath = tdir.join(format!("{}-test.yml", name));
            write_new(&tpath, &test_content(&name))?;
            println!("Created test at {}", tpath.display());
            Ok(())
        }
        "util" => {
            let ln = lang_name(&lang)?;
            let Some(ud) = proj.cfg.util_dirs.as_ref().and_then(|t| t.first()) else {
                return Err(CliError::new("No util file directory is configured.", 2)
                    .help("Please add a util directory in sgconfig.yml.")
                    .url("https://ast-grep.github.io/reference/sgconfig.html"));
            };
            let path = proj.dir.join(ud).join(format!("{}.yml", name));
            let content = format!(
                "id: {}\nlanguage: {}\nrule:\n  pattern: Your Rule Pattern here...\n# utils: Extract repeated rule as local utility here.",
                name, ln
            );
            write_new(&path, &content)?;
            println!("Created util at {}", path.display());
            Ok(())
        }
        _ => Ok(()),
    }
}

fn test_content(name: &str) -> String {
    format!("id: {}\nvalid:\n- \"valid code\"\ninvalid:\n- \"invalid code\"\n", name)
}
