                let m = self.b.mark();
                self.bump();
                self.namespace_name();
                self.b.field_last("name");
                if self.at("{") {
                    self.statement_block();
                    self.b.field_last("body");
                }
                self.b.wrap(m, "internal_module", true);
                true
            }
            "module" if (t2.t == T::Ident || t2.t == T::Str) && !t2.nl => {
                let m = self.b.mark();
                self.module_decl(m);
