                let m = self.b.mark();
                self.bump();
                self.b.field_last("name");
                // tree-sitter: global as identifier name
                self.statement_block();
                self.b.field_last("body");
                self.b.wrap(m, "internal_module", true);
                true
            }
            "declare" if !t2.nl && (t2.t == T::Ident) => {
                let m = self.b.mark();
                self.bump();
                if self.at_id("global") {
                    let mm = self.b.mark();
                    self.bump();
                    self.b.rename(self.b.last().unwrap(), "identifier");
                    self.b.nodes[self.b.last().unwrap() as usize].named = true;
                    self.b.field_last("name");
                    if self.at("{") {
                        self.statement_block();
                        self.b.field_last("body");
                    }
