            self.bump();
            self.ts_type_no_cond();
            self.b.field_last("right");
            self.expect("?");
            self.ts_type();
            self.b.field_last("consequence");
            self.expect(":");
            self.ts_type();
            self.b.field_last("alternative");
            self.b.wrap(m, "conditional_type", true);
        }
    }

    fn union_type(&mut self) {
        let m = self.b.mark();
        if self.at("|") {
            self.bump();
            self.intersection_type();
            self.b.wrap(m, "union_type", true);
        } else {
            self.intersection_type();
        }
        while self.at("|") {
            self.bump();
            self.intersection_type();
            self.b.wrap(m, "union_type", true);
        }
    }

    fn intersection_type(&mut self) {
        let m = self.b.mark();
        if self.at("&") {
            self.bump();
            self.type_operator();
            self.b.wrap(m, "intersection_type", true);
        } else {
            self.type_operator();
        }
        while self.at("&") {
            self.bump();
            self.type_operator();
            self.b.wrap(m, "intersection_type", true);
        }
    }

    fn type_operator(&mut self) {
        let m = self.b.mark();
        let t = self.peek();
        let tx = self.tx(t);
        let t2 = self.peek2();
        let starts_type = |p: &P, t2: Tok| -> bool {
            let x = p.tx(t2);
            t2.t == T::Ident || t2.t == T::Str || t2.t == T::Num || matches!(x, "(" | "[" | "{" | "`" | "-")
        };
        match tx {
            "keyof" if starts_type(self, t2) => {
                self.bump();
                self.type_operator();
                self.b.wrap(m, "index_type_query", true);
                return;
            }
            "readonly" if starts_type(self, t2) => {
                self.bump();
                self.type_operator();
                self.b.wrap(m, "readonly_type", true);
                return;
            }
            "unique" if self.tx(t2) == "symbol" => {
                self.bump();
                self.bump();
                return;
            }
            "infer" if t2.t == T::Ident => {
                self.bump();
                self.bump_named("type_identifier");
                if self.at_id("extends") {
                    // infer U extends X
                    let save = self.pos;
                    let cp = self.b.checkpoint();
                    self.bump();
                    self.ts_type_no_cond();
                    if self.at("?") {
                        // it was a conditional: rollback
                        self.b.restore(cp);
                        self.pos = save;
                    }
                }
                self.b.wrap(m, "infer_type", true);
                return;
            }
            _ => {}
        }
        self.postfix_type();
    }

    fn postfix_type(&mut self) {
        let m = self.b.mark();
        self.primary_type();
        loop {
            let t = self.peek();
            if t.nl {
                break;
            }
            if self.at("[") {
                let t2 = self.peek2();
                if self.tx(t2) == "]" {
                    self.bump();
                    self.bump();
                    self.b.wrap(m, "array_type", true);
                } else {
                    self.bump();
                    self.ts_type();
                    self.expect("]");
                    self.b.wrap(m, "lookup_type", true);
                }
                continue;
            }
            break;
        }
    }

    fn primary_type(&mut self) {
        let m = self.b.mark();
        let t = self.peek_re();
        let tx = self.tx(t);
        match t.t {
            T::Str => {
                self.string_lit();
                self.b.wrap(m, "literal_type", true);
                return;
            }
            T::Num => {
                self.bump_named("number");
                self.b.wrap(m, "literal_type", true);
                return;
            }
            T::Punct => match tx {
                "-" => {
                    let mu = self.b.mark();
                    self.bump();
                    self.b.field_last("operator");
                    self.bump_named("number");
                    self.b.field_last("argument");
                    self.b.wrap(mu, "unary_expression", true);
                    self.b.wrap(m, "literal_type", true);
                    return;
                }
                "(" => {
                    self.bump();
                    self.ts_type();
                    self.expect(")");
                    self.b.wrap(m, "parenthesized_type", true);
                    return;
                }
                "[" => {
                    self.tuple_type();
                    return;
                }
                "{" => {
                    self.object_type_body("object_type");
                    return;
                }
                "`" => {
                    self.template_literal_type();
                    return;
                }
                "*" => {
                    self.bump();
                    self.b.wrap(m, "existential_type", true);
                    return;
                }
                "?" => {
                    // flow maybe type
                    self.bump();
                    self.primary_type();
                    self.b.wrap(m, "flow_maybe_type", true);
                    return;
                }
                _ => {
                    let p = self.pos;
                    self.b.missing("type_identifier", true, p);
                    return;
                }
            },
            T::Ident => {}
            _ => {
                let p = self.pos;
                self.b.missing("type_identifier", true, p);
                return;
            }
        }
        match tx {
            "true" | "false" | "null" | "undefined" => {
                self.bump_named(intern(tx));
                self.b.wrap(m, "literal_type", true);
                return;
            }
            "this" => {
                self.bump_named("this");
                self.b.wrap(m, "this_type", true);
                return;
            }
            "typeof" => {
                self.bump();
                // expression: identifier / member / import(...)
                let mq = self.b.mark();
                if self.at_id("import") {
                    let mi = self.b.mark();
                    self.bump_named("import");
                    let _ = mi;
                } else {
                    self.bump_named("identifier");
                }
                loop {
                    if self.at(".") {
                        let first = self.b.stack[mq];
                        if self.b.nodes[first as usize].field.is_none() {
                            self.b.set_field(first, "object");
                        }
                        self.bump();
                        self.bump_named("property_identifier");
                        self.b.field_last("property");
                        self.b.wrap(mq, "member_expression", true);
                        continue;
                    }
                    if self.at("(") {
                        self.set_first_field_pub(mq, "function");
                        self.arguments();
                        self.b.field_last("arguments");
                        self.b.wrap(mq, "call_expression", true);
                        continue;
                    }
                    break;
                }
                if self.at("<") && !self.peek().nl {
                    self.type_arguments();
                }
                self.b.wrap(m, "type_query", true);
                return;
            }
            _ => {}
        }
        if PREDEFINED.contains(&tx) {
            let t2 = self.peek2();
            if self.tx(t2) != "." {
                self.bump();
                self.b.wrap(m, "predefined_type", true);
                return;
            }
        }
        // type identifier, nested, generic
        let mn = self.b.mark();
        let t2 = self.peek2();
        if self.tx(t2) == "." && !t2.nl {
            // nested_type_identifier: module: identifier/nested_identifier
            let mm = self.b.mark();
            self.bump_named("identifier");
            loop {
                let t2 = self.peek2();
                let t3 = self.peek_n(2);
                if self.at(".") && self.tx(self.peek_n(2)) == "." {
                    let first = self.b.stack[mm];
                    if self.b.nodes[first as usize].field.is_none() {
                        self.b.set_field(first, "object");
                    }
                    self.bump();
                    self.bump_named("property_identifier");
                    self.b.field_last("property");
                    self.b.wrap(mm, "nested_identifier", true);
                    let _ = (t2, t3);
                    continue;
                }
                break;
            }
            self.b.field_last("module");
            self.expect(".");
            self.bump_named("type_identifier");
            self.b.field_last("name");
            self.b.wrap(mn, "nested_type_identifier", true);
        } else {
            self.bump_named("type_identifier");
        }
        if self.at("<") && !self.peek().nl {
            self.b.field_last("name");
            self.type_arguments();
            self.b.field_last("type_arguments");
            self.b.wrap(m, "generic_type", true);
        }
    }

    pub fn set_first_field_pub(&mut self, m: usize, f: &'static str) {
        for i in m..self.b.stack.len() {
            let id = self.b.stack[i];
            if !self.b.nodes[id as usize].extra {
                self.b.nodes[id as usize].field = Some(f);
                return;
            }
        }
    }

    fn template_literal_type(&mut self) {
        let t = self.peek();
        self.flush_comments_to(t.s);
        let m = self.b.mark();
        let b = self.src.as_bytes();
        self.b.leaf("`", false, t.s, t.s + 1);
        let mut i = t.s + 1;
        let mut frag = i;
        loop {
            if i >= b.len() {
                self.pos = i;
                break;
            }
            match b[i] {
                b'`' => {
                    if frag < i {
                        self.b.leaf("string_fragment", true, frag, i);
                    }
                    self.b.leaf("`", false, i, i + 1);
                    self.pos = i + 1;
                    break;
                }
                b'\\' => {
                    if frag < i {
                        self.b.leaf("string_fragment", true, frag, i);
                    }
                    let e = super::js::escape_end(self.src, i);
                    self.b.leaf("escape_sequence", true, i, e);
                    i = e;
                    frag = i;
                }
                b'$' if i + 1 < b.len() && b[i + 1] == b'{' => {
                    if frag < i {
                        self.b.leaf("string_fragment", true, frag, i);
                    }
                    let ms = self.b.mark();
                    self.b.leaf("${", false, i, i + 2);
                    self.pos = i + 2;
                    self.ts_type();
                    self.expect("}");
                    self.b.wrap(ms, "template_type", true);
                    i = self.pos;
                    frag = i;
                }
                _ => i += 1,
            }
        }
        self.b.wrap(m, "template_literal_type", true);
    }

    fn tuple_type(&mut self) {
        let m = self.b.mark();
        self.bump(); // [
        while !self.at("]") && self.peek().t != T::Eof {
            let me = self.b.mark();
            let t = self.peek();
            let t2 = self.peek2();
            let tx2 = self.tx(t2);
            if self.at("...") {
                // rest: ...name: T or ...T
                let t3 = self.peek_n(2);
                if self.peek2().t == T::Ident && self.tx(t3) == ":" {
                    let mr = self.b.mark();
                    self.bump();
                    self.bump_named("identifier");
                    self.b.wrap(mr, "rest_pattern", true);
                    self.b.field_last("name");
                    self.type_annotation();
                    self.b.field_last("type");
                    self.b.wrap(me, "required_parameter", true);
                } else {
                    self.bump();
                    self.ts_type();
                    self.b.wrap(me, "rest_type", true);
                }
            } else if t.t == T::Ident && (tx2 == ":" || (tx2 == "?" && self.tx(self.peek_n(2)) == ":")) {
                self.bump_named("identifier");
                self.b.field_last("name");
                let opt = self.at("?");
                if opt {
                    self.bump();
                }
                self.type_annotation();
                self.b.field_last("type");
                self.b.wrap(me, if opt { "optional_parameter" } else { "required_parameter" }, true);
            } else {
                self.ts_type();
                if self.at("?") {
                    self.bump();
                    self.b.wrap(me, "optional_type", true);
                }
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect("]");
        self.b.wrap(m, "tuple_type", true);
    }

    fn object_type_body(&mut self, kind: &'static str) {
        let m = self.b.mark();
        self.expect("{");
        loop {
            if self.at("}") || self.peek().t == T::Eof {
                break;
            }
            if self.at(",") || self.at(";") {
                self.bump();
                continue;
            }
            let before = self.pos;
            self.type_member();
            if self.pos == before {
                self.error_token();
            }
        }
        self.expect("}");
        self.b.wrap(m, kind, true);
    }

    fn type_member(&mut self) {
        let m = self.b.mark();
        let t = self.peek();
        let tx = self.tx(t);
        // call signature
        if tx == "(" || tx == "<" {
            self.call_signature();
            self.b.wrap(m, "call_signature", true);
            return;
        }
        if tx == "new" && matches!(self.tx(self.peek2()), "(" | "<") {
            self.bump();
            if self.at("<") {
                self.type_parameters();
                self.b.field_last("type_parameters");
            }
            self.formal_parameters();
            self.b.field_last("parameters");
            if self.at(":") {
                self.type_annotation();
                self.b.field_last("type");
            }
            self.b.wrap(m, "construct_signature", true);
            return;
        }
        // modifiers: readonly, +/- readonly
        let mut modifiers = 0;
        loop {
            let t = self.peek();
            let t2 = self.peek2();
            let tx = self.tx(t);
            let tx2 = self.tx(t2);
            if (tx == "-" || tx == "+") && tx2 == "readonly" {
                self.bump();
                self.bump();
                modifiers += 1;
                continue;
            }
            if tx == "readonly" && !matches!(tx2, ":" | "?" | "(" | "," | ";" | "}" | "<") {
                self.bump();
                modifiers += 1;
                continue;
            }
            if (tx == "get" || tx == "set") && t2.t == T::Ident && !matches!(tx2, ":" | "?" | "(" | "<") {
                self.bump();
                modifiers += 1;
                continue;
            }
            break;
        }
        let _ = modifiers;
        // index signature / mapped type
        if self.at("[") {
            let t2 = self.peek2();
            let t3 = self.peek_n(2);
            let tx3 = self.tx(t3);
            if t2.t == T::Ident && (tx3 == ":" || tx3 == "in") {
                self.bump(); // [
                if tx3 == ":" {
                    self.bump_named("identifier");
                    self.b.field_last("name");
                    self.bump();
                    self.ts_type();
                    self.b.field_last("index_type");
                } else {
                    let mc = self.b.mark();
                    self.bump_named("type_identifier");
                    self.b.field_last("name");
                    self.bump(); // in
                    self.ts_type();
                    self.b.field_last("type");
                    if self.at_id("as") {
                        self.bump();
                        self.ts_type();
                        self.b.field_last("alias");
                    }
                    self.b.wrap(mc, "mapped_type_clause", true);
                }
                self.expect("]");
                // annotation variants
                let t = self.peek();
                let tx = self.tx(t);
                let ma = self.b.mark();
                if tx == "?" && self.tx(self.peek2()) == ":" {
                    let tq = self.peek();
                    let tc = self.peek2();
                    self.flush_comments_to(tq.s);
                    self.pos = tc.e;
                    self.b.leaf("?:", false, tq.s, tc.e);
                    self.ts_type();
                    self.b.wrap(ma, "opting_type_annotation", true);
                } else if (tx == "-" || tx == "+") && self.tx(self.peek2()) == "?" {
                    let tq = self.peek();
                    let tc = self.peek_n(2);
                    self.flush_comments_to(tq.s);
                    self.pos = tc.e;
                    let k = if tx == "-" { "-?:" } else { "+?:" };
                    self.b.leaf(k, false, tq.s, tc.e);
                    self.ts_type();
                    self.b.wrap(ma, if tx == "-" { "omitting_type_annotation" } else { "adding_type_annotation" }, true);
                } else if tx == ":" {
                    self.type_annotation();
                }
                if self.b.mark() > ma {
                    self.b.field_last("type");
                }
                self.b.wrap(m, "index_signature", true);
                return;
            }
        }
        // property or method signature
        self.property_name();
        self.b.field_last("name");
        if self.at("?") {
            self.bump();
        }
        if self.at("(") || self.at("<") {
            self.call_signature();
            self.b.wrap(m, "method_signature", true);
            return;
        }
        if self.at(":") {
            self.type_annotation();
            self.b.field_last("type");
        }
        self.b.wrap(m, "property_signature", true);
    }

    pub fn ts_entity_name(&mut self) {
        self.namespace_name();
    }

    /// formal parameter in TS: required_parameter / optional_parameter
    pub fn ts_formal_parameter(&mut self) {
        let m = self.b.mark();
        while self.at("@") {
            self.decorator();
            self.b.field_last("decorator");
        }
        loop {
            let t = self.peek();
            let t2 = self.peek2();
            let tx = self.tx(t);
            let next_is_name = t2.t == T::Ident || matches!(self.tx(t2), "{" | "[" | "...");
            if matches!(tx, "public" | "private" | "protected") && next_is_name {
                let ma = self.b.mark();
                self.bump();
                self.b.wrap(ma, "accessibility_modifier", true);
                continue;
            }
            if tx == "override" && next_is_name {
                let ma = self.b.mark();
                self.bump();
                self.b.wrap(ma, "override_modifier", true);
                continue;
            }
            if tx == "readonly" && next_is_name {
                self.bump();
                continue;
            }
            break;
        }
        if self.at("...") {
            self.rest_pattern();
        } else if self.at_id("this") {
            self.bump_named("this");
        } else {
            self.binding_pattern();
        }
        self.b.field_last("pattern");
        let mut optional = false;
        if self.at("?") {
            self.bump();
            optional = true;
        }
        if self.at(":") {
            self.type_annotation();
            self.b.field_last("type");
        }
        if self.at("=") {
            self.bump();
            self.assign_expr();
            self.b.field_last("value");
        }
        self.b.wrap(m, if optional { "optional_parameter" } else { "required_parameter" }, true);
    }

    /// class members with TS modifiers. Returns true if handled.
    pub fn ts_class_member(&mut self, m: usize) -> bool {
        let mut is_abstract = false;
        // modifiers
        loop {
            let t = self.peek();
            let t2 = self.peek2();
            let tx = self.tx(t);
            let tx2 = self.tx(t2);
            let is_mod_pos = t2.t != T::Eof
                && !t2.nl
                && !matches!(tx2, "(" | "=" | ";" | ":" | "}" | "?" | "!" | "<" | ",")
                || (t2.t == T::Punct && tx2 == "[" )
                || (t2.t == T::Punct && tx2 == "*")
                || (t2.t == T::Punct && tx2 == "#");
            if !is_mod_pos || t.t != T::Ident {
                break;
            }
            match tx {
                "public" | "private" | "protected" => {
                    let ma = self.b.mark();
                    self.bump();
                    self.b.wrap(ma, "accessibility_modifier", true);
                }
                "override" => {
                    let ma = self.b.mark();
                    self.bump();
                    self.b.wrap(ma, "override_modifier", true);
                }
                "static" | "readonly" | "declare" => {
                    self.bump();
                }
                "abstract" => {
                    self.bump();
                    is_abstract = true;
                }
                _ => break,
            }
        }
        // index signature
        if self.at("[") {
            let t2 = self.peek2();
            let t3 = self.peek_n(2);
            if t2.t == T::Ident && self.tx(t3) == ":" {
                self.bump();
                self.bump_named("identifier");
                self.b.field_last("name");
                self.bump();
                self.ts_type();
                self.b.field_last("index_type");
                self.expect("]");
                if self.at(":") {
                    self.type_annotation();
                    self.b.field_last("type");
                }
                self.b.wrap(m, "index_signature", true);
                self.semicolon_opt();
                return true;
            }
        }
        // method or field
        let mut is_method = false;
        if self.at_id("async") {
            let t2 = self.peek2();
            if !t2.nl && !matches!(self.tx(t2), "(" | "=" | ";" | ":" | "}" | "?" | "!" | "<") {
                self.bump();
                is_method = true;
            }
        }
        if self.at("*") {
            self.bump();
            is_method = true;
        }
        if self.at_id("get") || self.at_id("set") {
            let t2 = self.peek2();
            if !matches!(self.tx(t2), "(" | "=" | ";" | ":" | "}" | "?" | "!" | "<") {
                self.bump();
                is_method = true;
            }
        }
        let _ = is_method;
        self.property_name();
        self.b.field_last("name");
        if self.at("?") || self.at("!") {
            self.bump();
        }
        if self.at("(") || self.at("<") {
            self.call_signature();
            if self.at("{") {
                self.statement_block();
                self.b.field_last("body");
                self.b.wrap(m, "method_definition", true);
                if self.at(";") {
                    self.bump();
                }
            } else {
                let k = if is_abstract { "abstract_method_signature" } else { "method_signature" };
                self.b.wrap(m, k, true);
                self.semicolon_opt();
            }
            return true;
        }
        if self.at(":") {
            self.type_annotation();
            self.b.field_last("type");
        }
        if self.at("=") {
            self.bump();
            self.assign_expr();
            self.b.field_last("value");
        }
        self.b.wrap(m, "public_field_definition", true);
        self.semicolon_opt();
        let _ = self.is_ident_tok(self.peek());
        true
    }
}
