                self.ts_enum(m);
                true
            }
            "namespace" if (t2.t == T::Ident) && !t2.nl => {
                let m = self.b.mark();
                self.bump();
                self.namespace_name();
                self.b.field_last("name");
                if self.at("{") {
                    self.statement_block();
                    self.b.field_last("body");
                }
                self.b.wrap(m, "internal_module", true);
                true
            }
            "module" if (t2.t == T::Ident || t2.t == T::Str) && !t2.nl => {
                let m = self.b.mark();
                self.module_decl(m);
                true
            }
            "global" if tx2 == "{" => {
                let m = self.b.mark();
                self.bump();
                self.b.field_last("name");
                // tree-sitter: global as identifier name
                self.statement_block();
                self.b.field_last("body");
                self.b.wrap(m, "internal_module", true);
                true
            }
            "declare" if !t2.nl && (t2.t == T::Ident) => {
                let m = self.b.mark();
                self.bump();
                if self.at_id("global") {
                    let mm = self.b.mark();
                    self.bump();
                    self.b.rename(self.b.last().unwrap(), "identifier");
                    self.b.nodes[self.b.last().unwrap() as usize].named = true;
                    self.b.field_last("name");
                    if self.at("{") {
                        self.statement_block();
                        self.b.field_last("body");
                    }
                    self.b.wrap(mm, "internal_module", true);
                } else if self.at_id("module") && (self.peek2().t == T::Str || self.tx(self.peek2()) == "global") {
                    let mm = self.b.mark();
                    self.module_decl(mm);
                } else if self.at_id("function") || (self.at_id("async") && self.tx(self.peek2()) == "function") {
                    let mf = self.b.mark();
                    self.function_signature(mf);
                } else {
                    self.statement();
                }
                self.b.wrap(m, "ambient_declaration", true);
                true
            }
            "abstract" if tx2 == "class" => {
                let m = self.b.mark();
                self.class_like(m, true);
                true
            }
            _ => false,
        }
    }

    fn function_signature(&mut self, m: usize) {
        if self.at_id("async") {
            self.bump();
        }
        self.bump(); // function
        if self.at("*") {
            self.bump();
        }
        if self.peek().t == T::Ident {
            self.bump_named("identifier");
            self.b.field_last("name");
        }
        self.call_signature();
        self.semicolon();
        self.b.wrap(m, "function_signature", true);
    }

    fn module_decl(&mut self, m: usize) {
        self.bump(); // module
        if self.peek().t == T::Str {
            self.string_lit();
        } else {
            self.namespace_name();
        }
        self.b.field_last("name");
        if self.at("{") {
            self.statement_block();
            self.b.field_last("body");
        } else {
            self.semicolon_opt();
        }
        self.b.wrap(m, "module", true);
    }

    fn semicolon_opt(&mut self) {
        if self.at(";") {
            self.bump();
        } else {
            self.asi();
        }
    }

    fn namespace_name(&mut self) {
        let m = self.b.mark();
        self.bump_named("identifier");
        while self.at(".") {
            let first = self.b.stack[m];
            if self.b.nodes[first as usize].field.is_none() {
                self.b.set_field(first, "object");
            }
            self.bump();
            self.bump_named("identifier");
            self.b.field_last("property");
            self.b.wrap(m, "nested_identifier", true);
        }
    }

    fn interface_decl(&mut self, m: usize) {
        self.bump(); // interface
        self.bump_named("type_identifier");
        self.b.field_last("name");
        if self.at("<") {
            self.type_parameters();
            self.b.field_last("type_parameters");
        }
        if self.at_id("extends") {
            let me = self.b.mark();
            self.bump();
            loop {
                self.ts_type_no_cond();
                self.b.field_last("type");
                if !self.eat(",") {
                    break;
                }
            }
            self.b.wrap(me, "extends_type_clause", true);
        }
        self.object_type_body("interface_body");
        self.b.field_last("body");
        self.b.wrap(m, "interface_declaration", true);
    }

    fn type_alias(&mut self, m: usize) {
        self.bump(); // type
        self.bump_named("type_identifier");
        self.b.field_last("name");
        if self.at("<") {
            self.type_parameters();
            self.b.field_last("type_parameters");
        }
        self.expect("=");
        self.ts_type();
        self.b.field_last("value");
        self.semicolon();
        self.b.wrap(m, "type_alias_declaration", true);
    }

    pub fn ts_enum(&mut self, m: usize) {
        self.bump(); // enum
        self.bump_named("identifier");
        self.b.field_last("name");
        let mb = self.b.mark();
        self.expect("{");
        while !self.at("}") && self.peek().t != T::Eof {
            let me = self.b.mark();
            let t = self.peek();
            match t.t {
                T::Str => self.string_lit(),
                T::Num => {
                    self.bump_named("number");
                }
                _ => {
                    if self.at("[") {
                        self.property_name();
                    } else {
                        self.bump_named("property_identifier");
                    }
                }
            }
            if self.at("=") {
                self.b.field_last("name");
                self.bump();
                self.assign_expr();
                self.b.field_last("value");
                self.b.wrap(me, "enum_assignment", true);
            } else {
                self.b.field_last("name");
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect("}");
        self.b.wrap(mb, "enum_body", true);
        self.b.field_last("body");
        self.b.wrap(m, "enum_declaration", true);
    }

    // ---------- annotations ----------
    pub fn type_annotation(&mut self) {
        let m = self.b.mark();
        self.bump(); // :
        self.ts_type();
        self.b.wrap(m, "type_annotation", true);
    }

    pub fn return_type_annotation(&mut self) {
        let m = self.b.mark();
        // asserts / type predicate
        let t1 = self.peek_n(1);
        let t2 = self.peek_n(2);
        let tx1 = self.tx(t1);
        let tx2 = self.tx(t2);
        if tx1 == "asserts" && t2.t == T::Ident && tx2 != "is" || (tx1 == "asserts" && tx2 == "this") {
            self.bump(); // :
            let ma = self.b.mark();
            self.bump(); // asserts
            let t = self.peek();
            let t2 = self.peek2();
            if self.tx(t2) == "is" {
                let mp = self.b.mark();
                let k = if self.tx(t) == "this" { "this" } else { "identifier" };
                self.bump_named(k);
                self.b.field_last("name");
                self.bump();
                self.ts_type();
                self.b.field_last("type");
                self.b.wrap(mp, "type_predicate", true);
            } else {
                let k = if self.tx(t) == "this" { "this" } else { "identifier" };
                self.bump_named(k);
            }
            self.b.wrap(ma, "asserts", true);
            self.b.wrap(m, "asserts_annotation", true);
            return;
        }
        if (t1.t == T::Ident) && tx2 == "is" && !t2.nl {
            self.bump(); // :
            let mp = self.b.mark();
            let k = if tx1 == "this" { "this" } else { "identifier" };
            self.bump_named(k);
            self.b.field_last("name");
            self.bump(); // is
            self.ts_type();
            self.b.field_last("type");
            self.b.wrap(mp, "type_predicate", true);
            self.b.wrap(m, "type_predicate_annotation", true);
            return;
        }
        self.type_annotation();
    }

    pub fn try_return_type(&mut self) -> bool {
        let m = self.b.mark();
        self.return_type_annotation();
        !self.has_missing_from(m)
    }

    // ---------- type parameters / arguments ----------
    pub fn type_parameters(&mut self) {
        let m = self.b.mark();
        self.bump(); // <
        while !self.at_gt() && self.peek().t != T::Eof {
            let mp = self.b.mark();
            if self.at_id("const") || self.at_id("in") || self.at_id("out") {
                let t2 = self.peek2();
                if t2.t == T::Ident {
                    self.bump();
                }
            }
            self.bump_named("type_identifier");
            self.b.field_last("name");
            if self.at_id("extends") {
                let mc = self.b.mark();
                self.bump();
                self.ts_type();
                self.b.wrap(mc, "constraint", true);
                self.b.field_last("constraint");
            }
            if self.at("=") {
                let md = self.b.mark();
                self.bump();
                self.ts_type();
                self.b.wrap(md, "default_type", true);
                self.b.field_last("value");
            }
            self.b.wrap(mp, "type_parameter", true);
            if !self.eat(",") {
                break;
            }
        }
        self.expect_gt();
        self.b.wrap(m, "type_parameters", true);
    }

    pub fn try_type_parameters(&mut self) -> bool {
        let m = self.b.mark();
        self.type_parameters();
        !self.has_missing_from(m)
    }

    fn at_gt(&self) -> bool {
        let t = self.peek();
        t.t == T::Punct && self.tx(t).starts_with('>')
    }

    fn expect_gt(&mut self) -> bool {
        let t = self.peek();
        if t.t == T::Punct && self.tx(t).starts_with('>') {
            self.bump_partial(1);
            true
        } else {
            let p = self.pos;
            self.b.missing(">", false, p);
            false
        }
    }

    pub fn type_arguments(&mut self) {
        let m = self.b.mark();
        self.bump(); // <
        while !self.at_gt() && self.peek().t != T::Eof {
            let before = self.pos;
            self.ts_type();
            if self.pos == before {
                break;
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect_gt();
        self.b.wrap(m, "type_arguments", true);
    }

    pub fn try_type_arguments(&mut self) -> bool {
        if !self.at("<") {
            return false;
        }
        let m = self.b.mark();
        let save = self.in_type;
        self.in_type = true;
        self.type_arguments();
        self.in_type = save;
        !self.has_missing_from(m)
    }

    // ---------- types ----------
    pub fn ts_type(&mut self) {
        let save = self.in_type;
        self.in_type = true;
        self.ts_type_inner(true);
        self.in_type = save;
    }

    fn ts_type_no_cond(&mut self) {
        let save = self.in_type;
        self.in_type = true;
        self.ts_type_inner(false);
        self.in_type = save;
    }

    fn is_function_type_ahead(&self) -> bool {
        let t = self.peek();
        if self.tx(t) == "<" {
            return true;
        }
        if self.tx(t) != "(" {
            return false;
        }
        // find matching paren
        let mut depth = 0i32;
        let mut pos = t.s;
        loop {
            let tk = self.peek_at(pos, false);
            if tk.t == T::Eof {
                return false;
            }
            let tx = self.tx(tk);
            if tk.t == T::Punct {
                match tx {
                    "(" | "[" | "{" => depth += 1,
                    ")" | "]" | "}" => {
                        depth -= 1;
                        if depth == 0 {
                            let n = self.peek_at(tk.e, false);
                            return self.tx(n) == "=>";
                        }
                    }
                    _ => {}
                }
            }
            pos = tk.e;
        }
    }

    fn ts_type_inner(&mut self, allow_cond: bool) {
        let m = self.b.mark();
        let t = self.peek();
        let tx = self.tx(t);
        // function types
        if (tx == "(" || tx == "<") && self.is_function_type_ahead() {
            if tx == "<" {
                self.type_parameters();
                self.b.field_last("type_parameters");
            }
            self.formal_parameters();
            self.b.field_last("parameters");
            self.expect("=>");
            if self.peek_n(1).t == T::Ident && self.tx(self.peek_n(1)) == "is" {
                let mp = self.b.mark();
                let k = if tx == "this" { "this" } else { "identifier" };
                self.bump_named(k);
                self.b.field_last("name");
                self.bump();
                self.ts_type();
                self.b.field_last("type");
                self.b.wrap(mp, "type_predicate", true);
            } else {
                self.ts_type();
            }
            self.b.field_last("return_type");
            self.b.wrap(m, "function_type", true);
            return;
        }
        if tx == "new" || (tx == "abstract" && self.tx(self.peek2()) == "new") {
            if tx == "abstract" {
                self.bump();
            }
            self.bump(); // new
            if self.at("<") {
                self.type_parameters();
                self.b.field_last("type_parameters");
            }
            self.formal_parameters();
            self.b.field_last("parameters");
            self.expect("=>");
            self.ts_type();
            self.b.field_last("type");
            self.b.wrap(m, "constructor_type", true);
            return;
        }
        self.union_type();
        if allow_cond && self.at_id("extends") && !self.peek().nl {
            self.b.field_last("left");
            self.bump();
            self.ts_type_no_cond();
            self.b.field_last("right");
            self.expect("?");
            self.ts_type();
            self.b.field_last("consequence");
            self.expect(":");
            self.ts_type();
            self.b.field_last("alternative");
            self.b.wrap(m, "conditional_type", true);
        }
    }

    fn union_type(&mut self) {
        let m = self.b.mark();
        if self.at("|") {
            self.bump();
            self.intersection_type();
            self.b.wrap(m, "union_type", true);
        } else {
            self.intersection_type();
        }
        while self.at("|") {
            self.bump();
            self.intersection_type();
            self.b.wrap(m, "union_type", true);
        }
    }

    fn intersection_type(&mut self) {
        let m = self.b.mark();
        if self.at("&") {
            self.bump();
            self.type_operator();
            self.b.wrap(m, "intersection_type", true);
        } else {
            self.type_operator();
        }
        while self.at("&") {
            self.bump();
            self.type_operator();
            self.b.wrap(m, "intersection_type", true);
        }
    }

    fn type_operator(&mut self) {
        let m = self.b.mark();
        let t = self.peek();
        let tx = self.tx(t);
        let t2 = self.peek2();
        let starts_type = |p: &P, t2: Tok| -> bool {
            let x = p.tx(t2);
            t2.t == T::Ident || t2.t == T::Str || t2.t == T::Num || matches!(x, "(" | "[" | "{" | "`" | "-")
        };
        match tx {
            "keyof" if starts_type(self, t2) => {
                self.bump();
                self.type_operator();
                self.b.wrap(m, "index_type_query", true);
                return;
            }
            "readonly" if starts_type(self, t2) => {
                self.bump();
                self.type_operator();
                self.b.wrap(m, "readonly_type", true);
                return;
            }
            "unique" if self.tx(t2) == "symbol" => {
                self.bump();
                self.bump();
                return;
            }
            "infer" if t2.t == T::Ident => {
                self.bump();
                self.bump_named("type_identifier");
                if self.at_id("extends") {
                    // infer U extends X
                    let save = self.pos;
                    let cp = self.b.checkpoint();
                    self.bump();
                    self.ts_type_no_cond();
                    if self.at("?") {
                        // it was a conditional: rollback
                        self.b.restore(cp);
                        self.pos = save;
                    }
                }
                self.b.wrap(m, "infer_type", true);
                return;
            }
            _ => {}
        }
        self.postfix_type();
    }

    fn postfix_type(&mut self) {
        let m = self.b.mark();
        self.primary_type();
        loop {
            let t = self.peek();
            if t.nl {
                break;
            }
            if self.at("[") {
                let t2 = self.peek2();
                if self.tx(t2) == "]" {
                    self.bump();
                    self.bump();
                    self.b.wrap(m, "array_type", true);
                } else {
                    self.bump();
                    self.ts_type();
                    self.expect("]");
                    self.b.wrap(m, "lookup_type", true);
                }
                continue;
            }
            break;
        }
    }

    fn primary_type(&mut self) {
        let m = self.b.mark();
        let t = self.peek_re();
        let tx = self.tx(t);
        match t.t {
            T::Str => {
                self.string_lit();
                self.b.wrap(m, "literal_type", true);
                return;
            }
            T::Num => {
                self.bump_named("number");
                self.b.wrap(m, "literal_type", true);
                return;
            }
            T::Punct => match tx {
                "-" => {
                    let mu = self.b.mark();
                    self.bump();
                    self.b.field_last("operator");
                    self.bump_named("number");
                    self.b.field_last("argument");
                    self.b.wrap(mu, "unary_expression", true);
                    self.b.wrap(m, "literal_type", true);
                    return;
                }
                "(" => {
                    self.bump();
                    self.ts_type();
                    self.expect(")");
                    self.b.wrap(m, "parenthesized_type", true);
                    return;
                }
                "[" => {
                    self.tuple_type();
                    return;
                }
                "{" => {
                    self.object_type_body("object_type");
                    return;
                }
                "`" => {
                    self.template_literal_type();
                    return;
                }
                "*" => {
                    self.bump();
                    self.b.wrap(m, "existential_type", true);
                    return;
                }
                "?" => {
                    // flow maybe type
                    self.bump();
                    self.primary_type();
                    self.b.wrap(m, "flow_maybe_type", true);
                    return;
                }
                _ => {
                    let p = self.pos;
                    self.b.missing("type_identifier", true, p);
                    return;
                }
            },
            T::Ident => {}
            _ => {
                let p = self.pos;
                self.b.missing("type_identifier", true, p);
                return;
            }
        }
        match tx {
            "true" | "false" | "null" | "undefined" => {
                self.bump_named(intern(tx));
                self.b.wrap(m, "literal_type", true);
                return;
            }
            "this" => {
                self.bump_named("this");
                self.b.wrap(m, "this_type", true);
                return;
            }
            "typeof" => {
                self.bump();
                // expression: identifier / member / import(...)
                let mq = self.b.mark();
                if self.at_id("import") {
                    let mi = self.b.mark();
                    self.bump_named("import");
                    let _ = mi;
                } else {
                    self.bump_named("identifier");
                }
                loop {
                    if self.at(".") {
                        let first = self.b.stack[mq];
                        if self.b.nodes[first as usize].field.is_none() {
                            self.b.set_field(first, "object");
                        }
                        self.bump();
                        self.bump_named("property_identifier");
                        self.b.field_last("property");
                        self.b.wrap(mq, "member_expression", true);
                        continue;
                    }
                    if self.at("(") {
                        self.set_first_field_pub(mq, "function");
                        self.arguments();
                        self.b.field_last("arguments");
                        self.b.wrap(mq, "call_expression", true);
                        continue;
                    }
                    break;
                }
                if self.at("<") && !self.peek().nl {
                    self.type_arguments();
                }
                self.b.wrap(m, "type_query", true);
                return;
            }
            _ => {}
        }
        if PREDEFINED.contains(&tx) {
            let t2 = self.peek2();
            if self.tx(t2) != "." {
                self.bump();
                self.b.wrap(m, "predefined_type", true);
                return;
            }
        }
        // type identifier, nested, generic
        let mn = self.b.mark();
        let t2 = self.peek2();
        if self.tx(t2) == "." && !t2.nl {
            // nested_type_identifier: module: identifier/nested_identifier
            let mm = self.b.mark();
            self.bump_named("identifier");
            loop {
                let t2 = self.peek2();
                let t3 = self.peek_n(2);
                if self.at(".") && self.tx(self.peek_n(2)) == "." {
                    let first = self.b.stack[mm];
                    if self.b.nodes[first as usize].field.is_none() {
                        self.b.set_field(first, "object");
                    }
                    self.bump();
                    self.bump_named("property_identifier");
                    self.b.field_last("property");
                    self.b.wrap(mm, "nested_identifier", true);
                    let _ = (t2, t3);
                    continue;
                }
                break;
            }
            self.b.field_last("module");
            self.expect(".");
            self.bump_named("type_identifier");
            self.b.field_last("name");
            self.b.wrap(mn, "nested_type_identifier", true);
        } else {
            self.bump_named("type_identifier");
        }
        if self.at("<") && !self.peek().nl {
            self.b.field_last("name");
            self.type_arguments();
            self.b.field_last("type_arguments");
            self.b.wrap(m, "generic_type", true);
        }
    }

    pub fn set_first_field_pub(&mut self, m: usize, f: &'static str) {
        for i in m..self.b.stack.len() {
            let id = self.b.stack[i];
            if !self.b.nodes[id as usize].extra {
                self.b.nodes[id as usize].field = Some(f);
                return;
            }
        }
    }

    fn template_literal_type(&mut self) {
        let t = self.peek();
        self.flush_comments_to(t.s);
        let m = self.b.mark();
        let b = self.src.as_bytes();
        self.b.leaf("`", false, t.s, t.s + 1);
        let mut i = t.s + 1;
        let mut frag = i;
        loop {
            if i >= b.len() {
                self.pos = i;
                break;
            }
            match b[i] {
                b'`' => {
                    if frag < i {
                        self.b.leaf("string_fragment", true, frag, i);
                    }
                    self.b.leaf("`", false, i, i + 1);
                    self.pos = i + 1;
                    break;
                }
                b'\\' => {
                    if frag < i {
                        self.b.leaf("string_fragment", true, frag, i);
                    }
                    let e = super::js::escape_end(self.src, i);
                    self.b.leaf("escape_sequence", true, i, e);
                    i = e;
                    frag = i;
                }
                b'$' if i + 1 < b.len() && b[i + 1] == b'{' => {
                    if frag < i {
                        self.b.leaf("string_fragment", true, frag, i);
                    }
                    let ms = self.b.mark();
                    self.b.leaf("${", false, i, i + 2);
                    self.pos = i + 2;
                    self.ts_type();
                    self.expect("}");
