                self.bump();
                self.bump();
                modifiers += 1;
                continue;
            }
            if tx == "readonly" && !matches!(tx2, ":" | "?" | "(" | "," | ";" | "}" | "<") {
                self.bump();
                modifiers += 1;
                continue;
