                    self.b.leaf("?:", false, tq.s, tc.e);
                    self.ts_type();
                    self.b.wrap(ma, "opting_type_annotation", true);
                } else if (tx == "-" || tx == "+") && self.tx(self.peek2()) == "?" {
                    let tq = self.peek();
                    let tc = self.peek_n(2);
                    self.flush_comments_to(tq.s);
                    self.pos = tc.e;
                    let k = if tx == "-" { "-?:" } else { "+?:" };
                    self.b.leaf(k, false, tq.s, tc.e);
                    self.ts_type();
                    self.b.wrap(ma, if tx == "-" { "omitting_type_annotation" } else { "adding_type_annotation" }, true);
