// Python parser producing tree-sitter-python compatible CST
use super::js::intern;
use crate::tree::{Builder, Tree};

#[derive(Clone, Copy, PartialEq, Debug)]
enum K {
    Name,
    Num,
    Str,
    Op,
    Newline,
    Indent,
    Dedent,
    Comment,
    LineCont,
    Eof,
}

#[derive(Clone, Copy, Debug)]
struct Tk {
