    s: usize,
    e: usize,
}

const KEYWORDS: &[&str] = &[
    "and", "as", "assert", "async", "await", "break", "class", "continue", "def", "del", "elif", "else", "except",
    "finally", "for", "from", "global", "if", "import", "in", "is", "lambda", "nonlocal", "not", "or", "pass",
    "raise", "return", "try", "while", "with", "yield", "None", "True", "False",
];

const OPS3: &[&str] = &["**=", "//=", ">>=", "<<=", "..."];
const OPS2: &[&str] = &[
    "**", "//", ">>", "<<", "<=", ">=", "==", "!=", "->", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "@=", ":=", "<>",
];

fn is_id_start(c: char) -> bool {
    c == '_' || c.is_alphabetic() || (!c.is_ascii() && !c.is_whitespace())
}
fn is_id_char(c: char) -> bool {
    is_id_start(c) || c.is_ascii_digit()
}

/// scan a string literal starting at i (prefix included). returns end.
fn scan_string(src: &str, i: usize) -> usize {
    let b = src.as_bytes();
    let mut j = i;
    while j < b.len() && b[j].is_ascii_alphabetic() {
        j += 1;
    }
    let prefix = &src[i..j].to_ascii_lowercase();
    let raw = prefix.contains('r');
    let q = b[j];
    let triple = j + 2 < b.len() && b[j + 1] == q && b[j + 2] == q;
    let mut k = if triple { j + 3 } else { j + 1 };
    let fstr = prefix.contains('f') || prefix.contains('t');
    let mut depth = 0i32;
    while k < b.len() {
        let c = b[k];
        if c == b'\\' && (!raw || true) {
            k += 2;
            continue;
        }
        if fstr {
            if c == b'{' {
                if k + 1 < b.len() && b[k + 1] == b'{' && depth == 0 {
                    k += 2;
                    continue;
                }
                depth += 1;
                k += 1;
                continue;
            }
            if c == b'}' && depth > 0 {
                depth -= 1;
                k += 1;
                continue;
            }
            if depth > 0 && (c == b'"' || c == b'\'') && c != q {
                // nested string inside interpolation
                k = scan_string(src, k);
                continue;
            }
        }
        if c == q {
            if triple {
                if k + 2 < b.len() && b[k + 1] == q && b[k + 2] == q {
                    return k + 3;
                }
            } else {
                return k + 1;
            }
        }
        if c == b'\n' && !triple && depth == 0 {
            return k;
        }
        k += 1;
    }
    b.len()
}

fn is_string_start(src: &str, i: usize) -> bool {
    let b = src.as_bytes();
    let mut j = i;
    while j < b.len() && j - i < 3 && b[j].is_ascii_alphabetic() {
        j += 1;
    }
    if j >= b.len() || (b[j] != b'"' && b[j] != b'\'') {
        return false;
    }
    let p = src[i..j].to_ascii_lowercase();
    p.chars().all(|c| matches!(c, 'r' | 'b' | 'u' | 'f' | 't'))
}

/// tokenize a region. `bracket` = start inside brackets (no newlines/indent).
fn tokenize(src: &str, start: usize, end: usize, bracket: bool) -> Vec<Tk> {
    let b = src.as_bytes();
    let mut out: Vec<Tk> = Vec::new();
    let mut i = start;
    let mut depth: i32 = if bracket { 1 } else { 0 };
    let mut indents: Vec<usize> = vec![0];
    let mut at_line_start = !bracket;
    let mut last_end = start; // end of last token or comment
    let mut line_has_tokens = false;
    // returns column of position
    let col = |p: usize| -> usize {
        let mut q = p;
        while q > 0 && b[q - 1] != b'\n' {
            q -= 1;
        }
        // count chars (tabs as 8?) - use byte width with tab to next multiple of 8
        let mut c = 0;
        for &ch in &b[q..p] {
            if ch == b'\t' {
                c = (c / 8 + 1) * 8;
            } else {
                c += 1;
            }
        }
        c
    };
    let mut pending_newline = false;
    loop {
        if at_line_start && depth == 0 {
            // find first non-ws char of this line
            let mut j = i;
            while j < end && (b[j] == b' ' || b[j] == b'\t' || b[j] == 0x0c) {
                j += 1;
            }
            if j >= end {
                i = j;
                break;
            }
            if b[j] == b'\n' || b[j] == b'\r' {
                i = j + 1;
                continue;
            }
            if b[j] == b'#' {
                // comment line
                let c = col(j);
                let mut e = j;
                while e < end && b[e] != b'\n' {
                    e += 1;
                }
                let mut ce = e;
                if ce > j && b[ce - 1] == b'\r' {
                    ce -= 1;
                }
                if pending_newline {
                    out.push(Tk { k: K::Newline, s: last_end, e: last_end });
                    pending_newline = false;
                }
                while c < *indents.last().unwrap() {
                    indents.pop();
                    out.push(Tk { k: K::Dedent, s: last_end, e: last_end });
                }
                out.push(Tk { k: K::Comment, s: j, e: ce });
                last_end = ce;
                i = e;
                continue;
            }
            if b[j] == b'\\' && j + 1 < end && (b[j + 1] == b'\n' || b[j + 1] == b'\r') {
                // continuation at line start: treat as normal
            }
            let c = col(j);
            let top = *indents.last().unwrap();
            if c > top {
                if pending_newline {
                    pending_newline = false;
                    out.push(Tk { k: K::Indent, s: j, e: j });
                } else {
                    out.push(Tk { k: K::Indent, s: j, e: j });
                }
                indents.push(c);
            } else {
                if pending_newline {
                    out.push(Tk { k: K::Newline, s: last_end, e: last_end });
                    pending_newline = false;
                }
                while c < *indents.last().unwrap() {
                    indents.pop();
                    out.push(Tk { k: K::Dedent, s: last_end, e: last_end });
                }
            }
            at_line_start = false;
            line_has_tokens = false;
            i = j;
        }
        if i >= end {
            break;
        }
        let c = b[i];
        if c == b' ' || c == b'\t' || c == 0x0c || c == b'\r' {
            i += 1;
            continue;
        }
        if c == b'\n' {
            i += 1;
            if depth == 0 {
                if line_has_tokens {
                    pending_newline = true;
                }
                at_line_start = true;
            }
            continue;
        }
        if c == b'#' {
            let mut e = i;
            while e < end && b[e] != b'\n' {
                e += 1;
            }
            let mut ce = e;
            if ce > i && b[ce - 1] == b'\r' {
                ce -= 1;
            }
            out.push(Tk { k: K::Comment, s: i, e: ce });
            last_end = ce;
            i = e;
            continue;
        }
        if c == b'\\' && i + 1 < end && (b[i + 1] == b'\n' || b[i + 1] == b'\r') {
            let mut e = i + 1;
            if b[e] == b'\r' {
                e += 1;
            }
            if e < end && b[e] == b'\n' {
                e += 1;
            }
            out.push(Tk { k: K::LineCont, s: i, e });
            i = e;
            continue;
        }
        line_has_tokens = true;
        let s = i;
        let ch = src[i..].chars().next().unwrap();
        let (k, e) = if is_string_start(src, i) {
            (K::Str, scan_string(src, i).min(end))
        } else if ch.is_ascii_digit() || (ch == '.' && i + 1 < end && b[i + 1].is_ascii_digit()) {
            (K::Num, scan_number(src, i))
        } else if is_id_start(ch) {
            let mut e = i;
            for (o, c2) in src[i..end].char_indices() {
                if !is_id_char(c2) {
                    e = i + o;
                    break;
                }
                e = i + o + c2.len_utf8();
            }
            (K::Name, e)
        } else {
            let r = &src[i..end];
            let mut l = ch.len_utf8();
            for o in OPS3 {
                if r.starts_with(o) {
                    l = 3;
                    break;
                }
            }
            if l != 3 {
                for o in OPS2 {
                    if r.starts_with(o) {
                        l = 2;
                        break;
                    }
                }
            }
            match ch {
                '(' | '[' | '{' => depth += 1,
                ')' | ']' | '}' => depth = (depth - 1).max(if bracket { 1 } else { 0 }),
                _ => {}
            }
            (K::Op, i + l)
        };
        out.push(Tk { k, s, e });
        last_end = e;
        i = e;
    }
    if !bracket {
        if line_has_tokens || pending_newline {
            out.push(Tk { k: K::Newline, s: last_end, e: last_end });
        }
        while indents.len() > 1 {
            indents.pop();
            out.push(Tk { k: K::Dedent, s: last_end, e: last_end });
        }
    }
    out.push(Tk { k: K::Eof, s: end, e: end });
    out
}

fn scan_number(src: &str, mut i: usize) -> usize {
    let b = src.as_bytes();
    let n = b.len();
    if b[i] == b'0' && i + 1 < n && matches!(b[i + 1], b'x' | b'X' | b'o' | b'O' | b'b' | b'B') {
        i += 2;
        while i < n && (b[i].is_ascii_hexdigit() || b[i] == b'_') {
            i += 1;
        }
    } else {
        while i < n && (b[i].is_ascii_digit() || b[i] == b'_') {
            i += 1;
        }
        if i < n && b[i] == b'.' && !(i + 1 < n && b[i + 1] == b'.') {
            i += 1;
            while i < n && (b[i].is_ascii_digit() || b[i] == b'_') {
                i += 1;
            }
        }
        if i < n && (b[i] == b'e' || b[i] == b'E') {
            let mut j = i + 1;
            if j < n && (b[j] == b'+' || b[j] == b'-') {
                j += 1;
            }
            if j < n && b[j].is_ascii_digit() {
                i = j;
                while i < n && (b[i].is_ascii_digit() || b[i] == b'_') {
                    i += 1;
                }
            }
        }
    }
    while i < n && matches!(b[i], b'j' | b'J' | b'l' | b'L') {
        i += 1;
    }
    i
}

struct P<'a> {
    src: &'a str,
    toks: Vec<Tk>,
    i: usize,
    b: Builder,
    depth: usize,
}

pub fn parse(src: &str) -> Tree {
    let toks = tokenize(src, 0, src.len(), false);
    let mut p = P { src, toks, i: 0, b: Builder::new(), depth: 0 };
    let m = p.b.mark();
    loop {
        p.skip_newlines();
        if p.k() == K::Eof {
            break;
        }
        if p.k() == K::Dedent || p.k() == K::Indent {
            p.i += 1;
            continue;
        }
        let before = p.i;
        p.statement();
        if p.i == before {
            p.error_token();
        }
    }
    p.flush_extras(usize::MAX);
    let start = p.b.stack[m..].first().map(|&c| p.b.nodes[c as usize].start).unwrap_or_else(|| {
        let t = src.len() - src.trim_start().len();
        t
    });
    let root = p.b.wrap_all(m, "module", start, src.len());
    p.b.finish(root, src)
}

impl<'a> P<'a> {
    // ---- token helpers ----
    fn idx(&self, n: usize) -> usize {
        let mut j = self.i;
        let mut c = 0;
        loop {
            while j < self.toks.len() && matches!(self.toks[j].k, K::Comment | K::LineCont) {
                j += 1;
            }
            if j >= self.toks.len() {
                return self.toks.len() - 1;
            }
            if c == n {
                return j;
            }
            c += 1;
            j += 1;
        }
    }
    fn tok(&self, n: usize) -> Tk {
        self.toks[self.idx(n)]
    }
    fn k(&self) -> K {
        self.tok(0).k
    }
    fn tx(&self) -> &'a str {
        let t = self.tok(0);
        &self.src[t.s..t.e]
    }
    fn txn(&self, n: usize) -> &'a str {
        let t = self.tok(n);
        if matches!(t.k, K::Newline | K::Indent | K::Dedent | K::Eof) {
            return "";
        }
        &self.src[t.s..t.e]
    }
    fn at(&self, s: &str) -> bool {
        let t = self.tok(0);
        matches!(t.k, K::Op | K::Name) && &self.src[t.s..t.e] == s
    }
    fn at_kw(&self, s: &str) -> bool {
        let t = self.tok(0);
        t.k == K::Name && &self.src[t.s..t.e] == s
    }
    fn flush_extras(&mut self, upto: usize) {
        while self.i < self.toks.len() && matches!(self.toks[self.i].k, K::Comment | K::LineCont) {
            let t = self.toks[self.i];
            if t.s >= upto {
                break;
            }
            if t.k == K::Comment {
                self.b.extra("comment", t.s, t.e);
            } else {
                self.b.extra("line_continuation", t.s, t.e);
            }
            self.i += 1;
        }
    }
    fn advance_raw(&mut self) -> Tk {
        self.flush_extras(usize::MAX);
        let t = self.toks[self.i];
        if t.k != K::Eof {
            self.i += 1;
        }
        t
    }
    fn bump(&mut self) -> u32 {
        let t = self.advance_raw();
        let k = intern(&self.src[t.s..t.e]);
        self.b.leaf(k, false, t.s, t.e)
    }
    fn bump_named(&mut self, kind: &'static str) -> u32 {
        let t = self.advance_raw();
        self.b.leaf(kind, true, t.s, t.e)
    }
    fn hidden_tok(&mut self) {
        // newline/indent/dedent: zero width hidden; flush comments before it
        let t = self.toks[self.idx(0)];
        self.flush_extras(t.s + 1);
        if self.i < self.toks.len() && self.toks[self.i].k != K::Eof {
            let t = self.toks[self.i];
            self.i += 1;
            self.b.hidden(t.s, t.e);
        }
    }
    fn eat(&mut self, s: &str) -> bool {
        if self.at(s) {
            self.bump();
            true
        } else {
            false
        }
    }
    fn expect(&mut self, s: &str) {
        if !self.eat(s) {
            let p = self.cur_pos();
            self.b.missing(intern(s), false, p);
        }
    }
    fn cur_pos(&self) -> usize {
        // end of last pushed node
        self.b.last().map(|l| self.b.nodes[l as usize].end).unwrap_or(0)
    }
    fn error_token(&mut self) {
        if self.k() == K::Eof {
            return;
        }
        let m = self.b.mark();
        let t = self.tok(0);
        match t.k {
            K::Name => {
                self.bump_named("identifier");
            }
            K::Newline | K::Indent | K::Dedent => {
                self.hidden_tok();
                return;
            }
            _ => {
                self.bump();
            }
        }
        self.b.wrap(m, "ERROR", true);
    }
    fn skip_newlines(&mut self) {
        while self.k() == K::Newline {
            self.hidden_tok();
        }
    }
    fn at_stmt_end(&self) -> bool {
        matches!(self.k(), K::Newline | K::Eof | K::Dedent) || self.at(";")
    }

    // ---- statements ----
    fn statement(&mut self) {
        let t = self.tok(0);
        let tx = self.tx();
        if t.k == K::Name {
            match tx {
                "def" => return self.function_def(self.b.mark()),
                "class" => return self.class_def(self.b.mark()),
                "if" => return self.if_stmt(),
                "for" => return self.for_stmt(self.b.mark()),
                "while" => return self.while_stmt(),
                "try" => return self.try_stmt(),
                "with" => return self.with_stmt(self.b.mark()),
                "async" if matches!(self.txn(1), "def" | "for" | "with") => {
                    let m = self.b.mark();
                    self.bump();
                    match self.tx() {
                        "def" => return self.function_def(m),
                        "for" => return self.for_stmt(m),
                        _ => return self.with_stmt(m),
                    }
                }
                "match" if self.is_match_stmt() => return self.match_stmt(),
                _ => {}
            }
        }
        if self.at("@") {
            return self.decorated();
        }
        self.simple_statements();
    }

    fn is_match_stmt(&self) -> bool {
        // match <expr>: NEWLINE INDENT case
        let n = self.txn(1);
        if matches!(n, "=" | "." | "(" | "[" | ":" | "," | ")") && n != "(" && n != "[" {
            return false;
        }
        // look for ':' followed by newline/indent before end of line
        let mut j = 1;
        loop {
            let t = self.tok(j);
            match t.k {
                K::Newline | K::Eof => return false,
                K::Indent => return self.txn(j - 1) == ":",
                _ => {}
            }
            j += 1;
            if j > 200 {
                return false;
            }
        }
    }

    fn simple_statements(&mut self) {
        loop {
            let before = self.i;
            self.simple_statement();
            if self.i == before {
                self.error_token();
            }
            if self.at(";") {
                self.bump();
                if matches!(self.k(), K::Newline | K::Eof | K::Dedent) {
                    break;
                }
                continue;
            }
            break;
        }
        if self.k() == K::Newline {
            self.hidden_tok();
        } else if !matches!(self.k(), K::Eof | K::Dedent) {
            // junk on line
            while !matches!(self.k(), K::Newline | K::Eof | K::Dedent | K::Indent) {
                let before = self.i;
                self.error_token();
                if self.i == before {
                    break;
                }
            }
            if self.k() == K::Newline {
                self.hidden_tok();
            }
        }
    }

    fn simple_statement(&mut self) {
        let m = self.b.mark();
        let tx = self.tx();
        if self.k() == K::Name {
            match tx {
                "pass" | "break" | "continue" if !matches!(self.txn(1), "=" | "." | "(" | "[") => {
                    self.bump();
                    let k = match tx {
                        "pass" => "pass_statement",
                        "break" => "break_statement",
                        _ => "continue_statement",
                    };
                    self.b.wrap(m, k, true);
                    return;
                }
                "return" => {
                    self.bump();
                    if !self.at_stmt_end() {
                        self.expression_list_or_single();
                    }
                    self.b.wrap(m, "return_statement", true);
                    return;
                }
                "del" => {
                    self.bump();
                    self.expression_list_or_single();
                    self.b.wrap(m, "delete_statement", true);
                    return;
                }
                "raise" => {
                    self.bump();
                    if !self.at_stmt_end() {
                        self.expression_list_or_single();
                        if self.at_kw("from") {
                            self.bump();
                            self.expression();
                            self.b.field_last("cause");
                        }
                    }
                    self.b.wrap(m, "raise_statement", true);
                    return;
                }
                "global" | "nonlocal" => {
                    self.bump();
                    loop {
                        self.bump_named("identifier");
                        if !self.eat(",") {
                            break;
                        }
                    }
                    self.b.wrap(m, if tx == "global" { "global_statement" } else { "nonlocal_statement" }, true);
                    return;
                }
                "assert" => {
                    self.bump();
                    self.expression();
                    while self.eat(",") {
                        self.expression();
                    }
                    self.b.wrap(m, "assert_statement", true);
                    return;
                }
                "import" => {
                    self.bump();
                    self.import_names(false);
                    self.b.wrap(m, "import_statement", true);
                    return;
                }
                "from" => {
                    self.import_from(m);
                    return;
                }
                "print" if !matches!(self.txn(1), "(" | "=" | "." | "[" | "," | ")" | "") || self.txn(1) == ">>" => {
                    self.bump();
                    if self.at(">>") {
                        let mc = self.b.mark();
                        self.bump();
                        self.expression();
                        self.b.wrap(mc, "chevron", true);
                        if self.eat(",") {}
                    }
                    while !self.at_stmt_end() {
                        self.expression();
                        self.b.field_last("argument");
                        if !self.eat(",") {
                            break;
                        }
                    }
                    self.b.wrap(m, "print_statement", true);
                    return;
                }
                "exec" if self.tok(1).k == K::Str => {
                    self.bump();
                    self.string_or_concat();
                    self.b.field_last("code");
                    if self.at_kw("in") {
                        self.bump();
                        self.expression();
                        while self.eat(",") {
                            self.expression();
                        }
                    }
                    self.b.wrap(m, "exec_statement", true);
                    return;
                }
                "type" if self.tok(1).k == K::Name && matches!(self.txn(2), "=" | "[") => {
                    self.bump();
                    let mt = self.b.mark();
                    self.primary_type_expr();
                    self.b.wrap(mt, "type", true);
                    self.b.field_last("left");
                    self.expect("=");
                    let mr = self.b.mark();
                    self.expression();
                    self.b.wrap(mr, "type", true);
                    self.b.field_last("right");
                    self.b.wrap(m, "type_alias_statement", true);
                    return;
                }
                _ => {}
            }
        }
        // expression statement / assignment
        self.expression_statement(m);
    }

    fn primary_type_expr(&mut self) {
        // name optionally with [T] type parameters
        let m = self.b.mark();
        self.bump_named("identifier");
        if self.at("[") {
            self.type_parameters();
            self.b.wrap(m, "generic_type", true);
        }
    }

    fn type_parameters(&mut self) {
        let m = self.b.mark();
        self.bump(); // [
        while !self.at("]") && self.k() != K::Eof {
            self.type_expr();
            if !self.eat(",") {
                break;
            }
        }
        self.expect("]");
        self.b.wrap(m, "type_parameter", true);
    }

    fn type_expr(&mut self) {
        let m = self.b.mark();
        if self.at("*") || self.at("**") {
            self.bump();
            self.expression();
            self.b.wrap(m, "splat_type", true);
        } else {
            self.expression();
        }
        self.b.wrap(m, "type", true);
    }

    fn import_names(&mut self, from: bool) {
        loop {
            let m = self.b.mark();
            if from {
                self.bump_named("identifier");
                let mm = self.b.mark();
                let _ = mm;
                self.b.wrap(m, "dotted_name", true);
            } else {
                self.dotted_name();
            }
            if self.at_kw("as") {
                self.b.field_last("name");
                self.bump();
                self.bump_named("identifier");
                self.b.field_last("alias");
                self.b.wrap(m, "aliased_import", true);
            }
            self.b.field_last("name");
            if !self.at(",") {
                break;
            }
            self.bump();
            if self.at(")") || self.at_stmt_end() {
                break;
            }
        }
    }

    fn dotted_name(&mut self) {
        let m = self.b.mark();
        self.bump_named("identifier");
        while self.at(".") && self.tok(1).k == K::Name {
            self.bump();
            self.bump_named("identifier");
        }
        self.b.wrap(m, "dotted_name", true);
    }

    fn import_from(&mut self, m: usize) {
        self.bump(); // from
        let is_future = self.tx() == "__future__";
        if self.at(".") || self.at("...") {
            let mr = self.b.mark();
            let mp = self.b.mark();
            while self.at(".") || self.at("...") {
                if self.at("...") {
                    // split into three dots
                    let t = self.advance_raw();
                    for k in 0..3 {
                        self.b.leaf(".", false, t.s + k, t.s + k + 1);
                    }
                } else {
                    self.bump();
                }
            }
            self.b.wrap(mp, "import_prefix", true);
            if self.k() == K::Name && !self.at_kw("import") {
                self.dotted_name();
            }
            self.b.wrap(mr, "relative_import", true);
        } else {
            self.dotted_name();
        }
        self.b.field_last("module_name");
        self.expect("import");
        if self.at("*") {
            let mw = self.b.mark();
            self.bump();
            self.b.wrap(mw, "wildcard_import", true);
        } else if self.at("(") {
            self.bump();
            self.import_names(true);
            self.expect(")");
        } else {
            self.import_names(true);
        }
        let k = if is_future { "future_import_statement" } else { "import_from_statement" };
        if is_future {
            // future import: module_name field removed
            for i in m..self.b.stack.len() {
                let id = self.b.stack[i] as usize;
                if self.b.nodes[id].field == Some("module_name") {
                    self.b.nodes[id].field = None;
                }
            }
        }
        self.b.wrap(m, k, true);
    }

    fn expression_statement(&mut self, m: usize) {
        let ml = self.b.mark();
        let n = self.expression_list_items(true);
        let is_assign = self.at("=") || self.at(":") || is_augassign(self.tx()) && self.k() == K::Op;
        if n > 1 {
            let k = if is_assign { "pattern_list" } else { "expression_list" };
            self.b.wrap(ml, k, true);
        }
        if self.at(":") {
            // annotated assignment
            self.b.field_last("left");
            self.bump();
            let mt = self.b.mark();
            self.expression();
            self.b.wrap(mt, "type", true);
            self.b.field_last("type");
            if self.at("=") {
                self.bump();
                self.assign_rhs();
                self.b.field_last("right");
            }
            self.b.wrap(ml, "assignment", true);
        } else if self.at("=") {
            self.to_pattern_last();
            self.b.field_last("left");
            self.bump();
            self.assign_rhs();
            self.b.field_last("right");
            self.b.wrap(ml, "assignment", true);
        } else if self.k() == K::Op && is_augassign(self.tx()) {
            self.b.field_last("left");
            self.bump();
            self.b.field_last("operator");
            self.assign_rhs();
            self.b.field_last("right");
            self.b.wrap(ml, "augmented_assignment", true);
        }
        self.b.wrap(m, "expression_statement", true);
    }

    fn to_pattern_last(&mut self) {
        if let Some(id) = self.b.last() {
            self.to_pattern(id);
        }
    }

    fn to_pattern(&mut self, id: u32) {
        let k = self.b.nodes[id as usize].kind;
        let nk = match k {
            "list_splat" => "list_splat_pattern",
            "tuple" => "tuple_pattern",
            "list" => "list_pattern",
            "expression_list" => "pattern_list",
            _ => return,
        };
        self.b.nodes[id as usize].kind = nk;
        let ch = self.b.nodes[id as usize].children.clone();
        for c in ch {
            self.to_pattern(c);
        }
    }

    fn assign_rhs(&mut self) {
        // right side: expression list, yield, or chained assignment
        let m = self.b.mark();
        if self.at_kw("yield") {
            self.yield_expr();
        } else {
            let n = self.expression_list_items(true);
            if n > 1 {
                let k = if self.at("=") { "pattern_list" } else { "expression_list" };
                self.b.wrap(m, k, true);
            }
        }
        if self.at("=") {
            self.to_pattern_last();
            self.b.field_last("left");
            self.bump();
            self.assign_rhs();
            self.b.field_last("right");
            self.b.wrap(m, "assignment", true);
        }
    }

    /// parse comma separated expressions; returns count (trailing comma counts as list)
    fn expression_list_items(&mut self, allow_star: bool) -> usize {
        let mut n = 0;
        loop {
            if allow_star && self.at("*") {
                let m = self.b.mark();
                self.bump();
                self.expression();
                self.b.wrap(m, "list_splat", true);
            } else {
                self.expression();
            }
            n += 1;
            if !self.at(",") {
                break;
            }
            self.bump();
            n = n.max(2);
            if self.at_stmt_end() || self.at("=") || self.at(")") || self.at(":") || is_augassign(self.tx()) && self.k() == K::Op || self.at_kw("in") {
                break;
            }
        }
        n
    }

    fn expression_list_or_single(&mut self) {
        let m = self.b.mark();
        let n = self.expression_list_items(true);
        if n > 1 {
            self.b.wrap(m, "expression_list", true);
        }
    }

    fn block(&mut self) {
        // after ':'
        if self.k() == K::Indent {
            self.hidden_tok();
            let m = self.b.mark();
            loop {
                self.skip_newlines();
                if matches!(self.k(), K::Dedent | K::Eof) {
                    break;
                }
                if self.k() == K::Indent {
                    self.hidden_tok();
                    continue;
                }
                let before = self.i;
                self.statement();
                if self.i == before {
                    self.error_token();
                }
            }
            if self.k() == K::Dedent {
                self.hidden_tok();
            }
            self.b.wrap(m, "block", true);
        } else if self.k() == K::Newline {
            let m = self.b.mark();
            self.hidden_tok();
            self.b.wrap(m, "block", true);
        } else {
            let m = self.b.mark();
            self.simple_statements();
            self.b.wrap(m, "block", true);
        }
    }

    fn function_def(&mut self, m: usize) {
        self.bump(); // def
        self.bump_named("identifier");
        self.b.field_last("name");
        if self.at("[") {
            self.type_parameters();
            self.b.field_last("type_parameters");
        }
        self.parameters("parameters", ")");
        self.b.field_last("parameters");
        if self.at("->") {
            self.bump();
            self.type_expr();
            self.b.field_last("return_type");
        }
        self.expect(":");
        self.block();
        self.b.field_last("body");
        self.b.wrap(m, "function_definition", true);
    }

    fn parameters(&mut self, kind: &'static str, close: &str) {
        let m = self.b.mark();
        let paren = close == ")";
        if paren {
            self.expect("(");
        }
        while !self.at(close) && self.k() != K::Eof && !(close == ":" && self.at(":")) {
            let mp = self.b.mark();
            if self.at("*") {
                self.bump();
                if self.at(",") || self.at(close) {
                    self.b.wrap(mp, "keyword_separator", true);
                } else {
                    self.bump_named("identifier");
                    self.b.wrap(mp, "list_splat_pattern", true);
                    self.typed_tail(mp, true);
                }
            } else if self.at("**") {
                self.bump();
                self.bump_named("identifier");
                self.b.wrap(mp, "dictionary_splat_pattern", true);
                self.typed_tail(mp, true);
            } else if self.at("/") {
                self.bump();
                self.b.wrap(mp, "positional_separator", true);
            } else if self.at("(") {
                // python2 tuple param
                self.primary();
                self.to_pattern_last();
            } else {
                self.bump_named("identifier");
                self.typed_tail(mp, paren);
            }
            if !self.eat(",") {
                break;
            }
        }
        if paren {
            self.expect(")");
        }
        self.b.wrap_at(m, kind, true, self.cur_pos());
    }

    fn typed_tail(&mut self, mp: usize, allow_type: bool) {
        let mut typed = false;
        if allow_type && self.at(":") {
            self.bump();
            self.type_expr();
            self.b.field_last("type");
            typed = true;
        }
        if self.at("=") {
            if !typed {
                // name field on identifier
                self.set_field_first(mp, "name");
            } else {
                self.set_field_first(mp, "name");
            }
            self.bump();
            self.expression();
            self.b.field_last("value");
            self.b.wrap(mp, if typed { "typed_default_parameter" } else { "default_parameter" }, true);
        } else if typed {
            self.b.wrap(mp, "typed_parameter", true);
        }
    }

    fn set_field_first(&mut self, m: usize, f: &'static str) {
        for i in m..self.b.stack.len() {
            let id = self.b.stack[i] as usize;
            if !self.b.nodes[id].extra {
                self.b.nodes[id].field = Some(f);
                return;
            }
        }
    }

    fn class_def(&mut self, m: usize) {
        self.bump(); // class
        self.bump_named("identifier");
        self.b.field_last("name");
        if self.at("[") {
            self.type_parameters();
            self.b.field_last("type_parameters");
        }
        if self.at("(") {
            self.argument_list();
            self.b.field_last("superclasses");
        }
        self.expect(":");
        self.block();
        self.b.field_last("body");
        self.b.wrap(m, "class_definition", true);
    }

    fn decorated(&mut self) {
        let m = self.b.mark();
        while self.at("@") {
            let md = self.b.mark();
            self.bump();
            self.expression();
            self.b.wrap(md, "decorator", true);
            if self.k() == K::Newline {
                self.hidden_tok();
            }
        }
        let md = self.b.mark();
        if self.at_kw("async") {
            self.bump();
        }
        if self.at_kw("def") {
            self.function_def(md);
        } else if self.at_kw("class") {
            self.class_def(md);
        } else {
            self.statement();
        }
        self.b.field_last("definition");
        self.b.wrap(m, "decorated_definition", true);
    }

    fn if_stmt(&mut self) {
        let m = self.b.mark();
        self.bump();
        self.named_expression_or_expr();
        self.b.field_last("condition");
        self.expect(":");
        self.block();
        self.b.field_last("consequence");
        while self.at_kw("elif") {
            let me = self.b.mark();
            self.bump();
            self.named_expression_or_expr();
            self.b.field_last("condition");
            self.expect(":");
            self.block();
            self.b.field_last("consequence");
            self.b.wrap(me, "elif_clause", true);
            self.b.field_last("alternative");
        }
        if self.at_kw("else") {
            self.else_clause();
            self.b.field_last("alternative");
        }
        self.b.wrap(m, "if_statement", true);
    }

    fn else_clause(&mut self) {
        let me = self.b.mark();
        self.bump();
        self.expect(":");
        self.block();
        self.b.field_last("body");
        self.b.wrap(me, "else_clause", true);
    }

    fn for_stmt(&mut self, m: usize) {
        self.bump(); // for
        let ml = self.b.mark();
        let n = self.target_list();
        if n > 1 {
            self.b.wrap(ml, "pattern_list", true);
        }
        self.b.field_last("left");
        self.expect("in");
        self.expression_list_or_single();
        self.b.field_last("right");
        self.expect(":");
        self.block();
        self.b.field_last("body");
        if self.at_kw("else") {
            self.else_clause();
            self.b.field_last("alternative");
        }
        self.b.wrap(m, "for_statement", true);
    }

    fn target_list(&mut self) -> usize {
        let mut n = 0;
        loop {
            if self.at("*") {
                let m = self.b.mark();
                self.bump();
                self.binary(PREC_OR_MIN);
                self.b.wrap(m, "list_splat_pattern", true);
            } else {
                self.binary(PREC_OR_MIN);
                self.to_pattern_last();
            }
            n += 1;
            if !self.at(",") {
                break;
            }
            self.bump();
            n = n.max(2);
            if self.at_kw("in") || self.at("=") {
                break;
            }
        }
        n
    }

    fn while_stmt(&mut self) {
        let m = self.b.mark();
        self.bump();
        self.named_expression_or_expr();
        self.b.field_last("condition");
        self.expect(":");
        self.block();
        self.b.field_last("body");
        if self.at_kw("else") {
            self.else_clause();
            self.b.field_last("alternative");
        }
        self.b.wrap(m, "while_statement", true);
    }

    fn try_stmt(&mut self) {
        let m = self.b.mark();
        self.bump();
        self.expect(":");
        self.block();
        self.b.field_last("body");
        loop {
            if self.at_kw("except") {
                let me = self.b.mark();
                self.bump();
                let group = self.at("*");
                if group {
                    self.bump();
                }
                if !self.at(":") {
                    let mv = self.b.mark();
                    self.expression();
                    if self.at_kw("as") {
                        self.bump();
                        let mt = self.b.mark();
                        self.expression();
                        self.b.wrap(mt, "as_pattern_target", true);
                        self.b.field_last("alias");
                        self.b.wrap(mv, "as_pattern", true);
                    } else if self.at(",") {
                        self.bump();
                        self.expression();
                    }
                    self.set_field_first(mv, "value");
                }
                self.expect(":");
                self.block();
                self.b.wrap(me, if group { "except_group_clause" } else { "except_clause" }, true);
                continue;
            }
            if self.at_kw("else") {
                self.else_clause();
                continue;
            }
            if self.at_kw("finally") {
                let mf = self.b.mark();
                self.bump();
                self.expect(":");
                self.block();
                self.b.wrap(mf, "finally_clause", true);
                continue;
            }
            break;
        }
        self.b.wrap(m, "try_statement", true);
    }

    fn with_stmt(&mut self, m: usize) {
        self.bump(); // with
        let mc = self.b.mark();
        let paren = self.at("(") && self.with_paren_items();
        if paren {
            self.bump();
        }
        loop {
            let mi = self.b.mark();
            let mv = self.b.mark();
            self.expression();
            if self.at_kw("as") {
                self.bump();
                let mt = self.b.mark();
                self.expression();
                self.b.wrap(mt, "as_pattern_target", true);
                self.b.field_last("alias");
                self.b.wrap(mv, "as_pattern", true);
            }
            self.b.field_last("value");
            self.b.wrap(mi, "with_item", true);
            if !self.eat(",") {
                break;
            }
            if paren && self.at(")") {
                break;
            }
        }
        if paren {
            self.expect(")");
        }
        self.b.wrap(mc, "with_clause", true);
        self.expect(":");
        self.block();
        self.b.field_last("body");
        self.b.wrap(m, "with_statement", true);
    }

    fn with_paren_items(&self) -> bool {
        // `with (a as b, c):` - parenthesized with items: check matching paren followed by ':'
        let mut depth = 0;
        let mut j = 0;
        let mut has_as = false;
        loop {
            let t = self.tok(j);
            if t.k == K::Eof || t.k == K::Newline {
                return false;
            }
            let x = &self.src[t.s..t.e];
            if t.k == K::Op {
                match x {
                    "(" | "[" | "{" => depth += 1,
                    ")" | "]" | "}" => {
                        depth -= 1;
                        if depth == 0 {
                            return self.txn(j + 1) == ":" && has_as;
                        }
                    }
                    _ => {}
                }
            }
            if t.k == K::Name && x == "as" && depth == 1 {
                has_as = true;
            }
            j += 1;
        }
    }

    fn match_stmt(&mut self) {
        let m = self.b.mark();
        self.bump(); // match
        let ms = self.b.mark();
        let n = self.expression_list_items(true);
        if n > 1 {
            self.b.wrap(ms, "expression_list", true);
        }
        self.b.field_last("subject");
        self.expect(":");
        let mb = self.b.mark();
        // block begins right after ':' (indent included)
        if self.k() == K::Indent {
            let t = self.tok(0);
            self.flush_extras(t.s + 1);
            self.i = self.idx(0) + 1;
            let colon_end = self.cur_pos();
            self.b.hidden(colon_end, colon_end);
        }
        loop {
            self.skip_newlines();
            if matches!(self.k(), K::Dedent | K::Eof) {
                break;
            }
            if self.at_kw("case") {
                self.case_clause();
                self.b.field_last("alternative");
            } else {
                let before = self.i;
                self.statement();
                if self.i == before {
                    self.error_token();
                }
            }
        }
        if self.k() == K::Dedent {
            self.hidden_tok();
        }
        self.b.wrap(mb, "block", true);
        self.b.field_last("body");
        self.b.wrap(m, "match_statement", true);
    }

    fn case_clause(&mut self) {
        let m = self.b.mark();
        self.bump(); // case
        loop {
            self.case_pattern();
            if !self.eat(",") {
                break;
            }
            if self.at(":") || self.at_kw("if") {
                break;
            }
        }
        if self.at_kw("if") {
            let mg = self.b.mark();
            self.bump();
            self.expression();
            self.b.wrap(mg, "if_clause", true);
            self.b.field_last("guard");
        }
        self.expect(":");
        self.block();
        self.b.field_last("consequence");
        self.b.wrap(m, "case_clause", true);
    }

    fn case_pattern(&mut self) {
        let m = self.b.mark();
        self.or_pattern();
        if self.at_kw("as") {
            self.bump();
            self.bump_named("identifier");
            self.b.wrap(m, "as_pattern", true);
        }
        self.b.wrap(m, "case_pattern", true);
    }

    fn or_pattern(&mut self) {
        let m = self.b.mark();
        self.closed_pattern();
        if self.at("|") {
            while self.at("|") {
                self.bump();
                self.closed_pattern();
            }
            self.b.wrap(m, "union_pattern", true);
        }
    }

    fn closed_pattern(&mut self) {
        let m = self.b.mark();
        let t = self.tok(0);
        let tx = self.tx();
        match t.k {
            K::Num => {
                self.number_tok();
                self.complex_tail(m);
            }
            K::Str => self.string_or_concat(),
            K::Op => match tx {
                "-" => {
                    self.bump();
                    self.number_tok();
                    self.complex_tail(m);
                }
                "*" => {
                    self.bump();
                    self.bump_named("identifier");
                    self.b.wrap(m, "splat_pattern", true);
                }
                "**" => {
                    self.bump();
                    self.bump_named("identifier");
                    self.b.wrap(m, "splat_pattern", true);
                }
                "(" | "[" => {
                    let close = if tx == "(" { ")" } else { "]" };
                    self.bump();
                    let mut n = 0;
                    let mut comma = false;
                    while !self.at(close) && self.k() != K::Eof {
                        self.case_pattern();
                        n += 1;
                        if !self.eat(",") {
                            break;
                        }
                        comma = true;
                    }
                    self.expect(close);
                    let _ = n;
                    let _ = comma;
                    self.b.wrap(m, if tx == "(" { "tuple_pattern" } else { "list_pattern" }, true);
                }
                "{" => {
                    self.bump();
                    while !self.at("}") && self.k() != K::Eof {
                        if self.at("**") {
                            let ms = self.b.mark();
                            self.bump();
                            self.bump_named("identifier");
                            self.b.wrap(ms, "splat_pattern", true);
                        } else {
                            self.closed_pattern();
                            self.b.field_last("key");
                            self.expect(":");
                            self.case_pattern();
                            self.b.field_last("value");
                        }
                        if !self.eat(",") {
                            break;
                        }
                    }
                    self.expect("}");
                    self.b.wrap(m, "dict_pattern", true);
                }
                _ => {
                    self.error_token();
                }
            },
            K::Name => match tx {
                "None" => {
                    self.bump_named("none");
                }
                "True" => {
                    self.bump_named("true");
                }
                "False" => {
                    self.bump_named("false");
                }
                "_" if !matches!(self.txn(1), "." | "(") => {
                    self.bump();
                }
                _ => {
                    let md = self.b.mark();
                    self.bump_named("identifier");
                    while self.at(".") {
                        self.bump();
                        self.bump_named("identifier");
                    }
                    self.b.wrap(md, "dotted_name", true);
                    if self.at("(") {
                        self.bump();
                        while !self.at(")") && self.k() != K::Eof {
                            if self.tok(0).k == K::Name && self.txn(1) == "=" {
                                let mk = self.b.mark();
                                self.bump_named("identifier");
                                self.bump();
                                self.or_pattern_simple();
                                self.b.wrap(mk, "keyword_pattern", true);
                                self.b.wrap(mk, "case_pattern", true);
                            } else {
                                self.case_pattern();
                            }
                            if !self.eat(",") {
                                break;
                            }
                        }
                        self.expect(")");
                        self.b.wrap(m, "class_pattern", true);
                    }
                }
            },
            _ => self.error_token(),
        }
    }

    fn or_pattern_simple(&mut self) {
        let m = self.b.mark();
        self.closed_pattern();
        if self.at("|") {
            while self.at("|") {
                self.bump();
                self.closed_pattern();
            }
            self.b.wrap(m, "union_pattern", true);
        }
    }

    fn complex_tail(&mut self, m: usize) {
        if self.at("+") || self.at("-") {
            if self.tok(1).k == K::Num {
                self.bump();
                self.number_tok();
                self.b.wrap(m, "complex_pattern", true);
            }
        }
    }

    fn number_tok(&mut self) {
        let t = self.tok(0);
        let tx = &self.src[t.s..t.e];
        let lower = tx.to_ascii_lowercase();
        let is_float = !lower.starts_with("0x")
            && !lower.starts_with("0o")
            && !lower.starts_with("0b")
            && (tx.contains('.') || lower.contains('e'));
        self.bump_named(if is_float { "float" } else { "integer" });
    }

    // ---- expressions ----
    fn named_expression_or_expr(&mut self) {
        self.expression();
    }

    fn expression(&mut self) {
        self.depth += 1;
        if self.depth > 300 {
            self.error_token();
            self.depth -= 1;
            return;
        }
        let m = self.b.mark();
        if self.at_kw("lambda") {
            self.lambda();
            self.depth -= 1;
            return;
        }
        if self.at_kw("yield") {
            self.yield_expr();
            self.depth -= 1;
            return;
        }
        // walrus
        if self.tok(0).k == K::Name && self.txn(1) == ":=" {
            self.bump_named("identifier");
            self.b.field_last("name");
            self.bump();
            self.expression();
            self.b.field_last("value");
            self.b.wrap(m, "named_expression", true);
            self.depth -= 1;
            return;
        }
        self.binary(PREC_OR_MIN);
        if self.at_kw("if") {
            self.bump();
            self.binary(PREC_OR_MIN);
            self.expect("else");
            self.expression();
            self.b.wrap(m, "conditional_expression", true);
        }
        self.depth -= 1;
    }

    fn yield_expr(&mut self) {
        let m = self.b.mark();
        self.bump(); // yield
        if self.at_kw("from") {
            self.bump();
            self.expression();
        } else if !(self.at_stmt_end() || self.at(")") || self.at("]") || self.at("}") || self.at("=")) {
            self.expression_list_or_single();
        }
        self.b.wrap(m, "yield", true);
    }

    fn lambda(&mut self) {
        let m = self.b.mark();
        self.bump(); // lambda
        if !self.at(":") {
            self.parameters("lambda_parameters", ":");
            self.b.field_last("parameters");
        }
        self.expect(":");
        self.expression();
        self.b.field_last("body");
        self.b.wrap(m, "lambda", true);
    }

    fn binop(&self) -> Option<(u8, bool, &'static str)> {
        let t = self.tok(0);
        let tx = &self.src[t.s..t.e];
        if t.k == K::Name {
            return match tx {
                "or" => Some((10, false, "boolean_operator")),
                "and" => Some((11, false, "boolean_operator")),
                "in" | "is" => Some((13, false, "comparison_operator")),
                "not" if self.txn(1) == "in" => Some((13, false, "comparison_operator")),
                _ => None,
            };
        }
        if t.k != K::Op {
            return None;
        }
        Some(match tx {
            "<" | ">" | "<=" | ">=" | "==" | "!=" | "<>" => (13, false, "comparison_operator"),
            "|" => (14, false, "binary_operator"),
            "&" => (15, false, "binary_operator"),
            "^" => (16, false, "binary_operator"),
            "<<" | ">>" => (17, false, "binary_operator"),
            "+" | "-" => (18, false, "binary_operator"),
            "*" | "@" | "/" | "%" | "//" => (19, false, "binary_operator"),
            "**" => (21, true, "binary_operator"),
            _ => return None,
        })
    }

    fn binary(&mut self, min: u8) {
        let m = self.b.mark();
        self.unary(min);
        loop {
            let Some((p, right, kind)) = self.binop() else { break };
            if p < min {
                break;
            }
            if kind == "comparison_operator" {
                // chain
                while let Some((13, _, _)) = self.binop() {
                    self.comparison_op();
                    self.binary(14);
                }
                self.b.wrap(m, kind, true);
                continue;
            }
            self.b.field_last("left");
            self.bump();
            self.b.field_last("operator");
            self.binary(if right { p } else { p + 1 });
            self.b.field_last("right");
            self.b.wrap(m, kind, true);
        }
    }

    fn comparison_op(&mut self) {
        let tx = self.tx();
        if tx == "not" {
            let m = self.b.mark();
            self.bump();
            self.bump();
            self.b.wrap(m, "not in", false);
        } else if tx == "is" && self.txn(1) == "not" {
            let m = self.b.mark();
            self.bump();
            self.bump();
            self.b.wrap(m, "is not", false);
        } else {
            self.bump();
        }
        self.b.field_last("operators");
    }

    fn unary(&mut self, min: u8) {
        let m = self.b.mark();
        if self.at_kw("not") && min <= 12 {
            self.bump();
            self.binary(12);
            self.b.field_last("argument");
            self.b.wrap(m, "not_operator", true);
            return;
        }
        if self.k() == K::Op && matches!(self.tx(), "-" | "+" | "~") {
            self.bump();
            self.b.field_last("operator");
            self.binary(20);
            self.b.field_last("argument");
            self.b.wrap(m, "unary_operator", true);
            return;
        }
        if self.at_kw("await") && !matches!(self.txn(1), "=" | "." | ")" | "," | "") {
            self.bump();
            self.binary(20);
            self.b.wrap(m, "await", true);
            return;
        }
        self.postfix();
    }

    fn postfix(&mut self) {
        let m = self.b.mark();
        self.primary();
        loop {
            if self.at(".") {
                self.set_field_first(m, "object");
                self.bump();
                self.bump_named("identifier");
                self.b.field_last("attribute");
                self.b.wrap(m, "attribute", true);
            } else if self.at("(") {
                self.set_field_first(m, "function");
                if self.is_generator_call() {
                    self.paren_generator();
                } else {
                    self.argument_list();
                }
                self.b.field_last("arguments");
                self.b.wrap(m, "call", true);
            } else if self.at("[") {
                self.set_field_first(m, "value");
                self.bump();
                loop {
                    if self.at("]") {
                        break;
                    }
                    self.subscript_item();
                    self.b.field_last("subscript");
                    if !self.eat(",") {
                        break;
                    }
                }
                self.expect("]");
                self.b.wrap(m, "subscript", true);
            } else {
                break;
            }
        }
    }

    fn is_generator_call(&self) -> bool {
        // ( expr for ... )  with single generator
        let mut depth = 0;
        let mut j = 0;
        loop {
            let t = self.tok(j);
            if t.k == K::Eof {
                return false;
            }
            let x = &self.src[t.s..t.e];
            if t.k == K::Op {
                match x {
                    "(" | "[" | "{" => depth += 1,
                    ")" | "]" | "}" => {
                        depth -= 1;
                        if depth == 0 {
                            return false;
                        }
                    }
                    "," if depth == 1 => return false,
                    _ => {}
                }
            }
            if t.k == K::Name && depth == 1 && (x == "for" || (x == "async" && self.txn(j + 1) == "for")) && j > 1 {
                return true;
            }
            j += 1;
        }
    }

    fn subscript_item(&mut self) {
        let m = self.b.mark();
        if self.at(":") || self.tok_is_slice() {
            // slice
            if !self.at(":") {
                self.expression();
            }
            self.expect(":");
            if !self.at(":") && !self.at("]") && !self.at(",") {
                self.expression();
            }
            if self.at(":") {
                self.bump();
                if !self.at("]") && !self.at(",") {
                    self.expression();
                }
            }
            self.b.wrap(m, "slice", true);
        } else {
            self.expression();
        }
    }

    fn tok_is_slice(&self) -> bool {
        // scan current item for ':' at depth 0 before ',' or ']'
        let mut depth = 0;
        let mut j = 0;
        loop {
            let t = self.tok(j);
            if t.k == K::Eof {
                return false;
            }
            let x = &self.src[t.s..t.e];
            if t.k == K::Op {
                match x {
                    "(" | "[" | "{" => depth += 1,
                    ")" | "]" | "}" => {
                        if depth == 0 {
                            return false;
                        }
                        depth -= 1;
                    }
                    "," if depth == 0 => return false,
                    ":" if depth == 0 => return true,
                    _ => {}
                }
            }
            if t.k == K::Name && x == "lambda" {
                return false;
            }
            j += 1;
        }
    }

    fn argument_list(&mut self) {
        let m = self.b.mark();
        self.bump(); // (
        while !self.at(")") && self.k() != K::Eof {
            let ma = self.b.mark();
            if self.at("*") {
                self.bump();
                self.expression();
                self.b.wrap(ma, "list_splat", true);
            } else if self.at("**") {
                self.bump();
                self.expression();
                self.b.wrap(ma, "dictionary_splat", true);
            } else if self.tok(0).k == K::Name && self.txn(1) == "=" {
                self.bump_named("identifier");
                self.b.field_last("name");
                self.bump();
                self.expression();
                self.b.field_last("value");
                self.b.wrap(ma, "keyword_argument", true);
            } else {
                let before = self.i;
                self.expression();
                if self.at_kw("for") || self.at_kw("async") {
                    // generator argument
                    self.comprehension_clauses();
                    self.b.wrap(ma, "generator_expression", true);
                }
                if self.i == before {
                    break;
                }
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect(")");
        self.b.wrap(m, "argument_list", true);
    }

    fn paren_generator(&mut self) {
        let m = self.b.mark();
        self.bump(); // (
        self.expression();
        self.b.field_last("body");
        self.comprehension_clauses();
        self.expect(")");
        self.b.wrap(m, "generator_expression", true);
    }

    fn comprehension_clauses(&mut self) {
        loop {
            if self.at_kw("for") || (self.at_kw("async") && self.txn(1) == "for") {
                let m = self.b.mark();
                if self.at_kw("async") {
                    self.bump();
                }
                self.bump(); // for
                let ml = self.b.mark();
                let n = self.target_list();
                if n > 1 {
                    self.b.wrap(ml, "pattern_list", true);
                }
                self.b.field_last("left");
                self.expect("in");
                // right: or-expression (no conditional)
                let mr = self.b.mark();
                self.binary(PREC_OR_MIN);
                let mut multi = false;
                while self.at(",") && !self.at_close() {
                    multi = true;
                    self.bump();
                    if self.at_close() {
                        break;
                    }
                    self.binary(PREC_OR_MIN);
                }
                if multi {
                    self.b.wrap(mr, "expression_list", true);
                }
                self.b.field_last("right");
                self.b.wrap(m, "for_in_clause", true);
            } else if self.at_kw("if") {
                let m = self.b.mark();
                self.bump();
                self.binary(PREC_OR_MIN);
                self.b.wrap(m, "if_clause", true);
            } else {
                break;
            }
        }
    }

    fn at_close(&self) -> bool {
        self.at(")") || self.at("]") || self.at("}")
    }

    fn primary(&mut self) {
        let m = self.b.mark();
        let t = self.tok(0);
        let tx = self.tx();
        match t.k {
            K::Num => self.number_tok(),
            K::Str => self.string_or_concat(),
            K::Name => match tx {
                "None" => {
                    self.bump_named("none");
                }
                "True" => {
                    self.bump_named("true");
                }
                "False" => {
                    self.bump_named("false");
                }
                _ => {
                    self.bump_named("identifier");
                }
            },
            K::Op => match tx {
                "(" => self.paren(),
                "[" => self.list_like(),
                "{" => self.dict_or_set(),
                "..." => {
                    self.bump_named("ellipsis");
                }
                "*" => {
                    self.bump();
                    self.binary(PREC_OR_MIN);
                    self.b.wrap(m, "list_splat", true);
                }
                _ => self.error_token(),
            },
            _ => {
                let p = self.cur_pos();
                self.b.missing("identifier", true, p);
            }
        }
    }

    fn paren(&mut self) {
        let m = self.b.mark();
        self.bump(); // (
        if self.at(")") {
            self.bump();
            self.b.wrap(m, "tuple", true);
            return;
        }
        if self.at_kw("yield") {
            self.yield_expr();
            self.expect(")");
            self.b.wrap(m, "parenthesized_expression", true);
            return;
        }
        let mut n = 0;
        let mut trailing = false;
        loop {
            if self.at("*") {
                let ms = self.b.mark();
                self.bump();
                self.binary(PREC_OR_MIN);
                self.b.wrap(ms, "list_splat", true);
            } else {
                self.expression();
            }
            n += 1;
            if n == 1 && (self.at_kw("for") || self.at_kw("async")) {
                self.b.field_last("body");
                self.comprehension_clauses();
                self.expect(")");
                self.b.wrap(m, "generator_expression", true);
                return;
            }
            if !self.at(",") {
                break;
            }
            self.bump();
            trailing = true;
            if self.at(")") {
                break;
            }
            trailing = false;
        }
        self.expect(")");
        if n == 1 && !trailing {
            // parenthesized list splat
            let last = self.b.stack[self.b.stack.len() - 2];
            let k = if self.b.nodes[last as usize].kind == "list_splat" { "parenthesized_list_splat" } else { "parenthesized_expression" };
            self.b.wrap(m, k, true);
        } else {
            self.b.wrap(m, "tuple", true);
        }
    }

    fn list_like(&mut self) {
        let m = self.b.mark();
        self.bump(); // [
        let mut n = 0;
        while !self.at("]") && self.k() != K::Eof {
            if self.at("*") {
                let ms = self.b.mark();
                self.bump();
                self.binary(PREC_OR_MIN);
                self.b.wrap(ms, "list_splat", true);
            } else {
                self.expression();
            }
            n += 1;
            if n == 1 && (self.at_kw("for") || self.at_kw("async")) {
                self.b.field_last("body");
                self.comprehension_clauses();
                self.expect("]");
                self.b.wrap(m, "list_comprehension", true);
                return;
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect("]");
        self.b.wrap(m, "list", true);
    }

    fn dict_or_set(&mut self) {
        let m = self.b.mark();
        self.bump(); // {
        if self.at("}") {
            self.bump();
            self.b.wrap(m, "dictionary", true);
            return;
        }
        let mut is_dict = None;
        let mut n = 0;
        while !self.at("}") && self.k() != K::Eof {
            let me = self.b.mark();
            if self.at("**") {
                self.bump();
                self.binary(PREC_OR_MIN);
                self.b.wrap(me, "dictionary_splat", true);
                is_dict = Some(true);
            } else if self.at("*") {
                self.bump();
                self.binary(PREC_OR_MIN);
                self.b.wrap(me, "list_splat", true);
                is_dict = Some(false);
            } else {
                self.expression();
                if self.at(":") {
                    self.b.field_last("key");
                    self.bump();
                    self.expression();
                    self.b.field_last("value");
                    self.b.wrap(me, "pair", true);
                    is_dict = Some(true);
                } else {
                    is_dict = Some(is_dict.unwrap_or(false));
                }
            }
            n += 1;
            if n == 1 && (self.at_kw("for") || self.at_kw("async")) {
                self.b.field_last("body");
                self.comprehension_clauses();
                self.expect("}");
                let k = if is_dict == Some(true) { "dictionary_comprehension" } else { "set_comprehension" };
                self.b.wrap(m, k, true);
                return;
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect("}");
        self.b.wrap(m, if is_dict == Some(false) { "set" } else { "dictionary" }, true);
    }

    fn string_or_concat(&mut self) {
        let m = self.b.mark();
        let mut n = 0;
        while self.k() == K::Str {
            self.string();
            n += 1;
        }
        if n > 1 {
            self.b.wrap(m, "concatenated_string", true);
        }
    }

    fn string(&mut self) {
        let t = self.advance_raw();
        let m = self.b.mark();
        let src = self.src;
        let b = src.as_bytes();
        let mut j = t.s;
        while j < t.e && b[j].is_ascii_alphabetic() {
            j += 1;
        }
        let prefix = src[t.s..j].to_ascii_lowercase();
        let raw = prefix.contains('r');
        let fstr = prefix.contains('f') || prefix.contains('t');
        let bytes = prefix.contains('b');
        let q = b[j];
        let triple = j + 2 < t.e && b[j + 1] == q && b[j + 2] == q;
        let qlen = if triple { 3 } else { 1 };
        let start_end = j + qlen;
        self.b.leaf("string_start", true, t.s, start_end.min(t.e));
        let closed = t.e >= start_end + qlen && &src[t.e - qlen..t.e] == &src[j..j + qlen] && t.e - qlen >= start_end;
        let content_end = if closed { t.e - qlen } else { t.e };
        self.string_body(start_end, content_end, raw, fstr, bytes, q);
        if closed {
            self.b.leaf("string_end", true, content_end, t.e);
        }
        self.b.wrap(m, "string", true);
    }

    fn string_body(&mut self, s: usize, e: usize, raw: bool, fstr: bool, bytes: bool, q: u8) {
        let b = self.src.as_bytes();
        let mut i = s;
        let mut cs = s; // content start
        let mut content_mark: Option<usize> = None;
        let _ = bytes;
        let flush_content = |p: &mut P, cs: usize, i: usize, cm: &mut Option<usize>| {
            if let Some(mk) = cm.take() {
                p.b.wrap_at(mk, "string_content", true, cs);
                // fix range to text span
                let id = p.b.last().unwrap() as usize;
                p.b.nodes[id].start = cs;
                p.b.nodes[id].end = i;
            } else if i > cs {
                p.b.leaf("string_content", true, cs, i);
            }
        };
        while i < e {
            let c = b[i];
            if c == b'\\' && !raw {
                if content_mark.is_none() {
                    content_mark = Some(self.b.mark());
                }
                let mut k = i + 1;
                if k < e {
                    let ch = self.src[k..].chars().next().unwrap();
                    match ch {
                        'x' => {
                            k += 1;
                            let mut n = 0;
                            while k < e && n < 2 && b[k].is_ascii_hexdigit() {
                                k += 1;
                                n += 1;
                            }
                        }
                        'u' | 'U' if !bytes => {
                            let want = if ch == 'u' { 4 } else { 8 };
                            k += 1;
                            let mut n = 0;
                            while k < e && n < want && b[k].is_ascii_hexdigit() {
                                k += 1;
                                n += 1;
                            }
                        }
                        'N' if !bytes && k + 1 < e && b[k + 1] == b'{' => {
                            while k < e && b[k] != b'}' {
                                k += 1;
                            }
                            k += 1;
                        }
                        '0'..='7' => {
                            let mut n = 0;
                            while k < e && n < 3 && (b'0'..=b'7').contains(&b[k]) {
                                k += 1;
                                n += 1;
                            }
                        }
                        '\r' => {
                            k += 1;
                            if k < e && b[k] == b'\n' {
                                k += 1;
                            }
                        }
                        _ => k += ch.len_utf8(),
                    }
                }
                let is_escape = {
                    let ch = self.src[i + 1..].chars().next().unwrap_or(' ');
                    matches!(ch, '\\' | '\'' | '"' | 'a' | 'b' | 'f' | 'n' | 'r' | 't' | 'v' | '\n' | '\r' | '0'..='7' | 'x')
                        || (!bytes && matches!(ch, 'u' | 'U' | 'N'))
                };
                if is_escape {
                    self.b.leaf("escape_sequence", true, i, k.min(e));
                }
                i = k;
                continue;
            }
            if fstr && c == b'{' {
                if i + 1 < e && b[i + 1] == b'{' {
                    if content_mark.is_none() {
                        content_mark = Some(self.b.mark());
                    }
                    self.b.leaf("escape_interpolation", true, i, i + 2);
                    i += 2;
                    continue;
                }
                flush_content(self, cs, i, &mut content_mark);
                let end = self.interpolation(i, e, q);
                i = end;
                cs = i;
                continue;
            }
            if fstr && c == b'}' && i + 1 < e && b[i + 1] == b'}' {
                if content_mark.is_none() {
                    content_mark = Some(self.b.mark());
                }
                self.b.leaf("escape_interpolation", true, i, i + 2);
                i += 2;
                continue;
            }
            i += 1;
        }
        flush_content(self, cs, i.min(e), &mut content_mark);
    }

    /// parse an f-string interpolation starting at '{' (position i). returns end position
    fn interpolation(&mut self, i: usize, e: usize, q: u8) -> usize {
        let b = self.src.as_bytes();
        // find matching '}' respecting nesting and strings
        let mut depth = 0;
        let mut k = i;
        let mut expr_end = None;
        let mut close = e;
        while k < e {
            let c = b[k];
            if c == b'\'' || c == b'"' {
                if c != q {
                    k = scan_string(self.src, k).min(e);
                    continue;
                }
            }
            match c {
                b'{' | b'[' | b'(' => depth += 1,
                b'}' | b']' | b')' => {
                    depth -= 1;
                    if depth == 0 {
                        close = k;
                        break;
                    }
                }
                b'!' if depth == 1 && expr_end.is_none() && k + 1 < e && b[k + 1] != b'=' => expr_end = Some(k),
                b':' if depth == 1 && expr_end.is_none() => expr_end = Some(k),
                _ => {}
            }
            k += 1;
        }
        let m = self.b.mark();
        self.b.leaf("{", false, i, i + 1);
        let mut ee = expr_end.unwrap_or(close);
        // trailing '=' self-documenting
        let mut eq_pos = None;
        {
            let mut z = ee;
            while z > i + 1 && b[z - 1] == b' ' {
                z -= 1;
            }
            if z > i + 1 && b[z - 1] == b'=' && !(z > i + 2 && matches!(b[z - 2], b'=' | b'!' | b'<' | b'>')) {
                eq_pos = Some(z - 1);
                ee = z - 1;
            }
        }
        // parse expression in [i+1, ee)
        let saved_toks = std::mem::replace(&mut self.toks, tokenize(self.src, i + 1, ee, true));
        let saved_i = self.i;
        self.i = 0;
        let mx = self.b.mark();
        let n = self.expression_list_items(true);
        if n > 1 {
            self.b.wrap(mx, "expression_list", true);
        }
        self.b.field_last("expression");
        self.flush_extras(usize::MAX);
        self.toks = saved_toks;
        self.i = saved_i;
        if let Some(p) = eq_pos {
            self.b.leaf("=", false, p, p + 1);
        }
        let mut pos = expr_end.unwrap_or(close);
        if pos < close && b[pos] == b'!' {
            let mut z = pos + 1;
            while z < close && b[z] != b':' {
                z += 1;
            }
            self.b.leaf("type_conversion", true, pos, z);
            self.b.field_last("type_conversion");
            pos = z;
        }
        if pos < close && b[pos] == b':' {
            let mf = self.b.mark();
            self.b.leaf(":", false, pos, pos + 1);
            let mut z = pos + 1;
            while z < close {
                if b[z] == b'{' {
                    // nested format expression
                    let end = self.format_expression(z, close, q);
                    z = end;
                    continue;
                }
                z += 1;
            }
            self.b.wrap(mf, "format_specifier", true);
            let id = self.b.last().unwrap() as usize;
            self.b.nodes[id].start = pos;
            self.b.nodes[id].end = close;
            self.b.field_last("format_specifier");
        }
        if close < e {
            self.b.leaf("}", false, close, close + 1);
        }
        self.b.wrap(m, "interpolation", true);
        (close + 1).min(e)
    }

    fn format_expression(&mut self, i: usize, e: usize, q: u8) -> usize {
        let b = self.src.as_bytes();
        let mut depth = 0;
        let mut k = i;
        let mut close = e;
        while k < e {
            match b[k] {
                b'{' => depth += 1,
                b'}' => {
                    depth -= 1;
                    if depth == 0 {
                        close = k;
                        break;
                    }
                }
                _ => {}
            }
            k += 1;
        }
        let _ = q;
        let m = self.b.mark();
        self.b.leaf("{", false, i, i + 1);
        let saved_toks = std::mem::replace(&mut self.toks, tokenize(self.src, i + 1, close, true));
        let saved_i = self.i;
        self.i = 0;
        self.expression();
        self.b.field_last("expression");
        self.toks = saved_toks;
        self.i = saved_i;
        if close < e {
            self.b.leaf("}", false, close, close + 1);
        }
        self.b.wrap(m, "format_expression", true);
        (close + 1).min(e)
    }
}

const PREC_OR_MIN: u8 = 10;

fn is_augassign(s: &str) -> bool {
    matches!(s, "+=" | "-=" | "*=" | "/=" | "//=" | "%=" | "**=" | ">>=" | "<<=" | "&=" | "^=" | "|=" | "@=")
}

#[allow(dead_code)]
fn is_keyword(s: &str) -> bool {
    KEYWORDS.contains(&s)
}
