// Rust parser producing tree-sitter-rust compatible CST
use super::js::intern;
use crate::tree::{Builder, Tree};

#[derive(Clone, Copy, PartialEq, Debug)]
enum K {
    Ident,
    Lifetime,
    Int,
    Float,
    Str,
    RawStr,
    Char,
    Op,
    LineComment,
    BlockComment,
    Eof,
}

#[derive(Clone, Copy, Debug)]
struct Tk {
    k: K,
    s: usize,
    e: usize,
}

const PRIMS: &[&str] = &[
    "u8", "i8", "u16", "i16", "u32", "i32", "u64", "i64", "u128", "i128", "isize", "usize", "f32", "f64", "bool",
    "str", "char",
];

const OPS: &[&str] = &[
    "<<=", "...", "..=", "::", "->", "=>", "..", "==", "!=", "<=", "&&", "||", "+=", "-=", "*=", "/=", "%=", "^=",
    "&=", "|=", "<<",
];

fn is_id_start(c: char) -> bool {
    c == '_' || c.is_alphabetic()
}
fn is_id_char(c: char) -> bool {
    c == '_' || c.is_alphanumeric()
}

fn tokenize(src: &str) -> Vec<Tk> {
    let b = src.as_bytes();
    let n = b.len();
    let mut out = Vec::new();
    let mut i = 0;
    if src.starts_with("#!") && !src.starts_with("#![") {
        // shebang handled by parser via first token? emit as comment-like
        let e = src.find('\n').unwrap_or(n);
        out.push(Tk { k: K::LineComment, s: 0, e: 0 });
        out.pop();
        i = e;
        out.push(Tk { k: K::Op, s: 0, e });
        out.last_mut().unwrap().k = K::Eof; // marker replaced below
        out.pop();
        out.push(Tk { k: K::Ident, s: 0, e });
        out.last_mut().unwrap().k = K::Char;
        out.pop();
    }
    while i < n {
        let c = b[i];
        if c.is_ascii_whitespace() {
            i += 1;
            continue;
        }
        if c == b'/' && i + 1 < n && b[i + 1] == b'/' {
            let s = i;
            while i < n && b[i] != b'\n' {
                i += 1;
            }
            out.push(Tk { k: K::LineComment, s, e: i });
            continue;
        }
        if c == b'/' && i + 1 < n && b[i + 1] == b'*' {
            let s = i;
            i += 2;
            let mut depth = 1;
            while i < n && depth > 0 {
                if b[i] == b'/' && i + 1 < n && b[i + 1] == b'*' {
                    depth += 1;
                    i += 2;
                } else if b[i] == b'*' && i + 1 < n && b[i + 1] == b'/' {
                    depth -= 1;
                    i += 2;
                } else {
                    i += 1;
                }
            }
            out.push(Tk { k: K::BlockComment, s, e: i });
            continue;
        }
        let s = i;
        // raw strings / byte strings
        if (c == b'r' || c == b'b' || c == b'c') && i + 1 < n {
            let mut j = i;
            if (b[j] == b'b' || b[j] == b'c') && j + 1 < n && b[j + 1] == b'r' {
                j += 1;
            }
            if b[j] == b'r' && j + 1 < n && (b[j + 1] == b'"' || (b[j + 1] == b'#' && raw_follows(b, j + 1))) {
                let mut k = j + 1;
                let mut hashes = 0;
                while k < n && b[k] == b'#' {
                    hashes += 1;
                    k += 1;
                }
                if k < n && b[k] == b'"' {
                    k += 1;
                    loop {
                        if k >= n {
                            break;
                        }
                        if b[k] == b'"' {
                            let mut h = 0;
                            while h < hashes && k + 1 + h < n && b[k + 1 + h] == b'#' {
                                h += 1;
                            }
                            if h == hashes {
                                k += 1 + hashes;
                                break;
                            }
                        }
                        k += 1;
                    }
                    out.push(Tk { k: K::RawStr, s, e: k.min(n) });
                    i = k.min(n);
                    continue;
                }
            }
            if (c == b'b' || c == b'c') && b[i + 1] == b'"' {
                let e = scan_str(b, i + 1);
                out.push(Tk { k: K::Str, s, e });
                i = e;
                continue;
            }
            if c == b'b' && b[i + 1] == b'\'' {
                let e = scan_char(b, i + 1);
                out.push(Tk { k: K::Char, s, e });
                i = e;
                continue;
            }
        }
        if c == b'"' {
            let e = scan_str(b, i);
            out.push(Tk { k: K::Str, s, e });
            i = e;
            continue;
        }
        if c == b'\'' {
            // char literal or lifetime
            if i + 2 < n && b[i + 1] == b'\\' {
                let e = scan_char(b, i);
                out.push(Tk { k: K::Char, s, e });
                i = e;
                continue;
            }
            let ch = src[i + 1..].chars().next().unwrap_or(' ');
            let l = ch.len_utf8();
            if i + 1 + l < n && b[i + 1 + l] == b'\'' {
                out.push(Tk { k: K::Char, s, e: i + 2 + l });
                i += 2 + l;
                continue;
            }
            if is_id_start(ch) {
                let mut e = i + 1;
                for (o, c2) in src[i + 1..].char_indices() {
                    if !is_id_char(c2) {
                        e = i + 1 + o;
                        break;
                    }
                    e = i + 1 + o + c2.len_utf8();
                }
                out.push(Tk { k: K::Lifetime, s, e });
                i = e;
                continue;
            }
            out.push(Tk { k: K::Op, s, e: i + 1 });
            i += 1;
            continue;
        }
        if c.is_ascii_digit() {
            let (k, e) = scan_num(src, i);
            out.push(Tk { k, s, e });
            i = e;
            continue;
        }
        let ch = src[i..].chars().next().unwrap();
        if is_id_start(ch) {
            let mut e = i;
            // raw identifier r#name
            if c == b'r' && i + 2 < n && b[i + 1] == b'#' && (b[i + 2] as char).is_alphabetic() {
                e = i + 2;
            }
            for (o, c2) in src[e..].char_indices() {
                if !is_id_char(c2) {
                    e += o;
                    break;
                }
                if e + o + c2.len_utf8() >= n {
                    e = n;
                    break;
                }
            }
            if e == i {
                e = i + ch.len_utf8();
            }
            out.push(Tk { k: K::Ident, s, e });
            i = e;
            continue;
        }
        let r = &src[i..];
        let mut l = ch.len_utf8();
        for o in OPS {
            if r.starts_with(o) {
                l = o.len();
                break;
            }
        }
        out.push(Tk { k: K::Op, s, e: i + l });
        i += l;
    }
    out.push(Tk { k: K::Eof, s: n, e: n });
    out
}

fn raw_follows(b: &[u8], mut k: usize) -> bool {
    while k < b.len() && b[k] == b'#' {
        k += 1;
    }
    k < b.len() && b[k] == b'"'
}

fn scan_str(b: &[u8], i: usize) -> usize {
    let mut k = i + 1;
    while k < b.len() {
        match b[k] {
            b'\\' => k += 2,
            b'"' => return k + 1,
            _ => k += 1,
        }
    }
    b.len()
}

fn scan_char(b: &[u8], i: usize) -> usize {
    let mut k = i + 1;
    while k < b.len() {
        match b[k] {
            b'\\' => k += 2,
            b'\'' => return k + 1,
            b'\n' => return k,
            _ => k += 1,
        }
    }
    b.len()
}

fn scan_num(src: &str, mut i: usize) -> (K, usize) {
    let b = src.as_bytes();
    let n = b.len();
    let mut float = false;
    if b[i] == b'0' && i + 1 < n && matches!(b[i + 1], b'x' | b'o' | b'b') {
        i += 2;
        while i < n && (b[i].is_ascii_hexdigit() || b[i] == b'_') {
            i += 1;
        }
    } else {
        while i < n && (b[i].is_ascii_digit() || b[i] == b'_') {
            i += 1;
        }
        if i + 1 < n && b[i] == b'.' && b[i + 1].is_ascii_digit() {
            float = true;
            i += 1;
            while i < n && (b[i].is_ascii_digit() || b[i] == b'_') {
                i += 1;
            }
        } else if i < n && b[i] == b'.' && !(i + 1 < n && (b[i + 1] == b'.' || is_id_start(b[i + 1] as char))) {
            float = true;
            i += 1;
        }
        if i < n && (b[i] == b'e' || b[i] == b'E') {
            let mut j = i + 1;
            if j < n && (b[j] == b'+' || b[j] == b'-') {
                j += 1;
            }
            if j < n && b[j].is_ascii_digit() {
                float = true;
                i = j;
                while i < n && (b[i].is_ascii_digit() || b[i] == b'_') {
                    i += 1;
                }
            }
        }
    }
    // suffix
    let s = i;
    while i < n && (b[i].is_ascii_alphanumeric() || b[i] == b'_') {
        i += 1;
    }
    let suf = &src[s..i];
    if suf.starts_with('f') {
        float = true;
    }
    (if float { K::Float } else { K::Int }, i)
}

struct P<'a> {
    src: &'a str,
    toks: Vec<Tk>,
    i: usize,
    b: Builder,
    no_struct: bool,
    depth: usize,
}

pub fn parse(src: &str) -> Tree {
    let toks = tokenize(src);
    let mut p = P { src, toks, i: 0, b: Builder::new(), no_struct: false, depth: 0 };
    let m = p.b.mark();
    if src.starts_with("#!") && !src.starts_with("#![") {
        let e = src.find('\n').unwrap_or(src.len());
        p.b.leaf("shebang", true, 0, e);
        while p.i < p.toks.len() && p.toks[p.i].s < e {
            p.i += 1;
        }
    }
    loop {
        if p.k() == K::Eof {
            break;
        }
        let before = p.i;
        p.statement();
        if p.i == before {
            p.error_token();
        }
    }
    p.flush_extras();
    let start = p.b.stack[m..].first().map(|&c| p.b.nodes[c as usize].start).unwrap_or(src.len() - src.trim_start().len());
    let root = p.b.wrap_all(m, "source_file", start, src.len());
    p.b.finish(root, src)
}

impl<'a> P<'a> {
    fn idx(&self, n: usize) -> usize {
        let mut j = self.i;
        let mut c = 0;
        loop {
            while j < self.toks.len() && matches!(self.toks[j].k, K::LineComment | K::BlockComment) {
                j += 1;
            }
            if j >= self.toks.len() {
                return self.toks.len() - 1;
            }
            if c == n {
                return j;
            }
            c += 1;
            j += 1;
        }
    }
    fn tok(&self, n: usize) -> Tk {
        self.toks[self.idx(n)]
    }
    fn k(&self) -> K {
        self.tok(0).k
    }
    fn txn(&self, n: usize) -> &'a str {
        let t = self.tok(n);
        if t.k == K::Eof {
            return "";
        }
        &self.src[t.s..t.e]
    }
    fn tx(&self) -> &'a str {
        self.txn(0)
    }
    fn at(&self, s: &str) -> bool {
        let t = self.tok(0);
        matches!(t.k, K::Op | K::Ident) && &self.src[t.s..t.e] == s
    }
    /// adjacency: next two tokens are directly adjacent
    fn adjacent(&self, n: usize) -> bool {
        self.tok(n).e == self.tok(n + 1).s
    }
    fn flush_extras(&mut self) {
        while self.i < self.toks.len() && matches!(self.toks[self.i].k, K::LineComment | K::BlockComment) {
            let t = self.toks[self.i];
            self.comment(t);
            self.i += 1;
        }
    }
    fn comment(&mut self, t: Tk) {
        let txt = &self.src[t.s..t.e];
        let b = self.src.as_bytes();
        if t.k == K::LineComment {
            let m = self.b.mark();
            self.b.leaf("//", false, t.s, t.s + 2);
            let third = b.get(t.s + 2).copied();
            let fourth = b.get(t.s + 3).copied();
            let doc_outer = third == Some(b'/') && fourth != Some(b'/');
            let doc_inner = third == Some(b'!');
            let mut end = t.e;
            if doc_outer || doc_inner {
                // doc comments include the trailing newline
                if end < b.len() && b[end] == b'\n' {
                    end += 1;
                }
                let mm = self.b.mark();
                self.b.leaf(if doc_outer { "/" } else { "!" }, false, t.s + 2, t.s + 3);
                self.b.wrap(mm, if doc_outer { "outer_doc_comment_marker" } else { "inner_doc_comment_marker" }, true);
                self.b.field_last(if doc_outer { "outer" } else { "inner" });
                self.b.leaf("doc_comment", true, t.s + 3, end);
                self.b.field_last("doc");
            }
            let id = self.b.wrap(m, "line_comment", true);
            self.b.nodes[id as usize].extra = true;
            self.b.nodes[id as usize].end = end;
        } else {
            let m = self.b.mark();
            self.b.leaf("/*", false, t.s, t.s + 2);
            let doc_outer = txt.starts_with("/**") && !txt.starts_with("/***") && txt.len() > 4;
            let doc_inner = txt.starts_with("/*!");
            if doc_outer || doc_inner {
                let mm = self.b.mark();
                self.b.leaf(if doc_outer { "*" } else { "!" }, false, t.s + 2, t.s + 3);
                self.b.wrap(mm, if doc_outer { "outer_doc_comment_marker" } else { "inner_doc_comment_marker" }, true);
                self.b.field_last(if doc_outer { "outer" } else { "inner" });
                if t.e >= t.s + 5 {
                    self.b.leaf("doc_comment", true, t.s + 3, t.e - 2);
                    self.b.field_last("doc");
                }
            }
            if t.e >= t.s + 4 && txt.ends_with("*/") {
                self.b.leaf("*/", false, t.e - 2, t.e);
            }
            let id = self.b.wrap(m, "block_comment", true);
            self.b.nodes[id as usize].extra = true;
        }
    }
    fn advance(&mut self) -> Tk {
        self.flush_extras();
        let t = self.toks[self.i];
        if t.k != K::Eof {
            self.i += 1;
        }
        t
    }
    fn bump(&mut self) -> u32 {
        let t = self.advance();
        let k = intern(&self.src[t.s..t.e]);
        self.b.leaf(k, false, t.s, t.e)
    }
    fn bump_named(&mut self, kind: &'static str) -> u32 {
        let t = self.advance();
        self.b.leaf(kind, true, t.s, t.e)
    }
    /// bump n adjacent tokens as one anonymous token
    fn bump_join(&mut self, n: usize) -> u32 {
        let first = self.advance();
        let mut e = first.e;
        for _ in 1..n {
            let t = self.advance();
            e = t.e;
        }
        let k = intern(&self.src[first.s..e]);
        self.b.leaf(k, false, first.s, e)
    }
    fn eat(&mut self, s: &str) -> bool {
        if self.at(s) {
            self.bump();
            true
        } else {
            false
        }
    }
    fn cur_pos(&self) -> usize {
        self.b.last().map(|l| self.b.nodes[l as usize].end).unwrap_or(0)
    }
    fn expect(&mut self, s: &str) {
        if !self.eat(s) {
            let p = self.cur_pos();
            self.b.missing(intern(s), false, p);
        }
    }
    fn error_token(&mut self) {
        if self.k() == K::Eof {
            return;
        }
        let m = self.b.mark();
        if self.k() == K::Ident {
            self.bump_named("identifier");
        } else {
            self.bump();
        }
        self.b.wrap(m, "ERROR", true);
    }
    fn set_field_first(&mut self, m: usize, f: &'static str) {
        for i in m..self.b.stack.len() {
            let id = self.b.stack[i] as usize;
            if !self.b.nodes[id].extra {
                self.b.nodes[id].field = Some(f);
                return;
            }
        }
    }

    // ---------- statements ----------
    fn statement(&mut self) {
        let m = self.b.mark();
        if self.item(m) {
            return;
        }
        let t = self.tok(0);
        let tx = self.tx();
        if t.k == K::Ident && tx == "let" {
            self.let_decl(m);
            return;
        }
        if self.at(";") {
            self.bump();
            self.b.wrap(m, "empty_statement", true);
            return;
        }
        // expression statement
        let block_like = self.expression_stmt_expr();
        if self.at(";") {
            self.bump();
            self.b.wrap(m, "expression_statement", true);
        } else if block_like {
            self.b.wrap(m, "expression_statement", true);
        } else {
            // tail expression (in block) or missing ';'
        }
    }

    /// parse expression at statement start; returns true if block-like
    fn expression_stmt_expr(&mut self) -> bool {
        let tx = self.tx();
        let t = self.tok(0);
        let is_label = t.k == K::Lifetime && self.txn(1) == ":";
        let block_kw = matches!(tx, "if" | "match" | "loop" | "while" | "for" | "{" | "unsafe" | "async" | "const" | "try")
            && t.k != K::Str;
        if (block_kw || is_label) && !(tx == "async" && self.txn(1) == "move" && self.txn(2) == "|") && !(tx == "async" && self.txn(1) == "|") && !(tx == "const" && self.txn(1) != "{") {
            let m = self.b.mark();
            self.primary();
            // allow method call continuation like `match x {}.foo()`? tree-sitter treats as statement end
            if self.at(".") || self.at("?") {
                self.postfix_from(m);
                self.binary_rest(m, 0);
                return false;
            }
            return true;
        }
        self.expression();
        false
    }

    fn outer_attrs(&mut self) {
        while self.at("#") && (self.txn(1) == "[" || (self.txn(1) == "!" && self.txn(2) == "[")) {
            self.attribute_item();
        }
    }

    fn attribute_item(&mut self) {
        let m = self.b.mark();
        self.bump(); // #
        let inner = self.eat("!");
        self.expect("[");
        self.attribute();
        self.expect("]");
        self.b.wrap(m, if inner { "inner_attribute_item" } else { "attribute_item" }, true);
    }

    fn attribute(&mut self) {
        let m = self.b.mark();
        if self.at("unsafe") && self.txn(1) == "(" {
            self.bump();
            self.bump();
            self.attribute();
            self.expect(")");
            self.b.wrap(m, "attribute", true);
            return;
        }
        self.path_expr_simple();
        if self.at("=") {
            self.bump();
            self.expression();
            self.b.field_last("value");
        } else if self.at("(") || self.at("[") || self.at("{") {
            self.token_tree();
            self.b.field_last("arguments");
        }
        self.b.wrap(m, "attribute", true);
    }

    fn path_expr_simple(&mut self) {
        // identifier or scoped_identifier
        let m = self.b.mark();
        if self.at("::") {
            self.bump();
            self.path_segment_ident();
            self.b.field_last("name");
            self.b.wrap(m, "scoped_identifier", true);
        } else {
            self.path_segment_ident();
        }
        while self.at("::") && self.tok(1).k == K::Ident {
            self.set_field_first(m, "path");
            self.bump();
            self.path_segment_ident();
            self.b.field_last("name");
            self.b.wrap(m, "scoped_identifier", true);
        }
    }

    fn path_segment_ident(&mut self) {
        let tx = self.tx();
        match tx {
            "self" => {
                self.bump_named("self");
            }
            "super" => {
                self.bump_named("super");
            }
            "crate" => {
                self.bump_named("crate");
            }
            _ => {
                if self.k() == K::Ident {
                    self.bump_named("identifier");
                } else {
                    let p = self.cur_pos();
                    self.b.missing("identifier", true, p);
                }
            }
        }
    }

    fn visibility(&mut self) {
        if self.at("pub") {
            let m = self.b.mark();
            self.bump();
            if self.at("(") {
                let t1 = self.txn(1);
                if matches!(t1, "crate" | "self" | "super") && self.txn(2) == ")" {
                    self.bump();
                    self.bump();
                    self.bump();
                } else if t1 == "in" {
                    self.bump();
                    self.bump();
                    self.path_expr_simple();
                    self.expect(")");
                }
            }
            self.b.wrap(m, "visibility_modifier", true);
        } else if self.at("crate") && self.txn(1) != "::" {
            let m = self.b.mark();
            self.bump();
            self.b.wrap(m, "visibility_modifier", true);
        }
    }

    /// items; returns true if parsed an item
    fn item(&mut self, m: usize) -> bool {
        let save_i = self.i;
        let save_cp = self.b.checkpoint();
        // attributes
        if self.at("#") && (self.txn(1) == "[" || (self.txn(1) == "!" && self.txn(2) == "[")) {
            self.attribute_item();
            return true;
        }
        self.visibility();
        let has_vis = self.b.mark() > m;
        // function modifiers
        let mut mods = 0;
        let mm = self.b.mark();
        loop {
            let tx = self.tx();
            match tx {
                "async" | "const" | "unsafe" | "default" if matches!(self.txn(1), "fn" | "unsafe" | "extern" | "async" | "const" | "impl" | "trait") && !(tx == "const" && self.txn(1) == "{") => {
                    if tx == "const" && !matches!(self.txn(1), "fn" | "unsafe" | "extern" | "async") {
                        break;
                    }
                    self.bump();
                    mods += 1;
                }
                "extern" if matches!(self.txn(1), "fn") || (self.tok(1).k == K::Str && matches!(self.txn(2), "fn" | "unsafe")) => {
                    let me = self.b.mark();
                    self.bump();
                    if self.k() == K::Str {
                        self.string_literal();
                    }
                    self.b.wrap(me, "extern_modifier", true);
                    mods += 1;
                }
                _ => break,
            }
        }
        let tx = self.tx();
        if mods > 0 && !matches!(tx, "fn" | "impl" | "trait") {
            self.i = save_i;
            self.b.restore(save_cp);
            return false;
        }
        match tx {
            "fn" => {
                if mods > 0 {
                    self.b.wrap(mm, "function_modifiers", true);
                }
                self.function_item(m);
                true
            }
            "impl" if mods == 0 || true => {
                if mods > 0 {
                    // unsafe impl: keep modifiers as plain tokens
                }
                self.impl_item(m);
                true
            }
            "trait" => {
                self.trait_item(m);
                true
            }
            "struct" => {
                self.struct_item(m, "struct_item");
                true
            }
            "union" if self.tok(1).k == K::Ident => {
                self.struct_item(m, "union_item");
                true
            }
            "enum" => {
                self.enum_item(m);
                true
            }
            "mod" => {
                self.bump();
                self.bump_named("identifier");
                self.b.field_last("name");
                if self.at("{") {
                    self.declaration_list();
                    self.b.field_last("body");
                } else {
                    self.expect(";");
                }
                self.b.wrap(m, "mod_item", true);
                true
            }
            "use" => {
                self.bump();
                self.use_tree();
                self.b.field_last("argument");
                self.expect(";");
                self.b.wrap(m, "use_declaration", true);
                true
            }
            "extern" if self.txn(1) == "crate" => {
                self.bump();
                self.bump();
                self.path_segment_ident();
                self.b.field_last("name");
                if self.at("as") {
                    self.bump();
                    self.bump_named("identifier");
                    self.b.field_last("alias");
                }
                self.expect(";");
                self.b.wrap(m, "extern_crate_declaration", true);
                true
            }
            "extern" => {
                let me = self.b.mark();
                self.bump();
                if self.k() == K::Str {
                    self.string_literal();
                }
                self.b.wrap(me, "extern_modifier", true);
                if self.at("{") {
                    self.declaration_list();
                    self.b.field_last("body");
                } else {
                    self.expect(";");
                }
                self.b.wrap(m, "foreign_mod_item", true);
                true
            }
            "const" if self.txn(1) != "{" && (self.tok(1).k == K::Ident) => {
                self.bump();
                if self.at("_") {
                    self.bump();
                } else {
                    self.bump_named("identifier");
                }
                self.b.field_last("name");
                if self.at(":") {
                    self.bump();
                    self.ty();
                    self.b.field_last("type");
                }
                if self.eat("=") {
                    self.expression();
                    self.b.field_last("value");
                }
                self.expect(";");
                self.b.wrap(m, "const_item", true);
                true
            }
            "static" if self.tok(1).k == K::Ident && !matches!(self.txn(1), "move") || (self.txn(1) == "mut") => {
                self.bump();
                if self.at("ref") {
                    self.bump();
                }
                if self.at("mut") {
                    self.bump_named("mutable_specifier");
                }
                self.bump_named("identifier");
                self.b.field_last("name");
                if self.at(":") {
                    self.bump();
                    self.ty();
                    self.b.field_last("type");
                }
                if self.eat("=") {
                    self.expression();
                    self.b.field_last("value");
                }
                self.expect(";");
                self.b.wrap(m, "static_item", true);
                true
            }
            "type" if self.tok(1).k == K::Ident => {
                self.bump();
                self.bump_named("type_identifier");
                self.b.field_last("name");
                if self.at("<") {
                    self.type_parameters();
                    self.b.field_last("type_parameters");
                }
                let is_assoc = !self.at("=");
                if self.at(":") {
                    self.trait_bounds();
                    self.b.field_last("bounds");
                }
                if self.at("where") {
                    self.where_clause();
                }
                if self.eat("=") {
                    self.ty();
                    self.b.field_last("type");
                }
                if self.at("where") {
                    self.where_clause();
                }
                self.expect(";");
                self.b.wrap(m, if is_assoc { "associated_type" } else { "type_item" }, true);
                true
            }
            "macro_rules" if self.txn(1) == "!" => {
                self.macro_definition(m);
                true
            }
            _ => {
                if has_vis {
                    // visibility without item: error
                    return true;
                }
                // macro invocation as item
                if self.k() == K::Ident && self.txn(1) == "!" && !matches!(self.txn(2), "=") {
                    let mi = self.b.mark();
                    self.macro_invocation_from(mi);
                    let ends_brace = self.b.nodes[self.b.last().unwrap() as usize].end > 0
                        && self.src.as_bytes()[self.cur_pos() - 1] == b'}';
                    if self.at(";") {
                        self.bump();
                        self.b.wrap(m, "expression_statement", true);
                        return true;
                    }
                    if ends_brace {
                        return true;
                    }
                    // tail expression or continuation
                    self.postfix_from(mi);
                    self.binary_rest(mi, 0);
                    self.assign_rest(mi);
                    if self.at(";") {
                        self.bump();
                        self.b.wrap(m, "expression_statement", true);
                    }
                    return true;
                }
                false
            }
        }
    }

    fn macro_definition(&mut self, m: usize) {
        self.bump(); // macro_rules
        self.bump(); // !
        self.bump_named("identifier");
        self.b.field_last("name");
        let close = match self.tx() {
            "(" => ")",
            "[" => "]",
            _ => "}",
        };
        self.bump();
        while !self.at(close) && self.k() != K::Eof {
            let mr = self.b.mark();
            self.token_tree_pattern();
            self.b.field_last("left");
            self.expect("=>");
            self.token_tree();
            self.b.field_last("right");
            self.b.wrap(mr, "macro_rule", true);
            if !self.eat(";") {
                break;
            }
        }
        self.expect(close);
        if close != "}" {
            self.eat(";");
        }
        self.b.wrap(m, "macro_definition", true);
    }

    fn token_tree_pattern(&mut self) {
        let m = self.b.mark();
        let close = match self.tx() {
            "(" => ")",
            "[" => "]",
            "{" => "}",
            _ => {
                self.error_token();
                return;
            }
        };
        self.bump();
        while !self.at(close) && self.k() != K::Eof {
            self.tt_pattern_item();
        }
        self.expect(close);
        self.b.wrap(m, "token_tree_pattern", true);
    }

    fn tt_pattern_item(&mut self) {
        let tx = self.tx();
        if matches!(tx, "(" | "[" | "{") {
            self.token_tree_pattern();
            return;
        }
        if tx == "$" {
            let m = self.b.mark();
            if self.txn(1) == "(" {
                self.bump();
                self.bump();
                while !self.at(")") && self.k() != K::Eof {
                    self.tt_pattern_item();
                }
                self.expect(")");
                // separator and repetition operator
                if !matches!(self.tx(), "*" | "+" | "?") {
                    self.tt_leaf();
                }
                if matches!(self.tx(), "*" | "+" | "?") {
                    self.bump();
                }
                self.b.wrap(m, "token_repetition_pattern", true);
                return;
            }
            if self.tok(1).k == K::Ident && self.txn(2) == ":" {
                // $name:frag
                let t = self.advance();
                let t2 = self.advance();
                self.b.leaf("metavariable", true, t.s, t2.e);
                self.bump();
                self.bump_named("fragment_specifier");
                self.b.field_last("type");
                self.b.wrap(m, "token_binding_pattern", true);
                return;
            }
        }
        self.tt_leaf();
    }

    fn token_tree(&mut self) {
        let m = self.b.mark();
        let close = match self.tx() {
            "(" => ")",
            "[" => "]",
            "{" => "}",
            _ => {
                self.error_token();
                return;
            }
        };
        self.bump();
        while !self.at(close) && self.k() != K::Eof {
            self.tt_item();
        }
        self.expect(close);
        self.b.wrap(m, "token_tree", true);
    }

    fn tt_item(&mut self) {
        let tx = self.tx();
        if matches!(tx, "(" | "[" | "{") {
            self.token_tree();
            return;
        }
        if tx == "$" && self.txn(1) == "(" {
            let m = self.b.mark();
            self.bump();
            self.bump();
            while !self.at(")") && self.k() != K::Eof {
                self.tt_item();
            }
            self.expect(")");
            if !matches!(self.tx(), "*" | "+" | "?") {
                self.tt_leaf();
            }
            if matches!(self.tx(), "*" | "+" | "?") {
                self.bump();
            }
            self.b.wrap(m, "token_repetition", true);
            return;
        }
        self.tt_leaf();
    }

    fn tt_leaf(&mut self) {
        let t = self.tok(0);
        let tx = self.tx();
        match t.k {
            K::Ident => {
                if tx == "$" {
                    self.bump();
                    return;
                }
                if matches!(tx, "true" | "false") {
                    self.bump_named("boolean_literal");
                } else if tx == "self" {
                    self.bump_named("self");
                } else if tx == "super" {
                    self.bump_named("super");
                } else if tx == "crate" {
                    self.bump_named("crate");
                } else if PRIMS.contains(&tx) {
                    self.bump_named("primitive_type");
                } else if is_keyword(tx) {
                    self.bump();
                } else {
                    self.bump_named("identifier");
                }
            }
            K::Op if tx == "$" && self.tok(1).k == K::Ident && self.adjacent(0) => {
                let a = self.advance();
                let b2 = self.advance();
                self.b.leaf("metavariable", true, a.s, b2.e);
            }
            K::Lifetime => self.lifetime(),
            K::Int => {
                self.bump_named("integer_literal");
            }
            K::Float => {
                self.bump_named("float_literal");
            }
            K::Str => self.string_literal(),
            K::RawStr => self.raw_string(),
            K::Char => {
                self.bump_named("char_literal");
            }
            K::Op => {
                if tx == "-" && matches!(self.tok(1).k, K::Int | K::Float) && false {
                } else {
                    self.bump();
                }
            }
            _ => self.error_token(),
        }
    }

    fn use_tree(&mut self) {
        let m = self.b.mark();
        if self.at("{") {
            self.use_list();
            return;
        }
        if self.at("*") {
            self.bump();
            self.b.wrap(m, "use_wildcard", true);
            return;
        }
        if self.at("::") {
            self.bump();
        }
        // path
        let mp = self.b.mark();
        self.path_segment_ident();
        loop {
            if self.at("::") {
                let n1 = self.txn(1);
                if n1 == "{" {
                    self.set_field_first(mp, "path");
                    self.bump();
                    self.use_list();
                    self.b.field_last("list");
                    self.b.wrap(m, "scoped_use_list", true);
                    return;
                }
                if n1 == "*" {
                    self.bump();
                    self.bump();
                    self.b.wrap(m, "use_wildcard", true);
                    return;
                }
                self.set_field_first(mp, "path");
                self.bump();
                self.path_segment_ident();
                self.b.field_last("name");
                self.b.wrap(mp, "scoped_identifier", true);
                continue;
            }
            break;
        }
        if self.at("as") {
            self.b.field_last("path");
            self.bump();
            if self.at("_") {
                self.bump();
            } else {
                self.bump_named("identifier");
            }
            self.b.field_last("alias");
            self.b.wrap(m, "use_as_clause", true);
        }
    }

    fn use_list(&mut self) {
        let m = self.b.mark();
        self.bump(); // {
        while !self.at("}") && self.k() != K::Eof {
            self.use_tree();
            if !self.eat(",") {
                break;
            }
        }
        self.expect("}");
        self.b.wrap(m, "use_list", true);
    }

    fn declaration_list(&mut self) {
        let m = self.b.mark();
        self.bump(); // {
        while !self.at("}") && self.k() != K::Eof {
            let mi = self.b.mark();
            let before = self.i;
            if !self.item(mi) {
                if self.at(";") {
                    self.bump();
                    self.b.wrap(mi, "empty_statement", true);
                } else {
                    self.error_token();
                }
            }
            if self.i == before {
                self.error_token();
            }
        }
        self.expect("}");
        self.b.wrap(m, "declaration_list", true);
    }

    fn function_item(&mut self, m: usize) {
        self.bump(); // fn
        if self.k() == K::Ident {
            self.bump_named("identifier");
        } else if self.at("$") {
            self.tt_leaf();
        }
        self.b.field_last("name");
        if self.at("<") {
            self.type_parameters();
            self.b.field_last("type_parameters");
        }
        self.parameters();
        self.b.field_last("parameters");
        if self.at("->") {
            self.bump();
            self.ty();
            self.b.field_last("return_type");
        }
        if self.at("where") {
            self.where_clause();
        }
        if self.at("{") {
            self.block();
            self.b.field_last("body");
            self.b.wrap(m, "function_item", true);
        } else {
            self.expect(";");
            self.b.wrap(m, "function_signature_item", true);
        }
    }

    fn parameters(&mut self) {
        let m = self.b.mark();
        self.expect("(");
        while !self.at(")") && self.k() != K::Eof {
            self.outer_attrs();
            let mp = self.b.mark();
            // self parameter
            let is_self = {
                let mut j = 0;
                if self.txn(j) == "&" {
                    j += 1;
                    if self.tok(j).k == K::Lifetime {
                        j += 1;
                    }
                }
                if self.txn(j) == "mut" {
                    j += 1;
                }
                self.txn(j) == "self" && self.txn(j + 1) != "::"
            };
            if is_self {
                if self.eat("&") {
                    if self.k() == K::Lifetime {
                        self.lifetime();
                    }
                }
                if self.at("mut") {
                    self.bump_named("mutable_specifier");
                }
                self.bump_named("self");
                if self.at(":") {
                    self.bump();
                    self.ty();
                    self.b.field_last("type");
                }
                self.b.wrap(mp, "self_parameter", true);
            } else if self.at("...") {
                self.bump();
                self.b.wrap(mp, "variadic_parameter", true);
            } else if self.at("_") && self.txn(1) != ":" {
                self.bump();
            } else {
                // pattern : type, or bare type (fn pointers / trait methods)
                let save = self.i;
                let cp = self.b.checkpoint();
                if self.at("mut") {
                    self.bump_named("mutable_specifier");
                }
                self.pattern();
                self.b.field_last("pattern");
                if self.at(":") {
                    self.bump();
                    self.ty();
                    self.b.field_last("type");
                    self.b.wrap(mp, "parameter", true);
                } else {
                    // it was a type
                    self.i = save;
                    self.b.restore(cp);
                    self.ty();
                }
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect(")");
        self.b.wrap(m, "parameters", true);
    }

    fn type_parameters(&mut self) {
        let m = self.b.mark();
        self.bump(); // <
        while !self.at(">") && self.k() != K::Eof {
            self.outer_attrs();
            let mp = self.b.mark();
            if self.k() == K::Lifetime {
                self.lifetime();
                self.b.field_last("name");
                if self.at(":") {
                    self.trait_bounds();
                    self.b.field_last("bounds");
                }
                self.b.wrap(mp, "lifetime_parameter", true);
            } else if self.at("const") {
                self.bump();
                self.bump_named("identifier");
                self.b.field_last("name");
                self.expect(":");
                self.ty();
                self.b.field_last("type");
                if self.eat("=") {
                    if self.at("{") {
                        self.block();
                    } else {
                        self.primary();
                    }
                    self.b.field_last("value");
                }
                self.b.wrap(mp, "const_parameter", true);
            } else {
                self.bump_named("type_identifier");
                self.b.field_last("name");
                if self.at(":") {
                    self.trait_bounds();
                    self.b.field_last("bounds");
                }
                if self.at("=") {
                    self.bump();
                    self.ty();
                    self.b.field_last("default_type");
                }
                self.b.wrap(mp, "type_parameter", true);
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect(">");
        self.b.wrap(m, "type_parameters", true);
    }

    fn trait_bounds(&mut self) {
        let m = self.b.mark();
        self.bump(); // :
        loop {
            if self.at("{") || self.at("=") || self.at(";") || self.at(",") || self.at(">") || self.at("where") {
                break;
            }
            self.bound();
            if !self.eat("+") {
                break;
            }
        }
        self.b.wrap(m, "trait_bounds", true);
    }

    fn bound(&mut self) {
        let m = self.b.mark();
        if self.k() == K::Lifetime {
            self.lifetime();
        } else if self.at("?") {
            self.bump();
            self.ty_no_bounds();
            self.b.wrap(m, "removed_trait_bound", true);
        } else if self.at("(") {
            self.bump();
            self.bound();
            self.expect(")");
        } else if self.at("for") {
            self.higher_ranked(m);
        } else {
            self.ty_no_bounds();
        }
    }

    fn higher_ranked(&mut self, m: usize) {
        self.bump(); // for
        self.type_parameters();
        self.b.field_last("type_parameters");
        self.ty_no_bounds();
        self.b.field_last("type");
        self.b.wrap(m, "higher_ranked_trait_bound", true);
    }

    fn where_clause(&mut self) {
        let m = self.b.mark();
        self.bump(); // where
        while !self.at("{") && !self.at(";") && self.k() != K::Eof && !self.at("=") {
            let mp = self.b.mark();
            if self.k() == K::Lifetime {
                self.lifetime();
            } else if self.at("for") {
                let mh = self.b.mark();
                self.higher_ranked(mh);
            } else {
                self.ty_no_bounds();
            }
            self.b.field_last("left");
            if self.at(":") {
                self.trait_bounds();
                self.b.field_last("bounds");
            }
            self.b.wrap(mp, "where_predicate", true);
            if !self.eat(",") {
                break;
            }
        }
        self.b.wrap(m, "where_clause", true);
    }

    fn impl_item(&mut self, m: usize) {
        self.bump(); // impl
        if self.at("<") && !self.is_generic_args_type_ahead() {
            self.type_parameters();
            self.b.field_last("type_parameters");
        }
        let neg = self.at("!");
        if neg {
            self.bump();
        }
        self.ty_no_bounds();
        if self.at("for") {
            self.b.field_last("trait");
            self.bump();
            self.ty();
            self.b.field_last("type");
        } else {
            self.b.field_last("type");
        }
        if self.at("where") {
            self.where_clause();
        }
        if self.at("{") {
            self.declaration_list();
            self.b.field_last("body");
        } else {
            self.expect(";");
        }
        self.b.wrap(m, "impl_item", true);
    }

    fn is_generic_args_type_ahead(&self) -> bool {
        false
    }

    fn trait_item(&mut self, m: usize) {
        self.bump(); // trait
        self.bump_named("type_identifier");
        self.b.field_last("name");
        if self.at("<") {
            self.type_parameters();
            self.b.field_last("type_parameters");
        }
        if self.at(":") {
            self.trait_bounds();
            self.b.field_last("bounds");
        }
        if self.at("where") {
            self.where_clause();
        }
        if self.at("{") {
            self.declaration_list();
            self.b.field_last("body");
        }
        self.b.wrap(m, "trait_item", true);
    }

    fn struct_item(&mut self, m: usize, kind: &'static str) {
        self.bump(); // struct
        self.bump_named("type_identifier");
        self.b.field_last("name");
        if self.at("<") {
            self.type_parameters();
            self.b.field_last("type_parameters");
        }
        if self.at("where") {
            self.where_clause();
        }
        if self.at("{") {
            self.field_declaration_list();
            self.b.field_last("body");
        } else if self.at("(") {
            self.ordered_field_list();
            self.b.field_last("body");
            if self.at("where") {
                self.where_clause();
            }
            self.expect(";");
        } else {
            self.expect(";");
        }
        self.b.wrap(m, kind, true);
    }

    fn field_declaration_list(&mut self) {
        let m = self.b.mark();
        self.bump(); // {
        while !self.at("}") && self.k() != K::Eof {
            self.outer_attrs();
            if self.at("}") {
                break;
            }
            let mf = self.b.mark();
            self.visibility();
            self.bump_named("field_identifier");
            self.b.field_last("name");
            self.expect(":");
            self.ty();
            self.b.field_last("type");
            if self.at("=") {
                self.bump();
                self.expression();
                self.b.field_last("default_value");
            }
            self.b.wrap(mf, "field_declaration", true);
            if !self.eat(",") {
                break;
            }
        }
        self.expect("}");
        self.b.wrap(m, "field_declaration_list", true);
    }

    fn ordered_field_list(&mut self) {
        let m = self.b.mark();
        self.bump(); // (
        while !self.at(")") && self.k() != K::Eof {
            self.outer_attrs();
            self.visibility();
            self.ty();
            self.b.field_last("type");
            if !self.eat(",") {
                break;
            }
        }
        self.expect(")");
        self.b.wrap(m, "ordered_field_declaration_list", true);
    }

    fn enum_item(&mut self, m: usize) {
        self.bump(); // enum
        self.bump_named("type_identifier");
        self.b.field_last("name");
        if self.at("<") {
            self.type_parameters();
            self.b.field_last("type_parameters");
        }
        if self.at("where") {
            self.where_clause();
        }
        let ml = self.b.mark();
        self.expect("{");
        while !self.at("}") && self.k() != K::Eof {
            self.outer_attrs();
            if self.at("}") {
                break;
            }
            let mv = self.b.mark();
            self.visibility();
            self.bump_named("identifier");
            self.b.field_last("name");
            if self.at("{") {
                self.field_declaration_list();
                self.b.field_last("body");
            } else if self.at("(") {
                self.ordered_field_list();
                self.b.field_last("body");
            }
            if self.eat("=") {
                self.expression();
                self.b.field_last("value");
            }
            self.b.wrap(mv, "enum_variant", true);
            if !self.eat(",") {
                break;
            }
        }
        self.expect("}");
        self.b.wrap(ml, "enum_variant_list", true);
        self.b.field_last("body");
        self.b.wrap(m, "enum_item", true);
    }

    fn let_decl(&mut self, m: usize) {
        self.bump(); // let
        if self.at("mut") && !matches!(self.txn(1), ":" | "=") {
            self.bump_named("mutable_specifier");
        }
        self.pattern();
        self.b.field_last("pattern");
        if self.at(":") {
            self.bump();
            self.ty();
            self.b.field_last("type");
        }
        if self.eat("=") {
            self.expression();
            self.b.field_last("value");
        }
        if self.at("else") {
            let me = self.b.mark();
            self.bump();
            self.block();
            self.b.wrap(me, "else_clause", true);
            self.b.field_last("alternative");
        }
        self.expect(";");
        self.b.wrap(m, "let_declaration", true);
    }

    fn block(&mut self) {
        let m = self.b.mark();
        self.expect("{");
        while !self.at("}") && self.k() != K::Eof {
            let before = self.i;
            self.statement();
            if self.i == before {
                self.error_token();
            }
        }
        self.expect("}");
        self.b.wrap(m, "block", true);
    }

    fn lifetime(&mut self) {
        let t = self.advance();
        let m = self.b.mark();
        self.b.leaf("'", false, t.s, t.s + 1);
        let tx = &self.src[t.s + 1..t.e];
        if tx == "static" {
            self.b.leaf("static", false, t.s + 1, t.e);
        } else {
            self.b.leaf("identifier", true, t.s + 1, t.e);
        }
        self.b.wrap(m, "lifetime", true);
    }

    fn label(&mut self) {
        let t = self.advance();
        let m = self.b.mark();
        self.b.leaf("'", false, t.s, t.s + 1);
        self.b.leaf("identifier", true, t.s + 1, t.e);
        self.b.wrap(m, "label", true);
    }

    // ---------- types ----------
    fn ty(&mut self) {
        let m = self.b.mark();
        self.ty_no_bounds();
        if self.at("+") && !self.b.stack.is_empty() {
            while self.eat("+") {
                if self.k() == K::Lifetime {
                    self.lifetime();
                } else if self.at("?") {
                    let mr = self.b.mark();
                    self.bump();
                    self.ty_no_bounds();
                    self.b.wrap(mr, "removed_trait_bound", true);
                } else {
                    self.ty_no_bounds();
                }
            }
            self.b.wrap(m, "bounded_type", true);
        }
    }

    fn ty_no_bounds(&mut self) {
        let m = self.b.mark();
        let t = self.tok(0);
        let tx = self.tx();
        match tx {
            "&" | "&&" => {
                if tx == "&&" {
                    // split &&
                    let t = self.advance();
                    let mi = self.b.mark();
                    let _ = mi;
                    self.b.leaf("&", false, t.s, t.s + 1);
                    let m2 = self.b.mark();
                    self.b.leaf("&", false, t.s + 1, t.e);
                    self.ref_type_rest(m2);
                    self.b.field_last("type");
                    self.b.wrap(m, "reference_type", true);
                    return;
                }
                self.bump();
                self.ref_type_rest(m);
                return;
            }
            "*" => {
                self.bump();
                if self.at("const") {
                    self.bump();
                } else if self.at("mut") {
                    self.bump_named("mutable_specifier");
                }
                self.ty_no_bounds();
                self.b.field_last("type");
                self.b.wrap(m, "pointer_type", true);
                return;
            }
            "(" => {
                self.bump();
                if self.at(")") {
                    self.bump();
                    self.b.wrap(m, "unit_type", true);
                    return;
                }
                let mut n = 0;
                let mut comma = false;
                while !self.at(")") && self.k() != K::Eof {
                    self.ty();
                    n += 1;
                    if !self.eat(",") {
                        break;
                    }
                    comma = true;
                }
                self.expect(")");
                if n == 1 && !comma {
                    // parenthesized type: tree-sitter has no node; keep tuple_type? use tuple_type
                    self.b.wrap(m, "tuple_type", true);
                } else {
                    self.b.wrap(m, "tuple_type", true);
                }
                return;
            }
            "[" => {
                self.bump();
                self.ty();
                self.b.field_last("element");
                if self.eat(";") {
                    self.expression();
                    self.b.field_last("length");
                }
                self.expect("]");
                self.b.wrap(m, "array_type", true);
                return;
            }
            "!" => {
                self.bump();
                self.b.wrap(m, "never_type", true);
                return;
            }
            "_" => {
                self.bump();
                return;
            }
            "dyn" if self.tok(1).k != K::Op || matches!(self.txn(1), "(" | "?" | "::" | "<") => {
                self.bump();
                self.bound_list_type();
                self.b.field_last("trait");
                self.b.wrap(m, "dynamic_type", true);
                return;
            }
            "impl" => {
                self.bump();
                self.bound_list_type();
                self.b.field_last("trait");
                self.b.wrap(m, "abstract_type", true);
                return;
            }
            "fn" | "unsafe" | "extern" if tx == "fn" || matches!(self.txn(1), "fn" | "extern") || self.tok(1).k == K::Str => {
                self.fn_type(m);
                return;
            }
            "for" if self.txn(1) == "<" => {
                // higher-ranked fn type or bound
                self.bump();
                self.type_parameters();
                self.b.field_last("type_parameters");
                self.ty_no_bounds();
                self.b.wrap(m, "higher_ranked_trait_bound", true);
                return;
            }
            "<" => {
                // qualified path <T as Trait>::X
                self.qualified_path_type(m);
                return;
            }
            _ => {}
        }
        if t.k == K::Ident || tx == "::" {
            if PRIMS.contains(&tx) && self.txn(1) != "::" {
                self.bump_named("primitive_type");
                return;
            }
            self.type_path(m);
            return;
        }
        if t.k == K::Op && tx == "$" {
            self.tt_leaf();
            return;
        }
        let p = self.cur_pos();
        self.b.missing("type_identifier", true, p);
    }

    fn bound_list_type(&mut self) {
        // single trait type (bounds handled by bounded_type in ty)
        let m = self.b.mark();
        if self.at("for") {
            self.higher_ranked(m);
        } else if self.at("(") {
            self.bump();
            self.ty();
            self.expect(")");
        } else if self.at("?") {
            self.bump();
            self.ty_no_bounds();
            self.b.wrap(m, "removed_trait_bound", true);
        } else {
            self.ty_no_bounds();
        }
    }

    fn ref_type_rest(&mut self, m: usize) {
        if self.k() == K::Lifetime {
            self.lifetime();
        }
        if self.at("mut") {
            self.bump_named("mutable_specifier");
        }
        self.ty_no_bounds();
        self.b.field_last("type");
        self.b.wrap(m, "reference_type", true);
    }

    fn fn_type(&mut self, m: usize) {
        let mm = self.b.mark();
        let mut mods = false;
        while matches!(self.tx(), "unsafe" | "extern" | "const" | "async") {
            if self.at("extern") {
                let me = self.b.mark();
                self.bump();
                if self.k() == K::Str {
                    self.string_literal();
                }
                self.b.wrap(me, "extern_modifier", true);
            } else {
                self.bump();
            }
            mods = true;
        }
        if mods {
            self.b.wrap(mm, "function_modifiers", true);
        }
        self.expect("fn");
        self.parameters();
        self.b.field_last("parameters");
        if self.at("->") {
            self.bump();
            self.ty();
            self.b.field_last("return_type");
        }
        self.b.wrap(m, "function_type", true);
    }

    fn qualified_path_type(&mut self, m: usize) {
        let mb = self.b.mark();
        self.bump(); // <
        let mq = self.b.mark();
        self.ty();
        if self.at("as") {
            self.b.field_last("type");
            self.bump();
            self.ty();
            self.b.field_last("alias");
            self.b.wrap(mq, "qualified_type", true);
        }
        self.expect(">");
        self.b.wrap(mb, "bracketed_type", true);
        // ::Name
        while self.at("::") {
            self.set_field_first(m, "path");
            self.bump();
            self.bump_named("type_identifier");
            self.b.field_last("name");
            self.b.wrap(m, "scoped_type_identifier", true);
        }
        if self.at("<") {
            self.b.field_last("type");
            self.type_arguments();
            self.b.field_last("type_arguments");
            self.b.wrap(m, "generic_type", true);
        }
    }

    /// type path: Foo, a::b::Foo, Foo<T>, Fn(A) -> B
    fn type_path(&mut self, m: usize) {
        // collect segments: path segments are identifiers (with optional generic args), last is type_identifier
        // Determine number of segments
        let mut segs = 1;
        {
            let mut j = 0;
            if self.txn(0) == "::" {
                j = 1;
            }
            loop {
                // skip ident
                j += 1;
                if self.txn(j) == "<" && self.txn(j + 1) != "" {
                    // generic args in middle: skip balanced
                    let mut depth = 0;
                    loop {
                        let x = self.txn(j);
                        if x == "" {
                            break;
                        }
                        if x == "<" {
                            depth += 1;
                        } else if x == ">" {
                            depth -= 1;
                            if depth == 0 {
                                j += 1;
                                break;
                            }
                        } else if x == "->" {
                        }
                        j += 1;
                    }
                }
                if self.txn(j) == "::" && self.tok(j + 1).k == K::Ident {
                    segs += 1;
                    j += 1;
                    continue;
                }
                break;
            }
        }
        let leading = self.at("::");
        if segs == 1 && !leading {
            self.type_ident_with_args(m);
            return;
        }
        // build path prefix as expression-style path (identifier / scoped_identifier / generic_type)
        let mp = self.b.mark();
        if leading {
            self.bump();
        }
        let mut done = 0;
        // first segment
        if !leading {
            self.path_segment_type_prefix();
            done = 1;
        } else {
            // ::a::b - leading global path
        }
        while done < segs - 1 {
            if done > 0 || leading {
                if done > 0 {
                    self.set_field_first(mp, "path");
                }
                if !(leading && done == 0) {
                    self.bump(); // ::
                }
                self.path_segment_ident();
                if done > 0 || leading {
                    self.b.field_last("name");
                }
                self.b.wrap(mp, "scoped_identifier", true);
            }
            done += 1;
            if self.at("<") && self.txn(1) != "" && done < segs - 1 + 1 && self.txn_after_generic_is_path() {
                self.b.field_last("type");
                self.type_arguments();
                self.b.field_last("type_arguments");
                self.b.wrap(mp, "generic_type", true);
            }
        }
        self.b.field_last("path");
        self.expect("::");
        self.bump_named("type_identifier");
        self.b.field_last("name");
        self.b.wrap(m, "scoped_type_identifier", true);
        self.type_args_tail(m);
    }

    fn txn_after_generic_is_path(&self) -> bool {
        let mut depth = 0;
        let mut j = 0;
        loop {
            let x = self.txn(j);
            if x == "" {
                return false;
            }
            if x == "<" {
                depth += 1;
            } else if x == ">" {
                depth -= 1;
                if depth == 0 {
                    return self.txn(j + 1) == "::";
                }
            }
            j += 1;
        }
    }

    fn path_segment_type_prefix(&mut self) {
        let m = self.b.mark();
        self.path_segment_ident();
        if self.at("<") && self.txn_after_generic_is_path() {
            self.b.rename(self.b.last().unwrap(), "type_identifier");
            self.b.field_last("type");
            self.type_arguments();
            self.b.field_last("type_arguments");
            self.b.wrap(m, "generic_type", true);
        }
    }

    fn type_ident_with_args(&mut self, m: usize) {
        let tx = self.tx();
        if tx == "Self" && false {
        }
        if self.k() == K::Ident {
            self.bump_named("type_identifier");
        } else {
            let p = self.cur_pos();
            self.b.missing("type_identifier", true, p);
        }
        self.type_args_tail(m);
    }

    fn type_args_tail(&mut self, m: usize) {
        if self.at("<") {
            self.b.field_last("type");
            self.type_arguments();
            self.b.field_last("type_arguments");
            self.b.wrap(m, "generic_type", true);
        } else if self.at("(") {
            // Fn(A) -> B
            self.b.field_last("trait");
            self.parameters();
            self.b.field_last("parameters");
            if self.at("->") {
                self.bump();
                self.ty();
                self.b.field_last("return_type");
            }
            self.b.wrap(m, "function_type", true);
        }
    }

    fn type_arguments(&mut self) {
        let m = self.b.mark();
        self.bump(); // <
        while !self.at(">") && self.k() != K::Eof {
            let ma = self.b.mark();
            if self.k() == K::Lifetime {
                self.lifetime();
            } else if self.k() == K::Ident && (self.txn(1) == "=" || (self.txn(1) == ":" && self.txn(2) != ":")) && self.txn(1) != "::" {
                self.bump_named("type_identifier");
                self.b.field_last("name");
                if self.at(":") {
                    self.trait_bounds();
                    self.b.field_last("bounds");
                    self.b.wrap(ma, "associated_type", true);
                } else {
                    self.bump();
                    self.ty();
                    self.b.field_last("type");
                    self.b.wrap(ma, "type_binding", true);
                }
            } else if matches!(self.k(), K::Int | K::Float | K::Str | K::Char) || self.at("{") || self.at("-") || self.at("true") || self.at("false") {
                if self.at("{") {
                    self.block();
                } else {
                    self.literal();
                }
            } else {
                self.ty();
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect(">");
        self.b.wrap(m, "type_arguments", true);
    }

    // ---------- patterns ----------
    fn pattern(&mut self) {
        let m = self.b.mark();
        if self.at("|") {
            self.bump();
        }
        self.pattern_single();
        if self.at("|") {
            while self.at("|") {
                self.bump();
                self.pattern_single();
            }
            self.b.wrap(m, "or_pattern", true);
        }
    }

    fn pattern_single(&mut self) {
        let m = self.b.mark();
        let t = self.tok(0);
        let tx = self.tx();
        match tx {
            "_" => {
                self.bump();
                return;
            }
            "(" => {
                self.bump();
                while !self.at(")") && self.k() != K::Eof {
                    self.pattern();
                    if !self.eat(",") {
                        break;
                    }
                }
                self.expect(")");
                self.b.wrap(m, "tuple_pattern", true);
                return;
            }
            "[" => {
                self.bump();
                while !self.at("]") && self.k() != K::Eof {
                    self.pattern();
                    if !self.eat(",") {
                        break;
                    }
                }
                self.expect("]");
                self.b.wrap(m, "slice_pattern", true);
                return;
            }
            "&" | "&&" => {
                if tx == "&&" {
                    let t = self.advance();
                    self.b.leaf("&", false, t.s, t.s + 1);
                    let m2 = self.b.mark();
                    self.b.leaf("&", false, t.s + 1, t.e);
                    if self.at("mut") {
                        self.bump_named("mutable_specifier");
                    }
                    self.pattern_single();
                    self.b.wrap(m2, "reference_pattern", true);
                    self.b.wrap(m, "reference_pattern", true);
                    return;
                }
                self.bump();
                if self.at("mut") {
                    self.bump_named("mutable_specifier");
                }
                self.pattern_single();
                self.b.wrap(m, "reference_pattern", true);
                return;
            }
            ".." => {
                self.bump();
                if matches!(self.k(), K::Int | K::Float | K::Char) || self.at("-") {
                    self.literal();
                    self.b.wrap(m, "range_pattern", true);
                    return;
                }
                self.b.wrap(m, "remaining_field_pattern", true);
                return;
            }
            "ref" => {
                self.bump();
                if self.at("mut") {
                    self.bump_named("mutable_specifier");
                }
                self.pattern_single();
                self.b.wrap(m, "ref_pattern", true);
                return;
            }
            "mut" => {
                self.bump_named("mutable_specifier");
                self.pattern_single();
                self.b.wrap(m, "mut_pattern", true);
                return;
            }
            "box" if self.tok(1).k == K::Ident || self.txn(1) == "(" => {
                self.bump();
                self.pattern_single();
                return;
            }
            _ => {}
        }
        if matches!(t.k, K::Int | K::Float | K::Str | K::RawStr | K::Char) || tx == "-" || tx == "true" || tx == "false" {
            if tx == "-" {
                let mn = self.b.mark();
                self.bump();
                self.literal();
                self.b.wrap(mn, "negative_literal", true);
            } else {
                self.literal();
            }
            self.range_pattern_tail(m);
            return;
        }
        if t.k == K::Ident || tx == "::" || tx == "<" {
            // path, possibly tuple struct / struct / captured
            if t.k == K::Ident && self.txn(1) == "@" {
                self.bump_named("identifier");
                self.bump();
                self.pattern_single();
                self.b.wrap(m, "captured_pattern", true);
                return;
            }
            if t.k == K::Ident && self.txn(1) == "!" {
                self.macro_invocation_from(m);
                return;
            }
            self.expr_path();
            if self.at("(") {
                self.b.field_last("type");
                self.bump();
                while !self.at(")") && self.k() != K::Eof {
                    self.pattern();
                    if !self.eat(",") {
                        break;
                    }
                }
                self.expect(")");
                self.b.wrap(m, "tuple_struct_pattern", true);
                return;
            }
            if self.at("{") {
                // struct pattern; type name as type_identifier
                let last = self.b.last().unwrap();
                if self.b.nodes[last as usize].kind == "identifier" {
                    self.b.rename(last, "type_identifier");
                } else if self.b.nodes[last as usize].kind == "scoped_identifier" {
                    self.b.rename(last, "scoped_type_identifier");
                    let ch = self.b.nodes[last as usize].children.clone();
                    if let Some(&lc) = ch.last() {
                        if self.b.nodes[lc as usize].kind == "identifier" {
                            self.b.rename(lc, "type_identifier");
                        }
                    }
                }
                self.b.field_last("type");
                self.bump();
                while !self.at("}") && self.k() != K::Eof {
                    let mf = self.b.mark();
                    if self.at("..") {
                        self.bump();
                        self.b.wrap(mf, "remaining_field_pattern", true);
                    } else {
                        if self.at("ref") {
                            self.bump();
                        }
                        if self.at("mut") {
                            self.bump_named("mutable_specifier");
                        }
                        if self.txn(1) == ":" {
                            self.bump_named("field_identifier");
                            self.b.field_last("name");
                            self.bump();
                            self.pattern();
                            self.b.field_last("pattern");
                        } else {
                            self.bump_named("shorthand_field_identifier");
                            self.b.field_last("name");
                        }
                        self.b.wrap(mf, "field_pattern", true);
                    }
                    if !self.eat(",") {
                        break;
                    }
                }
                self.expect("}");
                self.b.wrap(m, "struct_pattern", true);
                return;
            }
            self.range_pattern_tail(m);
            return;
        }
        if tx == "$" {
            self.tt_leaf();
            return;
        }
        self.error_token();
    }

    fn range_pattern_tail(&mut self, m: usize) {
        if self.at("..=") || self.at("...") || self.at("..") {
            self.bump();
            if matches!(self.k(), K::Int | K::Float | K::Char | K::Ident) || self.at("-") || self.at("::") {
                if self.at("-") {
                    let mn = self.b.mark();
                    self.bump();
                    self.literal();
                    self.b.wrap(mn, "negative_literal", true);
                } else if self.k() == K::Ident {
                    self.expr_path();
                } else {
                    self.literal();
                }
            }
            self.b.wrap(m, "range_pattern", true);
        }
    }

    fn literal(&mut self) {
        let t = self.tok(0);
        match t.k {
            K::Int => {
                self.bump_named("integer_literal");
            }
            K::Float => {
                self.bump_named("float_literal");
            }
            K::Str => self.string_literal(),
            K::RawStr => self.raw_string(),
            K::Char => {
                self.bump_named("char_literal");
            }
            _ => {
                if self.at("true") || self.at("false") {
                    self.bump_named("boolean_literal");
                } else if self.at("-") {
                    let m = self.b.mark();
                    self.bump();
                    self.literal();
                    self.b.wrap(m, "negative_literal", true);
                } else {
                    self.error_token();
                }
            }
        }
    }

    fn string_literal(&mut self) {
        let t = self.advance();
        let m = self.b.mark();
        let b = self.src.as_bytes();
        let q = self.src[t.s..].find('"').map(|x| t.s + x).unwrap_or(t.s);
        self.b.leaf("\"", false, t.s, q + 1);
        if q + 1 > t.s + 1 {
            // prefix b" or c": tree-sitter token is `b"`
            let id = self.b.last().unwrap();
            let k = intern(&self.src[t.s..q + 1]);
            self.b.rename(id, k);
        }
        let close = t.e >= q + 2 && b[t.e - 1] == b'"';
        let ce = if close { t.e - 1 } else { t.e };
        let mut i = q + 1;
        let mut cs = i;
        while i < ce {
            if b[i] == b'\\' {
                if cs < i {
                    self.b.leaf("string_content", true, cs, i);
                }
                let mut k = i + 1;
                if k < ce {
                    match b[k] {
                        b'x' => k += 3,
                        b'u' => {
                            while k < ce && b[k] != b'}' {
                                k += 1;
                            }
                            k += 1;
                        }
                        b'\n' => {
                            k += 1;
                            while k < ce && (b[k] == b' ' || b[k] == b'\t' || b[k] == b'\n') {
                                k += 1;
                            }
                        }
                        _ => k += self.src[k..].chars().next().map(|c| c.len_utf8()).unwrap_or(1),
                    }
                }
                let k = k.min(ce);
                self.b.leaf("escape_sequence", true, i, k);
                i = k;
                cs = i;
            } else {
                i += 1;
            }
        }
        if cs < ce {
            self.b.leaf("string_content", true, cs, ce);
        }
        if close {
            self.b.leaf("\"", false, t.e - 1, t.e);
        }
        self.b.wrap(m, "string_literal", true);
    }

    fn raw_string(&mut self) {
        let t = self.advance();
        let m = self.b.mark();
        let txt = &self.src[t.s..t.e];
        let q = txt.find('"').unwrap_or(0);
        let hashes = txt[..q].chars().filter(|&c| c == '#').count();
        let cs = t.s + q + 1;
        let ce = t.e.saturating_sub(1 + hashes).max(cs);
        // prefix token r#" is anonymous: tree-sitter hides it; only string_content visible
        self.b.hidden(t.s, cs);
        self.b.leaf("string_content", true, cs, ce);
        self.b.hidden(ce, t.e);
        self.b.wrap(m, "raw_string_literal", true);
    }

    // ---------- expressions ----------
    fn expression(&mut self) {
        self.depth += 1;
        if self.depth > 300 {
            self.error_token();
            self.depth -= 1;
            return;
        }
        let m = self.b.mark();
        self.range_or_lower(m);
        self.depth -= 1;
    }

    fn range_or_lower(&mut self, m: usize) {
        // assignment (right assoc, lowest) > range
        if self.at("..") || self.at("..=") {
            self.bump();
            if self.expr_can_start() {
                self.binary(2);
            }
            self.b.wrap(m, "range_expression", true);
            return;
        }
        self.binary(2);
        if self.at("..") || self.at("..=") || self.at("...") {
            self.bump();
            if self.expr_can_start() {
                self.binary(2);
            }
            self.b.wrap(m, "range_expression", true);
        }
        self.assign_rest(m);
    }

    fn assign_rest(&mut self, m: usize) {
        if self.at("=") && !self.at("==") {
            self.b.field_last("left");
            self.bump();
            self.expression();
            self.b.field_last("right");
            self.b.wrap(m, "assignment_expression", true);
        } else if matches!(self.tx(), "+=" | "-=" | "*=" | "/=" | "%=" | "^=" | "&=" | "|=" | "<<=") && self.k() == K::Op {
            self.b.field_last("left");
            self.bump();
            self.b.field_last("operator");
            self.expression();
            self.b.field_last("right");
            self.b.wrap(m, "compound_assignment_expr", true);
        } else if self.at(">") && self.adjacent(0) && self.txn(1) == ">" && self.adjacent(1) && self.txn(2) == "=" {
            self.b.field_last("left");
            self.bump_join(3);
            self.b.field_last("operator");
            self.expression();
            self.b.field_last("right");
            self.b.wrap(m, "compound_assignment_expr", true);
        }
    }

    fn expr_can_start(&self) -> bool {
        let t = self.tok(0);
        if t.k == K::Eof {
            return false;
        }
        let tx = self.tx();
        if t.k == K::Op {
            return matches!(tx, "(" | "[" | "-" | "!" | "*" | "&" | "&&" | "|" | "||" | "::" | "<" | "$") || (tx == "{" && !self.no_struct);
        }
        !matches!(tx, "as" | "else")
    }

    /// binary operator at current position: (prec, op token count)
    fn binop(&self) -> Option<(u8, usize)> {
        let t = self.tok(0);
        if t.k != K::Op {
            if t.k == K::Ident && self.tx() == "as" {
                return Some((11, 1));
            }
            return None;
        }
        let tx = self.tx();
        Some(match tx {
            "||" => (3, 1),
            "&&" => (4, 1),
            "==" | "!=" | "<=" => (5, 1),
            "<" => (5, 1),
            ">" => {
                if self.adjacent(0) && self.txn(1) == "=" && !(self.adjacent(1) && self.txn(2) == "=") {
                    (5, 2)
                } else if self.adjacent(0) && self.txn(1) == ">" {
                    if self.adjacent(1) && self.txn(2) == "=" {
                        return None;
                    }
                    (9, 2)
                } else {
                    (5, 1)
                }
            }
            "|" => (6, 1),
            "^" => (7, 1),
            "&" => (8, 1),
            "<<" => (9, 1),
            "+" | "-" => (10, 1),
            "*" | "/" | "%" => (11, 1),
            _ => return None,
        })
        .map(|(p, n)| if tx == "*" || tx == "/" || tx == "%" { (12, n) } else if p == 11 && tx != "as" { (11, n) } else { (p, n) })
    }

    fn binary(&mut self, min: u8) {
        let m = self.b.mark();
        self.unary();
        self.binary_rest(m, min);
    }

    fn binary_rest(&mut self, m: usize, min: u8) {
        loop {
            if self.at("as") {
                if 13 < min {
                    break;
                }
                self.b.field_last("value");
                self.bump();
                self.ty_no_bounds();
                self.b.field_last("type");
                self.b.wrap(m, "type_cast_expression", true);
                continue;
            }
            let Some((p, n)) = self.binop() else { break };
            if p < min {
                break;
            }
            self.b.field_last("left");
            if n == 2 {
                self.bump_join(2);
            } else {
                self.bump();
            }
            self.b.field_last("operator");
            self.binary(p + 1);
            self.b.field_last("right");
            self.b.wrap(m, "binary_expression", true);
        }
    }

    fn unary(&mut self) {
        let m = self.b.mark();
        let tx = self.tx();
        match tx {
            "-" | "!" | "*" => {
                self.bump();
                self.unary();
                self.b.wrap(m, "unary_expression", true);
                return;
            }
            "&" | "&&" => {
                if tx == "&&" {
                    let t = self.advance();
                    self.b.leaf("&", false, t.s, t.s + 1);
                    let m2 = self.b.mark();
                    self.b.leaf("&", false, t.s + 1, t.e);
                    if self.at("mut") {
                        self.bump_named("mutable_specifier");
                    }
                    self.unary();
                    self.b.field_last("value");
                    self.b.wrap(m2, "reference_expression", true);
                    self.b.field_last("value");
                    self.b.wrap(m, "reference_expression", true);
                    return;
                }
                self.bump();
                if self.at("raw") && matches!(self.txn(1), "const" | "mut") {
                    self.bump();
                    self.bump();
                } else if self.at("mut") {
                    self.bump_named("mutable_specifier");
                }
                self.unary();
                self.b.field_last("value");
                self.b.wrap(m, "reference_expression", true);
                return;
            }
            _ => {}
        }
        self.postfix();
    }

    fn postfix(&mut self) {
        let m = self.b.mark();
        self.primary();
        self.postfix_from(m);
    }

    fn postfix_from(&mut self, m: usize) {
        loop {
            let tx = self.tx();
            match tx {
                "?" => {
                    self.bump();
                    self.b.wrap(m, "try_expression", true);
                }
                "." => {
                    self.set_field_first(m, "value");
                    if self.txn(1) == "await" {
                        self.bump();
                        self.bump();
                        self.b.wrap(m, "await_expression", true);
                        continue;
                    }
                    self.bump();
                    let t = self.tok(0);
                    if t.k == K::Int || t.k == K::Float {
                        if t.k == K::Float {
                            // tuple.0.1 lexed as float: split
                            let tk = self.advance();
                            let txt = &self.src[tk.s..tk.e];
                            if let Some(dot) = txt.find('.') {
                                self.b.leaf("integer_literal", true, tk.s, tk.s + dot);
                                self.b.field_last("field");
                                self.b.wrap(m, "field_expression", true);
                                self.set_field_first(m, "value");
                                self.b.leaf(".", false, tk.s + dot, tk.s + dot + 1);
                                self.b.leaf("integer_literal", true, tk.s + dot + 1, tk.e);
                                self.b.field_last("field");
                                self.b.wrap(m, "field_expression", true);
                                continue;
                            }
                            self.b.leaf("integer_literal", true, tk.s, tk.e);
                        } else {
                            self.bump_named("integer_literal");
                        }
                    } else if t.k == K::Ident {
                        self.bump_named("field_identifier");
                    } else {
                        let p = self.cur_pos();
                        self.b.missing("field_identifier", true, p);
                    }
                    self.b.field_last("field");
                    self.b.wrap(m, "field_expression", true);
                    // turbofish on method
                    if self.at("::") && self.txn(1) == "<" {
                        self.set_field_first(m, "function");
                        self.bump();
                        self.type_arguments();
                        self.b.field_last("type_arguments");
                        self.b.wrap(m, "generic_function", true);
                    }
                }
                "(" => {
                    self.set_field_first(m, "function");
                    self.arguments();
                    self.b.field_last("arguments");
                    self.b.wrap(m, "call_expression", true);
                }
                "[" => {
                    self.bump();
                    let save = self.no_struct;
                    self.no_struct = false;
                    self.expression();
                    self.no_struct = save;
                    self.expect("]");
                    self.b.wrap(m, "index_expression", true);
                }
                _ => break,
            }
        }
    }

    fn arguments(&mut self) {
        let m = self.b.mark();
        self.bump(); // (
        let save = self.no_struct;
        self.no_struct = false;
        while !self.at(")") && self.k() != K::Eof {
            self.outer_attrs();
            let before = self.i;
            self.expression();
            if self.i == before {
                break;
            }
            if !self.eat(",") {
                break;
            }
        }
        self.no_struct = save;
        self.expect(")");
        self.b.wrap(m, "arguments", true);
    }

    /// expression path: identifier, scoped_identifier, generic_function (turbofish)
    fn expr_path(&mut self) {
        let m = self.b.mark();
        if self.at("<") {
            // qualified path <T as Trait>::x
            let mb = self.b.mark();
            self.bump();
            let mq = self.b.mark();
            self.ty();
            if self.at("as") {
                self.b.field_last("type");
                self.bump();
                self.ty();
                self.b.field_last("alias");
                self.b.wrap(mq, "qualified_type", true);
            }
            self.expect(">");
            self.b.wrap(mb, "bracketed_type", true);
        } else if self.at("::") {
            self.bump();
            self.path_segment_ident();
            self.b.field_last("name");
            self.b.wrap(m, "scoped_identifier", true);
        } else {
            let t = self.tok(0);
            let tx = self.tx();
            if t.k == K::Ident && PRIMS.contains(&tx) && self.txn(1) == "::" {
                self.bump_named("primitive_type");
            } else if t.k == K::Ident && self.txn(1) == "<" && self.txn_after_generic_is_path() && self.txn(1) == "<" && false {
            } else {
                self.path_segment_ident();
            }
        }
        loop {
            if self.at("::") {
                let n1 = self.txn(1);
                if n1 == "<" {
                    // turbofish
                    let after_is_path = {
                        // check `::<...>::`
                        let mut depth = 0;
                        let mut j = 1;
                        let mut res = false;
                        loop {
                            let x = self.txn(j);
                            if x == "" {
                                break;
                            }
                            if x == "<" {
                                depth += 1;
                            } else if x == ">" {
                                depth -= 1;
                                if depth == 0 {
                                    res = self.txn(j + 1) == "::";
                                    break;
                                }
                            }
                            j += 1;
                        }
                        res
                    };
                    if after_is_path {
                        // generic_type_with_turbofish as path
                        self.b.field_last("type");
                        let last = self.b.last().unwrap();
                        if self.b.nodes[last as usize].kind == "identifier" {
                            self.b.rename(last, "type_identifier");
                        }
                        self.bump();
                        self.type_arguments();
                        self.b.field_last("type_arguments");
                        self.b.wrap(m, "generic_type_with_turbofish", true);
                        continue;
                    }
                    self.b.field_last("function");
                    self.bump();
                    self.type_arguments();
                    self.b.field_last("type_arguments");
                    self.b.wrap(m, "generic_function", true);
                    break;
                }
                if self.tok(1).k == K::Ident || n1 == "$" {
                    self.set_field_first(m, "path");
                    self.bump();
                    self.path_segment_ident();
                    self.b.field_last("name");
                    self.b.wrap(m, "scoped_identifier", true);
                    continue;
                }
            }
            break;
        }
    }

    fn primary(&mut self) {
        let m = self.b.mark();
        let t = self.tok(0);
        let tx = self.tx();
        match t.k {
            K::Int | K::Float | K::Str | K::RawStr | K::Char => {
                self.literal();
                return;
            }
            K::Lifetime => {
                if self.txn(1) == ":" {
                    self.label();
                    self.bump();
                    match self.tx() {
                        "loop" => self.loop_expr(m),
                        "while" => self.while_expr(m),
                        "for" => self.for_expr(m),
                        _ => {
                            self.block_inner(m);
                        }
                    }
                    return;
                }
                self.error_token();
                return;
            }
            K::Eof => {
                let p = self.cur_pos();
                self.b.missing("identifier", true, p);
                return;
            }
            _ => {}
        }
        match tx {
            "(" => {
                self.bump();
                if self.at(")") {
                    self.bump();
                    self.b.wrap(m, "unit_expression", true);
                    return;
                }
                let save = self.no_struct;
                self.no_struct = false;
                self.expression();
                let mut tuple = false;
                while self.at(",") {
                    tuple = true;
                    self.bump();
                    if self.at(")") {
                        break;
                    }
                    self.expression();
                }
                self.no_struct = save;
                self.expect(")");
                self.b.wrap(m, if tuple { "tuple_expression" } else { "parenthesized_expression" }, true);
            }
            "[" => {
                self.bump();
                let save = self.no_struct;
                self.no_struct = false;
                if !self.at("]") {
                    self.outer_attrs();
                    self.expression();
                    if self.at(";") {
                        self.bump();
                        self.expression();
                        self.b.field_last("length");
                    } else {
                        while self.eat(",") {
                            if self.at("]") {
                                break;
                            }
                            self.expression();
                        }
                    }
                }
                self.no_struct = save;
                self.expect("]");
                self.b.wrap(m, "array_expression", true);
            }
            "{" => {
                self.block();
            }
            "|" | "||" => self.closure(m),
            "true" | "false" => {
                self.bump_named("boolean_literal");
            }
            "if" => self.if_expr(m),
            "match" => self.match_expr(m),
            "loop" => self.loop_expr(m),
            "while" => self.while_expr(m),
            "for" if self.txn(1) != "<" => self.for_expr(m),
            "unsafe" if self.txn(1) == "{" => {
                self.bump();
                self.block();
                self.b.wrap(m, "unsafe_block", true);
            }
            "async" if self.txn(1) == "{" || (self.txn(1) == "move" && self.txn(2) == "{") => {
                self.bump();
                self.eat("move");
                self.block();
                self.b.wrap(m, "async_block", true);
            }
            "async" | "move" | "static" if matches!(self.txn(1), "|" | "||" | "move") => self.closure(m),
            "const" if self.txn(1) == "{" => {
                self.bump();
                self.block();
                self.b.wrap(m, "const_block", true);
            }
            "try" if self.txn(1) == "{" => {
                self.bump();
                self.block();
                self.b.wrap(m, "try_block", true);
            }
            "gen" if self.txn(1) == "{" => {
                self.bump();
                self.block();
                self.b.wrap(m, "gen_block", true);
            }
            "return" => {
                self.bump();
                if self.expr_can_start() && !self.at("}") {
                    self.expression();
                }
                self.b.wrap(m, "return_expression", true);
            }
            "break" => {
                self.bump();
                if self.k() == K::Lifetime {
                    self.label();
                }
                if self.expr_can_start() && !self.at("}") {
                    self.expression();
                }
                self.b.wrap(m, "break_expression", true);
            }
            "continue" => {
                self.bump();
                if self.k() == K::Lifetime {
                    self.label();
                }
                self.b.wrap(m, "continue_expression", true);
            }
            "yield" => {
                self.bump();
                if self.expr_can_start() && !self.at("}") {
                    self.expression();
                }
                self.b.wrap(m, "yield_expression", true);
            }
            "self" if self.txn(1) != "::" => {
                self.bump_named("self");
            }
            "$" => {
                self.tt_leaf();
            }
            _ => {
                if t.k == K::Ident || tx == "::" || tx == "<" {
                    self.expr_path();
                    // macro invocation
                    if self.at("!") && self.matches_macro_open() {
                        let last = self.b.last().unwrap();
                        let lk = self.b.nodes[last as usize].kind;
                        if lk == "identifier" || lk == "scoped_identifier" {
                            self.b.field_last("macro");
                            self.bump();
                            self.token_tree();
                            self.b.wrap(m, "macro_invocation", true);
                            return;
                        }
                    }
                    // struct expression
                    if self.at("{") && !self.no_struct && self.struct_lit_ahead() {
                        let last = self.b.last().unwrap();
                        let lk = self.b.nodes[last as usize].kind;
                        if lk == "identifier" {
                            self.b.rename(last, "type_identifier");
                        } else if lk == "scoped_identifier" {
                            self.b.rename(last, "scoped_type_identifier");
                            let ch = self.b.nodes[last as usize].children.clone();
                            if let Some(&lc) = ch.last() {
                                if self.b.nodes[lc as usize].kind == "identifier" {
                                    self.b.rename(lc, "type_identifier");
                                }
                            }
                        }
                        self.b.field_last("name");
                        self.field_initializer_list();
                        self.b.field_last("body");
                        self.b.wrap(m, "struct_expression", true);
                    }
                    return;
                }
                self.error_token();
            }
        }
    }

    fn matches_macro_open(&self) -> bool {
        matches!(self.txn(1), "(" | "[" | "{")
    }

    fn struct_lit_ahead(&self) -> bool {
        // `{ }` or `{ ident :` or `{ ident ,` or `{ ident }` or `{ ..`
        let n1 = self.tok(1);
        let x1 = self.txn(1);
        if x1 == "}" || x1 == ".." {
            return true;
        }
        if n1.k == K::Ident || n1.k == K::Int {
            let x2 = self.txn(2);
            return matches!(x2, ":" | "," | "}");
        }
        x1 == "#"
    }

    fn field_initializer_list(&mut self) {
        let m = self.b.mark();
        self.bump(); // {
        while !self.at("}") && self.k() != K::Eof {
            self.outer_attrs();
            let mf = self.b.mark();
            if self.at("..") {
                self.bump();
                self.expression();
                self.b.wrap(mf, "base_field_initializer", true);
            } else if self.txn(1) == ":" {
                if self.k() == K::Int {
                    self.bump_named("integer_literal");
                } else {
                    self.bump_named("field_identifier");
                }
                self.b.field_last("field");
                self.bump();
                self.expression();
                self.b.field_last("value");
                self.b.wrap(mf, "field_initializer", true);
            } else {
                self.bump_named("identifier");
                self.b.wrap(mf, "shorthand_field_initializer", true);
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect("}");
        self.b.wrap(m, "field_initializer_list", true);
    }

    fn closure(&mut self, m: usize) {
        if self.at("static") {
            self.bump();
        }
        if self.at("async") {
            self.bump();
        }
        if self.at("move") {
            self.bump();
        }
        let mp = self.b.mark();
        if self.at("||") {
            let t = self.advance();
            self.b.leaf("|", false, t.s, t.s + 1);
            self.b.leaf("|", false, t.s + 1, t.e);
        } else {
            self.bump(); // |
            while !self.at("|") && self.k() != K::Eof {
                let mx = self.b.mark();
                self.pattern_single_closure();
                if self.at(":") {
                    self.b.field_last("pattern");
                    self.bump();
                    self.ty();
                    self.b.field_last("type");
                    self.b.wrap(mx, "parameter", true);
                }
                if !self.eat(",") {
                    break;
                }
            }
            self.expect("|");
        }
        self.b.wrap(mp, "closure_parameters", true);
        self.b.field_last("parameters");
        if self.at("->") {
            self.bump();
            self.ty();
            self.b.field_last("return_type");
            self.block();
        } else if self.at("_") && self.txn(1) == "=>" {
            self.bump();
        } else {
            self.expression();
        }
        self.b.field_last("body");
        self.b.wrap(m, "closure_expression", true);
    }

    fn pattern_single_closure(&mut self) {
        // patterns in closure params cannot contain top-level |
        if self.at("mut") && self.tok(1).k == K::Ident {
            let m = self.b.mark();
            self.bump_named("mutable_specifier");
            self.pattern_single();
            self.b.wrap(m, "mut_pattern", true);
            return;
        }
        self.pattern_single();
    }

    fn condition(&mut self) {
        let save = self.no_struct;
        self.no_struct = true;
        let m = self.b.mark();
        self.cond_atom();
        if self.at("&&") || self.at("||") {
            let mut is_chain = self.b.nodes[self.b.last().unwrap() as usize].kind == "let_condition";
            let saved_i = self.i;
            let cp = self.b.checkpoint();
            // try parse as let chain
            let mut parts_let = is_chain;
            while self.at("&&") {
                self.bump();
                let before = self.b.mark();
                self.cond_atom();
                if self.b.nodes[self.b.stack[before.min(self.b.stack.len() - 1)] as usize].kind == "let_condition" {
                    parts_let = true;
                }
            }
            if parts_let && !self.at("||") {
                self.b.wrap(m, "let_chain", true);
            } else {
                self.i = saved_i;
                self.b.restore(cp);
                is_chain = false;
                let _ = is_chain;
                self.binary_rest(m, 0);
            }
        }
        self.no_struct = save;
    }

    fn cond_atom(&mut self) {
        let m = self.b.mark();
        if self.at("let") {
            self.bump();
            self.pattern();
            self.b.field_last("pattern");
            self.expect("=");
            // value: expression without && / ||
            let mv = self.b.mark();
            self.unary();
            self.binary_rest(mv, 5);
            self.b.field_last("value");
            self.b.wrap(m, "let_condition", true);
        } else {
            self.unary();
            self.binary_rest(m, 5);
        }
    }

    fn if_expr(&mut self, m: usize) {
        self.bump(); // if
        self.condition();
        self.b.field_last("condition");
        self.block();
        self.b.field_last("consequence");
        if self.at("else") {
            let me = self.b.mark();
            self.bump();
            if self.at("if") {
                let mi = self.b.mark();
                self.if_expr(mi);
            } else {
                self.block();
            }
            self.b.wrap(me, "else_clause", true);
            self.b.field_last("alternative");
        }
        self.b.wrap(m, "if_expression", true);
    }

    fn match_expr(&mut self, m: usize) {
        self.bump(); // match
        let save = self.no_struct;
        self.no_struct = true;
        self.expression();
        self.no_struct = save;
        self.b.field_last("value");
        let mb = self.b.mark();
        self.expect("{");
        while !self.at("}") && self.k() != K::Eof {
            let ma = self.b.mark();
            self.outer_attrs();
            let mp = self.b.mark();
            self.pattern();
            if self.at("if") {
                self.bump();
                self.condition();
                self.b.field_last("condition");
            }
            self.b.wrap(mp, "match_pattern", true);
            self.b.field_last("pattern");
            self.expect("=>");
            let block_like = matches!(self.tx(), "{" | "if" | "match" | "loop" | "while" | "for" | "unsafe") && self.tok(0).k != K::Str;
            if block_like {
                let mv = self.b.mark();
                self.primary();
                if self.at(".") || self.at("?") || (self.binop().is_some() && !self.at("|")) {
                    self.postfix_from(mv);
                    self.binary_rest(mv, 0);
                }
            } else {
                self.expression();
            }
            self.b.field_last("value");
            let has_comma = self.eat(",");
            self.b.wrap(ma, "match_arm", true);
            if !has_comma && !block_like && !self.at("}") {
                // missing comma
            }
        }
        self.expect("}");
        self.b.wrap(mb, "match_block", true);
        self.b.field_last("body");
        self.b.wrap(m, "match_expression", true);
    }

    fn loop_expr(&mut self, m: usize) {
        self.bump(); // loop
        self.block();
        self.b.field_last("body");
        self.b.wrap(m, "loop_expression", true);
    }

    fn while_expr(&mut self, m: usize) {
        self.bump();
        self.condition();
        self.b.field_last("condition");
        self.block();
        self.b.field_last("body");
        self.b.wrap(m, "while_expression", true);
    }

    fn for_expr(&mut self, m: usize) {
        self.bump(); // for
        self.pattern();
        self.b.field_last("pattern");
        self.expect("in");
        let save = self.no_struct;
        self.no_struct = true;
        self.expression();
        self.no_struct = save;
        self.b.field_last("value");
        self.block();
        self.b.field_last("body");
        self.b.wrap(m, "for_expression", true);
    }

    fn block_inner(&mut self, m: usize) {
        self.block();
        let _ = m;
    }

    fn macro_invocation_from(&mut self, m: usize) {
        self.expr_path();
        self.b.field_last("macro");
        self.expect("!");
        self.token_tree();
        self.b.wrap(m, "macro_invocation", true);
    }
}

fn is_keyword(s: &str) -> bool {
    matches!(
        s,
        "as" | "async" | "await" | "break" | "const" | "continue" | "dyn" | "else" | "enum" | "extern" | "fn" | "for"
            | "if" | "impl" | "in" | "let" | "loop" | "match" | "mod" | "move" | "mut" | "pub" | "ref" | "return"
            | "static" | "struct" | "trait" | "type" | "union" | "unsafe" | "use" | "where" | "while" | "default"
            | "macro_rules" | "yield" | "gen"
    )
}
