    /// Creates config
    pub fn new(name: &str) -> Self {
        Config { name: name.to_string(), values: HashMap::new() }
    }

    pub fn get(&self, key: &str) -> Option<&i64> {
        self.values.get(key)
    }

    fn set(&mut self, key: String, v: i64) {
        self.values.insert(key, v); // insert
    }
}

