            i = (k2 + 1).min(n);
            k = K::Rune;
        } else if c.is_ascii_digit() || (c == b'.' && i + 1 < n && b[i + 1].is_ascii_digit()) {
            let (kk, e) = scan_num(b, i);
            k = kk;
            i = e;
        } else if is_id_start(ch) {
            let mut e = i;
            for (o, c2) in src[i..].char_indices() {
                if !is_id_char(c2) {
                    e = i + o;
                    break;
                }
                e = i + o + c2.len_utf8();
            }
            i = e;
            k = K::Ident;
        } else {
            let r = &src[i..];
            let mut l = ch.len_utf8();
            for o in OPS {
                if r.starts_with(o) {
                    l = o.len();
                    break;
                }
            }
            i += l;
            k = K::Op;
        }
        let txt = &src[s..i];
        need_semi = match k {
            K::Ident => !matches!(
                txt,
                "break" | "case" | "chan" | "const" | "continue" | "default" | "defer" | "else" | "fallthrough" | "for"
                    | "func" | "go" | "goto" | "if" | "import" | "interface" | "map" | "package" | "range" | "return"
                    | "select" | "struct" | "switch" | "type" | "var"
            ) || matches!(txt, "break" | "continue" | "fallthrough" | "return"),
            K::Op => matches!(txt, ")" | "]" | "}" | "++" | "--"),
            _ => true,
        };
        out.push(Tk { k, s, e: i });
    }
    out.push(Tk { k: K::Eof, s: n, e: n });
    out
}

fn scan_num(b: &[u8], mut i: usize) -> (K, usize) {
    let n = b.len();
    let mut float = false;
    if b[i] == b'0' && i + 1 < n && matches!(b[i + 1], b'x' | b'X' | b'o' | b'O' | b'b' | b'B') {
        let hex = matches!(b[i + 1], b'x' | b'X');
        i += 2;
        while i < n && (b[i].is_ascii_hexdigit() || b[i] == b'_' || (hex && b[i] == b'.')) {
            if b[i] == b'.' {
                float = true;
            }
            i += 1;
        }
        if hex && i < n && (b[i] == b'p' || b[i] == b'P') {
            float = true;
            i += 1;
            if i < n && (b[i] == b'+' || b[i] == b'-') {
                i += 1;
            }
            while i < n && b[i].is_ascii_digit() {
                i += 1;
            }
        }
    } else {
        while i < n && (b[i].is_ascii_digit() || b[i] == b'_') {
            i += 1;
        }
        if i < n && b[i] == b'.' {
            float = true;
            i += 1;
            while i < n && (b[i].is_ascii_digit() || b[i] == b'_') {
                i += 1;
            }
        }
        if i < n && (b[i] == b'e' || b[i] == b'E') {
            float = true;
            i += 1;
            if i < n && (b[i] == b'+' || b[i] == b'-') {
                i += 1;
            }
            while i < n && b[i].is_ascii_digit() {
                i += 1;
            }
        }
    }
    if i < n && b[i] == b'i' {
        return (K::Imag, i + 1);
    }
    (if float { K::Float } else { K::Int }, i)
}

struct P<'a> {
    src: &'a str,
    toks: Vec<Tk>,
    i: usize,
    b: Builder,
    no_lit: bool,
    depth: usize,
}

pub fn parse(src: &str) -> Tree {
    let toks = tokenize(src);
    let mut p = P { src, toks, i: 0, b: Builder::new(), no_lit: false, depth: 0 };
    let m = p.b.mark();
    loop {
        p.skip_nl_hidden();
        if p.k() == K::Eof {
            break;
        }
        let before = p.i;
        let ms = p.b.mark();
        p.top_level();
        if p.i == before {
            p.error_token();
            continue;
        }
        // terminator
        if p.k() == K::NL {
            p.nl();
        } else if p.at(";") {
            p.bump();
        } else if p.k() == K::Eof {
            p.go_eof_quirk(ms);
            let pos = src.len();
            p.flush_extras();
            p.b.leaf("", false, pos, pos);
        }
    }
    p.flush_extras();
    let start = p.b.stack[m..].first().map(|&c| p.b.nodes[c as usize].start).unwrap_or(src.len() - src.trim_start().len());
    let root = p.b.wrap_all(m, "source_file", start, src.len());
    p.b.finish(root, src)
}

impl<'a> P<'a> {
    fn idx(&self, n: usize) -> usize {
        let mut j = self.i;
        let mut c = 0;
        loop {
            while j < self.toks.len() && self.toks[j].k == K::Comment {
                j += 1;
            }
            if j >= self.toks.len() {
                return self.toks.len() - 1;
            }
            if c == n {
                return j;
            }
            c += 1;
            j += 1;
        }
    }
    fn tok(&self, n: usize) -> Tk {
        self.toks[self.idx(n)]
    }
    fn k(&self) -> K {
        self.tok(0).k
    }
    fn txn(&self, n: usize) -> &'a str {
        let t = self.tok(n);
        if matches!(t.k, K::Eof | K::NL) {
            return "";
        }
        &self.src[t.s..t.e]
    }
    fn tx(&self) -> &'a str {
        self.txn(0)
    }
    fn at(&self, s: &str) -> bool {
        let t = self.tok(0);
        matches!(t.k, K::Op | K::Ident) && &self.src[t.s..t.e] == s
    }
    fn flush_extras(&mut self) {
        while self.i < self.toks.len() && self.toks[self.i].k == K::Comment {
            let t = self.toks[self.i];
            self.b.extra("comment", t.s, t.e);
            self.i += 1;
        }
    }
    fn advance(&mut self) -> Tk {
        self.flush_extras();
        let t = self.toks[self.i];
        if t.k != K::Eof {
            self.i += 1;
        }
        t
    }
    fn bump(&mut self) -> u32 {
        let t = self.advance();
        let k = intern(&self.src[t.s..t.e]);
        self.b.leaf(k, false, t.s, t.e)
    }
    fn bump_named(&mut self, kind: &'static str) -> u32 {
        let t = self.advance();
        self.b.leaf(kind, true, t.s, t.e)
    }
    fn nl(&mut self) {
        let t = self.advance();
        self.b.hidden(t.s, t.e);
    }
    fn skip_nl_hidden(&mut self) {
        while self.k() == K::NL {
            self.nl();
        }
    }
    fn eat(&mut self, s: &str) -> bool {
        if self.at(s) {
            self.bump();
            true
        } else {
            false
        }
    }
    fn cur_pos(&self) -> usize {
        self.b.last().map(|l| self.b.nodes[l as usize].end).unwrap_or(0)
    }
    fn expect(&mut self, s: &str) {
        if !self.eat(s) {
            let p = self.cur_pos();
            self.b.missing(intern(s), false, p);
        }
    }
    fn error_token(&mut self) {
        if self.k() == K::Eof {
            return;
        }
        let m = self.b.mark();
        match self.k() {
            K::Ident => {
                self.bump_named("identifier");
            }
            K::NL => {
                self.nl();
                return;
            }
            _ => {
                self.bump();
            }
        }
        self.b.wrap(m, "ERROR", true);
    }
    fn set_field_first(&mut self, m: usize, f: &'static str) {
        for i in m..self.b.stack.len() {
            let id = self.b.stack[i] as usize;
            if !self.b.nodes[id].extra {
                self.b.nodes[id].field = Some(f);
                return;
            }
        }
    }

    /// tree-sitter-go quirk: top-level `a.b(x)` at EOF without newline parses as type conversion
    fn go_eof_quirk(&mut self, ms: usize) {
        if self.b.stack.len() != ms + 1 {
            return;
        }
        let st = self.b.stack[ms];
        if self.b.nodes[st as usize].kind != "expression_statement" {
            return;
        }
        let ch = self.b.nodes[st as usize].children.clone();
        if ch.len() != 1 {
            return;
        }
        let call = ch[0];
        if self.b.nodes[call as usize].kind != "call_expression" {
            return;
        }
        let cc = self.b.nodes[call as usize].children.clone();
        if cc.len() != 2 {
            return;
        }
        let (func, args) = (cc[0], cc[1]);
        if self.b.nodes[func as usize].kind != "selector_expression" {
            return;
        }
        let fc = self.b.nodes[func as usize].children.clone();
        let named: Vec<u32> = fc.iter().copied().filter(|&c| !self.b.nodes[c as usize].extra).collect();
        if named.len() != 3 || self.b.nodes[named[0] as usize].kind != "identifier" {
            return;
        }
        let ac: Vec<u32> = self.b.nodes[args as usize].children.iter().copied().filter(|&c| !self.b.nodes[c as usize].extra).collect();
        // ( expr ) or ( expr , )
        let inner: Vec<u32> = ac.iter().copied().filter(|&c| self.b.nodes[c as usize].named).collect();
        if inner.len() != 1 || self.b.nodes[inner[0] as usize].kind == "variadic_argument" {
            return;
        }
        // rebuild
        self.b.nodes[named[0] as usize].kind = "package_identifier";
        self.b.nodes[named[0] as usize].field = Some("package");
        self.b.nodes[named[2] as usize].kind = "type_identifier";
        self.b.nodes[named[2] as usize].field = Some("name");
        self.b.nodes[func as usize].kind = "qualified_type";
        self.b.nodes[func as usize].field = Some("type");
        self.b.nodes[inner[0] as usize].field = Some("operand");
        let mut new_children = vec![func];
        new_children.extend(self.b.nodes[args as usize].children.iter().copied());
        self.b.nodes[call as usize].children = new_children;
        self.b.nodes[call as usize].kind = "type_conversion_expression";
    }

    // ---------- top level ----------
    fn top_level(&mut self) {
        let m = self.b.mark();
        match self.tx() {
            "package" => {
                self.bump();
                self.bump_named("package_identifier");
                self.b.wrap(m, "package_clause", true);
            }
            "import" => {
                self.bump();
                if self.at("(") {
                    let ml = self.b.mark();
                    self.bump();
                    loop {
                        self.skip_nl_hidden();
                        if self.at(")") || self.k() == K::Eof {
                            break;
                        }
                        self.import_spec();
                        if self.at(";") {
                            self.bump();
                        } else if self.k() == K::NL {
                            self.nl();
                        }
                    }
                    self.expect(")");
                    self.b.wrap(ml, "import_spec_list", true);
                } else {
                    self.import_spec();
                }
                self.b.wrap(m, "import_declaration", true);
            }
            "func" if self.tok(1).k == K::Ident || self.txn(1) == "(" && self.is_method_decl() => {
                self.func_decl(m);
            }
            _ => self.statement(),
        }
    }

    fn is_method_decl(&self) -> bool {
        // func (recv) Name(
        let mut depth = 0;
        let mut j = 1;
        loop {
            let x = self.txn(j);
            let t = self.tok(j);
            if t.k == K::Eof {
                return false;
            }
            if x == "(" {
                depth += 1;
            } else if x == ")" {
                depth -= 1;
                if depth == 0 {
                    return self.tok(j + 1).k == K::Ident;
                }
            }
            j += 1;
        }
    }

    fn import_spec(&mut self) {
        let m = self.b.mark();
        if self.at(".") {
            let md = self.b.mark();
            self.bump();
            self.b.wrap(md, "dot", true);
            self.b.field_last("name");
        } else if self.at("_") {
            self.bump_named("blank_identifier");
            self.b.field_last("name");
        } else if self.k() == K::Ident {
            self.bump_named("package_identifier");
            self.b.field_last("name");
        }
        self.string_lit();
        self.b.field_last("path");
        self.b.wrap(m, "import_spec", true);
    }

    fn func_decl(&mut self, m: usize) {
        self.bump(); // func
        let method = self.at("(");
        if method {
            self.parameter_list();
            self.b.field_last("receiver");
            self.bump_named("field_identifier");
        } else {
            self.bump_named("identifier");
        }
        self.b.field_last("name");
        if self.at("[") {
            self.type_parameter_list();
            self.b.field_last("type_parameters");
        }
        self.parameter_list();
        self.b.field_last("parameters");
        self.result();
        if self.at("{") {
            self.block();
            self.b.field_last("body");
        }
        self.b.wrap(m, if method { "method_declaration" } else { "function_declaration" }, true);
    }

    fn result(&mut self) {
        if self.at("(") {
            self.parameter_list();
            self.b.field_last("result");
        } else if self.type_can_start() {
            self.ty();
            self.b.field_last("result");
        }
    }

    fn type_can_start(&self) -> bool {
        let t = self.tok(0);
        if t.k == K::Ident {
            return true;
        }
        matches!(self.tx(), "*" | "[" | "(" | "<-") || (self.tx() == "func")
    }

    fn type_parameter_list(&mut self) {
        let m = self.b.mark();
        self.bump(); // [
        while !self.at("]") && self.k() != K::Eof {
            let md = self.b.mark();
            loop {
                self.bump_named("identifier");
                self.b.field_last("name");
                if self.at(",") && self.tok(1).k == K::Ident && !self.type_follows_names() {
                    self.bump();
                    continue;
                }
                break;
            }
            let mc = self.b.mark();
            self.constraint_elem();
            self.b.wrap(mc, "type_constraint", true);
            self.b.field_last("type");
            self.b.wrap(md, "type_parameter_declaration", true);
            if !self.eat(",") {
                break;
            }
        }
        self.expect("]");
        self.b.wrap(m, "type_parameter_list", true);
    }

    fn type_follows_names(&self) -> bool {
        // at ',' ident: is ident followed by a type (i.e. it's a new decl)?
        let x2 = self.txn(2);
        !(x2 == "," || x2 == "]")
    }

    fn constraint_elem(&mut self) {
        loop {
            if self.at("~") {
                let m = self.b.mark();
                self.bump();
                self.ty();
                self.b.wrap(m, "negated_type", true);
            } else {
                self.ty();
            }
            if !self.eat("|") {
                break;
            }
        }
    }

    fn parameter_list(&mut self) {
        let m = self.b.mark();
        self.expect("(");
        // decide named form
        let named = self.params_named();
        while !self.at(")") && self.k() != K::Eof {
            self.skip_nl_hidden();
            if self.at(")") {
                break;
            }
            let mp = self.b.mark();
            if named {
                let mut variadic = false;
                loop {
                    if self.at("_") {
                        self.bump_named("identifier");
                    } else {
                        self.bump_named("identifier");
                    }
                    self.b.field_last("name");
                    if self.at(",") && !self.next_group_has_type() {
                        self.bump();
                        continue;
                    }
                    break;
                }
                if self.at("...") {
                    self.bump();
                    variadic = true;
                }
                self.ty();
                self.b.field_last("type");
                self.b.wrap(mp, if variadic { "variadic_parameter_declaration" } else { "parameter_declaration" }, true);
            } else {
                if self.at("...") {
                    self.bump();
                    self.ty();
                    self.b.field_last("type");
                    self.b.wrap(mp, "variadic_parameter_declaration", true);
                } else {
                    self.ty();
                    self.b.field_last("type");
                    self.b.wrap(mp, "parameter_declaration", true);
                }
            }
            self.skip_nl_hidden();
            if !self.eat(",") {
                break;
            }
            self.skip_nl_hidden();
        }
        self.expect(")");
        self.b.wrap(m, "parameter_list", true);
    }

    fn next_group_has_type(&self) -> bool {
        // at ',', next is ident: if after that ident comes ',' or ')' -> it's just another name in same group
        let x2 = self.txn(2);
        !(x2 == "," || x2 == ")" || x2 == "")
            && false
    }

    fn params_named(&self) -> bool {
        // named if any top-level segment has two parts (ident followed by type start)
        let mut depth = 0;
        let mut j = 1;
        let mut seg_tokens = 0;
        let mut first_is_ident = false;
        loop {
            let t = self.tok(j);
            let x = self.txn(j);
            if t.k == K::Eof {
                return false;
            }
            if t.k == K::NL {
                j += 1;
                continue;
            }
            if depth == 0 && (x == ")" || x == ",") {
                if seg_tokens >= 2 && first_is_ident {
                    return true;
                }
                if x == ")" {
                    return false;
                }
                seg_tokens = 0;
                j += 1;
                continue;
            }
            if matches!(x, "(" | "[" | "{") {
                depth += 1;
            } else if matches!(x, ")" | "]" | "}") {
                depth -= 1;
            }
            if depth == 0 || (depth == 1 && matches!(x, "(" | "[" | "{")) {
                if seg_tokens == 0 {
                    first_is_ident = t.k == K::Ident;
                }
                if seg_tokens == 1 && x == "." {
                    // qualified type: pkg.Type is one part
                    seg_tokens = 0;
                    j += 2;
                    seg_tokens = 1;
                    continue;
                }
                seg_tokens += 1;
            }
            j += 1;
        }
    }

    // ---------- types ----------
    fn ty(&mut self) {
        let m = self.b.mark();
        let t = self.tok(0);
        let tx = self.tx();
        match tx {
            "*" => {
                self.bump();
                self.ty();
                self.b.wrap(m, "pointer_type", true);
            }
            "[" => {
                self.bump();
                if self.at("]") {
                    self.bump();
                    self.ty();
                    self.b.field_last("element");
                    self.b.wrap(m, "slice_type", true);
                } else if self.at("...") {
                    self.bump();
                    self.expect("]");
                    self.ty();
                    self.b.field_last("element");
                    self.b.wrap(m, "implicit_length_array_type", true);
                } else {
                    self.expression();
                    self.b.field_last("length");
                    self.expect("]");
                    self.ty();
                    self.b.field_last("element");
                    self.b.wrap(m, "array_type", true);
                }
            }
            "map" => {
                self.bump();
                self.expect("[");
                self.ty();
                self.b.field_last("key");
                self.expect("]");
                self.ty();
                self.b.field_last("value");
                self.b.wrap(m, "map_type", true);
            }
            "chan" => {
                self.bump();
                if self.at("<-") {
                    self.bump();
                }
                self.ty();
                self.b.field_last("value");
                self.b.wrap(m, "channel_type", true);
            }
            "<-" if self.txn(1) == "chan" => {
                self.bump();
                self.bump();
                self.ty();
                self.b.field_last("value");
                self.b.wrap(m, "channel_type", true);
            }
            "func" => {
                self.bump();
                self.parameter_list();
                self.b.field_last("parameters");
                self.result_type_only();
                self.b.wrap(m, "function_type", true);
            }
            "struct" => {
                self.bump();
                self.field_declaration_list();
                self.b.wrap(m, "struct_type", true);
            }
            "interface" => {
                self.bump();
                self.interface_body();
                self.b.wrap(m, "interface_type", true);
            }
            "(" => {
                self.bump();
                self.ty();
                self.expect(")");
                self.b.wrap(m, "parenthesized_type", true);
            }
            _ => {
                if t.k == K::Ident {
                    if self.txn(1) == "." && self.tok(2).k == K::Ident {
                        self.bump_named("package_identifier");
                        self.b.field_last("package");
                        self.bump();
                        self.bump_named("type_identifier");
                        self.b.field_last("name");
                        self.b.wrap(m, "qualified_type", true);
                    } else {
                        self.bump_named("type_identifier");
                    }
                    if self.at("[") && self.txn(1) != "]" {
                        self.b.field_last("type");
                        self.type_arguments();
                        self.b.field_last("type_arguments");
                        self.b.wrap(m, "generic_type", true);
                    }
                } else {
                    let p = self.cur_pos();
                    self.b.missing("type_identifier", true, p);
                }
            }
        }
    }

    fn result_type_only(&mut self) {
        if self.at("(") {
            self.parameter_list();
            self.b.field_last("result");
        } else if self.tok(0).k == K::Ident && !matches!(self.tx(), "{") || matches!(self.tx(), "*" | "[" | "map" | "chan" | "func") {
            if self.k() == K::Ident || matches!(self.tx(), "*" | "[" | "map" | "chan" | "func") {
                self.ty();
                self.b.field_last("result");
            }
        }
    }

    fn type_arguments(&mut self) {
        let m = self.b.mark();
        self.bump(); // [
        while !self.at("]") && self.k() != K::Eof {
            let me = self.b.mark();
            self.constraint_elem();
            self.b.wrap(me, "type_elem", true);
            if !self.eat(",") {
                break;
            }
        }
        self.expect("]");
        self.b.wrap(m, "type_arguments", true);
    }

    fn field_declaration_list(&mut self) {
        let m = self.b.mark();
        self.expect("{");
        loop {
            self.skip_nl_hidden();
            if self.at("}") || self.k() == K::Eof {
                break;
            }
            let mf = self.b.mark();
            let embedded = self.at("*")
                || (self.k() == K::Ident && (matches!(self.txn(1), "" | ";" | "}") || self.tok(1).k == K::Str || self.tok(1).k == K::RawStr || (self.txn(1) == "." && matches!(self.txn(3), "" | ";" | "}"))));
            if embedded {
                if self.at("*") {
                    let mp = self.b.mark();
                    self.bump();
                    self.ty();
                    self.b.wrap(mp, "pointer_type", true);
                } else {
                    self.ty();
                }
                self.b.field_last("type");
            } else {
                loop {
                    self.bump_named("field_identifier");
                    self.b.field_last("name");
                    if !self.eat(",") {
                        break;
                    }
                }
                self.ty();
                self.b.field_last("type");
            }
            if self.k() == K::Str || self.k() == K::RawStr {
                self.string_lit();
                self.b.field_last("tag");
            }
            self.b.wrap(mf, "field_declaration", true);
            if self.at(";") {
                self.bump();
            } else if self.k() == K::NL {
                self.nl();
            } else {
                if !self.at("}") {
                    self.error_token();
                }
            }
        }
        self.expect("}");
        self.b.wrap(m, "field_declaration_list", true);
    }

    fn interface_body(&mut self) {
        self.expect("{");
        loop {
            self.skip_nl_hidden();
            if self.at("}") || self.k() == K::Eof {
                break;
            }
            let me = self.b.mark();
            if self.k() == K::Ident && self.txn(1) == "(" {
                self.bump_named("field_identifier");
                self.b.field_last("name");
                self.parameter_list();
                self.b.field_last("parameters");
                self.result_type_only();
                self.b.wrap(me, "method_elem", true);
            } else {
                self.constraint_elem();
                self.b.wrap(me, "type_elem", true);
            }
            if self.at(";") {
                self.bump();
            } else if self.k() == K::NL {
                self.nl();
            } else if !self.at("}") {
                self.error_token();
            }
        }
        self.expect("}");
    }

    // ---------- statements ----------
    fn block(&mut self) {
        let m = self.b.mark();
        self.expect("{");
        self.statement_list_until(&["}"]);
        self.expect("}");
        self.b.wrap(m, "block", true);
    }

    fn statement_list_until(&mut self, ends: &[&str]) {
        self.skip_nl_hidden_before_list();
        let ml = self.b.mark();
        let mut any = false;
        loop {
            if ends.iter().any(|e| self.at(e)) || self.k() == K::Eof {
                break;
            }
            if self.k() == K::NL {
                if any {
                    self.nl();
                } else {
                    self.nl();
                }
                continue;
            }
            let before = self.i;
            self.statement();
            if self.i == before {
                self.error_token();
                continue;
            }
            any = true;
            if self.at(";") {
                self.bump();
            } else if self.k() == K::NL {
                self.nl();
            }
        }
        if any {
            // statement_list excludes leading hidden newlines
            self.b.wrap(ml, "statement_list", true);
            // trim leading hidden tokens: tree-sitter list starts at first statement
            let id = self.b.last().unwrap() as usize;
            let ch = self.b.nodes[id].children.clone();
            let mut k = 0;
            while k < ch.len() && self.b.nodes[ch[k] as usize].hidden {
                k += 1;
            }
            if k > 0 {
                let rest = ch[k..].to_vec();
                self.b.nodes[id].children = rest.clone();
                if let Some(&f) = rest.first() {
                    self.b.nodes[id].start = self.b.nodes[f as usize].start;
                }
            }
        }
    }

    fn skip_nl_hidden_before_list(&mut self) {
        // newlines right after '{' are not part of the statement list
        while self.k() == K::NL {
            let t = self.advance();
            let _ = t;
        }
    }

    fn simple_statement(&mut self) {
        let m = self.b.mark();
        let ml = self.b.mark();
        let n = self.expression_list_count();
        let tx = self.tx();
        match tx {
            ":=" => {
                self.wrap_list(ml, n, true);
                self.b.field_last("left");
                self.bump();
                if self.at("range") {
                    // only in for headers; caller handles
                }
                let mr = self.b.mark();
                let nr = self.expression_list_count();
                self.wrap_list(mr, nr, true);
                self.b.field_last("right");
                self.b.wrap(m, "short_var_declaration", true);
            }
            "=" | "+=" | "-=" | "*=" | "/=" | "%=" | "&=" | "|=" | "^=" | "<<=" | ">>=" | "&^=" => {
                self.wrap_list(ml, n, true);
                self.b.field_last("left");
                self.bump();
                self.b.field_last("operator");
                let mr = self.b.mark();
                let nr = self.expression_list_count();
                self.wrap_list(mr, nr, true);
                self.b.field_last("right");
                self.b.wrap(m, "assignment_statement", true);
            }
            "++" | "--" => {
                self.bump();
                self.b.wrap(m, if tx == "++" { "inc_statement" } else { "dec_statement" }, true);
            }
            "<-" if n == 1 => {
                self.b.field_last("channel");
                self.bump();
                self.expression();
                self.b.field_last("value");
                self.b.wrap(m, "send_statement", true);
            }
            _ => {
                if n > 1 {
                    self.b.wrap(ml, "expression_list", true);
                }
                self.b.wrap(m, "expression_statement", true);
            }
        }
    }

    fn wrap_list(&mut self, m: usize, _n: usize, always: bool) {
        if always {
            self.b.wrap(m, "expression_list", true);
        }
    }

    fn expression_list_count(&mut self) -> usize {
        let mut n = 0;
        loop {
            self.expression();
            n += 1;
            if !self.at(",") {
                break;
            }
            self.bump();
        }
        n
    }

    fn statement(&mut self) {
        let m = self.b.mark();
        let t = self.tok(0);
        let tx = self.tx();
        if t.k == K::Ident {
            match tx {
                "var" | "const" => return self.var_const(m, tx == "var"),
                "type" => return self.type_decl(m),
                "return" => {
                    self.bump();
                    if !self.at_terminator() {
                        let ml = self.b.mark();
                        self.expression_list_count();
                        self.b.wrap(ml, "expression_list", true);
                    }
                    self.b.wrap(m, "return_statement", true);
                    return;
                }
                "go" | "defer" => {
                    self.bump();
                    self.expression();
                    self.b.wrap(m, if tx == "go" { "go_statement" } else { "defer_statement" }, true);
                    return;
                }
                "if" => return self.if_stmt(m),
                "for" => return self.for_stmt(m),
                "switch" => return self.switch_stmt(m),
                "select" => return self.select_stmt(m),
                "break" | "continue" | "goto" => {
                    self.bump();
                    if self.k() == K::Ident {
                        self.bump_named("label_name");
                        if tx == "goto" {
                        }
                        self.b.field_last("label");
                    }
                    let k = match tx {
                        "break" => "break_statement",
                        "continue" => "continue_statement",
                        _ => "goto_statement",
                    };
                    self.b.wrap(m, k, true);
                    return;
                }
                "fallthrough" => {
                    self.bump();
                    self.b.wrap(m, "fallthrough_statement", true);
                    return;
                }
                "func" if self.tok(1).k == K::Ident => {
                    // nested func decl (invalid) - treat as decl
                    self.func_decl(m);
                    return;
                }
                _ => {
                    if self.txn(1) == ":" && !matches!(tx, "default" | "case") && self.txn(1) != ":=" {
                        self.bump_named("label_name");
                        self.b.field_last("label");
                        self.bump();
                        self.skip_nl_hidden();
                        if !self.at("}") {
                            self.statement();
                        }
                        self.b.wrap(m, "labeled_statement", true);
                        return;
                    }
                }
            }
        }
        if self.at("{") {
            self.block();
            return;
        }
        if self.at(";") {
            self.bump();
            self.b.wrap(m, "empty_statement", true);
            return;
        }
        self.simple_statement();
    }

    fn at_terminator(&self) -> bool {
        matches!(self.k(), K::NL | K::Eof) || self.at(";") || self.at("}") || self.at(")")
    }

    fn var_const(&mut self, m: usize, is_var: bool) {
        self.bump();
        let spec = if is_var { "var_spec" } else { "const_spec" };
        if self.at("(") {
            let ml = self.b.mark();
            self.bump();
            loop {
                self.skip_nl_hidden();
                if self.at(")") || self.k() == K::Eof {
                    break;
                }
                self.var_spec(spec, is_var);
                if self.at(";") {
                    self.bump();
                } else if self.k() == K::NL {
                    self.nl();
                } else if !self.at(")") {
                    self.error_token();
                }
            }
            self.expect(")");
            if is_var {
                self.b.wrap(ml, "var_spec_list", true);
            }
        } else {
            self.var_spec(spec, is_var);
        }
        self.b.wrap(m, if is_var { "var_declaration" } else { "const_declaration" }, true);
    }

    fn var_spec(&mut self, kind: &'static str, _is_var: bool) {
        let m = self.b.mark();
        loop {
            self.bump_named("identifier");
            self.b.field_last("name");
            if !self.eat(",") {
                break;
            }
        }
        if !self.at("=") && !self.at_terminator() {
            self.ty();
            self.b.field_last("type");
        }
        if self.eat("=") {
            let ml = self.b.mark();
            self.expression_list_count();
            self.b.wrap(ml, "expression_list", true);
            self.b.field_last("value");
        }
        self.b.wrap(m, kind, true);
    }

    fn type_decl(&mut self, m: usize) {
        self.bump(); // type
        if self.at("(") {
            self.bump();
            loop {
                self.skip_nl_hidden();
                if self.at(")") || self.k() == K::Eof {
                    break;
                }
                self.type_spec();
                if self.at(";") {
                    self.bump();
                } else if self.k() == K::NL {
                    self.nl();
                } else if !self.at(")") {
                    self.error_token();
                }
            }
            self.expect(")");
        } else {
            self.type_spec();
        }
        self.b.wrap(m, "type_declaration", true);
    }

    fn type_spec(&mut self) {
        let m = self.b.mark();
        self.bump_named("type_identifier");
        self.b.field_last("name");
        if self.at("[") && self.is_type_params() {
            self.type_parameter_list();
            self.b.field_last("type_parameters");
        }
        if self.eat("=") {
            self.ty();
            self.b.field_last("type");
            self.b.wrap(m, "type_alias", true);
            return;
        }
        self.ty();
        self.b.field_last("type");
        self.b.wrap(m, "type_spec", true);
    }

    fn is_type_params(&self) -> bool {
        // [T any] vs [5]int
        self.tok(1).k == K::Ident && !matches!(self.txn(2), "]")
    }

    fn header_simple_statement(&mut self) {
        let save = self.no_lit;
        self.no_lit = true;
        self.simple_statement();
        self.no_lit = save;
    }

    fn if_stmt(&mut self, m: usize) {
        self.bump(); // if
        let save = self.no_lit;
        self.no_lit = true;
        // initializer ; condition
        let ms = self.b.mark();
        self.simple_statement();
        if self.at(";") {
            self.b.field_last("initializer");
            self.bump();
            let mc = self.b.mark();
            self.expression();
            let _ = mc;
            self.b.field_last("condition");
        } else {
            // unwrap expression_statement into condition
            self.unwrap_expr_stmt(ms);
            self.b.field_last("condition");
        }
        self.no_lit = save;
        self.block();
        self.b.field_last("consequence");
        if self.at("else") {
            self.bump();
            if self.at("if") {
                let mi = self.b.mark();
                self.if_stmt(mi);
            } else {
                self.block();
            }
            self.b.field_last("alternative");
        }
        self.b.wrap(m, "if_statement", true);
    }

    fn unwrap_expr_stmt(&mut self, ms: usize) {
        if let Some(&id) = self.b.stack.get(ms) {
            if self.b.nodes[id as usize].kind == "expression_statement" {
                let ch = self.b.nodes[id as usize].children.clone();
                self.b.stack.truncate(ms);
                for c in ch {
                    self.b.stack.push(c);
                }
            }
        }
    }

    fn for_stmt(&mut self, m: usize) {
        self.bump(); // for
        let save = self.no_lit;
        self.no_lit = true;
        if self.at("{") {
            // infinite loop
        } else if self.at("range") {
            let mr = self.b.mark();
            self.bump();
            self.expression();
            self.b.field_last("right");
            self.b.wrap(mr, "range_clause", true);
        } else if self.at(";") {
            self.for_clause_from(self.b.mark(), true);
        } else {
            let mc = self.b.mark();
            // try range clause: list (:= | =) range expr
            let ml = self.b.mark();
            self.expression_list_count();
            if (self.at(":=") || self.at("=")) && self.txn(1) == "range" {
                self.b.wrap(ml, "expression_list", true);
                self.b.field_last("left");
                self.bump();
                self.bump();
                self.expression();
                self.b.field_last("right");
                self.b.wrap(mc, "range_clause", true);
            } else {
                // rewind and parse as simple statement
                self.b.stack.truncate(mc);
                // re-parse: simplest is to rewind token index
                self.rewind_to(mc);
                let ms = self.b.mark();
                self.simple_statement();
                if self.at(";") {
                    self.b.field_last("initializer");
                    self.for_clause_from(mc, false);
                } else {
                    self.unwrap_expr_stmt(ms);
                    self.b.field_last("condition");
                }
            }
        }
        self.no_lit = save;
        self.block();
        self.b.field_last("body");
        self.b.wrap(m, "for_statement", true);
    }

    fn rewind_to(&mut self, _mark: usize) {
        // find token index of the first token after 'for'
        // we stored nothing; approach: scan back to 'for' keyword position
        let mut j = self.i;
        while j > 0 {
            j -= 1;
            let t = self.toks[j];
            if t.k == K::Ident && &self.src[t.s..t.e] == "for" {
                self.i = j + 1;
                return;
            }
        }
    }

    fn for_clause_from(&mut self, mc: usize, empty_init: bool) {
        let _ = empty_init;
        self.expect(";");
        if !self.at(";") {
            self.expression();
            self.b.field_last("condition");
        }
        self.expect(";");
        if !self.at("{") {
            self.simple_statement();
            self.b.field_last("update");
        }
        self.b.wrap(mc, "for_clause", true);
    }

    fn switch_stmt(&mut self, m: usize) {
        self.bump(); // switch
        let save = self.no_lit;
        self.no_lit = true;
        let mut type_switch = false;
        // detect type switch: contains .(type) before {
        {
            let mut j = 0;
            loop {
                let x = self.txn(j);
                if self.tok(j).k == K::Eof || x == "{" {
                    break;
                }
                if x == "." && self.txn(j + 1) == "(" && self.txn(j + 2) == "type" {
                    type_switch = true;
                    break;
                }
                j += 1;
            }
        }
        if type_switch {
            // [alias :=] expr . ( type )
            if self.k() == K::Ident && self.txn(1) == ":=" {
                let ma = self.b.mark();
                self.bump_named("identifier");
                self.b.wrap(ma, "expression_list", true);
                self.b.field_last("alias");
                self.bump();
            } else if !self.at_type_assert_ahead() {
                // initializer statement
                self.simple_statement();
                self.b.field_last("initializer");
                self.expect(";");
                if self.k() == K::Ident && self.txn(1) == ":=" {
                    let ma = self.b.mark();
                    self.bump_named("identifier");
                    self.b.wrap(ma, "expression_list", true);
                    self.b.field_last("alias");
                    self.bump();
                }
            }
            let mv = self.b.mark();
            self.primary();
            self.postfix_from(mv, true);
            self.b.field_last("value");
            self.expect(".");
            self.expect("(");
            self.expect("type");
            self.expect(")");
        } else if !self.at("{") {
            let ms = self.b.mark();
            self.simple_statement();
            if self.at(";") {
                self.b.field_last("initializer");
                self.bump();
                if !self.at("{") {
                    self.expression();
                    self.b.field_last("value");
                }
            } else {
                self.unwrap_expr_stmt(ms);
                self.b.field_last("value");
            }
        }
        self.no_lit = save;
        self.expect("{");
        loop {
            self.skip_nl_hidden();
            if self.at("}") || self.k() == K::Eof {
                break;
            }
            let mc = self.b.mark();
            if self.at("case") {
                self.bump();
                if type_switch {
                    loop {
                        self.ty();
                        self.b.field_last("type");
                        if self.at(",") {
                            self.bump();
                            self.b.field_last("type");
                            continue;
                        }
                        break;
                    }
                } else {
                    let ml = self.b.mark();
                    self.expression_list_count();
                    self.b.wrap(ml, "expression_list", true);
                    self.b.field_last("value");
                }
                self.expect(":");
                self.statement_list_until(&["case", "default", "}"]);
                self.b.wrap(mc, if type_switch { "type_case" } else { "expression_case" }, true);
            } else if self.at("default") {
                self.bump();
                self.expect(":");
                self.statement_list_until(&["case", "default", "}"]);
                self.b.wrap(mc, "default_case", true);
            } else {
                self.error_token();
            }
        }
        self.expect("}");
        self.b.wrap(m, if type_switch { "type_switch_statement" } else { "expression_switch_statement" }, true);
    }

    fn at_type_assert_ahead(&self) -> bool {
        // expression directly followed by .(type) without ';'
        let mut j = 0;
        loop {
            let x = self.txn(j);
            if self.tok(j).k == K::Eof || x == "{" {
                return true;
            }
            if x == ";" {
                return false;
            }
            if x == "." && self.txn(j + 1) == "(" && self.txn(j + 2) == "type" {
                return true;
            }
            j += 1;
        }
    }

    fn select_stmt(&mut self, m: usize) {
        self.bump(); // select
        self.expect("{");
        loop {
            self.skip_nl_hidden();
            if self.at("}") || self.k() == K::Eof {
                break;
            }
            let mc = self.b.mark();
            if self.at("case") {
                self.bump();
                // send or receive
                let ms = self.b.mark();
                let ml = self.b.mark();
                let n = self.expression_list_count();
                if self.at("<-") {
                    self.b.field_last("channel");
                    self.bump();
                    self.expression();
                    self.b.field_last("value");
                    self.b.wrap(ms, "send_statement", true);
                } else if self.at(":=") || self.at("=") {
                    self.b.wrap(ml, "expression_list", true);
                    self.b.field_last("left");
                    self.bump();
                    self.expression();
                    self.b.field_last("right");
                    self.b.wrap(ms, "receive_statement", true);
                } else {
                    let _ = n;
                    self.b.wrap(ms, "receive_statement", true);
                }
                self.b.field_last("communication");
                self.expect(":");
                self.statement_list_until(&["case", "default", "}"]);
                self.b.wrap(mc, "communication_case", true);
            } else if self.at("default") {
                self.bump();
                self.expect(":");
                self.statement_list_until(&["case", "default", "}"]);
                self.b.wrap(mc, "default_case", true);
            } else {
                self.error_token();
            }
        }
        self.expect("}");
        self.b.wrap(m, "select_statement", true);
    }

    // ---------- expressions ----------
    fn expression(&mut self) {
        self.depth += 1;
        if self.depth > 300 {
            self.error_token();
            self.depth -= 1;
            return;
        }
        self.binary(1);
        self.depth -= 1;
    }

    fn binop(&self) -> Option<u8> {
        let t = self.tok(0);
        if t.k != K::Op {
            return None;
        }
        Some(match self.tx() {
            "||" => 1,
            "&&" => 2,
            "==" | "!=" | "<" | "<=" | ">" | ">=" => 3,
            "+" | "-" | "|" | "^" => 4,
            "*" | "/" | "%" | "<<" | ">>" | "&" | "&^" => 5,
            _ => return None,
        })
    }

    fn binary(&mut self, min: u8) {
        let m = self.b.mark();
        self.unary();
        loop {
            let Some(p) = self.binop() else { break };
            if p < min {
                break;
            }
            self.b.field_last("left");
            self.bump();
            self.b.field_last("operator");
            self.skip_nl_hidden();
            self.binary(p + 1);
            self.b.field_last("right");
            self.b.wrap(m, "binary_expression", true);
        }
    }

    fn unary(&mut self) {
        let m = self.b.mark();
        if self.k() == K::Op && matches!(self.tx(), "+" | "-" | "!" | "^" | "*" | "&" | "<-") {
            if self.at("<-") && self.txn(1) == "chan" {
                self.postfix();
                return;
            }
            self.bump();
            self.b.field_last("operator");
            self.unary();
            self.b.field_last("operand");
            self.b.wrap(m, "unary_expression", true);
            return;
        }
        self.postfix();
    }

    fn postfix(&mut self) {
        let m = self.b.mark();
        self.primary();
        self.postfix_from(m, false);
    }

    fn postfix_from(&mut self, m: usize, stop_at_type_assert: bool) {
        loop {
            let tx = self.tx();
            match tx {
                "." => {
                    if self.txn(1) == "(" {
                        if self.txn(2) == "type" && stop_at_type_assert {
                            break;
                        }
                        if self.txn(2) == "type" {
                            break;
                        }
                        self.set_field_first(m, "operand");
                        self.bump();
                        self.bump();
                        self.ty();
                        self.b.field_last("type");
                        self.expect(")");
                        self.b.wrap(m, "type_assertion_expression", true);
                        continue;
                    }
                    self.set_field_first(m, "operand");
                    self.bump();
                    self.skip_nl_hidden();
                    self.bump_named("field_identifier");
                    self.b.field_last("field");
                    self.b.wrap(m, "selector_expression", true);
                }
                "(" => {
                    self.set_field_first(m, "function");
                    self.argument_list();
                    self.b.field_last("arguments");
                    self.b.wrap(m, "call_expression", true);
                }
                "[" => {
                    self.set_field_first(m, "operand");
                    self.bump();
                    let save = self.no_lit;
                    self.no_lit = false;
                    // slice or index or type args
                    if self.at(":") {
                        self.slice_rest(m);
                    } else {
                        let mi = self.b.mark();
                        self.expression();
                        if self.at(":") {
                            self.b.field_last("start");
                            self.slice_rest(m);
                        } else if self.at(",") {
                            // type instantiation f[A, B]
                            let _ = mi;
                            while self.eat(",") {
                                self.ty();
                            }
                            self.expect("]");
                            self.b.wrap(m, "index_expression", true);
                        } else {
                            self.b.field_last("index");
                            self.expect("]");
                            self.b.wrap(m, "index_expression", true);
                        }
                    }
                    self.no_lit = save;
                }
                "{" if !self.no_lit && self.is_composite_type(m) => {
                    self.set_field_first(m, "type");
                    self.convert_to_type(m);
                    self.literal_value();
                    self.b.field_last("body");
                    self.b.wrap(m, "composite_literal", true);
                }
                _ => break,
            }
        }
    }

    fn slice_rest(&mut self, m: usize) {
        self.bump(); // :
        if !self.at("]") && !self.at(":") {
            self.expression();
            self.b.field_last("end");
        }
        if self.eat(":") {
            self.expression();
            self.b.field_last("capacity");
        }
        self.expect("]");
        self.b.wrap(m, "slice_expression", true);
    }

    fn is_composite_type(&self, m: usize) -> bool {
        if self.b.stack.len() != m + 1 {
            return false;
        }
        let id = self.b.stack[m];
        let k = self.b.nodes[id as usize].kind;
        matches!(k, "identifier" | "selector_expression" | "index_expression" | "generic_type" | "qualified_type")
    }

    fn convert_to_type(&mut self, m: usize) {
        let id = self.b.stack[m] as usize;
        match self.b.nodes[id].kind {
            "identifier" => self.b.nodes[id].kind = "type_identifier",
            "selector_expression" => {
                let ch = self.b.nodes[id].children.clone();
                if ch.len() == 3 && self.b.nodes[ch[0] as usize].kind == "identifier" {
                    self.b.nodes[ch[0] as usize].kind = "package_identifier";
                    self.b.nodes[ch[0] as usize].field = Some("package");
                    self.b.nodes[ch[2] as usize].kind = "type_identifier";
                    self.b.nodes[ch[2] as usize].field = Some("name");
                    self.b.nodes[id].kind = "qualified_type";
                }
            }
            "index_expression" => {
                // generic type
                let ch = self.b.nodes[id].children.clone();
                if let Some(&f) = ch.first() {
                    if self.b.nodes[f as usize].kind == "identifier" {
                        self.b.nodes[f as usize].kind = "type_identifier";
                    }
                    self.b.nodes[f as usize].field = Some("type");
                }
                // wrap [ ... ] into type_arguments
                if ch.len() >= 3 {
                    let args: Vec<u32> = ch[1..].to_vec();
                    let s = self.b.nodes[args[0] as usize].start;
                    let e = self.b.nodes[*args.last().unwrap() as usize].end;
                    for &a in &args {
                        let ak = self.b.nodes[a as usize].kind;
                        if self.b.nodes[a as usize].named {
                            self.b.nodes[a as usize].field = None;
                            if ak == "identifier" {
                                self.b.nodes[a as usize].kind = "type_identifier";
                            }
                        }
                    }
                    let ta = self.b.nodes.len() as u32;
                    self.b.nodes.push(crate::tree::RawNode {
                        kind: "type_arguments",
                        named: true,
                        extra: false,
                        hidden: false,
                        missing: false,
                        field: Some("type_arguments"),
                        start: s,
                        end: e,
                        children: args,
                    });
                    self.b.nodes[id].children = vec![ch[0], ta];
                }
                self.b.nodes[id].kind = "generic_type";
            }
            _ => {}
        }
    }

    fn argument_list(&mut self) {
        let m = self.b.mark();
        self.bump(); // (
        let save = self.no_lit;
        self.no_lit = false;
        self.skip_nl_hidden();
        while !self.at(")") && self.k() != K::Eof {
            let ma = self.b.mark();
            if self.is_type_arg_start() {
                self.ty();
            } else {
                self.expression();
            }
            if self.at("...") {
                self.bump();
                self.b.wrap(ma, "variadic_argument", true);
            }
            self.skip_nl_hidden();
            if !self.eat(",") {
                break;
            }
            self.skip_nl_hidden();
        }
        self.no_lit = save;
        self.expect(")");
        self.b.wrap(m, "argument_list", true);
    }

    fn is_type_arg_start(&self) -> bool {
        // types as arguments: make([]int, n), new(T)
        match self.tx() {
            "[" => self.txn(1) == "]" || self.txn(1) == "...",
            "map" | "chan" | "struct" | "interface" => true,
            "func" => false,
            _ => false,
        }
    }

    fn literal_value(&mut self) {
        let m = self.b.mark();
        self.bump(); // {
        let save = self.no_lit;
        self.no_lit = false;
        loop {
            self.skip_nl_hidden();
            if self.at("}") || self.k() == K::Eof {
                break;
            }
            let me = self.b.mark();
            self.literal_element();
            if self.at(":") {
                self.b.field_last("key");
                self.bump();
                self.skip_nl_hidden();
                self.literal_element();
                self.b.field_last("value");
                self.b.wrap(me, "keyed_element", true);
            }
            self.skip_nl_hidden();
            if !self.eat(",") {
                break;
            }
        }
        self.skip_nl_hidden();
        self.no_lit = save;
        self.expect("}");
        self.b.wrap(m, "literal_value", true);
    }

    fn literal_element(&mut self) {
        let m = self.b.mark();
        if self.at("{") {
            self.literal_value();
        } else {
            self.expression();
        }
        self.b.wrap(m, "literal_element", true);
    }

    fn string_lit(&mut self) {
        let t = self.tok(0);
        if t.k == K::RawStr {
            let t = self.advance();
            let m = self.b.mark();
            self.b.leaf("`", false, t.s, t.s + 1);
            if t.e > t.s + 2 {
                self.b.leaf("raw_string_literal_content", true, t.s + 1, t.e - 1);
            }
            if t.e > t.s + 1 {
                self.b.leaf("`", false, t.e - 1, t.e);
            }
            self.b.wrap(m, "raw_string_literal", true);
            return;
        }
        if t.k != K::Str {
            let p = self.cur_pos();
            self.b.missing("interpreted_string_literal", true, p);
            return;
        }
        let t = self.advance();
        let m = self.b.mark();
        let b = self.src.as_bytes();
        self.b.leaf("\"", false, t.s, t.s + 1);
        let close = t.e > t.s + 1 && b[t.e - 1] == b'"';
        let ce = if close { t.e - 1 } else { t.e };
        let mut i = t.s + 1;
        let mut cs = i;
        while i < ce {
            if b[i] == b'\\' {
                if cs < i {
                    self.b.leaf("interpreted_string_literal_content", true, cs, i);
                }
                let mut k = i + 1;
                if k < ce {
                    match b[k] {
                        b'x' => k += 3,
                        b'u' => k += 5,
                        b'U' => k += 9,
                        b'0'..=b'7' => k += 3,
                        _ => k += 1,
                    }
                }
                let k = k.min(ce);
                self.b.leaf("escape_sequence", true, i, k);
                i = k;
                cs = i;
            } else {
                i += 1;
            }
        }
        if cs < ce {
            self.b.leaf("interpreted_string_literal_content", true, cs, ce);
        }
        if close {
            self.b.leaf("\"", false, t.e - 1, t.e);
        }
        self.b.wrap(m, "interpreted_string_literal", true);
    }

    fn primary(&mut self) {
        let m = self.b.mark();
        let t = self.tok(0);
        let tx = self.tx();
        match t.k {
            K::Int => {
                self.bump_named("int_literal");
            }
            K::Float => {
                self.bump_named("float_literal");
            }
            K::Imag => {
                self.bump_named("imaginary_literal");
            }
            K::Rune => {
                self.bump_named("rune_literal");
            }
            K::Str | K::RawStr => self.string_lit(),
            K::Ident => match tx {
                "nil" => {
                    self.bump_named("nil");
                }
                "true" => {
                    self.bump_named("true");
                }
                "false" => {
                    self.bump_named("false");
                }
                "iota" => {
                    self.bump_named("iota");
                }
                "func" => {
                    self.bump();
                    self.parameter_list();
                    self.b.field_last("parameters");
                    if !self.at("{") {
                        self.result_type_only();
                    }
                    if self.at("{") {
                        let save = self.no_lit;
                        self.no_lit = false;
                        self.block();
                        self.no_lit = save;
                        self.b.field_last("body");
                        self.b.wrap(m, "func_literal", true);
                    } else {
                        self.b.wrap(m, "function_type", true);
                    }
                }
                "map" | "chan" | "struct" | "interface" => {
                    self.ty();
                    if self.at("{") && tx != "interface" {
                        self.b.field_last("type");
                        self.literal_value();
                        self.b.field_last("body");
                        self.b.wrap(m, "composite_literal", true);
                    } else if self.at("(") {
                        self.b.field_last("type");
                        self.bump();
                        self.expression();
                        self.b.field_last("operand");
                        self.eat(",");
                        self.expect(")");
                        self.b.wrap(m, "type_conversion_expression", true);
                    }
                }
                _ => {
                    self.bump_named("identifier");
                }
            },
            K::Op => match tx {
                "(" => {
                    self.bump();
                    let save = self.no_lit;
                    self.no_lit = false;
                    self.expression();
                    self.no_lit = save;
                    self.expect(")");
                    self.b.wrap(m, "parenthesized_expression", true);
                }
                "[" => {
                    self.ty();
                    if self.at("{") {
                        self.b.field_last("type");
                        self.literal_value();
                        self.b.field_last("body");
                        self.b.wrap(m, "composite_literal", true);
                    } else if self.at("(") {
                        self.b.field_last("type");
                        self.bump();
                        self.expression();
                        self.b.field_last("operand");
                        self.eat(",");
                        self.expect(")");
                        self.b.wrap(m, "type_conversion_expression", true);
                    }
                }
                "*" => {
                    self.unary();
                }
                _ => self.error_token(),
            },
            _ => {
                let p = self.cur_pos();
                self.b.missing("identifier", true, p);
            }
        }
    }
}
