{"command":"cat > /workspace/src/lang/java.rs <<'EOF'
// Java parser producing tree-sitter-java compatible CST
use super::js::intern;
use crate::tree::{Builder, Tree};

#[derive(Clone, Copy, PartialEq, Debug)]
enum K {
    Ident,
    Num,
    Str,
    TextBlock,
    Char,
    Op,
    LineComment,
    BlockComment,
    Eof,
}

#[derive(Clone, Copy, Debug)]
struct Tk {
    k: K,
    s: usize,
    e: usize,
}

const OPS: &[&str] = &[
    ">>>=", "<<=", ">>=", "...", "->", "::", "++", "--", "&&", "||", "==", "!=", "<=", "+=", "-=", "*=", "/=", "%=",
    "&=", "|=", "^=", "<<",
];

const MODIFIERS: &[&str] = &[
    "public", "private", "protected", "static", "final", "abstract", "synchronized", "native", "transient", "volatile",
    "strictfp", "default", "sealed", "non-sealed",
];

fn tokenize(src: &str) -> Vec<Tk> {
    let b = src.as_bytes();
    let n = b.len();
    let mut out = Vec::new();
    let mut i = 0;
    while i < n {
        let c = b[i];
        if c.is_ascii_whitespace() {
            i += 1;
            continue;
        }
        if c == b'/' && i + 1 < n && b[i + 1] == b'/' {
            let s = i;
            while i < n && b[i] != b'\n' {
                i += 1;
            }
            let mut e = i;
            if e > s && b[e - 1] == b'\r' {
                e -= 1;
            }
            out.push(Tk { k: K::LineComment, s, e });
            continue;
        }
        if c == b'/' && i + 1 < n && b[i + 1] == b'*' {
            let s = i;
            i += 2;
            while i < n && !(b[i] == b'*' && i + 1 < n && b[i + 1] == b'/') {
                i += 1;
            }
            i = (i + 2).min(n);
            out.push(Tk { k: K::BlockComment, s, e: i });
            continue;
        }
        let s = i;
        if c == b'"' {
            if i + 2 < n && b[i + 1] == b'"' && b[i + 2] == b'"' {
                let mut k = i + 3;
                while k < n && !(b[k] == b'"' && k + 2 < n && b[k + 1] == b'"' && b[k + 2] == b'"') {
                    if b[k] == b'\\' {
                        k += 1;
                    }
                    k += 1;
                }
                i = (k + 3).min(n);
                out.push(Tk { k: K::TextBlock, s, e: i });
                continue;
            }
            let mut k = i + 1;
            while k < n && b[k] != b'"' && b[k] != b'\n' {
                if b[k] == b'\\' {
                    k += 1;
                }
                k += 1;
            }
            i = (k + 1).min(n);
            out.push(Tk { k: K::Str, s, e: i });
            continue;
        }
        if c == b'\'' {
            let mut k = i + 1;
            while k < n && b[k] != b'\'' && b[k] != b'\n' {
                if b[k] == b'\\' {
                    k += 1;
                }
                k += 1;
            }
            i = (k + 1).min(n);
            out.push(Tk { k: K::Char, s, e: i });
            continue;
        }
        if c.is_ascii_digit() || (c == b'.' && i + 1 < n && b[i + 1].is_ascii_digit()) {
            let mut k = i;
            if c == b'0' && k + 1 < n && matches!(b[k + 1], b'x' | b'X' | b'b' | b'B') {
                k += 2;
                while k < n && (b[k].is_ascii_hexdigit() || b[k] == b'_' || b[k] == b'.' || ((b[k] == b'p' || b[k] == b'P') && { k += 0; true })) {
                    if (b[k] == b'p' || b[k] == b'P') && k + 1 < n && (b[k + 1] == b'-' || b[k + 1] == b'+') {
                        k += 1;
                    }
                    k += 1;
                }
            } else {
                while k < n && (b[k].is_ascii_digit() || b[k] == b'_') {
                    k += 1;
                }
                if k < n && b[k] == b'.' && !(k + 1 < n && b[k + 1].is_ascii_alphabetic() && !matches!(b[k + 1], b'e' | b'E' | b'f' | b'F' | b'd' | b'D')) {
                    k += 1;
                    while k < n && (b[k].is_ascii_digit() || b[k] == b'_') {
                        k += 1;
                    }
                }
                if k < n && (b[k] == b'e' || b[k] == b'E') {
                    k += 1;
                    if k < n && (b[k] == b'+' || b[k] == b'-') {
                        k += 1;
                    }
                    while k < n && b[k].is_ascii_digit() {
                        k += 1;
                    }
                }
            }
            if k < n && matches!(b[k], b'l' | b'L' | b'f' | b'F' | b'd' | b'D') {
                k += 1;
            }
            i = k;
            out.push(Tk { k: K::Num, s, e: i });
            continue;
        }
        let ch = src[i..].chars().next().unwrap();
        if ch == '_' || ch == '$' || ch.is_alphabetic() {
            let mut e = i;
            for (o, c2) in src[i..].char_indices() {
                if !(c2 == '_' || c2 == '$' || c2.is_alphanumeric()) {
                    e = i + o;
                    break;
                }
                e = i + o + c2.len_utf8();
            }
            // non-sealed
            if &src[i..e] == "non" && src[e..].starts_with("-sealed") {
                e += 7;
            }
            i = e;
            out.push(Tk { k: K::Ident, s, e: i });
            continue;
        }
        let r = &src[i..];
        let mut l = ch.len_utf8();
        for o in OPS {
            if r.starts_with(o) {
                l = o.len();
                break;
            }
        }
        i += l;
        out.push(Tk { k: K::Op, s, e: i });
    }
    out.push(Tk { k: K::Eof, s: n, e: n });
    out
}

struct P<'a> {
    src: &'a str,
    toks: Vec<Tk>,
    i: usize,
    b: Builder,
    depth: usize,
}

pub fn parse(src: &str) -> Tree {
    let toks = tokenize(src);
    let mut p = P { src, toks, i: 0, b: Builder::new(), depth: 0 };
    let m = p.b.mark();
    loop {
        if p.k() == K::Eof {
            break;
        }
        let before = p.i;
        p.top_statement();
        if p.i == before {
            p.error_token();
        }
    }
    p.flush_extras();
    let start = p.b.stack[m..].first().map(|&c| p.b.nodes[c as usize].start).unwrap_or(src.len() - src.trim_start().len());
    let root = p.b.wrap_all(m, "program", start, src.len());
    p.b.finish(root, src)
}

impl<'a> P<'a> {
    fn idx(&self, n: usize) -> usize {
        let mut j = self.i;
        let mut c = 0;
        loop {
            while j < self.toks.len() && matches!(self.toks[j].k, K::LineComment | K::BlockComment) {
                j += 1;
            }
            if j >= self.toks.len() {
                return self.toks.len() - 1;
            }
            if c == n {
                return j;
            }
            c += 1;
            j += 1;
        }
    }
    fn tok(&self, n: usize) -> Tk {
        self.toks[self.idx(n)]
    }
    fn k(&self) -> K {
        self.tok(0).k
    }
    fn txn(&self, n: usize) -> &'a str {
        let t = self.tok(n);
        if t.k == K::Eof {
            return "";
        }
        &self.src[t.s..t.e]
    }
    fn tx(&self) -> &'a str {
        self.txn(0)
    }
    fn at(&self, s: &str) -> bool {
        let t = self.tok(0);
        matches!(t.k, K::Op | K::Ident) && &self.src[t.s..t.e] == s
    }
    fn adjacent(&self, n: usize) -> bool {
        self.tok(n).e == self.tok(n + 1).s
    }
    fn flush_extras(&mut self) {
        while self.i < self.toks.len() && matches!(self.toks[self.i].k, K::LineComment | K::BlockComment) {
            let t = self.toks[self.i];
            self.b.extra(if t.k == K::LineComment { "line_comment" } else { "block_comment" }, t.s, t.e);
            self.i += 1;
        }
    }
    fn advance(&mut self) -> Tk {
        self.flush_extras();
        let t = self.toks[self.i];
        if t.k != K::Eof {
            self.i += 1;
        }
        t
    }
    fn bump(&mut self) -> u32 {
        let t = self.advance();
        let k = intern(&self.src[t.s..t.e]);
        self.b.leaf(k, false, t.s, t.e)
    }
    fn bump_named(&mut self, kind: &'static str) -> u32 {
        let t = self.advance();
        self.b.leaf(kind, true, t.s, t.e)
    }
    fn bump_join(&mut self, n: usize) -> u32 {
        let first = self.advance();
        let mut e = first.e;
        for _ in 1..n {
            e = self.advance().e;
        }
        let k = intern(&self.src[first.s..e]);
        self.b.leaf(k, false, first.s, e)
    }
    fn wrap_kw(&mut self, kind: &'static str) {
        let m = self.b.mark();
        self.bump();
        self.b.wrap(m, kind, true);
    }
    fn eat(&mut self, s: &str) -> bool {
        if self.at(s) {
            self.bump();
            true
        } else {
            false
        }
    }
    fn cur_pos(&self) -> usize {
        self.b.last().map(|l| self.b.nodes[l as usize].end).unwrap_or(0)
    }
    fn expect(&mut self, s: &str) {
        if !self.eat(s) {
            let p = self.cur_pos();
            self.b.missing(intern(s), false, p);
        }
    }
    fn error_token(&mut self) {
        if self.k() == K::Eof {
            return;
        }
        let m = self.b.mark();
        if self.k() == K::Ident {
            self.bump_named("identifier");
        } else {
            self.bump();
        }
        self.b.wrap(m, "ERROR", true);
    }
    fn set_field_first(&mut self, m: usize, f: &'static str) {
        for i in m..self.b.stack.len() {
            let id = self.b.stack[i] as usize;
            if !self.b.nodes[id].extra {
                self.b.nodes[id].field = Some(f);
                return;
            }
        }
    }

    // ---------- declarations ----------
    fn top_statement(&mut self) {
        let m = self.b.mark();
        match self.tx() {
            "package" if self.tok(1).k == K::Ident => {
                self.bump();
                self.name_expr();
                self.expect(";");
                self.b.wrap(m, "package_declaration", true);
            }
            "import" if self.tok(1).k == K::Ident => {
                self.bump();
                self.eat("static");
                let mn = self.b.mark();
                self.bump_named("identifier");
                while self.at(".") && self.tok(1).k == K::Ident {
                    self.set_field_first(mn, "scope");
                    self.bump();
                    self.bump_named("identifier");
                    self.b.field_last("name");
                    self.b.wrap(mn, "scoped_identifier", true);
                }
                if self.at(".") && self.txn(1) == "*" {
                    self.bump();
                    self.wrap_kw("asterisk");
                }
                self.expect(";");
                self.b.wrap(m, "import_declaration", true);
            }
            _ => self.statement(),
        }
    }

    fn name_expr(&mut self) {
        let m = self.b.mark();
        self.bump_named("identifier");
        while self.at(".") && self.tok(1).k == K::Ident {
            self.set_field_first(m, "scope");
            self.bump();
            self.bump_named("identifier");
            self.b.field_last("name");
            self.b.wrap(m, "scoped_identifier", true);
        }
    }

    fn is_modifier_start(&self) -> bool {
        let tx = self.tx();
        (self.k() == K::Ident && MODIFIERS.contains(&tx) && !(tx == "default" && self.txn(1) == ":")
            && !(tx == "default" && self.txn(1) == "->"))
            || (self.at("@") && self.txn(1) != "interface")
    }

    fn modifiers(&mut self) -> bool {
        if !self.is_modifier_start() {
            return false;
        }
        let m = self.b.mark();
        while self.is_modifier_start() {
            if self.at("@") {
                self.annotation();
            } else {
                self.bump();
            }
        }
        self.b.wrap(m, "modifiers", true);
        true
    }

    fn annotation(&mut self) {
        let m = self.b.mark();
        self.bump(); // @
        self.name_expr();
        self.b.field_last("name");
        if self.at("(") {
            let ma = self.b.mark();
            self.bump();
            while !self.at(")") && self.k() != K::Eof {
                if self.k() == K::Ident && self.txn(1) == "=" {
                    let mp = self.b.mark();
                    self.bump_named("identifier");
                    self.b.field_last("key");
                    self.bump();
                    self.element_value();
                    self.b.field_last("value");
                    self.b.wrap(mp, "element_value_pair", true);
                } else {
                    self.element_value();
                }
                if !self.eat(",") {
                    break;
                }
            }
            self.expect(")");
            self.b.wrap(ma, "annotation_argument_list", true);
            self.b.field_last("arguments");
            self.b.wrap(m, "annotation", true);
        } else {
            self.b.wrap(m, "marker_annotation", true);
        }
    }

    fn element_value(&mut self) {
        if self.at("{") {
            let m = self.b.mark();
            self.bump();
            while !self.at("}") && self.k() != K::Eof {
                self.element_value();
                if !self.eat(",") {
                    break;
                }
            }
            self.expect("}");
            self.b.wrap(m, "element_value_array_initializer", true);
        } else if self.at("@") {
            self.annotation();
        } else {
            self.expression();
        }
    }

    /// try to parse a class-like declaration after modifiers
    fn type_declaration(&mut self, m: usize) -> bool {
        match self.tx() {
            "class" => {
                self.bump();
                self.bump_named("identifier");
                self.b.field_last("name");
                if self.at("<") {
                    self.type_parameters();
                    self.b.field_last("type_parameters");
                }
                if self.at("extends") {
                    let ms = self.b.mark();
                    self.bump();
                    self.ty();
                    self.b.wrap(ms, "superclass", true);
                    self.b.field_last("superclass");
                }
                if self.at("implements") {
                    let ms = self.b.mark();
                    self.bump();
                    self.type_list();
                    self.b.wrap(ms, "super_interfaces", true);
                    self.b.field_last("interfaces");
                }
                if self.at("permits") {
                    let ms = self.b.mark();
                    self.bump();
                    self.type_list();
                    self.b.wrap(ms, "permits", true);
                    self.b.field_last("permits");
                }
                self.class_body();
                self.b.field_last("body");
                self.b.wrap(m, "class_declaration", true);
                true
            }
            "interface" => {
                self.bump();
                self.bump_named("identifier");
                self.b.field_last("name");
                if self.at("<") {
                    self.type_parameters();
                    self.b.field_last("type_parameters");
                }
                if self.at("extends") {
                    let ms = self.b.mark();
                    self.bump();
                    self.type_list();
                    self.b.wrap(ms, "extends_interfaces", true);
                }
                if self.at("permits") {
                    let ms = self.b.mark();
                    self.bump();
                    self.type_list();
                    self.b.wrap(ms, "permits", true);
                    self.b.field_last("permits");
                }
                self.class_body_kind("interface_body");
                self.b.field_last("body");
                self.b.wrap(m, "interface_declaration", true);
                true
            }
            "@" if self.txn(1) == "interface" => {
                self.bump();
                self.bump();
                self.bump_named("identifier");
                self.b.field_last("name");
                self.class_body_kind("annotation_type_body");
                self.b.field_last("body");
                self.b.wrap(m, "annotation_type_declaration", true);
                true
            }
            "enum" if self.tok(1).k == K::Ident => {
                self.bump();
                self.bump_named("identifier");
                self.b.field_last("name");
                if self.at("implements") {
                    let ms = self.b.mark();
                    self.bump();
                    self.type_list();
                    self.b.wrap(ms, "super_interfaces", true);
                    self.b.field_last("interfaces");
                }
                self.enum_body();
                self.b.field_last("body");
                self.b.wrap(m, "enum_declaration", true);
                true
            }
            "record" if self.tok(1).k == K::Ident && matches!(self.txn(2), "(" | "<") => {
                self.bump();
                self.bump_named("identifier");
                self.b.field_last("name");
                if self.at("<") {
                    self.type_parameters();
                    self.b.field_last("type_parameters");
                }
                self.formal_parameters();
                self.b.field_last("parameters");
                if self.at("implements") {
                    let ms = self.b.mark();
                    self.bump();
                    self.type_list();
                    self.b.wrap(ms, "super_interfaces", true);
                    self.b.field_last("interfaces");
                }
                self.class_body();
                self.b.field_last("body");
                self.b.wrap(m, "record_declaration", true);
                true
            }
            _ => false,
        }
    }

    fn type_list(&mut self) {
        let m = self.b.mark();
        loop {
            self.ty();
            if !self.eat(",") {
                break;
            }
        }
        self.b.wrap(m, "type_list", true);
    }

    fn type_parameters(&mut self) {
        let m = self.b.mark();
        self.bump(); // <
        while !self.at(">") && self.k() != K::Eof {
            let mp = self.b.mark();
            while self.at("@") {
                self.annotation();
            }
            self.bump_named("type_identifier");
            if self.at("extends") {
                let mb = self.b.mark();
                self.bump();
                loop {
                    self.ty();
                    if !self.eat("&") {
                        break;
                    }
                }
                self.b.wrap(mb, "type_bound", true);
            }
            self.b.wrap(mp, "type_parameter", true);
            if !self.eat(",") {
                break;
            }
        }
        self.expect(">");
        self.b.wrap(m, "type_parameters", true);
    }

    fn class_body(&mut self) {
        self.class_body_kind("class_body");
    }

    fn class_body_kind(&mut self, kind: &'static str) {
        let m = self.b.mark();
        self.expect("{");
        while !self.at("}") && self.k() != K::Eof {
            let before = self.i;
            self.member(kind);
            if self.i == before {
                self.error_token();
            }
        }
        self.expect("}");
        self.b.wrap(m, kind, true);
    }

    fn enum_body(&mut self) {
        let m = self.b.mark();
        self.expect("{");
        while !self.at("}") && !self.at(";") && self.k() != K::Eof {
            let mc = self.b.mark();
            self.modifiers();
            self.bump_named("identifier");
            self.b.field_last("name");
            if self.at("(") {
                self.argument_list();
                self.b.field_last("arguments");
            }
            if self.at("{") {
                self.class_body();
                self.b.field_last("body");
            }
            self.b.wrap(mc, "enum_constant", true);
            if !self.eat(",") {
                break;
            }
        }
        if self.at(";") {
            let md = self.b.mark();
            self.bump();
            while !self.at("}") && self.k() != K::Eof {
                let before = self.i;
                self.member("class_body");
                if self.i == before {
                    self.error_token();
                }
            }
            self.b.wrap(md, "enum_body_declarations", true);
        }
        self.expect("}");
        self.b.wrap(m, "enum_body", true);
    }

    fn member(&mut self, body_kind: &str) {
        let m = self.b.mark();
        if self.at(";") {
            self.bump();
            return;
        }
        if self.at("{") {
            self.block();
            return;
        }
        if self.at("static") && self.txn(1) == "{" {
            self.bump();
            self.block();
            self.b.wrap(m, "static_initializer", true);
            return;
        }
        self.modifiers();
        if self.type_declaration(m) {
            return;
        }
        let mut tp = false;
        if self.at("<") {
            self.type_parameters();
            self.b.field_last("type_parameters");
            tp = true;
        }
        let _ = tp;
        // constructor: Ident (
        if self.k() == K::Ident && self.txn(1) == "(" {
            self.bump_named("identifier");
            self.b.field_last("name");
            self.formal_parameters();
            self.b.field_last("parameters");
            self.throws();
            let mb = self.b.mark();
            self.expect("{");
            self.block_statements_until_brace(true);
            self.expect("}");
            self.b.wrap(mb, "constructor_body", true);
            self.b.field_last("body");
            self.b.wrap(m, "constructor_declaration", true);
            return;
        }
        // compact constructor (records): Ident {
        if self.k() == K::Ident && self.txn(1) == "{" && body_kind == "class_body" {
            self.bump_named("identifier");
            self.b.field_last("name");
            self.block();
            self.b.field_last("body");
            self.b.wrap(m, "compact_constructor_declaration", true);
            return;
        }
        // type then name
        self.ty();
        self.b.field_last("type");
        if self.k() == K::Ident && self.txn(1) == "(" {
            self.bump_named("identifier");
            self.b.field_last("name");
            self.formal_parameters();
            self.b.field_last("parameters");
            if self.at("[") {
                self.dimensions();
                self.b.field_last("dimensions");
            }
            if body_kind == "annotation_type_body" && self.at("default") {
                // annotation element
            }
            if self.at("default") {
                self.bump();
                self.element_value();
                self.b.field_last("value");
                self.expect(";");
                self.b.wrap(m, "annotation_type_element_declaration", true);
                return;
            }
            self.throws();
            if self.at("{") {
                self.block();
                self.b.field_last("body");
            } else {
                self.expect(";");
            }
            let k = if body_kind == "annotation_type_body" { "annotation_type_element_declaration" } else { "method_declaration" };
            self.b.wrap(m, k, true);
            return;
        }
        // field
        self.declarators();
        self.expect(";");
        let k = if body_kind == "interface_body" || body_kind == "annotation_type_body" { "constant_declaration" } else { "field_declaration" };
        self.b.wrap(m, k, true);
    }

    fn throws(&mut self) {
        if self.at("throws") {
            let m = self.b.mark();
            self.bump();
            loop {
                self.ty();
                if !self.eat(",") {
                    break;
                }
            }
            self.b.wrap(m, "throws", true);
        }
    }

    fn declarators(&mut self) {
        loop {
            let m = self.b.mark();
            if self.at("_") {
                let mu = self.b.mark();
                self.bump();
                self.b.wrap(mu, "underscore_pattern", true);
            } else {
                self.bump_named("identifier");
            }
            self.b.field_last("name");
            if self.at("[") {
                self.dimensions();
                self.b.field_last("dimensions");
            }
            if self.eat("=") {
                if self.at("{") {
                    self.array_initializer();
                } else {
                    self.expression();
                }
                self.b.field_last("value");
            }
            self.b.wrap(m, "variable_declarator", true);
            self.b.field_last("declarator");
            if !self.eat(",") {
                break;
            }
        }
    }

    fn array_initializer(&mut self) {
        let m = self.b.mark();
        self.bump(); // {
        while !self.at("}") && self.k() != K::Eof {
            if self.at("{") {
                self.array_initializer();
            } else {
                self.expression();
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect("}");
        self.b.wrap(m, "array_initializer", true);
    }

    fn formal_parameters(&mut self) {
        let m = self.b.mark();
        self.expect("(");
        while !self.at(")") && self.k() != K::Eof {
            let mp = self.b.mark();
            self.modifiers();
            // receiver parameter: Type this
            self.ty();
            self.b.field_last("type");
            if self.at("...") {
                self.bump();
                let md = self.b.mark();
                self.bump_named("identifier");
                self.b.field_last("name");
                self.b.wrap(md, "variable_declarator", true);
                self.b.wrap(mp, "spread_parameter", true);
            } else if self.at("this") {
                self.bump_named("this");
                self.b.wrap(mp, "receiver_parameter", true);
            } else {
                if self.at("_") {
                    let mu = self.b.mark();
                    self.bump();
                    self.b.wrap(mu, "underscore_pattern", true);
                } else {
                    self.bump_named("identifier");
                }
                self.b.field_last("name");
                if self.at("[") {
                    self.dimensions();
                    self.b.field_last("dimensions");
                }
                self.b.wrap(mp, "formal_parameter", true);
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect(")");
        self.b.wrap(m, "formal_parameters", true);
    }

    fn dimensions(&mut self) {
        let m = self.b.mark();
        while self.at("[") && self.txn(1) == "]" {
            self.bump();
            self.bump();
        }
        self.b.wrap(m, "dimensions", true);
    }

    // ---------- types ----------
    fn ty(&mut self) {
        let m = self.b.mark();
        let mut annotated = false;
        while self.at("@") && self.txn(1) != "interface" {
            self.annotation();
            annotated = true;
        }
        let ms = self.b.mark();
        self.unannotated_type();
        if annotated {
            let _ = ms;
            self.b.wrap(m, "annotated_type", true);
        }
    }

    fn unannotated_type(&mut self) {
        let m = self.b.mark();
        let tx = self.tx();
        match tx {
            "int" | "long" | "short" | "byte" | "char" => self.wrap_kw("integral_type"),
            "float" | "double" => self.wrap_kw("floating_point_type"),
            "boolean" => self.wrap_kw("boolean_type"),
            "void" => self.wrap_kw("void_type"),
            "?" => {
                self.bump();
                if self.at("extends") || self.at("super") {
                    self.bump();
                    self.ty();
                }
                self.b.wrap(m, "wildcard", true);
                return;
            }
            _ => {
                if self.k() == K::Ident {
                    self.bump_named("type_identifier");
                    loop {
                        if self.at("<") {
                            self.type_arguments();
                            self.b.wrap(m, "generic_type", true);
                            continue;
                        }
                        if self.at(".") && (self.tok(1).k == K::Ident || self.txn(1) == "@") && !matches!(self.txn(1), "class" | "this" | "new") {
                            self.bump();
                            while self.at("@") {
                                self.annotation();
                            }
                            self.bump_named("type_identifier");
                            self.b.wrap(m, "scoped_type_identifier", true);
                            continue;
                        }
                        break;
                    }
                } else {
                    let p = self.cur_pos();
                    self.b.missing("type_identifier", true, p);
                    return;
                }
            }
        }
        if self.at("[") && self.txn(1) == "]" {
            self.set_field_first(m, "element");
            self.dimensions();
            self.b.field_last("dimensions");
            self.b.wrap(m, "array_type", true);
        }
    }

    fn type_arguments(&mut self) {
        let m = self.b.mark();
        self.bump(); // <
        while !self.at(">") && self.k() != K::Eof {
            self.ty();
            if !self.eat(",") {
                break;
            }
        }
        self.expect(">");
        self.b.wrap(m, "type_arguments", true);
    }

    /// speculative: does a local variable declaration start here?
    fn is_local_var_decl(&mut self) -> bool {
        let save = self.i;
        let cp = self.b.checkpoint();
        let ok = (|| {
            let tx = self.tx();
            if self.k() != K::Ident || matches!(tx, "return" | "new" | "this" | "super" | "throw" | "yield" | "true" | "false" | "null" | "case" | "default" | "else") {
                return false;
            }
            self.ty();
            if self.b.stack.iter().any(|&c| self.b.nodes[c as usize].missing) {
                return false;
            }
            if self.k() != K::Ident && !self.at("_") {
                return false;
            }
            let n = self.txn(1);
            matches!(n, "=" | ";" | "," | "[" | ":" | ")")
        })();
        self.i = save;
        self.b.restore(cp);
        ok
    }

    // ---------- statements ----------
    fn block(&mut self) {
        let m = self.b.mark();
        self.expect("{");
        self.block_statements_until_brace(false);
        self.expect("}");
        self.b.wrap(m, "block", true);
    }

    fn block_statements_until_brace(&mut self, ctor: bool) {
        let mut first = true;
        while !self.at("}") && self.k() != K::Eof {
            let before = self.i;
            if ctor && first && self.is_explicit_ctor_call() {
                let m = self.b.mark();
                self.explicit_ctor();
                let _ = m;
            } else {
                self.statement();
            }
            first = false;
            if self.i == before {
                self.error_token();
            }
        }
    }

    fn is_explicit_ctor_call(&self) -> bool {
        (self.at("this") || self.at("super")) && self.txn(1) == "("
            || (self.k() == K::Ident && self.txn(1) == "." && self.txn(2) == "super" && self.txn(3) == "(")
    }

    fn explicit_ctor(&mut self) {
        let m = self.b.mark();
        if self.k() == K::Ident && self.txn(1) == "." {
            self.bump_named("identifier");
            self.b.field_last("object");
            self.bump();
        }
        let k = if self.at("this") { "this" } else { "super" };
        self.bump_named(k);
        self.b.field_last("constructor");
        self.argument_list();
        self.b.field_last("arguments");
        self.expect(";");
        self.b.wrap(m, "explicit_constructor_invocation", true);
    }

    fn statement(&mut self) {
        let m = self.b.mark();
        let t = self.tok(0);
        let tx = self.tx();
        if self.at("{") {
            self.block();
            return;
        }
        if self.at(";") {
            self.bump();
            return;
        }
        if self.at("@") || (t.k == K::Ident && MODIFIERS.contains(&tx) && !(tx == "default" && matches!(self.txn(1), ":" | "->"))) {
            self.modifiers();
            if self.type_declaration(m) {
                return;
            }
            if self.at("<") || (self.k() == K::Ident && self.txn(1) == "(") {
                // method decl at top level (pattern)
                self.method_like(m);
                return;
            }
            self.ty();
            self.b.field_last("type");
            if self.k() == K::Ident && self.txn(1) == "(" {
                self.method_rest(m);
                return;
            }
            self.declarators();
            self.expect(";");
            self.b.wrap(m, "local_variable_declaration", true);
            return;
        }
        if t.k == K::Ident {
            match tx {
                "class" | "interface" | "enum" => {
                    if self.type_declaration(m) {
                        return;
                    }
                }
                "record" if self.tok(1).k == K::Ident && matches!(self.txn(2), "(" | "<") => {
                    if self.type_declaration(m) {
                        return;
                    }
                }
                "if" => {
                    self.bump();
                    self.paren_expr();
                    self.b.field_last("condition");
                    self.statement();
                    self.b.field_last("consequence");
                    if self.at("else") {
                        self.bump();
                        self.statement();
                        self.b.field_last("alternative");
                    }
                    self.b.wrap(m, "if_statement", true);
                    return;
                }
                "while" => {
                    self.bump();
                    self.paren_expr();
                    self.b.field_last("condition");
                    self.statement();
                    self.b.field_last("body");
                    self.b.wrap(m, "while_statement", true);
                    return;
                }
                "do" => {
                    self.bump();
                    self.statement();
                    self.b.field_last("body");
                    self.expect("while");
                    self.paren_expr();
                    self.b.field_last("condition");
                    self.expect(";");
                    self.b.wrap(m, "do_statement", true);
                    return;
                }
                "for" => return self.for_stmt(m),
                "return" => {
                    self.bump();
                    if !self.at(";") {
                        self.expression();
                    }
                    self.expect(";");
                    self.b.wrap(m, "return_statement", true);
                    return;
                }
                "throw" => {
                    self.bump();
                    self.expression();
                    self.expect(";");
                    self.b.wrap(m, "throw_statement", true);
                    return;
                }
                "break" | "continue" => {
                    self.bump();
                    if self.k() == K::Ident {
                        self.bump_named("identifier");
                    }
                    self.expect(";");
                    self.b.wrap(m, if tx == "break" { "break_statement" } else { "continue_statement" }, true);
                    return;
                }
                "yield" if !matches!(self.txn(1), "=" | "(" | "." | "[") => {
                    self.bump();
                    self.expression();
                    self.expect(";");
                    self.b.wrap(m, "yield_statement", true);
                    return;
                }
                "assert" => {
                    self.bump();
                    self.expression();
                    if self.eat(":") {
                        self.expression();
                    }
                    self.expect(";");
                    self.b.wrap(m, "assert_statement", true);
                    return;
                }
                "try" => return self.try_stmt(m),
                "synchronized" if self.txn(1) == "(" => {
                    self.bump();
                    self.paren_expr();
                    self.block();
                    self.b.field_last("body");
                    self.b.wrap(m, "synchronized_statement", true);
                    return;
                }
                "switch" => {
                    self.switch_expr(m);
                    if self.at(";") {
                        self.bump();
                        self.b.wrap(m, "expression_statement", true);
                    }
                    return;
                }
                "this" | "super" if self.txn(1) == "(" => {
                    self.explicit_ctor();
                    return;
                }
                _ => {
                    if self.txn(1) == ":" && !matches!(tx, "default" | "case") {
                        self.bump_named("identifier");
                        self.bump();
                        self.statement();
                        self.b.wrap(m, "labeled_statement", true);
                        return;
                    }
                }
            }
        }
        if self.at("<") {
            self.method_like(m);
            return;
        }
        if self.is_local_var_decl() {
            self.ty();
            self.b.field_last("type");
            self.declarators();
            self.expect(";");
            self.b.wrap(m, "local_variable_declaration", true);
            return;
        }
        // method declaration without modifiers (pattern): Type name(
        if self.is_method_decl_ahead() {
            self.method_like(m);
            return;
        }
        self.expression();
        self.expect(";");
        self.b.wrap(m, "expression_statement", true);
    }

    fn is_method_decl_ahead(&mut self) -> bool {
        let save = self.i;
        let cp = self.b.checkpoint();
        let ok = (|| {
            if self.k() != K::Ident {
                return false;
            }
            self.ty();
            if self.b.stack.iter().any(|&c| self.b.nodes[c as usize].missing) {
                return false;
            }
            if self.k() != K::Ident || self.txn(1) != "(" {
                return false;
            }
            // find matching paren then '{' or 'throws' or ';'
            let mut depth = 0;
            let mut j = 1;
            loop {
                let x = self.txn(j);
                if x.is_empty() {
                    return false;
                }
                if x == "(" {
                    depth += 1;
                } else if x == ")" {
                    depth -= 1;
                    if depth == 0 {
                        return matches!(self.txn(j + 1), "{" | "throws");
                    }
                }
                j += 1;
            }
        })();
        self.i = save;
        self.b.restore(cp);
        ok
    }

    fn method_like(&mut self, m: usize) {
        if self.at("<") {
            self.type_parameters();
            self.b.field_last("type_parameters");
        }
        if self.k() == K::Ident && self.txn(1) == "(" {
            // constructor
            self.bump_named("identifier");
            self.b.field_last("name");
            self.formal_parameters();
            self.b.field_last("parameters");
            self.throws();
            let mb = self.b.mark();
            self.expect("{");
            self.block_statements_until_brace(true);
            self.expect("}");
            self.b.wrap(mb, "constructor_body", true);
            self.b.field_last("body");
            self.b.wrap(m, "constructor_declaration", true);
            return;
        }
        self.ty();
        self.b.field_last("type");
        self.method_rest(m);
    }

    fn method_rest(&mut self, m: usize) {
        self.bump_named("identifier");
        self.b.field_last("name");
        self.formal_parameters();
        self.b.field_last("parameters");
        if self.at("[") {
            self.dimensions();
            self.b.field_last("dimensions");
        }
        self.throws();
        if self.at("{") {
            self.block();
            self.b.field_last("body");
        } else {
            self.expect(";");
        }
        self.b.wrap(m, "method_declaration", true);
    }

    fn paren_expr(&mut self) {
        let m = self.b.mark();
        self.expect("(");
        self.expression();
        self.expect(")");
        self.b.wrap(m, "parenthesized_expression", true);
    }

    fn for_stmt(&mut self, m: usize) {
        self.bump(); // for
        self.expect("(");
        // enhanced for?
        let enhanced = {
            let save = self.i;
            let cp = self.b.checkpoint();
            self.modifiers();
            let mut ok = false;
            if self.k() == K::Ident {
                self.ty();
                if self.k() == K::Ident || self.at("_") {
                    self.bump();
                    if self.at("[") {
                        self.dimensions();
                    }
                    ok = self.at(":");
                }
            }
            self.i = save;
            self.b.restore(cp);
            ok
        };
        if enhanced {
            self.modifiers();
            self.ty();
            self.b.field_last("type");
            self.bump_named("identifier");
            self.b.field_last("name");
            if self.at("[") {
                self.dimensions();
                self.b.field_last("dimensions");
            }
            self.expect(":");
            self.expression();
            self.b.field_last("value");
            self.expect(")");
            self.statement();
            self.b.field_last("body");
            self.b.wrap(m, "enhanced_for_statement", true);
            return;
        }
        if self.at(";") {
            self.bump();
        } else if self.is_local_var_decl() || self.is_modifier_start() {
            let md = self.b.mark();
            self.modifiers();
            self.ty();
            self.b.field_last("type");
            self.declarators();
            self.expect(";");
            self.b.wrap(md, "local_variable_declaration", true);
            self.b.field_last("init");
        } else {
            loop {
                self.expression();
                self.b.field_last("init");
                if !self.eat(",") {
                    break;
                }
            }
            self.expect(";");
        }
        if !self.at(";") {
            self.expression();
            self.b.field_last("condition");
        }
        self.expect(";");
        while !self.at(")") && self.k() != K::Eof {
            self.expression();
            self.b.field_last("update");
            if !self.eat(",") {
                break;
            }
        }
        self.expect(")");
        self.statement();
        self.b.field_last("body");
        self.b.wrap(m, "for_statement", true);
    }

    fn try_stmt(&mut self, m: usize) {
        self.bump(); // try
        let with_res = self.at("(");
        if with_res {
            let mr = self.b.mark();
            self.bump();
            while !self.at(")") && self.k() != K::Eof {
                let mres = self.b.mark();
                if self.is_local_var_decl() || self.is_modifier_start() {
                    self.modifiers();
                    self.ty();
                    self.b.field_last("type");
                    self.bump_named("identifier");
                    self.b.field_last("name");
                    self.expect("=");
                    self.expression();
                    self.b.field_last("value");
                } else {
                    self.expression();
                }
                self.b.wrap(mres, "resource", true);
                if !self.eat(";") {
                    break;
                }
            }
            self.expect(")");
            self.b.wrap(mr, "resource_specification", true);
            self.b.field_last("resources");
        }
        self.block();
        self.b.field_last("body");
        while self.at("catch") {
            let mc = self.b.mark();
            self.bump();
            self.expect("(");
            let mp = self.b.mark();
            self.modifiers();
            let mt = self.b.mark();
            loop {
                self.ty();
                if !self.eat("|") {
                    break;
                }
            }
            self.b.wrap(mt, "catch_type", true);
            self.bump_named("identifier");
            self.b.field_last("name");
            self.b.wrap(mp, "catch_formal_parameter", true);
            self.expect(")");
            self.block();
            self.b.field_last("body");
            self.b.wrap(mc, "catch_clause", true);
        }
        if self.at("finally") {
            let mf = self.b.mark();
            self.bump();
            self.block();
            self.b.wrap(mf, "finally_clause", true);
        }
        self.b.wrap(m, if with_res { "try_with_resources_statement" } else { "try_statement" }, true);
    }

    fn switch_expr(&mut self, m: usize) {
        self.bump(); // switch
        self.paren_expr();
        self.b.field_last("condition");
        let mb = self.b.mark();
        self.expect("{");
        while !self.at("}") && self.k() != K::Eof {
            let mg = self.b.mark();
            // labels
            let mut is_rule = false;
            let mut any = false;
            while self.at("case") || self.at("default") {
                any = true;
                let ml = self.b.mark();
                if self.at("default") {
                    self.bump();
                } else {
                    self.bump();
                    loop {
                        self.case_label_item();
                        if !self.eat(",") {
                            break;
                        }
                    }
                }
                self.b.wrap(ml, "switch_label", true);
                if self.at("->") {
                    is_rule = true;
                    self.bump();
                    break;
                }
                self.expect(":");
            }
            if !any {
                self.error_token();
                continue;
            }
            if is_rule {
                if self.at("{") {
                    self.block();
                } else if self.at("throw") {
                    self.statement();
                } else {
                    let me = self.b.mark();
                    self.expression();
                    self.expect(";");
                    self.b.wrap(me, "expression_statement", true);
                }
                self.b.wrap(mg, "switch_rule", true);
            } else {
                while !self.at("case") && !self.at("default") && !self.at("}") && self.k() != K::Eof {
                    let before = self.i;
                    self.statement();
                    if self.i == before {
                        self.error_token();
                    }
                }
                self.b.wrap(mg, "switch_block_statement_group", true);
            }
        }
        self.expect("}");
        self.b.wrap(mb, "switch_block", true);
        self.b.field_last("body");
        self.b.wrap(m, "switch_expression", true);
    }

    fn case_label_item(&mut self) {
        // pattern (type pattern) or expression
        let is_type_pattern = {
            let save = self.i;
            let cp = self.b.checkpoint();
            let mut ok = false;
            if self.k() == K::Ident {
                self.ty();
                ok = self.k() == K::Ident && matches!(self.txn(1), "->" | ":" | "," | "when" | "&&");
            }
            self.i = save;
            self.b.restore(cp);
            ok
        };
        if is_type_pattern {
            let mp = self.b.mark();
            let mt = self.b.mark();
            self.ty();
            self.bump_named("identifier");
            self.b.wrap(mt, "type_pattern", true);
            self.b.wrap(mp, "pattern", true);
            if self.at("when") {
                let mg = self.b.mark();
                self.bump();
                self.expression();
                self.b.wrap(mg, "guard", true);
            }
        } else {
            self.ternary();
        }
    }

    // ---------- expressions ----------
    fn expression(&mut self) {
        self.depth += 1;
        if self.depth > 300 {
            self.error_token();
            self.depth -= 1;
            return;
        }
        let m = self.b.mark();
        // lambda
        if self.is_lambda_ahead() {
            self.lambda(m);
            self.depth -= 1;
            return;
        }
        self.ternary();
        let tx = self.tx();
        let is_assign = matches!(tx, "=" | "+=" | "-=" | "*=" | "/=" | "%=" | "&=" | "|=" | "^=" | "<<=" | ">>>=" | ">>=") && self.k() == K::Op;
        let gtgt = self.at(">") && self.adjacent(0) && self.txn(1) == ">" && self.adjacent(1) && (self.txn(2) == "=" || (self.txn(2) == ">" && self.adjacent(2) && self.txn(3) == "="));
        if is_assign || gtgt {
            self.b.field_last("left");
            if gtgt {
                let n = if self.txn(2) == "=" { 3 } else { 4 };
                self.bump_join(n);
            } else {
                self.bump();
            }
            self.b.field_last("operator");
            self.expression();
            self.b.field_last("right");
            self.b.wrap(m, "assignment_expression", true);
        }
        self.depth -= 1;
    }

    fn is_lambda_ahead(&self) -> bool {
        if self.k() == K::Ident && self.txn(1) == "->" {
            return true;
        }
        if self.at("(") {
            let mut depth = 0;
            let mut j = 0;
            loop {
                let x = self.txn(j);
                if x.is_empty() {
                    return false;
                }
                if x == "(" {
                    depth += 1;
                } else if x == ")" {
                    depth -= 1;
                    if depth == 0 {
                        return self.txn(j + 1) == "->";
                    }
                }
                j += 1;
            }
        }
        false
    }

    fn lambda(&mut self, m: usize) {
        if self.k() == K::Ident {
            self.bump_named("identifier");
        } else {
            // inferred or formal
            let inferred = {
                let mut j = 1;
                let mut ok = true;
                loop {
                    let t = self.tok(j);
                    let x = self.txn(j);
                    if x == ")" {
                        break;
                    }
                    if t.k != K::Ident && x != "," {
                        ok = false;
                        break;
                    }
                    if t.k == K::Ident && !matches!(self.txn(j + 1), "," | ")") {
                        ok = false;
                        break;
                    }
                    j += 1;
                }
                ok && self.txn(1) != ")"
            };
            if inferred {
                let mi = self.b.mark();
                self.bump();
                loop {
                    self.bump_named("identifier");
                    if !self.eat(",") {
                        break;
                    }
                }
                self.expect(")");
                self.b.wrap(mi, "inferred_parameters", true);
            } else {
                self.formal_parameters();
            }
        }
        self.b.field_last("parameters");
        self.expect("->");
        if self.at("{") {
            self.block();
        } else {
            self.expression();
        }
        self.b.field_last("body");
        self.b.wrap(m, "lambda_expression", true);
    }

    fn ternary(&mut self) {
        let m = self.b.mark();
        self.binary(4);
        if self.at("?") {
            self.b.field_last("condition");
            self.bump();
            self.expression();
            self.b.field_last("consequence");
            self.expect(":");
            if self.is_lambda_ahead() {
                let ml = self.b.mark();
                self.lambda(ml);
            } else {
                self.ternary();
            }
            self.b.field_last("alternative");
            self.b.wrap(m, "ternary_expression", true);
        }
    }

    fn binop(&self) -> Option<(u8, usize)> {
        let t = self.tok(0);
        if t.k == K::Ident {
            return if self.tx() == "instanceof" { Some((10, 1)) } else { None };
        }
        if t.k != K::Op {
            return None;
        }
        let tx = self.tx();
        Some(match tx {
            "||" => (4, 1),
            "&&" => (5, 1),
            "|" => (6, 1),
            "^" => (7, 1),
            "&" => (8, 1),
            "==" | "!=" => (9, 1),
            "<" | "<=" => (10, 1),
            ">" => {
                if self.adjacent(0) && self.txn(1) == ">" {
                    if self.adjacent(1) && self.txn(2) == ">" {
                        if self.adjacent(2) && self.txn(3) == "=" {
                            return None;
                        }
                        (11, 3)
                    } else if self.adjacent(1) && self.txn(2) == "=" {
                        return None;
                    } else {
                        (11, 2)
                    }
                } else if self.adjacent(0) && self.txn(1) == "=" {
                    (10, 2)
                } else {
                    (10, 1)
                }
            }
            "<<" => (11, 1),
            "+" | "-" => (12, 1),
            "*" | "/" | "%" => (13, 1),
            _ => return None,
        })
    }

    fn binary(&mut self, min: u8) {
        let m = self.b.mark();
        self.unary();
        loop {
            let Some((p, n)) = self.binop() else { break };
            if p < min {
                break;
            }
            if self.at("instanceof") {
                self.b.field_last("left");
                self.bump();
                if self.at("final") {
                    self.bump();
                }
                self.ty();
                self.b.field_last("right");
                if self.k() == K::Ident && !matches!(self.tx(), "instanceof") {
                    self.bump_named("identifier");
                    self.b.field_last("name");
                }
                self.b.wrap(m, "instanceof_expression", true);
                continue;
            }
            self.b.field_last("left");
            if n > 1 {
                self.bump_join(n);
            } else {
                self.bump();
            }
            self.b.field_last("operator");
            self.binary(p + 1);
            self.b.field_last("right");
            self.b.wrap(m, "binary_expression", true);
        }
    }

    fn is_cast_ahead(&self) -> bool {
        // ( Type ) operand
        if !self.at("(") {
            return false;
        }
        let t1 = self.tok(1);
        let x1 = self.txn(1);
        let prim = matches!(x1, "int" | "long" | "short" | "byte" | "char" | "float" | "double" | "boolean");
        if t1.k != K::Ident {
            return false;
        }
        // find matching ')'
        let mut depth = 0;
        let mut j = 0;
        loop {
            let x = self.txn(j);
            if x.is_empty() {
                return false;
            }
            if x == "(" {
                depth += 1;
            } else if x == ")" {
                depth -= 1;
                if depth == 0 {
                    break;
                }
            } else if depth == 1 && !(self.tok(j).k == K::Ident || matches!(x, "." | "<" | ">" | "[" | "]" | "," | "?" | "&" | "@")) {
                return false;
            }
            j += 1;
        }
        let nt = self.tok(j + 1);
        let nx = self.txn(j + 1);
        if prim {
            return true;
        }
        matches!(nt.k, K::Ident | K::Num | K::Str | K::Char | K::TextBlock) && !matches!(nx, "instanceof")
            || matches!(nx, "(" | "!" | "~")
    }

    fn unary(&mut self) {
        let m = self.b.mark();
        let tx = self.tx();
        if self.k() == K::Op {
            match tx {
                "+" | "-" | "!" | "~" => {
                    self.bump();
                    self.b.field_last("operator");
                    self.unary();
                    self.b.field_last("operand");
                    self.b.wrap(m, "unary_expression", true);
                    return;
                }
                "++" | "--" => {
                    self.bump();
                    self.unary();
                    self.b.wrap(m, "update_expression", true);
                    return;
                }
                "(" if self.is_cast_ahead() => {
                    self.bump();
                    loop {
                        self.ty();
                        self.b.field_last("type");
                        if !self.eat("&") {
                            break;
                        }
                    }
                    self.expect(")");
                    if self.is_lambda_ahead() {
                        let ml = self.b.mark();
                        self.lambda(ml);
                    } else {
                        self.unary();
                    }
                    self.b.field_last("value");
                    self.b.wrap(m, "cast_expression", true);
                    return;
                }
                _ => {}
            }
        }
        self.postfix();
    }

    fn postfix(&mut self) {
        let m = self.b.mark();
        self.primary();
        loop {
            let tx = self.tx();
            match tx {
                "." => {
                    let n1 = self.txn(1);
                    if n1 == "<" {
                        // generic method call
                        self.set_field_first(m, "object");
                        self.bump();
                        self.type_arguments();
                        self.b.field_last("type_arguments");
                        self.bump_named("identifier");
                        self.b.field_last("name");
                        self.argument_list();
                        self.b.field_last("arguments");
                        self.b.wrap(m, "method_invocation", true);
                        continue;
                    }
                    if n1 == "new" {
                        self.bump();
                        let mn = self.b.mark();
                        let _ = mn;
                        self.object_creation(m, true);
                        continue;
                    }
                    if n1 == "class" {
                        self.bump();
                        self.bump();
                        self.b.wrap(m, "class_literal", true);
                        continue;
                    }
                    self.set_field_first(m, "object");
                    self.bump();
                    let t = self.tok(0);
                    if self.at("this") {
                        self.bump_named("this");
                        self.b.field_last("field");
                        self.b.wrap(m, "field_access", true);
                        continue;
                    }
                    if self.at("super") {
                        self.bump_named("super");
                        self.b.field_last("field");
                        self.b.wrap(m, "field_access", true);
                        continue;
                    }
                    if t.k == K::Ident {
                        self.bump_named("identifier");
                    } else {
                        let p = self.cur_pos();
                        self.b.missing("identifier", true, p);
                    }
                    if self.at("(") {
                        self.b.field_last("name");
                        self.argument_list();
                        self.b.field_last("arguments");
                        self.b.wrap(m, "method_invocation", true);
                    } else {
                        self.b.field_last("field");
                        self.b.wrap(m, "field_access", true);
                    }
                }
                "[" => {
                    self.set_field_first(m, "array");
                    self.bump();
                    self.expression();
                    self.b.field_last("index");
                    self.expect("]");
                    self.b.wrap(m, "array_access", true);
                }
                "++" | "--" => {
                    self.bump();
                    self.b.wrap(m, "update_expression", true);
                }
                "::" => {
                    self.bump();
                    if self.at("<") {
                        self.type_arguments();
                    }
                    if self.at("new") {
                        self.bump();
                    } else {
                        self.bump_named("identifier");
                    }
                    self.b.wrap(m, "method_reference", true);
                }
                _ => break,
            }
        }
    }

    fn argument_list(&mut self) {
        let m = self.b.mark();
        self.expect("(");
        while !self.at(")") && self.k() != K::Eof {
            let before = self.i;
            self.expression();
            if self.i == before {
                break;
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect(")");
        self.b.wrap(m, "argument_list", true);
    }

    fn object_creation(&mut self, m: usize, qualified: bool) {
        let _ = qualified;
        self.bump(); // new
        if self.at("<") {
            self.type_arguments();
            self.b.field_last("type_arguments");
        }
        // array creation?
        let mt = self.b.mark();
        while self.at("@") {
            self.annotation();
        }
        // parse type without array dims
        let tx = self.tx();
        let prim = matches!(tx, "int" | "long" | "short" | "byte" | "char" | "float" | "double" | "boolean");
        if prim {
            self.unannotated_simple();
        } else {
            self.unannotated_simple();
        }
        let _ = mt;
        self.b.field_last("type");
        if self.at("[") {
            // array creation
            while self.at("[") {
                if self.txn(1) == "]" {
                    self.dimensions();
                    self.b.field_last("dimensions");
                } else {
                    let md = self.b.mark();
                    self.bump();
                    self.expression();
                    self.expect("]");
                    self.b.wrap(md, "dimensions_expr", true);
                    self.b.field_last("dimensions");
                }
            }
            if self.at("{") {
                self.array_initializer();
                self.b.field_last("value");
            }
            self.b.wrap(m, "array_creation_expression", true);
            return;
        }
        self.argument_list();
        self.b.field_last("arguments");
        if self.at("{") {
            self.class_body();
        }
        self.b.wrap(m, "object_creation_expression", true);
    }

    fn unannotated_simple(&mut self) {
        let m = self.b.mark();
        let tx = self.tx();
        match tx {
            "int" | "long" | "short" | "byte" | "char" => self.wrap_kw("integral_type"),
            "float" | "double" => self.wrap_kw("floating_point_type"),
            "boolean" => self.wrap_kw("boolean_type"),
            _ => {
                self.bump_named("type_identifier");
                loop {
                    if self.at("<") {
                        self.type_arguments();
                        self.b.wrap(m, "generic_type", true);
                        continue;
                    }
                    if self.at(".") && self.tok(1).k == K::Ident {
                        self.bump();
                        self.bump_named("type_identifier");
                        self.b.wrap(m, "scoped_type_identifier", true);
                        continue;
                    }
                    break;
                }
            }
        }
    }

    fn string_lit(&mut self) {
        let t = self.advance();
        let m = self.b.mark();
        let b = self.src.as_bytes();
        let tb = t.k == K::TextBlock;
        let ql = if tb { 3 } else { 1 };
        let qk = if tb { "\"\"\"" } else { "\"" };
        self.b.leaf(qk, false, t.s, t.s + ql);
        let close = t.e >= t.s + 2 * ql && b[t.e - 1] == b'"';
        let ce = if close { t.e - ql } else { t.e };
        let frag = if tb { "multiline_string_fragment" } else { "string_fragment" };
        let mut i = t.s + ql;
        let mut cs = i;
        while i < ce {
            if b[i] == b'\\' {
                if cs < i {
                    self.b.leaf(frag, true, cs, i);
                }
                let mut k = i + 1;
                if k < ce {
                    match b[k] {
                        b'u' => {
                            while k < ce && b[k] == b'u' {
                                k += 1;
                            }
                            k += 4;
                        }
                        b'0'..=b'7' => {
                            let mut c = 0;
                            while k < ce && c < 3 && (b'0'..=b'7').contains(&b[k]) {
                                k += 1;
                                c += 1;
                            }
                        }
                        _ => k += 1,
                    }
                }
                let k = k.min(ce);
                self.b.leaf("escape_sequence", true, i, k);
                i = k;
                cs = i;
            } else {
                i += 1;
            }
        }
        if cs < ce {
            self.b.leaf(frag, true, cs, ce);
        }
        if close {
            self.b.leaf(qk, false, ce, t.e);
        }
        self.b.wrap(m, "string_literal", true);
    }

    fn number(&mut self) {
        let t = self.tok(0);
        let txt = &self.src[t.s..t.e];
        let l = txt.to_ascii_lowercase();
        let kind = if l.starts_with("0x") {
            if l.contains('.') || l.contains('p') { "hex_floating_point_literal" } else { "hex_integer_literal" }
        } else if l.starts_with("0b") {
            "binary_integer_literal"
        } else if l.contains('.') || l.contains('e') || ((l.ends_with('f') || l.ends_with('d')) && !l.starts_with("0x")) {
            "decimal_floating_point_literal"
        } else if l.len() > 1 && l.starts_with('0') && l.chars().nth(1).map_or(false, |c| c.is_ascii_digit() || c == '_') {
            "octal_integer_literal"
        } else {
            "decimal_integer_literal"
        };
        self.bump_named(kind);
    }

    fn primary(&mut self) {
        let m = self.b.mark();
        let t = self.tok(0);
        let tx = self.tx();
        match t.k {
            K::Num => self.number(),
            K::Str | K::TextBlock => self.string_lit(),
            K::Char => {
                self.bump_named("character_literal");
            }
            K::Ident => match tx {
                "true" => {
                    self.bump_named("true");
                }
                "false" => {
                    self.bump_named("false");
                }
                "null" => {
                    self.bump_named("null_literal");
                }
                "this" => {
                    self.bump_named("this");
                }
                "super" => {
                    self.bump_named("super");
                }
                "new" => self.object_creation(m, false),
                "switch" => self.switch_expr(m),
                "int" | "long" | "short" | "byte" | "char" | "float" | "double" | "boolean" | "void" => {
                    // class literal int.class or method ref int[]::new
                    self.unannotated_type();
                }
                _ => {
                    // method invocation without object
                    if self.txn(1) == "(" {
                        self.bump_named("identifier");
                        self.b.field_last("name");
                        self.argument_list();
                        self.b.field_last("arguments");
                        self.b.wrap(m, "method_invocation", true);
                    } else if self.txn(1) == "<" && self.generic_type_ref_ahead() {
                        self.ty();
                    } else if self.txn(1) == "[" && self.txn(2) == "]" {
                        self.ty();
                    } else {
                        self.bump_named("identifier");
                    }
                }
            },
            K::Op => match tx {
                "(" => {
                    self.bump();
                    self.expression();
                    self.expect(")");
                    self.b.wrap(m, "parenthesized_expression", true);
                }
                "@" => {
                    self.annotation();
                }
                _ => self.error_token(),
            },
            _ => {
                let p = self.cur_pos();
                self.b.missing("identifier", true, p);
            }
        }
    }

    fn generic_type_ref_ahead(&self) -> bool {
        // Type<Args>::method
        let mut depth = 0;
        let mut j = 1;
        loop {
            let x = self.txn(j);
            if x.is_empty() {
                return false;
            }
            if x == "<" {
                depth += 1;
            } else if x == ">" {
                depth -= 1;
                if depth == 0 {
                    return self.txn(j + 1) == "::";
                }
            } else if !(self.tok(j).k == K::Ident || matches!(x, "," | "." | "?" | "[" | "]")) {
                return false;
            }
            j += 1;
        }
    }
}
