use crate::tree::{Builder, Tree};

#[derive(Clone, Copy, PartialEq, Debug)]
enum K {
    Ident,
    Num,
    Str,
    RawStr,
    Char,
    Op,
    Comment,
    Preproc,
    Eof,
}

#[derive(Clone, Copy, Debug)]
struct Tk {
    k: K,
    s: usize,
    e: usize,
}

const OPS: &[&str] = &[
    "<<=", ">>=", "...", "->*", "<=>", "::", "->", "++", "--", "&&", "||", "==", "!=", "<=", ">=", "+=", "-=", "*=", "/=",
    "%=", "&=", "|=", "^=", "<<", ">>", ".*",
];

pub fn is_primitive(s: &str) -> bool {
    matches!(
