        while i < b.len() {
            if b[i] == b'\\' && i + 1 < b.len() && b[i + 1] == b'\n' {
                i += 2;
                continue;
            }
            if b[i] == b'\n' {
                return i;
            }
            i += 1;
        }
        b.len()
    }

