            s += 1;
        }
        let mut e = eol;
        while e > s && (b[e - 1] == b' ' || b[e - 1] == b'\t' || b[e - 1] == b'\r') {
            e -= 1;
        }
        if e > s {
            self.b.leaf("preproc_arg", true, s, e);
            self.b.field_last("value");
        }
