// C / C++ parser producing tree-sitter-c / tree-sitter-cpp compatible CST
use super::js::intern;
use crate::tree::{Builder, Tree};

#[derive(Clone, Copy, PartialEq, Debug)]
enum K {
    Ident,
    Num,
    Str,
    RawStr,
    Char,
    Op,
    Comment,
    Preproc,
    Eof,
}

#[derive(Clone, Copy, Debug)]
struct Tk {
    k: K,
    s: usize,
    e: usize,
}

const OPS: &[&str] = &[
    "<<=", ">>=", "...", "->*", "<=>", "::", "->", "++", "--", "&&", "||", "==", "!=", "<=", ">=", "+=", "-=", "*=", "/=",
    "%=", "&=", "|=", "^=", "<<", ">>", ".*",
];

pub fn is_primitive(s: &str) -> bool {
    matches!(
        s,
        "bool" | "char" | "int" | "float" | "double" | "void" | "size_t" | "ssize_t" | "ptrdiff_t" | "intptr_t"
            | "uintptr_t" | "charptr_t" | "nullptr_t" | "max_align_t" | "int8_t" | "int16_t" | "int32_t" | "int64_t"
            | "uint8_t" | "uint16_t" | "uint32_t" | "uint64_t" | "char8_t" | "char16_t" | "char32_t" | "wchar_t"
    )
}

fn tokenize(src: &str) -> Vec<Tk> {
    let b = src.as_bytes();
    let n = b.len();
    let mut out = Vec::new();
    let mut i = 0;
    let mut line_start = true;
    while i < n {
        let c = b[i];
        if c == b'\n' {
            line_start = true;
            i += 1;
            continue;
        }
        if c == b' ' || c == b'\t' || c == b'\r' || c == 0x0c {
            i += 1;
            continue;
        }
        if c == b'\\' && i + 1 < n && (b[i + 1] == b'\n' || b[i + 1] == b'\r') {
            i += 2;
            continue;
        }
        if c == b'/' && i + 1 < n && b[i + 1] == b'/' {
            let s = i;
            while i < n && b[i] != b'\n' {
                if b[i] == b'\\' && i + 1 < n && b[i + 1] == b'\n' {
                    i += 2;
                    continue;
                }
                i += 1;
            }
            let mut e = i;
            if e > s && b[e - 1] == b'\r' {
                e -= 1;
            }
            out.push(Tk { k: K::Comment, s, e });
            continue;
        }
        if c == b'/' && i + 1 < n && b[i + 1] == b'*' {
            let s = i;
            i += 2;
            while i < n && !(b[i] == b'*' && i + 1 < n && b[i + 1] == b'/') {
                i += 1;
            }
            i = (i + 2).min(n);
            out.push(Tk { k: K::Comment, s, e: i });
            continue;
        }
        if c == b'#' && line_start {
            // preprocessor directive token: '#' + word
            let s = i;
            let mut j = i + 1;
            while j < n && (b[j] == b' ' || b[j] == b'\t') {
                j += 1;
            }
            let ws = j;
            while j < n && (b[j].is_ascii_alphanumeric() || b[j] == b'_') {
                j += 1;
            }
            let _ = ws;
            out.push(Tk { k: K::Preproc, s, e: j });
            i = j;
            line_start = false;
            continue;
        }
        line_start = false;
        let s = i;
        // string prefixes
        let mut j = i;
        while j < n && j - i < 3 && (b[j] == b'L' || b[j] == b'u' || b[j] == b'U' || b[j] == b'8' || b[j] == b'R') {
            j += 1;
        }
        if j < n && b[j] == b'"' && (j == i || src[i..j].chars().all(|ch| "LuU8R".contains(ch))) && (j == i || matches!(&src[i..j], "L" | "u" | "U" | "u8" | "R" | "LR" | "uR" | "UR" | "u8R")) {
            if j > i && b[j - 1] == b'R' {
                // raw string R"delim( ... )delim"
                let mut k = j + 1;
                let ds = k;
                while k < n && b[k] != b'(' {
                    k += 1;
                }
                let delim = &src[ds..k];
                let close = format!("){}\"", delim);
                let rest = &src[k.min(n)..];
                let e = rest.find(&close).map(|x| k + x + close.len()).unwrap_or(n);
                out.push(Tk { k: K::RawStr, s, e });
                i = e;
                continue;
            }
            let mut k = j + 1;
            while k < n && b[k] != b'"' && b[k] != b'\n' {
                if b[k] == b'\\' {
                    k += 1;
                }
                k += 1;
            }
            i = (k + 1).min(n);
            out.push(Tk { k: K::Str, s, e: i });
            continue;
        }
        if j < n && b[j] == b'\'' && (j == i || matches!(&src[i..j], "L" | "u" | "U" | "u8")) {
            let mut k = j + 1;
            while k < n && b[k] != b'\'' && b[k] != b'\n' {
                if b[k] == b'\\' {
                    k += 1;
                }
                k += 1;
            }
            i = (k + 1).min(n);
            out.push(Tk { k: K::Char, s, e: i });
            continue;
        }
        if c.is_ascii_digit() || (c == b'.' && i + 1 < n && b[i + 1].is_ascii_digit()) {
            let mut k = i;
            while k < n && (b[k].is_ascii_alphanumeric() || b[k] == b'.' || b[k] == b'\'' || ((b[k] == b'+' || b[k] == b'-') && matches!(b[k - 1], b'e' | b'E' | b'p' | b'P') && !(src[i..k].starts_with("0x") && matches!(b[k - 1], b'e' | b'E')))) {
                k += 1;
            }
            i = k;
            out.push(Tk { k: K::Num, s, e: i });
            continue;
        }
        let ch = src[i..].chars().next().unwrap();
        if ch == '_' || ch.is_alphabetic() || ch == '$' {
            let mut e = i;
            for (o, c2) in src[i..].char_indices() {
                if !(c2 == '_' || c2.is_alphanumeric() || c2 == '$') {
                    e = i + o;
                    break;
                }
                e = i + o + c2.len_utf8();
            }
            i = e;
            out.push(Tk { k: K::Ident, s, e: i });
            continue;
        }
        let r = &src[i..];
        let mut l = ch.len_utf8();
        for o in OPS {
            if r.starts_with(o) {
                l = o.len();
                break;
            }
        }
        i += l;
        out.push(Tk { k: K::Op, s, e: i });
    }
    out.push(Tk { k: K::Eof, s: n, e: n });
    out
}

struct P<'a> {
    src: &'a str,
    toks: Vec<Tk>,
    i: usize,
    b: Builder,
    cpp: bool,
    depth: usize,
    no_gt: bool,
}

pub fn parse(src: &str, cpp: bool) -> Tree {
    let toks = tokenize(src);
    let mut p = P { src, toks, i: 0, b: Builder::new(), cpp, depth: 0, no_gt: false };
    let m = p.b.mark();
    loop {
        if p.k() == K::Eof {
            break;
        }
        let before = p.i;
        p.top_item();
        if p.i == before {
            p.error_token();
        }
    }
    p.flush_extras();
    let start = p.b.stack[m..].first().map(|&c| p.b.nodes[c as usize].start).unwrap_or(src.len() - src.trim_start().len());
    let root = p.b.wrap_all(m, "translation_unit", start, src.len());
    p.b.finish(root, src)
}

impl<'a> P<'a> {
    fn idx(&self, n: usize) -> usize {
        let mut j = self.i;
        let mut c = 0;
        loop {
            while j < self.toks.len() && self.toks[j].k == K::Comment {
                j += 1;
            }
            if j >= self.toks.len() {
                return self.toks.len() - 1;
            }
            if c == n {
                return j;
            }
            c += 1;
            j += 1;
        }
    }
    fn tok(&self, n: usize) -> Tk {
        self.toks[self.idx(n)]
    }
    fn k(&self) -> K {
        self.tok(0).k
    }
    fn txn(&self, n: usize) -> &'a str {
        let t = self.tok(n);
        if t.k == K::Eof {
            return "";
        }
        &self.src[t.s..t.e]
    }
    fn tx(&self) -> &'a str {
        self.txn(0)
    }
    fn at(&self, s: &str) -> bool {
        let t = self.tok(0);
        matches!(t.k, K::Op | K::Ident) && &self.src[t.s..t.e] == s
    }
    fn flush_extras(&mut self) {
        while self.i < self.toks.len() && self.toks[self.i].k == K::Comment {
            let t = self.toks[self.i];
            self.b.extra("comment", t.s, t.e);
            self.i += 1;
        }
    }
    fn advance(&mut self) -> Tk {
        self.flush_extras();
        let t = self.toks[self.i];
        if t.k != K::Eof {
            self.i += 1;
        }
        t
    }
    fn bump(&mut self) -> u32 {
        let t = self.advance();
        let k = intern(&self.src[t.s..t.e]);
        self.b.leaf(k, false, t.s, t.e)
    }
    fn bump_named(&mut self, kind: &'static str) -> u32 {
        let t = self.advance();
        self.b.leaf(kind, true, t.s, t.e)
    }
    fn wrap_kw(&mut self, kind: &'static str) {
        let m = self.b.mark();
        self.bump();
        self.b.wrap(m, kind, true);
    }
    fn eat(&mut self, s: &str) -> bool {
        if self.at(s) {
            self.bump();
            true
        } else {
            false
        }
    }
    fn cur_pos(&self) -> usize {
        self.b.last().map(|l| self.b.nodes[l as usize].end).unwrap_or(0)
    }
    fn expect(&mut self, s: &str) {
        if !self.eat(s) {
            let p = self.cur_pos();
            self.b.missing(intern(s), false, p);
        }
    }
    fn error_token(&mut self) {
        if self.k() == K::Eof {
            return;
        }
        let m = self.b.mark();
        if self.k() == K::Ident {
            self.bump_named("identifier");
        } else {
            self.bump();
        }
        self.b.wrap(m, "ERROR", true);
    }
    fn set_field_first(&mut self, m: usize, f: &'static str) {
        for i in m..self.b.stack.len() {
            let id = self.b.stack[i] as usize;
            if !self.b.nodes[id].extra {
                self.b.nodes[id].field = Some(f);
                return;
            }
        }
    }

    // ---------- preprocessor ----------
    fn line_end(&self, from: usize) -> usize {
        let b = self.src.as_bytes();
        let mut i = from;
        while i < b.len() {
            if b[i] == b'\\' && i + 1 < b.len() && b[i + 1] == b'\n' {
                i += 2;
                continue;
            }
            if b[i] == b'\n' {
                return i;
            }
            i += 1;
        }
        b.len()
    }

    fn skip_tokens_until(&mut self, pos: usize) {
        while self.i < self.toks.len() && self.toks[self.i].k != K::Eof && self.toks[self.i].s < pos {
            self.i += 1;
        }
    }

    fn preproc_arg(&mut self, from: usize, eol: usize) {
        // text from first non-space to end of line (excluding trailing spaces / comments?)
        let b = self.src.as_bytes();
        let mut s = from;
        while s < eol && (b[s] == b' ' || b[s] == b'\t') {
            s += 1;
        }
        let mut e = eol;
        while e > s && (b[e - 1] == b' ' || b[e - 1] == b'\t' || b[e - 1] == b'\r') {
            e -= 1;
        }
        if e > s {
            self.b.leaf("preproc_arg", true, s, e);
            self.b.field_last("value");
        }
    }

    fn preproc(&mut self, in_body: &str) {
        let t = self.tok(0);
        let directive = self.src[t.s..t.e].replace([' ', '\t'], "");
        let m = self.b.mark();
        let eol = self.line_end(t.e);
        let end_incl = if eol < self.src.len() { eol + 1 } else { eol };
        match directive.as_str() {
            "#include" => {
                self.advance();
                self.b.leaf("#include", false, t.s, t.e);
                let nt = self.tok(0);
                if nt.k == K::Str {
                    self.string_literal();
                } else if self.at("<") {
                    let b = self.src.as_bytes();
                    let mut k = nt.s;
                    while k < eol && b[k] != b'>' {
                        k += 1;
                    }
                    self.b.leaf("system_lib_string", true, nt.s, (k + 1).min(eol));
                    self.skip_tokens_until(k + 1);
                } else {
                    self.expression();
                }
                self.b.field_last("path");
                self.skip_tokens_until(eol);
                self.b.hidden(eol, end_incl);
                self.b.wrap(m, "preproc_include", true);
            }
            "#define" => {
                self.advance();
                self.b.leaf("#define", false, t.s, t.e);
                self.bump_named("identifier");
                self.b.field_last("name");
                let after_name = self.cur_pos();
                if self.at("(") && self.tok(0).s == after_name {
                    let mp = self.b.mark();
                    self.bump();
                    while !self.at(")") && self.tok(0).s < eol && self.k() != K::Eof {
                        if self.at("...") {
                            self.bump();
                        } else {
                            self.bump_named("identifier");
                        }
                        if !self.eat(",") {
                            break;
                        }
                    }
                    self.expect(")");
                    self.b.wrap(mp, "preproc_params", true);
                    self.b.field_last("parameters");
                    let from = self.cur_pos();
                    self.flush_extras_before(eol);
                    self.skip_tokens_until(eol);
                    self.preproc_arg(from, eol);
                    self.b.hidden(eol, end_incl);
                    self.b.wrap(m, "preproc_function_def", true);
                } else {
                    let from = self.cur_pos();
                    self.flush_extras_before(eol);
                    self.skip_tokens_until(eol);
                    self.preproc_arg(from, eol);
                    self.b.hidden(eol, end_incl);
                    self.b.wrap(m, "preproc_def", true);
                }
            }
            "#ifdef" | "#ifndef" | "#if" | "#elif" | "#elifdef" | "#elifndef" => {
                let kind = match directive.as_str() {
                    "#ifdef" | "#ifndef" => "preproc_ifdef",
                    "#if" => "preproc_if",
                    "#elif" => "preproc_elif",
                    _ => "preproc_elifdef",
                };
                self.advance();
                self.b.leaf(intern(&directive), false, t.s, t.e);
                if kind == "preproc_ifdef" || kind == "preproc_elifdef" {
                    self.bump_named("identifier");
                    self.b.field_last("name");
                } else {
                    let save_gt = self.no_gt;
                    self.no_gt = false;
                    self.preproc_expression(eol);
                    self.no_gt = save_gt;
                    self.b.field_last("condition");
                }
                self.skip_tokens_until(eol);
                self.b.hidden(eol, end_incl);
                // body until #elif/#else/#endif
                loop {
                    let t2 = self.tok(0);
                    if t2.k == K::Eof {
                        break;
                    }
                    if t2.k == K::Preproc {
                        let d = self.src[t2.s..t2.e].replace([' ', '\t'], "");
                        if d == "#endif" {
                            let eol2 = self.line_end(t2.e);
                            self.advance();
                            self.b.leaf("#endif", false, t2.s, t2.e);
                            self.skip_tokens_until(eol2);
                            break;
                        }
                        if d == "#else" || d.starts_with("#elif") {
                            if kind == "preproc_elif" || kind == "preproc_elifdef" {
                                break;
                            }
                            let ma = self.b.mark();
                            if d == "#else" {
                                let eol2 = self.line_end(t2.e);
                                self.advance();
                                self.b.leaf("#else", false, t2.s, t2.e);
                                self.skip_tokens_until(eol2);
                                loop {
                                    let t3 = self.tok(0);
                                    if t3.k == K::Eof {
                                        break;
                                    }
                                    if t3.k == K::Preproc && self.src[t3.s..t3.e].replace([' ', '\t'], "") == "#endif" {
                                        break;
                                    }
                                    let before = self.i;
                                    self.body_item(in_body);
                                    if self.i == before {
                                        self.error_token();
                                    }
                                }
                                self.b.wrap(ma, "preproc_else", true);
                            } else {
                                self.preproc(in_body);
                            }
                            self.b.field_last("alternative");
                            continue;
                        }
                    }
                    let before = self.i;
                    self.body_item(in_body);
                    if self.i == before {
                        self.error_token();
                    }
                }
                self.b.wrap(m, kind, true);
            }
            _ => {
                self.advance();
                let mm = self.b.mark();
                self.b.leaf("preproc_directive", true, t.s, t.e);
                let _ = mm;
                self.b.field_last("directive");
                let from = t.e;
                self.skip_tokens_until(eol);
                let b = self.src.as_bytes();
                let mut s = from;
                while s < eol && (b[s] == b' ' || b[s] == b'\t') {
                    s += 1;
                }
                let mut e = eol;
                while e > s && (b[e - 1] == b' ' || b[e - 1] == b'\t' || b[e - 1] == b'\r') {
                    e -= 1;
                }
                if e > s {
                    self.b.leaf("preproc_arg", true, s, e);
                    self.b.field_last("argument");
                }
                self.b.hidden(eol, end_incl);
                self.b.wrap(m, "preproc_call", true);
            }
        }
    }

    fn flush_extras_before(&mut self, _eol: usize) {}

    fn preproc_expression(&mut self, eol: usize) {
        // limited: parse expression tokens on this line
        let m = self.b.mark();
        if self.at("defined") {
            self.bump();
            let paren = self.eat("(");
            self.bump_named("identifier");
            if paren {
                self.expect(")");
            }
            self.b.wrap(m, "preproc_defined", true);
        } else {
            self.unary_c();
        }
        while self.tok(0).s < eol && self.binop().is_some() {
            let (p, _) = self.binop().unwrap();
            let _ = p;
            self.b.field_last("left");
            self.bump();
            self.b.field_last("operator");
            let mr = self.b.mark();
            if self.at("defined") {
                self.bump();
                let paren = self.eat("(");
                self.bump_named("identifier");
                if paren {
                    self.expect(")");
                }
                self.b.wrap(mr, "preproc_defined", true);
            } else {
                self.unary_c();
            }
            self.b.field_last("right");
            self.b.wrap(m, "binary_expression", true);
        }
    }

    fn body_item(&mut self, in_body: &str) {
        match in_body {
            "field" => self.field_member(),
            "stmt" => self.statement(),
            _ => self.top_item(),
        }
    }

    // ---------- top level ----------
    fn top_item(&mut self) {
        if self.k() == K::Preproc {
            self.preproc("top");
            return;
        }
        let m = self.b.mark();
        if self.cpp {
            if self.cpp_top(m) {
                return;
            }
        }
        if self.at(";") {
            self.bump();
            return;
        }
        if self.is_declaration_start() {
            self.declaration_or_definition(m, false);
            return;
        }
        self.statement();
    }

    fn cpp_top(&mut self, m: usize) -> bool {
        match self.tx() {
            "namespace" => {
                self.bump();
                if self.k() == K::Ident {
                    let mn = self.b.mark();
                    self.bump_named("namespace_identifier");
                    while self.at("::") {
                        self.bump();
                        self.bump_named("namespace_identifier");
                        self.b.wrap(mn, "nested_namespace_specifier", true);
                    }
                    self.b.field_last("name");
                }
                if self.at("=") {
                    self.bump();
                    self.qualified_name(true);
                    self.expect(";");
                    self.b.wrap(m, "namespace_alias_definition", true);
                    return true;
                }
                self.declaration_list();
                self.b.field_last("body");
                self.b.wrap(m, "namespace_definition", true);
                true
            }
            "template" if self.txn(1) == "<" => {
                self.bump();
                self.template_parameter_list();
                self.b.field_last("parameters");
                if self.at("class") || self.at("struct") {
                    // template class
                }
                let mi = self.b.mark();
                if !self.cpp_top(mi) {
                    self.declaration_or_definition(mi, false);
                }
                self.b.wrap(m, "template_declaration", true);
                true
            }
            "using" => {
                self.bump();
                if self.at("namespace") {
                    self.bump();
                    self.qualified_name(true);
                    self.expect(";");
                    self.b.wrap(m, "using_declaration", true);
                    return true;
                }
                if self.k() == K::Ident && self.txn(1) == "=" {
                    self.bump_named("type_identifier");
                    self.b.field_last("name");
                    self.bump();
                    let mt = self.b.mark();
                    self.type_specifiers();
                    self.abstract_declarator_opt();
                    self.b.wrap(mt, "type_descriptor", true);
                    self.b.field_last("type");
                    self.expect(";");
                    self.b.wrap(m, "alias_declaration", true);
                    return true;
                }
                self.qualified_name(false);
                self.expect(";");
                self.b.wrap(m, "using_declaration", true);
                true
            }
            "extern" if self.tok(1).k == K::Str => {
                self.bump();
                self.string_literal();
                self.b.field_last("value");
                if self.at("{") {
                    self.declaration_list();
                    self.b.field_last("body");
                } else {
                    let mi = self.b.mark();
                    self.declaration_or_definition(mi, false);
                    self.b.field_last("body");
                }
                self.b.wrap(m, "linkage_specification", true);
                true
            }
            _ => false,
        }
    }

    fn declaration_list(&mut self) {
        let m = self.b.mark();
        self.expect("{");
        while !self.at("}") && self.k() != K::Eof {
            let before = self.i;
            self.top_item();
            if self.i == before {
                self.error_token();
            }
        }
        self.expect("}");
        self.b.wrap(m, "declaration_list", true);
    }

    fn template_parameter_list(&mut self) {
        let m = self.b.mark();
        self.bump(); // <
        let save = self.no_gt;
        self.no_gt = true;
        while !self.at(">") && self.k() != K::Eof {
            let mp = self.b.mark();
            if self.at("typename") || self.at("class") {
                self.bump();
                let variadic = self.eat("...");
                if self.k() == K::Ident {
                    self.bump_named("type_identifier");
                }
                if self.at("=") {
                    self.bump();
                    let mt = self.b.mark();
                    self.type_specifiers();
                    self.abstract_declarator_opt();
                    self.b.wrap(mt, "type_descriptor", true);
                    self.b.field_last("default_type");
                    self.b.wrap(mp, "optional_type_parameter_declaration", true);
                } else {
                    self.b.wrap(mp, if variadic { "variadic_type_parameter_declaration" } else { "type_parameter_declaration" }, true);
                }
            } else {
                self.type_specifiers();
                self.b.field_last("type");
                self.declarator(false, false);
                self.b.field_last("declarator");
                if self.at("=") {
                    self.bump();
                    self.ternary_c();
                    self.b.field_last("default_value");
                    self.b.wrap(mp, "optional_parameter_declaration", true);
                } else {
                    self.b.wrap(mp, "parameter_declaration", true);
                }
            }
            if !self.eat(",") {
                break;
            }
        }
        self.no_gt = save;
        self.expect(">");
        self.b.wrap(m, "template_parameter_list", true);
    }

    fn is_type_keyword(&self, s: &str) -> bool {
        is_primitive(s)
            || matches!(
                s,
                "signed" | "unsigned" | "long" | "short" | "struct" | "union" | "enum" | "const" | "volatile" | "restrict"
                    | "static" | "extern" | "register" | "inline" | "auto" | "_Atomic" | "__inline" | "thread_local"
                    | "_Thread_local" | "typedef" | "__restrict" | "_Noreturn" | "noreturn"
            )
            || (self.cpp && matches!(s, "class" | "virtual" | "explicit" | "constexpr" | "typename" | "friend" | "mutable" | "consteval" | "decltype"))
    }

    fn is_declaration_start(&self) -> bool {
        let t = self.tok(0);
        let tx = self.tx();
        if t.k != K::Ident && !(self.cpp && (tx == "::" || tx == "~")) {
            return false;
        }
        if self.is_type_keyword(tx) {
            return true;
        }
        if matches!(tx, "return" | "if" | "while" | "for" | "do" | "switch" | "case" | "default" | "break" | "continue" | "goto" | "sizeof" | "else" | "delete" | "new" | "throw" | "this" | "true" | "false" | "nullptr" | "co_return" | "co_await" | "co_yield") {
            return false;
        }
        // Ident (::Ident)* (<...>)? followed by declarator start
        let mut j = 0;
        if self.cpp {
            if self.txn(0) == "::" {
                j += 1;
            }
            loop {
                if self.tok(j).k != K::Ident {
                    return false;
                }
                j += 1;
                if self.txn(j) == "<" {
                    // skip template args
                    let mut depth = 0;
                    loop {
                        let x = self.txn(j);
                        if x.is_empty() || x == ";" || x == "{" {
                            return false;
                        }
                        if x == "<" {
                            depth += 1;
                        } else if x == ">" {
                            depth -= 1;
                            if depth == 0 {
                                j += 1;
                                break;
                            }
                        } else if x == ">>" {
                            depth -= 2;
                            if depth <= 0 {
                                j += 1;
                                break;
                            }
                        }
                        j += 1;
                    }
                }
                if self.txn(j) == "::" {
                    j += 1;
                    if self.txn(j) == "~" {
                        return true;
                    }
                    continue;
                }
                break;
            }
            // constructor-like: Name::Name( or Name( at top
        } else {
            j = 1;
        }
        let nt = self.tok(j);
        let nx = self.txn(j);
        if nt.k == K::Ident {
            return !matches!(nx, "if" | "else");
        }
        if nx == "*" || (self.cpp && (nx == "&" || nx == "&&")) {
            // T * x  -> declaration if followed by ident and then ; = , [ ) (
            let mut k = j;
            while matches!(self.txn(k), "*" | "&" | "&&" | "const" | "volatile") {
                k += 1;
            }
            return self.tok(k).k == K::Ident && matches!(self.txn(k + 1), ";" | "=" | "," | "[" | ")" | "(" | "{" | ":");
        }
        if nx == "(" && self.txn(j + 1) == "*" {
            // T (*fp)(...)
            return true;
        }
        if self.cpp && j > 1 && nx == "(" {
            // qualified constructor definition A::A(...)
            let x0 = self.txn(0);
            let xl = self.txn(j - 1);
            return x0 == xl && self.txn(1) == "::";
        }
        false
    }

    fn type_specifiers(&mut self) -> bool {
        // parses leading qualifiers/storage + type specifier + trailing qualifiers
        // returns whether a type was found
        let mut found = false;
        loop {
            let tx = self.tx();
            if self.k() != K::Ident && !(self.cpp && tx == "::") {
                break;
            }
            match tx {
                "const" | "volatile" | "restrict" | "_Atomic" | "__restrict" | "constexpr" | "mutable" | "constinit" | "consteval" => {
                    if tx == "_Atomic" && self.txn(1) == "(" {
                        break;
                    }
                    self.wrap_kw("type_qualifier");
                }
                "static" | "extern" | "register" | "inline" | "auto" | "thread_local" | "_Thread_local" | "__inline" => {
                    if tx == "auto" && self.cpp {
                        if found {
                            break;
                        }
                        let ma = self.b.mark();
                        self.bump();
                        self.b.wrap(ma, "placeholder_type_specifier", true);
                        self.b.field_last("type");
                        found = true;
                        continue;
                    }
                    self.wrap_kw("storage_class_specifier");
                }
                "virtual" | "explicit" | "friend" if self.cpp => {
                    if tx == "virtual" {
                        self.wrap_kw("virtual");
                    } else if tx == "explicit" {
                        self.wrap_kw("explicit_function_specifier");
                    } else {
                        self.bump();
                    }
                }
                "signed" | "unsigned" | "long" | "short" if !found => {
                    let m = self.b.mark();
                    while matches!(self.tx(), "signed" | "unsigned" | "long" | "short") {
                        self.bump();
                    }
                    if self.k() == K::Ident && is_primitive(self.tx()) {
                        self.bump_named("primitive_type");
                        self.b.field_last("type");
                    }
                    self.b.wrap(m, "sized_type_specifier", true);
                    self.b.field_last("type");
                    found = true;
                }
                "struct" | "union" | "enum" | "class" if !found => {
                    self.struct_like();
                    self.b.field_last("type");
                    found = true;
                }
                _ => {
                    if found {
                        break;
                    }
                    if is_primitive(tx) {
                        self.bump_named("primitive_type");
                    } else if self.cpp {
                        if tx == "typename" {
                            self.bump();
                        }
                        if tx == "decltype" {
                            let md = self.b.mark();
                            self.bump();
                            self.expect("(");
                            self.expression();
                            self.expect(")");
                            self.b.wrap(md, "decltype", true);
                        } else {
                            self.qualified_name(true);
                        }
                    } else {
                        self.bump_named("type_identifier");
                    }
                    self.b.field_last("type");
                    found = true;
                }
            }
        }
        found
    }

    /// C++ qualified name: type context (type=true) gives type_identifier leaf
    fn qualified_name(&mut self, ty: bool) {
        let m = self.b.mark();
        if self.at("::") {
            self.bump();
            self.qualified_name(ty);
            self.b.field_last("name");
            self.b.wrap(m, "qualified_identifier", true);
            return;
        }
        // first segment
        let is_scope = |p: &P| -> bool {
            // ident followed by :: (possibly after template args)
            if p.txn(1) == "::" {
                return true;
            }
            if p.txn(1) == "<" {
                let mut depth = 0;
                let mut j = 1;
                loop {
                    let x = p.txn(j);
                    if x.is_empty() || x == ";" || x == "{" {
                        return false;
                    }
                    if x == "<" {
                        depth += 1;
                    } else if x == ">" {
                        depth -= 1;
                        if depth == 0 {
                            return p.txn(j + 1) == "::";
                        }
                    }
                    j += 1;
                }
            }
            false
        };
        if self.k() == K::Ident && is_scope(self) {
            let ms = self.b.mark();
            if self.txn(1) == "<" {
                self.bump_named("type_identifier");
                self.b.field_last("name");
                self.template_argument_list();
                self.b.field_last("arguments");
                self.b.wrap(ms, "template_type", true);
            } else {
                self.bump_named("namespace_identifier");
            }
            self.b.field_last("scope");
            self.bump(); // ::
            if self.at("~") {
                let md = self.b.mark();
                self.bump();
                self.bump_named("identifier");
                self.b.wrap(md, "destructor_name", true);
            } else if self.at("template") {
                self.bump();
                self.qualified_name(ty);
            } else {
                self.qualified_name(ty);
            }
            self.b.field_last("name");
            self.b.wrap(m, "qualified_identifier", true);
            return;
        }
        if self.k() == K::Ident {
            if ty {
                if is_primitive(self.tx()) {
                    self.bump_named("primitive_type");
                    return;
                }
                self.bump_named("type_identifier");
                if self.at("<") {
                    self.b.field_last("name");
                    self.template_argument_list();
                    self.b.field_last("arguments");
                    self.b.wrap(m, "template_type", true);
                }
            } else {
                if self.at("operator") {
                    self.operator_name();
                    return;
                }
                self.bump_named("identifier");
                if self.at("<") && self.template_args_ahead() {
                    self.b.field_last("name");
                    self.template_argument_list();
                    self.b.field_last("arguments");
                    self.b.wrap(m, "template_function", true);
                }
            }
        } else {
            let p = self.cur_pos();
            self.b.missing("identifier", true, p);
        }
    }

    fn operator_name(&mut self) {
        let m = self.b.mark();
        self.bump(); // operator
        if self.at("(") && self.txn(1) == ")" {
            self.bump();
            self.bump();
        } else if self.at("[") && self.txn(1) == "]" {
            self.bump();
            self.bump();
        } else if self.k() == K::Op {
            self.bump();
        } else {
            self.type_specifiers();
        }
        self.b.wrap(m, "operator_name", true);
    }

    fn template_args_ahead(&self) -> bool {
        let mut depth = 0;
        let mut j = 0;
        loop {
            let x = self.txn(j);
            let t = self.tok(j);
            if t.k == K::Eof || matches!(x, ";" | "{" | "}" | "&&" | "||") {
                return false;
            }
            if x == "<" {
                depth += 1;
            } else if x == ">" {
                depth -= 1;
                if depth == 0 {
                    return matches!(self.txn(j + 1), "(" | "::" | "{" | ")" | ";" | "," | ">" | "");
                }
            } else if x == ">>" {
                depth -= 2;
                if depth <= 0 {
                    return true;
                }
            }
            j += 1;
        }
    }

    fn template_argument_list(&mut self) {
        let m = self.b.mark();
        self.bump(); // <
        let save = self.no_gt;
        self.no_gt = true;
        while !self.at(">") && !self.at(">>") && self.k() != K::Eof {
            // type or expression
            if self.is_type_arg() {
                let mt = self.b.mark();
                self.type_specifiers();
                self.abstract_declarator_opt();
                self.b.wrap(mt, "type_descriptor", true);
            } else {
                self.ternary_c();
            }
            if !self.eat(",") {
                break;
            }
        }
        self.no_gt = save;
        if self.at(">>") {
            let t = self.advance();
            self.b.leaf(">", false, t.s, t.s + 1);
            // push back a '>' token
            self.i -= 1;
            self.toks[self.i] = Tk { k: K::Op, s: t.s + 1, e: t.e };
        } else {
            self.expect(">");
        }
        self.b.wrap(m, "template_argument_list", true);
    }

    fn is_type_arg(&self) -> bool {
        let tx = self.tx();
        if self.k() != K::Ident {
            return tx == "::";
        }
        if self.is_type_keyword(tx) {
            return true;
        }
        let n = self.txn(1);
        matches!(n, ">" | "," | "<" | "::" | "*" | "&" | ">>") && !matches!(tx, "true" | "false" | "nullptr")
    }

    fn struct_like(&mut self) {
        let m = self.b.mark();
        let kw = self.tx();
        self.bump();
        if kw == "enum" && (self.at("class") || self.at("struct")) {
            self.bump();
        }
        while self.at("__attribute__") || (self.cpp && self.at("[") && self.txn(1) == "[") {
            self.skip_attribute();
        }
        if self.k() == K::Ident {
            if self.cpp {
                self.qualified_name(true);
            } else {
                self.bump_named("type_identifier");
            }
            self.b.field_last("name");
        }
        if self.cpp && self.at("final") {
            self.wrap_kw("virtual_specifier");
        }
        if kw == "enum" && self.at(":") {
            self.bump();
            self.type_specifiers();
            self.b.field_last("base");
        }
        if self.cpp && self.at(":") && kw != "enum" {
            let mb = self.b.mark();
            self.bump();
            loop {
                if matches!(self.tx(), "public" | "private" | "protected") {
                    self.wrap_kw("access_specifier");
                }
                if self.at("virtual") {
                    self.wrap_kw("virtual");
                }
                if matches!(self.tx(), "public" | "private" | "protected") {
                    self.wrap_kw("access_specifier");
                }
                self.qualified_name(true);
                if !self.eat(",") {
                    break;
                }
            }
            self.b.wrap(mb, "base_class_clause", true);
        }
        if self.at("{") {
            if kw == "enum" {
                let ml = self.b.mark();
                self.bump();
                while !self.at("}") && self.k() != K::Eof {
                    let me = self.b.mark();
                    self.bump_named("identifier");
                    self.b.field_last("name");
                    if self.eat("=") {
                        self.ternary_c();
                        self.b.field_last("value");
                    }
                    self.b.wrap(me, "enumerator", true);
                    if !self.eat(",") {
                        break;
                    }
                }
                self.expect("}");
                self.b.wrap(ml, "enumerator_list", true);
            } else {
                self.field_declaration_list();
            }
            self.b.field_last("body");
        }
        let kind = match kw {
            "struct" => "struct_specifier",
            "union" => "union_specifier",
            "enum" => "enum_specifier",
            _ => "class_specifier",
        };
        self.b.wrap(m, kind, true);
    }

    fn skip_attribute(&mut self) {
        let m = self.b.mark();
        if self.at("__attribute__") {
            self.bump();
            self.bump();
            let mut depth = 1;
            while depth > 0 && self.k() != K::Eof {
                if self.at("(") {
                    depth += 1;
                } else if self.at(")") {
                    depth -= 1;
                }
                self.bump();
            }
            self.b.wrap(m, "attribute_specifier", true);
        } else {
            self.bump();
            self.bump();
            while !(self.at("]") && self.txn(1) == "]") && self.k() != K::Eof {
                self.bump();
            }
            self.bump();
            self.bump();
            self.b.wrap(m, "attribute_declaration", true);
        }
    }

    fn field_declaration_list(&mut self) {
        let m = self.b.mark();
        self.bump(); // {
        while !self.at("}") && self.k() != K::Eof {
            let before = self.i;
            self.field_member();
            if self.i == before {
                self.error_token();
            }
        }
        self.expect("}");
        self.b.wrap(m, "field_declaration_list", true);
    }

    fn field_member(&mut self) {
        if self.k() == K::Preproc {
            self.preproc("field");
            return;
        }
        let m = self.b.mark();
        if self.cpp && matches!(self.tx(), "public" | "private" | "protected") && self.txn(1) == ":" {
            self.wrap_kw("access_specifier");
            self.bump();
            return;
        }
        if self.at(";") {
            self.bump();
            return;
        }
        if self.cpp && self.at("template") {
            self.cpp_top(m);
            return;
        }
        if self.cpp && self.at("using") {
            self.cpp_top(m);
            return;
        }
        if self.cpp && self.at("friend") {
            self.bump();
            self.declaration_or_definition(m, true);
            let id = self.b.last().unwrap();
            let _ = id;
            self.b.wrap(m, "friend_declaration", true);
            return;
        }
        // constructor / destructor without type
        let ctor = self.cpp
            && ((self.k() == K::Ident && self.txn(1) == "(" && !self.is_type_keyword(self.tx()))
                || self.at("~")
                || (matches!(self.tx(), "explicit" | "virtual" | "inline" | "constexpr") && (self.txn(2) == "(" || self.txn(1) == "~")));
        if ctor {
            let mut has_spec = false;
            while matches!(self.tx(), "explicit" | "virtual" | "inline" | "constexpr") {
                match self.tx() {
                    "virtual" => self.wrap_kw("virtual"),
                    "explicit" => self.wrap_kw("explicit_function_specifier"),
                    "inline" => self.wrap_kw("storage_class_specifier"),
                    _ => self.wrap_kw("type_qualifier"),
                }
                has_spec = true;
            }
            let _ = has_spec;
            self.declarator(false, true);
            self.b.field_last("declarator");
            self.function_tail(m, true);
            return;
        }
        self.type_specifiers();
        if self.at(";") {
            self.bump();
            self.b.wrap(m, "field_declaration", true);
            return;
        }
        loop {
            if self.at(":") {
                // bitfield without name
                let mb = self.b.mark();
                self.bump();
                self.ternary_c();
                self.b.wrap(mb, "bitfield_clause", true);
            } else {
                self.declarator(true, false);
                self.b.field_last("declarator");
            }
            if self.at(":") {
                let mb = self.b.mark();
                self.bump();
                self.ternary_c();
                self.b.wrap(mb, "bitfield_clause", true);
            }
            if self.at("=") {
                self.bump();
                if self.at("{") {
                    self.initializer_list();
                } else if self.cpp && (self.at("default") || self.at("delete")) {
                    self.wrap_kw(if self.at("default") { "default_method_clause" } else { "delete_method_clause" });
                    self.expect(";");
                    self.b.wrap(m, "field_declaration", true);
                    return;
                } else {
                    self.ternary_c();
                }
                self.b.field_last("default_value");
            } else if self.cpp && self.at("{") && !self.last_is_function_declarator() {
                self.initializer_list();
                self.b.field_last("default_value");
            }
            if self.at("{") && self.last_is_function_declarator() {
                // inline method definition
                self.function_body(m);
                return;
            }
            if self.cpp && self.at(":") {
                break;
            }
            if !self.eat(",") {
                break;
            }
        }
        if self.cpp && self.at("=") && false {
        }
        self.expect(";");
        self.b.wrap(m, "field_declaration", true);
    }

    fn last_is_function_declarator(&self) -> bool {
        if let Some(l) = self.b.last() {
            let mut id = l;
            loop {
                let n = &self.b.nodes[id as usize];
                if n.kind == "function_declarator" {
                    return true;
                }
                if matches!(n.kind, "pointer_declarator" | "reference_declarator") {
                    if let Some(&c) = n.children.iter().rev().find(|&&c| self.b.nodes[c as usize].field == Some("declarator") || self.b.nodes[c as usize].named) {
                        id = c;
                        continue;
                    }
                }
                return false;
            }
        }
        false
    }

    fn function_body(&mut self, m: usize) {
        self.compound_statement();
        self.b.field_last("body");
        self.b.wrap(m, "function_definition", true);
    }

    fn function_tail(&mut self, m: usize, ctor: bool) {
        if self.cpp && self.at(":") && ctor {
            let mi = self.b.mark();
            self.bump();
            loop {
                let mf = self.b.mark();
                self.qualified_name(false);
                let id = self.b.last().unwrap();
                if self.b.nodes[id as usize].kind == "identifier" {
                    self.b.rename(id, "field_identifier");
                }
                if self.at("(") {
                    self.argument_list();
                } else if self.at("{") {
                    self.initializer_list();
                }
                self.b.wrap(mf, "field_initializer", true);
                if !self.eat(",") {
                    break;
                }
            }
            self.b.wrap(mi, "field_initializer_list", true);
        }
        if self.at("{") {
            self.compound_statement();
            self.b.field_last("body");
            self.b.wrap(m, "function_definition", true);
        } else if self.at("=") && self.cpp && (self.txn(1) == "default" || self.txn(1) == "delete") {
            self.bump();
            let k = if self.at("default") { "default_method_clause" } else { "delete_method_clause" };
            self.wrap_kw(k);
            self.expect(";");
            self.b.wrap(m, "function_definition", true);
        } else {
            self.expect(";");
            self.b.wrap(m, "declaration", true);
        }
    }

    fn declaration_or_definition(&mut self, m: usize, in_class: bool) {
        let _ = in_class;
        if self.at("typedef") {
            self.bump();
            self.type_specifiers();
            loop {
                self.declarator_typedef();
                self.b.field_last("declarator");
                if !self.eat(",") {
                    break;
                }
            }
            self.expect(";");
            self.b.wrap(m, "type_definition", true);
            return;
        }
        let found = self.type_specifiers();
        if !found && self.cpp {
            // constructor definition A::A(...)
        }
        if self.at(";") {
            // type specifier alone at top-level: node stays as specifier, ';' sibling
            let only_spec = self.b.mark() == m + 1
                && matches!(self.b.nodes[self.b.stack[m] as usize].kind, "struct_specifier" | "union_specifier" | "enum_specifier" | "class_specifier");
            if only_spec {
                self.b.nodes[self.b.stack[m] as usize].field = None;
                self.bump();
                return;
            }
            self.bump();
            self.b.wrap(m, "declaration", true);
            return;
        }
        let mut first = true;
        loop {
            let md = self.b.mark();
            self.declarator(false, false);
            if first && self.at("{") && self.last_is_function_declarator() {
                self.b.field_last("declarator");
                self.compound_statement();
                self.b.field_last("body");
                self.b.wrap(m, "function_definition", true);
                return;
            }
            if first && self.cpp && self.at(":") && self.last_is_function_declarator() {
                self.b.field_last("declarator");
                self.function_tail(m, true);
                return;
            }
            if first && self.cpp && self.at("=") && matches!(self.txn(1), "default" | "delete") && self.last_is_function_declarator() {
                self.b.field_last("declarator");
                self.function_tail(m, false);
                return;
            }
            first = false;
            if self.at("=") {
                self.bump();
                if self.at("{") {
                    self.initializer_list();
                } else {
                    self.assignment_c();
                }
                self.b.field_last("value");
                self.set_field_first(md, "declarator");
                self.b.wrap(md, "init_declarator", true);
            } else if self.cpp && self.at("{") {
                self.initializer_list();
                self.b.field_last("value");
                self.set_field_first(md, "declarator");
                self.b.wrap(md, "init_declarator", true);
            } else if self.cpp && self.at("(") && !self.last_is_function_declarator() {
                self.argument_list();
                self.b.field_last("value");
                self.set_field_first(md, "declarator");
                self.b.wrap(md, "init_declarator", true);
            }
            self.b.field_last("declarator");
            if !self.eat(",") {
                break;
            }
        }
        self.expect(";");
        self.b.wrap(m, "declaration", true);
    }

    fn declarator_typedef(&mut self) {
        // typedef names: primitive names stay primitive_type
        let m = self.b.mark();
        if self.at("*") {
            self.bump();
            while matches!(self.tx(), "const" | "volatile" | "restrict") {
                self.wrap_kw("type_qualifier");
            }
            self.declarator_typedef();
            self.b.field_last("declarator");
            self.b.wrap(m, "pointer_declarator", true);
            return;
        }
        if self.at("(") {
            self.bump();
            self.declarator_typedef();
            self.expect(")");
            self.b.wrap(m, "parenthesized_declarator", true);
        } else if self.k() == K::Ident {
            if is_primitive(self.tx()) {
                self.bump_named("primitive_type");
            } else {
                self.bump_named("type_identifier");
            }
        }
        self.declarator_suffix(m);
    }

    /// declarator: field=true uses field_identifier
    fn declarator(&mut self, field: bool, allow_ctor: bool) {
        let m = self.b.mark();
        let tx = self.tx();
        match tx {
            "*" => {
                self.bump();
                while matches!(self.tx(), "const" | "volatile" | "restrict" | "__restrict" | "_Atomic") {
                    self.wrap_kw("type_qualifier");
                }
                self.declarator(field, allow_ctor);
                self.b.field_last("declarator");
                self.b.wrap(m, "pointer_declarator", true);
                return;
            }
            "&" | "&&" if self.cpp => {
                self.bump();
                self.declarator(field, allow_ctor);
                self.b.wrap(m, "reference_declarator", true);
                return;
            }
            "(" => {
                self.bump();
                self.declarator(field, allow_ctor);
                self.expect(")");
                self.b.wrap(m, "parenthesized_declarator", true);
            }
            "..." if self.cpp => {
                self.bump();
                self.declarator(field, allow_ctor);
                self.b.wrap(m, "variadic_declarator", true);
                return;
            }
            "~" if self.cpp => {
                let md = self.b.mark();
                self.bump();
                self.bump_named("identifier");
                self.b.wrap(md, "destructor_name", true);
            }
            _ => {
                if self.k() == K::Ident || (self.cpp && tx == "::") {
                    if field && !(self.cpp && self.txn(1) == "::") {
                        if self.cpp && self.at("operator") {
                            self.operator_name();
                        } else {
                            self.bump_named("field_identifier");
                        }
                    } else if self.cpp {
                        self.qualified_name(false);
                    } else {
                        self.bump_named("identifier");
                    }
                } else {
                    let p = self.cur_pos();
                    let _ = p;
                    return;
                }
            }
        }
        self.declarator_suffix(m);
    }

    fn declarator_suffix(&mut self, m: usize) {
        loop {
            if self.at("(") {
                self.set_field_first(m, "declarator");
                self.parameter_list();
                self.b.field_last("parameters");
                // trailing qualifiers
                while self.cpp && matches!(self.tx(), "const" | "volatile" | "noexcept" | "override" | "final" | "&" | "&&" | "throw" | "->") {
                    match self.tx() {
                        "const" | "volatile" => self.wrap_kw("type_qualifier"),
                        "override" | "final" => self.wrap_kw("virtual_specifier"),
                        "noexcept" => {
                            let mn = self.b.mark();
                            self.bump();
                            if self.at("(") {
                                self.bump();
                                self.expression();
                                self.expect(")");
                            }
                            self.b.wrap(mn, "noexcept", true);
                        }
                        "->" => {
                            let mt = self.b.mark();
                            self.bump();
                            let md = self.b.mark();
                            self.type_specifiers();
                            self.abstract_declarator_opt();
                            self.b.wrap(md, "type_descriptor", true);
                            self.b.wrap(mt, "trailing_return_type", true);
                        }
                        _ => {
                            self.bump();
                        }
                    }
                }
                self.b.wrap(m, "function_declarator", true);
                continue;
            }
            if self.at("[") {
                self.set_field_first(m, "declarator");
                self.bump();
                while matches!(self.tx(), "const" | "volatile" | "restrict" | "static") {
                    self.wrap_kw(if self.at("static") { "storage_class_specifier" } else { "type_qualifier" });
                }
                if !self.at("]") {
                    self.expression();
                    self.b.field_last("size");
                }
                self.expect("]");
                self.b.wrap(m, "array_declarator", true);
                continue;
            }
            break;
        }
    }

    fn parameter_list(&mut self) {
        let m = self.b.mark();
        self.bump(); // (
        while !self.at(")") && self.k() != K::Eof {
            let mp = self.b.mark();
            if self.at("...") {
                self.bump();
            } else {
                self.type_specifiers();
                if !self.at(",") && !self.at(")") && !self.at("=") {
                    if self.is_abstract_declarator_start() {
                        self.abstract_declarator_opt();
                    } else {
                        self.declarator(false, false);
                        self.b.field_last("declarator");
                    }
                }
                if self.cpp && self.at("=") {
                    self.bump();
                    self.ternary_c();
                    self.b.field_last("default_value");
                    self.b.wrap(mp, "optional_parameter_declaration", true);
                } else {
                    self.b.wrap(mp, "parameter_declaration", true);
                }
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect(")");
        self.b.wrap(m, "parameter_list", true);
    }

    fn is_abstract_declarator_start(&self) -> bool {
        // * followed by ) or , or another * ; [ ; ( *)
        let mut j = 0;
        while matches!(self.txn(j), "*" | "&" | "&&" | "const" | "volatile") {
            j += 1;
        }
        let x = self.txn(j);
        (j > 0 && matches!(x, ")" | "," | "[" | ">" | "")) || (j == 0 && x == "[") || (x == "(" && self.txn(j + 1) == "*" && matches!(self.txn(j + 2), ")"))
    }

    fn abstract_declarator_opt(&mut self) {
        let m = self.b.mark();
        if self.at("*") {
            self.bump();
            while matches!(self.tx(), "const" | "volatile" | "restrict") {
                self.wrap_kw("type_qualifier");
            }
            if matches!(self.tx(), "*" | "[" | "(") {
                self.abstract_declarator_opt();
                self.b.field_last("declarator");
            }
            self.b.wrap(m, "abstract_pointer_declarator", true);
            return;
        }
        if self.cpp && (self.at("&") || self.at("&&")) {
            self.bump();
            if matches!(self.tx(), "*" | "[") {
                self.abstract_declarator_opt();
            }
            self.b.wrap(m, "abstract_reference_declarator", true);
            return;
        }
        if self.at("[") {
            self.bump();
            if !self.at("]") {
                self.expression();
                self.b.field_last("size");
            }
            self.expect("]");
            self.b.wrap(m, "abstract_array_declarator", true);
            return;
        }
        if self.at("(") && self.txn(1) == "*" {
            self.bump();
            self.abstract_declarator_opt();
            self.expect(")");
            self.b.wrap(m, "abstract_parenthesized_declarator", true);
            if self.at("(") {
                self.set_field_first(m, "declarator");
                self.parameter_list();
                self.b.field_last("parameters");
                self.b.wrap(m, "abstract_function_declarator", true);
            }
        }
    }

    fn initializer_list(&mut self) {
        let m = self.b.mark();
        self.bump(); // {
        while !self.at("}") && self.k() != K::Eof {
            let mi = self.b.mark();
            if self.at(".") || (self.at("[") && !self.cpp) {
                // designators
                while self.at(".") || self.at("[") {
                    let md = self.b.mark();
                    if self.at(".") {
                        self.bump();
                        self.bump_named("field_identifier");
                        self.b.wrap(md, "field_designator", true);
                    } else {
                        self.bump();
                        self.expression();
                        self.expect("]");
                        self.b.wrap(md, "subscript_designator", true);
                    }
                    self.b.field_last("designator");
                }
                self.expect("=");
                if self.at("{") {
                    self.initializer_list();
                } else {
                    self.assignment_c();
                }
                self.b.field_last("value");
                self.b.wrap(mi, "initializer_pair", true);
            } else if self.at("{") {
                self.initializer_list();
            } else {
                self.assignment_c();
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect("}");
        self.b.wrap(m, "initializer_list", true);
    }

    // ---------- statements ----------
    fn compound_statement(&mut self) {
        let m = self.b.mark();
        self.expect("{");
        while !self.at("}") && self.k() != K::Eof {
            let before = self.i;
            if self.k() == K::Preproc {
                self.preproc("stmt");
            } else {
                self.statement();
            }
            if self.i == before {
                self.error_token();
            }
        }
        self.expect("}");
        self.b.wrap(m, "compound_statement", true);
    }

    fn paren_expr(&mut self) {
        let m = self.b.mark();
        self.expect("(");
        if self.cpp && self.is_declaration_start() {
            // condition declaration
            let md = self.b.mark();
            self.type_specifiers();
            self.declarator(false, false);
            self.b.field_last("declarator");
            if self.eat("=") {
                self.expression();
                self.b.field_last("value");
            }
            self.b.wrap(md, "condition_clause", true);
        } else {
            self.expression();
        }
        self.expect(")");
        let k = if self.cpp { "condition_clause" } else { "parenthesized_expression" };
        self.b.wrap(m, k, true);
    }

    fn statement(&mut self) {
        let m = self.b.mark();
        let tx = self.tx();
        if self.k() == K::Preproc {
            self.preproc("stmt");
            return;
        }
        if self.at("{") {
            self.compound_statement();
            return;
        }
        if self.at(";") {
            self.bump();
            self.b.wrap(m, "expression_statement", true);
            return;
        }
        if self.k() == K::Ident {
            match tx {
                "if" => {
                    self.bump();
                    if self.cpp && self.at("constexpr") {
                        self.bump();
                    }
                    self.paren_expr();
                    self.b.field_last("condition");
                    self.statement();
                    self.b.field_last("consequence");
                    if self.at("else") {
                        let me = self.b.mark();
                        self.bump();
                        self.statement();
                        self.b.wrap(me, "else_clause", true);
                        self.b.field_last("alternative");
                    }
                    self.b.wrap(m, "if_statement", true);
                    return;
                }
                "while" => {
                    self.bump();
                    self.paren_expr();
                    self.b.field_last("condition");
                    self.statement();
                    self.b.field_last("body");
                    self.b.wrap(m, "while_statement", true);
                    return;
                }
                "do" => {
                    self.bump();
                    self.statement();
                    self.b.field_last("body");
                    self.expect("while");
                    let mp = self.b.mark();
                    self.expect("(");
                    self.expression();
                    self.expect(")");
                    self.b.wrap(mp, "parenthesized_expression", true);
                    self.b.field_last("condition");
                    self.expect(";");
                    self.b.wrap(m, "do_statement", true);
                    return;
                }
                "for" => return self.for_stmt(m),
                "switch" => {
                    self.bump();
                    self.paren_expr();
                    self.b.field_last("condition");
                    self.compound_statement_switch();
                    self.b.field_last("body");
                    self.b.wrap(m, "switch_statement", true);
                    return;
                }
                "case" | "default" => {
                    self.bump();
                    if tx == "case" {
                        self.expression();
                        self.b.field_last("value");
                    }
                    self.expect(":");
                    while !self.at("case") && !self.at("default") && !self.at("}") && self.k() != K::Eof {
                        let before = self.i;
                        self.statement();
                        if self.i == before {
                            self.error_token();
                        }
                    }
                    self.b.wrap(m, "case_statement", true);
                    return;
                }
                "return" | "co_return" => {
                    self.bump();
                    if !self.at(";") {
                        if self.cpp && self.at("{") {
                            self.initializer_list();
                        } else {
                            self.expression();
                        }
                    }
                    self.expect(";");
                    self.b.wrap(m, if tx == "return" { "return_statement" } else { "co_return_statement" }, true);
                    return;
                }
                "break" | "continue" => {
                    self.bump();
                    self.expect(";");
                    self.b.wrap(m, if tx == "break" { "break_statement" } else { "continue_statement" }, true);
                    return;
                }
                "goto" => {
                    self.bump();
                    self.bump_named("statement_identifier");
                    self.b.field_last("label");
                    self.expect(";");
                    self.b.wrap(m, "goto_statement", true);
                    return;
                }
                "try" if self.cpp => {
                    self.bump();
                    self.compound_statement();
                    self.b.field_last("body");
                    while self.at("catch") {
                        let mc = self.b.mark();
                        self.bump();
                        self.parameter_list();
                        self.b.field_last("parameters");
                        self.compound_statement();
                        self.b.field_last("body");
                        self.b.wrap(mc, "catch_clause", true);
                    }
                    self.b.wrap(m, "try_statement", true);
                    return;
                }
                "throw" if self.cpp => {
                    self.bump();
                    if !self.at(";") {
                        self.expression();
                    }
                    self.expect(";");
                    self.b.wrap(m, "throw_statement", true);
                    return;
                }
                _ => {
                    if self.txn(1) == ":" && !self.is_type_keyword(tx) && !matches!(tx, "public" | "private" | "protected") {
                        self.bump_named("statement_identifier");
                        self.b.field_last("label");
                        self.bump();
                        if !self.at("}") {
                            self.statement();
                        }
                        self.b.wrap(m, "labeled_statement", true);
                        return;
                    }
                }
            }
        }
        if self.cpp {
            let save = self.i;
            if self.cpp_top(m) {
                return;
            }
            self.i = save;
        }
        if self.at("typedef") || self.is_declaration_start() {
            self.declaration_or_definition(m, false);
            return;
        }
        self.expression();
        self.expect(";");
        self.b.wrap(m, "expression_statement", true);
    }

    fn compound_statement_switch(&mut self) {
        self.compound_statement();
    }

    fn for_stmt(&mut self, m: usize) {
        self.bump(); // for
        self.expect("(");
        // range-based for (C++)
        if self.cpp {
            let save = self.i;
            let cp = self.b.checkpoint();
            if self.is_declaration_start() {
                self.type_specifiers();
                self.declarator(false, false);
                if self.at(":") {
                    self.b.field_last("declarator");
                    self.bump();
                    if self.at("{") {
                        self.initializer_list();
                    } else {
                        self.expression();
                    }
                    self.b.field_last("right");
                    self.expect(")");
                    self.statement();
                    self.b.field_last("body");
                    self.b.wrap(m, "for_range_loop", true);
                    return;
                }
            }
            self.i = save;
            self.b.restore(cp);
        }
        if self.at(";") {
            self.bump();
        } else if self.is_declaration_start() {
            let md = self.b.mark();
            self.declaration_or_definition(md, false);
            self.b.field_last("initializer");
        } else {
            self.expression();
            self.b.field_last("initializer");
            self.expect(";");
        }
        if !self.at(";") {
            self.expression();
            self.b.field_last("condition");
        }
        self.expect(";");
        if !self.at(")") {
            self.expression();
            self.b.field_last("update");
        }
        self.expect(")");
        self.statement();
        self.b.field_last("body");
        self.b.wrap(m, "for_statement", true);
    }

    // ---------- expressions ----------
    fn expression(&mut self) {
        let m = self.b.mark();
        self.assignment_c();
        if self.at(",") {
            self.b.field_last("left");
            self.bump();
            self.expression();
            self.b.field_last("right");
            self.b.wrap(m, "comma_expression", true);
        }
    }

    fn assignment_c(&mut self) {
        self.depth += 1;
        if self.depth > 300 {
            self.error_token();
            self.depth -= 1;
            return;
        }
        let m = self.b.mark();
        self.ternary_c();
        let tx = self.tx();
        if self.k() == K::Op && matches!(tx, "=" | "+=" | "-=" | "*=" | "/=" | "%=" | "&=" | "|=" | "^=" | "<<=" | ">>=") {
            self.b.field_last("left");
            self.bump();
            self.b.field_last("operator");
            if self.cpp && self.at("{") {
                self.initializer_list();
            } else {
                self.assignment_c();
            }
            self.b.field_last("right");
            self.b.wrap(m, "assignment_expression", true);
        }
        self.depth -= 1;
    }

    fn ternary_c(&mut self) {
        let m = self.b.mark();
        self.binary_c(1);
        if self.at("?") {
            self.b.field_last("condition");
            self.bump();
            if !self.at(":") {
                self.expression();
                self.b.field_last("consequence");
            }
            self.expect(":");
            self.assignment_c();
            self.b.field_last("alternative");
            self.b.wrap(m, "conditional_expression", true);
        }
    }

    fn binop(&self) -> Option<(u8, bool)> {
        let t = self.tok(0);
        if t.k != K::Op {
            if self.cpp && t.k == K::Ident {
                return match self.tx() {
                    "and" | "or" | "bitand" | "bitor" | "xor" | "not_eq" => Some((if self.tx() == "or" { 1 } else { 2 }, false)),
                    _ => None,
                };
            }
            return None;
        }
        Some(match self.tx() {
            "||" => (1, false),
            "&&" => (2, false),
            "|" => (3, false),
            "^" => (4, false),
            "&" => (5, false),
            "==" | "!=" => (6, false),
            "<" | "<=" | ">=" => (7, false),
            ">" if !self.no_gt => (7, false),
            "<=>" => (7, false),
            "<<" => (9, false),
            ">>" if !self.no_gt => (9, false),
            "+" | "-" => (10, false),
            "*" | "/" | "%" => (11, false),
            _ => return None,
        })
    }

    fn binary_c(&mut self, min: u8) {
        let m = self.b.mark();
        self.unary_c();
        loop {
            let Some((p, _)) = self.binop() else { break };
            if p < min {
                break;
            }
            self.b.field_last("left");
            self.bump();
            self.b.field_last("operator");
            self.binary_c(p + 1);
            self.b.field_last("right");
            self.b.wrap(m, "binary_expression", true);
        }
    }

    fn is_cast_ahead(&self) -> bool {
        if !self.at("(") {
            return false;
        }
        let t1 = self.tok(1);
        let x1 = self.txn(1);
        if t1.k != K::Ident && !(self.cpp && x1 == "::") {
            return false;
        }
        let is_type_kw = is_primitive(x1) || matches!(x1, "struct" | "union" | "enum" | "const" | "volatile" | "unsigned" | "signed" | "long" | "short");
        // find matching ')'
        let mut depth = 0;
        let mut j = 0;
        let mut ntok = 0;
        loop {
            let x = self.txn(j);
            if x.is_empty() {
                return false;
            }
            if x == "(" {
                depth += 1;
            } else if x == ")" {
                depth -= 1;
                if depth == 0 {
                    break;
                }
            } else if depth == 1 {
                if !(self.tok(j).k == K::Ident || matches!(x, "*" | "::" | "<" | ">" | "&" | "[" | "]" | ",")) {
                    return false;
                }
                ntok += 1;
            }
            j += 1;
        }
        if is_type_kw {
            return true;
        }
        let nt = self.tok(j + 1);
        let nx = self.txn(j + 1);
        // (T)x  or (T*)x
        let _ = ntok;
        let has_ptr = (1..j).any(|k| self.txn(k) == "*");
        if has_ptr && ntok >= 2 {
            return matches!(nt.k, K::Ident | K::Num | K::Str | K::Char) || matches!(nx, "(" | "&" | "*" | "!" | "~" | "-");
        }
        ntok == 1 && (matches!(nt.k, K::Ident | K::Num | K::Str | K::Char) || matches!(nx, "(" | "!" | "~")) && !matches!(nx, "sizeof")
            && self.tok(1).k == K::Ident
            && !matches!(self.txn(j + 1), "?" | ":" | ";" | ")" | "," | "]")
            && (nt.k != K::Ident || !matches!(nx, "and" | "or"))
            && nx != "("
            || (ntok == 1 && nx == "(" && false)
    }

    fn unary_c(&mut self) {
        let m = self.b.mark();
        let tx = self.tx();
        if self.k() == K::Op {
            match tx {
                "!" | "~" | "-" | "+" => {
                    self.bump();
                    self.b.field_last("operator");
                    self.unary_c();
                    self.b.field_last("argument");
                    self.b.wrap(m, "unary_expression", true);
                    return;
                }
                "*" | "&" => {
                    self.bump();
                    self.b.field_last("operator");
                    self.unary_c();
                    self.b.field_last("argument");
                    self.b.wrap(m, "pointer_expression", true);
                    return;
                }
                "++" | "--" => {
                    self.bump();
                    self.b.field_last("operator");
                    self.unary_c();
                    self.b.field_last("argument");
                    self.b.wrap(m, "update_expression", true);
                    return;
                }
                "(" if self.is_cast_ahead() => {
                    self.bump();
                    let mt = self.b.mark();
                    self.type_specifiers();
                    self.abstract_declarator_opt();
                    self.b.wrap(mt, "type_descriptor", true);
                    self.b.field_last("type");
                    self.expect(")");
                    if self.at("{") {
                        self.initializer_list();
                        self.b.field_last("value");
