                break;
            }
        }
        self.expect("]");
        self.b.wrap(mc, "lambda_capture_specifier", true);
        self.b.field_last("captures");
        if self.at("(") {
            let md = self.b.mark();
            self.parameter_list();
            self.b.field_last("parameters");
            while matches!(self.tx(), "mutable" | "constexpr" | "noexcept") {
                self.bump();
            }
