// JSON and YAML parsers
use crate::tree::{Builder, Tree};

// ---------------- JSON ----------------
struct J<'a> {
    s: &'a [u8],
    src: &'a str,
    i: usize,
    b: Builder,
    depth: usize,
}

pub fn parse_json(src: &str) -> Tree {
    let mut p = J { s: src.as_bytes(), src, i: 0, b: Builder::new(), depth: 0 };
    let m = p.b.mark();
    p.ws();
    while p.i < p.s.len() {
        let before = p.i;
        p.value();
        p.ws();
        if p.i == before {
            let mm = p.b.mark();
            let c = p.src[p.i..].chars().next().unwrap();
            p.b.leaf(super::js::intern(&c.to_string()), false, p.i, p.i + c.len_utf8());
            p.i += c.len_utf8();
            p.b.wrap(mm, "ERROR", true);
            p.ws();
        }
    }
    let start = p.b.stack[m..].first().map(|&c| p.b.nodes[c as usize].start).unwrap_or(src.len() - src.trim_start().len());
    let root = p.b.wrap_all(m, "document", start, src.len());
    p.b.finish(root, src)
}

impl<'a> J<'a> {
    fn ws(&mut self) {
        loop {
            while self.i < self.s.len() && (self.s[self.i] as char).is_whitespace() {
                self.i += 1;
            }
            if self.i + 1 < self.s.len() && self.s[self.i] == b'/' && self.s[self.i + 1] == b'/' {
                let st = self.i;
                while self.i < self.s.len() && self.s[self.i] != b'\n' {
                    self.i += 1;
                }
                self.b.extra("comment", st, self.i);
                continue;
            }
            if self.i + 1 < self.s.len() && self.s[self.i] == b'/' && self.s[self.i + 1] == b'*' {
                let st = self.i;
                self.i += 2;
                while self.i + 1 < self.s.len() && !(self.s[self.i] == b'*' && self.s[self.i + 1] == b'/') {
                    self.i += 1;
                }
                self.i = (self.i + 2).min(self.s.len());
                self.b.extra("comment", st, self.i);
                continue;
            }
            break;
        }
    }
    fn tok(&mut self, k: &'static str) {
        self.b.leaf(k, false, self.i, self.i + k.len());
        self.i += k.len();
    }
    fn value(&mut self) {
        self.depth += 1;
        if self.depth > 500 {
            self.depth -= 1;
            return;
        }
        let c = self.s[self.i];
        match c {
            b'{' => {
                let m = self.b.mark();
                self.tok("{");
                self.ws();
                while self.i < self.s.len() && self.s[self.i] != b'}' {
                    let mp = self.b.mark();
                    if self.s[self.i] == b'"' {
                        self.string();
                    } else {
                        self.value();
                    }
                    self.b.field_last("key");
                    self.ws();
                    if self.i < self.s.len() && self.s[self.i] == b':' {
                        self.tok(":");
                        self.ws();
                        if self.i < self.s.len() {
                            self.value();
                            self.b.field_last("value");
                        }
                    }
                    self.b.wrap(mp, "pair", true);
                    self.ws();
                    if self.i < self.s.len() && self.s[self.i] == b',' {
                        self.tok(",");
                        self.ws();
                    } else {
                        break;
                    }
                }
                if self.i < self.s.len() && self.s[self.i] == b'}' {
                    self.tok("}");
                }
                self.b.wrap(m, "object", true);
            }
            b'[' => {
                let m = self.b.mark();
                self.tok("[");
                self.ws();
                while self.i < self.s.len() && self.s[self.i] != b']' {
                    let before = self.i;
                    self.value();
                    if self.i == before {
                        break;
                    }
                    self.ws();
                    if self.i < self.s.len() && self.s[self.i] == b',' {
                        self.tok(",");
                        self.ws();
                    } else {
                        break;
                    }
                }
                if self.i < self.s.len() && self.s[self.i] == b']' {
                    self.tok("]");
                }
                self.b.wrap(m, "array", true);
            }
            b'"' => self.string(),
            _ => {
                let st = self.i;
                while self.i < self.s.len() && !matches!(self.s[self.i], b',' | b']' | b'}' | b':' | b' ' | b'\n' | b'\t' | b'\r' | b'"' | b'{' | b'[') {
                    self.i += 1;
                }
                if self.i == st {
                    self.depth -= 1;
                    return;
                }
                let t = &self.src[st..self.i];
                let kind = match t {
                    "true" => "true",
                    "false" => "false",
                    "null" => "null",
                    _ => {
                        if t.starts_with(|c: char| c.is_ascii_digit() || c == '-') {
                            "number"
                        } else {
                            "ERROR"
                        }
                    }
                };
                self.b.leaf(kind, true, st, self.i);
            }
        }
        self.depth -= 1;
    }
    fn string(&mut self) {
        let m = self.b.mark();
        self.tok("\"");
        let mut cs = self.i;
        while self.i < self.s.len() && self.s[self.i] != b'"' && self.s[self.i] != b'\n' {
            if self.s[self.i] == b'\\' {
                if cs < self.i {
                    self.b.leaf("string_content", true, cs, self.i);
                }
                let st = self.i;
                let mut k = self.i + 1;
                if k < self.s.len() && self.s[k] == b'u' {
                    k += 5;
                } else {
                    k += 1;
                }
                let k = k.min(self.s.len());
                self.b.leaf("escape_sequence", true, st, k);
                self.i = k;
                cs = k;
            } else {
                self.i += 1;
            }
        }
        if cs < self.i {
            self.b.leaf("string_content", true, cs, self.i);
        }
        if self.i < self.s.len() && self.s[self.i] == b'"' {
            self.tok("\"");
        }
        self.b.wrap(m, "string", true);
    }
}

// ---------------- YAML ----------------
struct Y<'a> {
    s: &'a [u8],
    src: &'a str,
    i: usize,
    b: Builder,
    depth: usize,
}

pub fn parse_yaml(src: &str) -> Tree {
    let mut p = Y { s: src.as_bytes(), src, i: 0, b: Builder::new(), depth: 0 };
    let m = p.b.mark();
    p.skip_space_comments();
    loop {
        if p.i >= p.s.len() {
            break;
        }
        let before = p.i;
        p.document();
        if p.i == before {
            p.i += 1;
        }
        p.skip_space_comments();
    }
    let start = p.b.stack[m..].first().map(|&c| p.b.nodes[c as usize].start).unwrap_or(src.len() - src.trim_start().len());
    let root = p.b.wrap_all(m, "stream", start, src.len());
    p.b.finish(root, src)
}

impl<'a> Y<'a> {
    fn col(&self, pos: usize) -> usize {
        let mut q = pos;
        while q > 0 && self.s[q - 1] != b'\n' {
            q -= 1;
        }
        pos - q
    }
    fn at_line_start_marker(&self, marker: &[u8]) -> bool {
        self.col(self.i) == 0 && self.s[self.i..].starts_with(marker) && (self.i + 3 >= self.s.len() || matches!(self.s[self.i + 3], b' ' | b'\n' | b'\r' | b'\t'))
    }
    /// skip spaces/newlines/comments; comments become extras
    fn skip_space_comments(&mut self) {
        loop {
            while self.i < self.s.len() && matches!(self.s[self.i], b' ' | b'\t' | b'\n' | b'\r') {
                self.i += 1;
            }
            if self.i < self.s.len() && self.s[self.i] == b'#' {
                let st = self.i;
                while self.i < self.s.len() && self.s[self.i] != b'\n' {
                    self.i += 1;
                }
                let mut e = self.i;
                if e > st && self.s[e - 1] == b'\r' {
                    e -= 1;
                }
                self.b.extra("comment", st, e);
                continue;
            }
            break;
        }
    }
    fn skip_inline_space(&mut self) {
        while self.i < self.s.len() && matches!(self.s[self.i], b' ' | b'\t') {
            self.i += 1;
        }
    }
    fn document(&mut self) {
        let m = self.b.mark();
        if self.at_line_start_marker(b"---") {
            self.b.leaf("---", false, self.i, self.i + 3);
            self.i += 3;
            self.skip_space_comments();
        }
        if self.i < self.s.len() && !self.at_line_start_marker(b"---") && !self.at_line_start_marker(b"...") {
            let c = self.col(self.i);
            self.node(c as i64 - 1, true);
            self.skip_space_comments();
        }
        if self.i < self.s.len() && self.at_line_start_marker(b"...") {
            self.b.leaf("...", false, self.i, self.i + 3);
            self.i += 3;
        }
        self.b.wrap_at(m, "document", true, self.i);
    }

    /// parse a node whose content must be indented more than `parent`
    fn node(&mut self, parent: i64, _top: bool) {
        self.depth += 1;
        if self.depth > 200 {
            self.depth -= 1;
            return;
        }
        self.skip_space_comments();
        if self.i >= self.s.len() {
            self.depth -= 1;
            return;
        }
        let c = self.col(self.i) as i64;
        let m = self.b.mark();
        // properties: anchor / tag
        self.properties();
        if self.i < self.s.len() && self.s[self.i] == b'-' && self.is_seq_indicator(self.i) {
            self.block_sequence(c);
            self.b.wrap(m, "block_node", true);
        } else if self.is_mapping_key_ahead() && c > parent {
            self.block_mapping(c);
            self.b.wrap(m, "block_node", true);
        } else if self.i < self.s.len() && (self.s[self.i] == b'|' || self.s[self.i] == b'>') {
            self.block_scalar(parent);
            self.b.wrap(m, "block_node", true);
        } else {
            self.flow_node_inline(false);
            self.b.wrap(m, "flow_node", true);
        }
        self.depth -= 1;
    }

    fn properties(&mut self) {
        loop {
            if self.i < self.s.len() && self.s[self.i] == b'&' {
                let st = self.i;
                let ma = self.b.mark();
                self.b.leaf("&", false, st, st + 1);
                self.i += 1;
                let ns = self.i;
                while self.i < self.s.len() && !matches!(self.s[self.i], b' ' | b'\n' | b'\r' | b',' | b']' | b'}') {
                    self.i += 1;
                }
                self.b.leaf("anchor_name", true, ns, self.i);
                self.b.wrap(ma, "anchor", true);
                self.skip_inline_space();
                continue;
            }
            if self.i < self.s.len() && self.s[self.i] == b'!' {
                let st = self.i;
                while self.i < self.s.len() && !matches!(self.s[self.i], b' ' | b'\n' | b'\r') {
                    self.i += 1;
                }
                self.b.leaf("tag", true, st, self.i);
                self.skip_inline_space();
                continue;
            }
            break;
        }
    }

    fn is_seq_indicator(&self, pos: usize) -> bool {
        pos < self.s.len() && self.s[pos] == b'-' && (pos + 1 >= self.s.len() || matches!(self.s[pos + 1], b' ' | b'\n' | b'\r' | b'\t'))
    }

    /// is there `key:` at current position on this line?
    fn is_mapping_key_ahead(&self) -> bool {
        let mut k = self.i;
        if k < self.s.len() && (self.s[k] == b'"' || self.s[k] == b'\'') {
            let q = self.s[k];
            k += 1;
            while k < self.s.len() && self.s[k] != q && self.s[k] != b'\n' {
                if self.s[k] == b'\\' && q == b'"' {
                    k += 1;
                }
                k += 1;
            }
            k += 1;
            while k < self.s.len() && self.s[k] == b' ' {
                k += 1;
            }
            return k < self.s.len() && self.s[k] == b':' && (k + 1 >= self.s.len() || matches!(self.s[k + 1], b' ' | b'\n' | b'\r'));
        }
        if k < self.s.len() && matches!(self.s[k], b'[' | b'{' | b'|' | b'>' | b'#') {
            return false;
        }
        if k < self.s.len() && self.s[k] == b'?' && (k + 1 >= self.s.len() || self.s[k + 1] == b' ') {
            return true;
        }
        while k < self.s.len() && self.s[k] != b'\n' {
            if self.s[k] == b':' && (k + 1 >= self.s.len() || matches!(self.s[k + 1], b' ' | b'\n' | b'\r' | b'\t')) {
                return true;
            }
            if self.s[k] == b'#' && k > 0 && self.s[k - 1] == b' ' {
                return false;
            }
            k += 1;
        }
        false
    }

    fn line_has_more(&self) -> bool {
        let mut k = self.i;
        while k < self.s.len() && matches!(self.s[k], b' ' | b'\t') {
            k += 1;
        }
        k < self.s.len() && !matches!(self.s[k], b'\n' | b'\r' | b'#')
    }

    /// next content line column (after skipping blank/comment lines) without consuming
    fn peek_content(&self) -> Option<(usize, usize)> {
        let mut k = self.i;
        loop {
            while k < self.s.len() && matches!(self.s[k], b' ' | b'\t' | b'\n' | b'\r') {
                k += 1;
            }
            if k < self.s.len() && self.s[k] == b'#' {
                while k < self.s.len() && self.s[k] != b'\n' {
                    k += 1;
                }
                continue;
            }
            break;
        }
        if k >= self.s.len() {
            return None;
        }
        Some((k, self.col(k)))
    }

    fn block_mapping(&mut self, indent: i64) {
        let m = self.b.mark();
        loop {
            let mp = self.b.mark();
            // key
            let explicit = self.s[self.i] == b'?' && (self.i + 1 >= self.s.len() || self.s[self.i + 1] == b' ');
            if explicit {
                self.b.leaf("?", false, self.i, self.i + 1);
                self.i += 1;
                self.skip_inline_space();
                self.node(indent, false);
                self.b.field_last("key");
                self.skip_space_comments();
            } else {
                let mk = self.b.mark();
                self.properties();
                self.flow_scalar(true);
                self.b.wrap(mk, "flow_node", true);
                self.b.field_last("key");
                self.skip_inline_space();
            }
            if self.i < self.s.len() && self.s[self.i] == b':' {
                self.b.leaf(":", false, self.i, self.i + 1);
                self.i += 1;
                self.skip_inline_space();
                // value
                if self.line_has_more() {
                    if self.s[self.i] == b'|' || self.s[self.i] == b'>' {
                        let mv = self.b.mark();
                        self.block_scalar(indent);
                        self.b.wrap(mv, "block_node", true);
                        self.b.field_last("value");
                    } else if self.s[self.i] == b'&' || self.s[self.i] == b'!' {
                        // properties then maybe block on next line
                        let mv = self.b.mark();
                        self.properties();
                        if self.line_has_more() {
                            self.flow_node_inline(false);
                            self.b.wrap(mv, "flow_node", true);
                        } else if let Some((_, c)) = self.peek_content() {
                            if (c as i64) > indent || (c as i64 == indent && self.seq_at_peek()) {
                                self.node(indent, false);
                            }
                            self.b.wrap(mv, "block_node", true);
                        }
                        self.b.field_last("value");
                    } else {
                        let mv = self.b.mark();
                        self.flow_node_inline(false);
                        self.b.wrap(mv, "flow_node", true);
                        self.b.field_last("value");
                    }
                } else if let Some((k, c)) = self.peek_content() {
                    let is_seq = self.is_seq_indicator(k);
                    if (c as i64) > indent || ((c as i64) == indent && is_seq) {
                        self.skip_space_comments();
                        self.node(if is_seq && c as i64 == indent { indent - 1 } else { indent }, false);
                        self.b.field_last("value");
                    }
                }
            }
            self.b.wrap(mp, "block_mapping_pair", true);
            // next pair?
            match self.peek_content() {
                Some((k, c)) if c as i64 == indent && !self.is_seq_indicator(k) && !self.marker_at(k) => {
                    self.skip_space_comments();
                    if !self.is_mapping_key_ahead() {
                        break;
                    }
                }
                _ => break,
            }
        }
        self.b.wrap(m, "block_mapping", true);
    }

    fn marker_at(&self, k: usize) -> bool {
        self.col(k) == 0 && (self.s[k..].starts_with(b"---") || self.s[k..].starts_with(b"..."))
    }

    fn seq_at_peek(&self) -> bool {
        self.peek_content().map_or(false, |(k, _)| self.is_seq_indicator(k))
    }

    fn block_sequence(&mut self, indent: i64) {
        let m = self.b.mark();
        loop {
            let mi = self.b.mark();
            self.b.leaf("-", false, self.i, self.i + 1);
            self.i += 1;
            self.skip_inline_space();
            if self.line_has_more() {
                let c = self.col(self.i) as i64;
                self.node(c - 1, false);
            } else if let Some((_, c)) = self.peek_content() {
                if c as i64 > indent {
                    self.skip_space_comments();
                    self.node(indent, false);
                }
            }
            self.b.wrap(mi, "block_sequence_item", true);
            match self.peek_content() {
                Some((k, c)) if c as i64 == indent && self.is_seq_indicator(k) => {
                    self.skip_space_comments();
                }
                _ => break,
            }
        }
        self.b.wrap(m, "block_sequence", true);
    }

    fn block_scalar(&mut self, parent: i64) {
        let m = self.b.mark();
        let st = self.i;
        let ind = self.s[self.i];
        self.b.leaf(if ind == b'|' { "|" } else { ">" }, false, st, st + 1);
        self.i += 1;
        while self.i < self.s.len() && matches!(self.s[self.i], b'+' | b'-' | b'0'..=b'9') {
            self.i += 1;
        }
        // rest of line (comment)
        self.skip_inline_space();
        if self.i < self.s.len() && self.s[self.i] == b'#' {
            let cs = self.i;
            while self.i < self.s.len() && self.s[self.i] != b'\n' {
                self.i += 1;
            }
            self.b.extra("comment", cs, self.i);
        }
        // content lines with indentation > parent
        let mut end = self.i;
        let mut k = self.i;
        loop {
            // move to next line
            while k < self.s.len() && self.s[k] != b'\n' {
                k += 1;
            }
            if k >= self.s.len() {
                break;
            }
            k += 1;
            let ls = k;
            let mut c = 0;
            while k < self.s.len() && self.s[k] == b' ' {
                k += 1;
                c += 1;
            }
            if k >= self.s.len() {
                break;
            }
            if self.s[k] == b'\n' || self.s[k] == b'\r' {
                continue;
            }
            if (c as i64) <= parent {
                let _ = ls;
                break;
            }
            while k < self.s.len() && self.s[k] != b'\n' {
                k += 1;
            }
            end = k;
            if end > 0 && self.s[end - 1] == b'\r' {
                end -= 1;
            }
        }
        self.i = end;
        self.b.wrap(m, "block_scalar", true);
        let id = self.b.last().unwrap() as usize;
        self.b.nodes[id].end = end;
    }

    fn flow_node_inline(&mut self, in_flow: bool) {
        // contents of a flow_node (not wrapped)
        if self.i >= self.s.len() {
            return;
        }
        match self.s[self.i] {
            b'[' => self.flow_sequence(),
            b'{' => self.flow_mapping(),
            b'*' => {
                let ma = self.b.mark();
                self.b.leaf("*", false, self.i, self.i + 1);
                self.i += 1;
                let ns = self.i;
                while self.i < self.s.len() && !matches!(self.s[self.i], b' ' | b'\n' | b'\r' | b',' | b']' | b'}') {
                    self.i += 1;
                }
                self.b.leaf("alias_name", true, ns, self.i);
                self.b.wrap(ma, "alias", true);
            }
            _ => self.flow_scalar_ex(false, in_flow),
        }
    }

    fn flow_scalar(&mut self, key: bool) {
        self.flow_scalar_ex(key, false)
    }

    fn flow_scalar_ex(&mut self, key: bool, in_flow: bool) {
        let c = self.s[self.i];
        if c == b'"' || c == b'\'' {
            let m = self.b.mark();
            let q = c;
            let qk: &'static str = if q == b'"' { "\"" } else { "'" };
            self.b.leaf(qk, false, self.i, self.i + 1);
            self.i += 1;
            while self.i < self.s.len() && self.s[self.i] != q {
                if q == b'"' && self.s[self.i] == b'\\' {
                    let st = self.i;
                    let mut k = self.i + 2;
                    if st + 1 < self.s.len() {
                        match self.s[st + 1] {
                            b'x' => k = st + 4,
                            b'u' => k = st + 6,
                            b'U' => k = st + 10,
                            _ => {}
                        }
                    }
                    let k = k.min(self.s.len());
                    self.b.leaf("escape_sequence", true, st, k);
                    self.i = k;
                    continue;
                }
                if q == b'\'' && self.s[self.i] == b'\'' {
                    break;
                }
                self.i += 1;
            }
            if q == b'\'' {
                // handle '' escapes
                while self.i + 1 < self.s.len() && self.s[self.i] == b'\'' && self.s[self.i + 1] == b'\'' {
                    self.b.leaf("escape_sequence", true, self.i, self.i + 2);
                    self.i += 2;
                    while self.i < self.s.len() && self.s[self.i] != b'\'' {
                        self.i += 1;
                    }
                }
            }
            if self.i < self.s.len() {
                self.b.leaf(qk, false, self.i, self.i + 1);
                self.i += 1;
            }
            self.b.wrap(m, if q == b'"' { "double_quote_scalar" } else { "single_quote_scalar" }, true);
            return;
        }
        // plain scalar: until ': ' / ' #' / end of line (multi-line continuation not supported)
        let st = self.i;
        let mut e = self.i;
        let mut k = self.i;
        while k < self.s.len() && self.s[k] != b'\n' {
            let ch = self.s[k];
            if ch == b':' && (k + 1 >= self.s.len() || matches!(self.s[k + 1], b' ' | b'\n' | b'\r' | b'\t') || (in_flow && matches!(self.s[k + 1], b',' | b']' | b'}'))) {
                break;
            }
            if ch == b'#' && k > st && matches!(self.s[k - 1], b' ' | b'\t') {
                break;
            }
            if in_flow && matches!(ch, b',' | b']' | b'}' | b'[' | b'{') {
                break;
            }
            k += 1;
            if !matches!(ch, b' ' | b'\t' | b'\r') {
                e = k;
            }
        }
        let _ = key;
        self.i = e;
        let text = &self.src[st..e];
        let kind = scalar_kind(text);
        let m = self.b.mark();
        self.b.leaf(kind, true, st, e);
        self.b.wrap(m, "plain_scalar", true);
    }

    fn flow_ws(&mut self) {
        loop {
            while self.i < self.s.len() && matches!(self.s[self.i], b' ' | b'\t' | b'\n' | b'\r') {
                self.i += 1;
            }
            if self.i < self.s.len() && self.s[self.i] == b'#' {
                let st = self.i;
                while self.i < self.s.len() && self.s[self.i] != b'\n' {
                    self.i += 1;
                }
                self.b.extra("comment", st, self.i);
                continue;
            }
            break;
        }
    }

    fn flow_sequence(&mut self) {
        let m = self.b.mark();
        self.b.leaf("[", false, self.i, self.i + 1);
        self.i += 1;
        self.flow_ws();
        while self.i < self.s.len() && self.s[self.i] != b']' {
            let before = self.i;
            self.flow_item();
            self.flow_ws();
            if self.i < self.s.len() && self.s[self.i] == b',' {
                self.b.leaf(",", false, self.i, self.i + 1);
                self.i += 1;
                self.flow_ws();
            } else if self.i == before {
                break;
            } else if self.i < self.s.len() && self.s[self.i] != b']' {
                break;
            }
        }
        if self.i < self.s.len() && self.s[self.i] == b']' {
            self.b.leaf("]", false, self.i, self.i + 1);
            self.i += 1;
        }
        self.b.wrap(m, "flow_sequence", true);
    }

    fn flow_item(&mut self) {
        // flow node or flow pair
        let m = self.b.mark();
        let mn = self.b.mark();
        self.properties();
        self.flow_node_inline(true);
        self.b.wrap(mn, "flow_node", true);
        self.skip_inline_space();
        if self.i < self.s.len() && self.s[self.i] == b':' {
            self.b.field_last("key");
            self.b.leaf(":", false, self.i, self.i + 1);
            self.i += 1;
            self.flow_ws();
            if self.i < self.s.len() && !matches!(self.s[self.i], b',' | b']' | b'}') {
                let mv = self.b.mark();
                self.properties();
                self.flow_node_inline(true);
                self.b.wrap(mv, "flow_node", true);
                self.b.field_last("value");
            }
            self.b.wrap(m, "flow_pair", true);
        }
    }

    fn flow_mapping(&mut self) {
        let m = self.b.mark();
        self.b.leaf("{", false, self.i, self.i + 1);
        self.i += 1;
        self.flow_ws();
        while self.i < self.s.len() && self.s[self.i] != b'}' {
            let before = self.i;
            self.flow_item();
            self.flow_ws();
            if self.i < self.s.len() && self.s[self.i] == b',' {
                self.b.leaf(",", false, self.i, self.i + 1);
                self.i += 1;
                self.flow_ws();
            } else if self.i == before || (self.i < self.s.len() && self.s[self.i] != b'}') {
                break;
            }
        }
        if self.i < self.s.len() && self.s[self.i] == b'}' {
            self.b.leaf("}", false, self.i, self.i + 1);
            self.i += 1;
        }
        self.b.wrap(m, "flow_mapping", true);
    }
}

fn scalar_kind(t: &str) -> &'static str {
    match t {
        "null" | "Null" | "NULL" | "~" | "" => return "null_scalar",
        "true" | "True" | "TRUE" | "false" | "False" | "FALSE" => return "boolean_scalar",
        _ => {}
    }
    let s = t.strip_prefix(['-', '+']).unwrap_or(t);
    if !s.is_empty() && s.chars().all(|c| c.is_ascii_digit()) {
        return "integer_scalar";
    }
    if (s.starts_with("0x") && s.len() > 2 && s[2..].chars().all(|c| c.is_ascii_hexdigit()))
        || (s.starts_with("0o") && s.len() > 2 && s[2..].chars().all(|c| ('0'..='7').contains(&c)))
    {
        return "integer_scalar";
    }
    if matches!(s, ".inf" | ".Inf" | ".INF" | ".nan" | ".NaN" | ".NAN") {
        return "float_scalar";
    }
    // float: digits . digits (e[+-]digits)?
    let mut seen_digit = false;
    let mut seen_dot = false;
    let mut seen_e = false;
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c.is_ascii_digit() {
            seen_digit = true;
        } else if c == b'.' && !seen_dot && !seen_e {
            seen_dot = true;
        } else if (c == b'e' || c == b'E') && seen_digit && !seen_e {
            seen_e = true;
            if i + 1 < b.len() && (b[i + 1] == b'+' || b[i + 1] == b'-') {
                i += 1;
            }
        } else {
            return "string_scalar";
        }
        i += 1;
    }
    if seen_digit && (seen_dot || seen_e) {
        return "float_scalar";
    }
    "string_scalar"
}
