// Ruby parser producing tree-sitter-ruby compatible CST (common subset)
use super::js::intern;
use crate::tree::{Builder, Tree};

#[derive(Clone, Copy, PartialEq, Debug)]
enum K {
    Ident,
    Const,
    IVar,
    CVar,
    GVar,
    Sym,
    Num,
    Str,
    Op,
    NL,
    Comment,
    Eof,
}

#[derive(Clone, Copy, Debug)]
struct Tk {
    k: K,
    s: usize,
    e: usize,
    sp: bool, // preceded by whitespace
}

const OPS: &[&str] = &[
    "**=", "<=>", "===", "...", "<<=", ">>=", "&&=", "||=", "&.", "**", "==", "!=", "=~", "!~", ">=", "<=", "&&", "||",
    "<<", ">>", "+=", "-=", "*=", "/=", "%=", "|=", "&=", "^=", "::", "..", "=>", "->",
];

const KW: &[&str] = &[
    "alias", "and", "begin", "break", "case", "class", "def", "defined?", "do", "else", "elsif", "end", "ensure",
    "false", "for", "if", "in", "module", "next", "nil", "not", "or", "redo", "rescue", "retry", "return", "self",
    "super", "then", "true", "undef", "unless", "until", "when", "while", "yield", "__FILE__", "__LINE__",
];

fn tokenize(src: &str) -> Vec<Tk> {
    let b = src.as_bytes();
    let n = b.len();
    let mut out: Vec<Tk> = Vec::new();
    let mut i = 0;
    let mut sp = true;
    let mut paren_depth: Vec<u8> = Vec::new();
    while i < n {
        let c = b[i];
        if c == b' ' || c == b'\t' || c == b'\r' {
            i += 1;
            sp = true;
            continue;
        }
        if c == b'\\' && i + 1 < n && b[i + 1] == b'\n' {
            i += 2;
            sp = true;
            continue;
        }
        if c == b'\n' {
            if paren_depth.last().map_or(true, |&d| d == b'{') {
                out.push(Tk { k: K::NL, s: i, e: i + 1, sp });
            }
            i += 1;
            sp = true;
            continue;
        }
        if c == b'#' {
            let s = i;
            while i < n && b[i] != b'\n' {
                i += 1;
            }
            out.push(Tk { k: K::Comment, s, e: i, sp });
            continue;
        }
        if c == b'=' && (i == 0 || b[i - 1] == b'\n') && src[i..].starts_with("=begin") {
            let s = i;
            let e = src[i..].find("\n=end").map(|x| i + x + 5).unwrap_or(n);
            let mut e2 = e;
            while e2 < n && b[e2] != b'\n' {
                e2 += 1;
            }
            out.push(Tk { k: K::Comment, s, e: e2, sp });
            i = e2;
            continue;
        }
        let s = i;
        let prev_value = out.last().map_or(false, |t| matches!(t.k, K::Ident | K::Const | K::IVar | K::CVar | K::GVar | K::Num | K::Str | K::Sym) || (t.k == K::Op && matches!(&src[t.s..t.e], ")" | "]" | "}")));
        let prev_is_ident = out.last().map_or(false, |t| t.k == K::Ident);
        if c == b'"' || c == b'\'' || c == b'`' {
            let e = scan_str(b, i, c);
            out.push(Tk { k: K::Str, s, e, sp });
            i = e;
            sp = false;
            continue;
        }
        if c == b'%' && i + 1 < n && (matches!(b[i + 1], b'w' | b'W' | b'i' | b'I' | b'q' | b'Q' | b'r') && i + 2 < n && !b[i + 2].is_ascii_alphanumeric() && b[i + 2] != b' ' || matches!(b[i + 1], b'(' | b'[' | b'{')) && (!prev_value || (sp && prev_is_ident)) {
            let mut j = i + 1;
            if b[j].is_ascii_alphabetic() {
                j += 1;
            }
            let open = b[j];
            let close = match open {
                b'(' => b')',
                b'[' => b']',
                b'{' => b'}',
                b'<' => b'>',
                x => x,
            };
            let mut k = j + 1;
            let mut depth = 1;
            while k < n {
                if b[k] == b'\\' {
                    k += 2;
                    continue;
                }
                if b[k] == open && open != close {
                    depth += 1;
                } else if b[k] == close {
                    depth -= 1;
                    if depth == 0 {
                        break;
                    }
                }
                k += 1;
            }
            let e = (k + 1).min(n);
            out.push(Tk { k: K::Str, s, e, sp });
            i = e;
            sp = false;
            continue;
        }
        if c == b'/' && (!prev_value || (sp && prev_is_ident && i + 1 < n && b[i + 1] != b' ')) {
            // regex
            let mut k = i + 1;
            while k < n && b[k] != b'/' && b[k] != b'\n' {
                if b[k] == b'\\' {
                    k += 1;
                }
                k += 1;
            }
            k += 1;
            while k < n && b[k].is_ascii_alphabetic() {
                k += 1;
            }
            let e = k.min(n);
            out.push(Tk { k: K::Str, s, e, sp });
            i = e;
            sp = false;
            continue;
        }
        if c == b':' && i + 1 < n && b[i + 1] != b':' && (b[i + 1] == b'"' || b[i + 1].is_ascii_alphabetic() || b[i + 1] == b'_' || (matches!(b[i + 1], b'+' | b'-' | b'*' | b'/' | b'<' | b'>' | b'=' | b'!' | b'[') && !prev_value)) && !(prev_value && !sp) {
            if b[i + 1] == b'"' {
                let e = scan_str(b, i + 1, b'"');
                out.push(Tk { k: K::Sym, s, e, sp });
                i = e;
            } else {
                let mut k = i + 1;
                if b[k].is_ascii_alphabetic() || b[k] == b'_' {
                    while k < n && (b[k].is_ascii_alphanumeric() || b[k] == b'_') {
                        k += 1;
                    }
                    if k < n && matches!(b[k], b'?' | b'!' | b'=') && !(k + 1 < n && b[k + 1] == b'=') && !(b[k] == b'=' && k + 1 < n && b[k + 1] == b'>') {
                        k += 1;
                    }
                } else {
                    while k < n && matches!(b[k], b'+' | b'-' | b'*' | b'/' | b'<' | b'>' | b'=' | b'!' | b'[' | b']' | b'%' | b'~') {
                        k += 1;
                    }
                }
                out.push(Tk { k: K::Sym, s, e: k, sp });
                i = k;
            }
            sp = false;
            continue;
        }
        if c.is_ascii_digit() {
            let mut k = i;
            while k < n && (b[k].is_ascii_alphanumeric() || b[k] == b'_' || (b[k] == b'.' && k + 1 < n && b[k + 1].is_ascii_digit())) {
                k += 1;
            }
            out.push(Tk { k: K::Num, s, e: k, sp });
            i = k;
            sp = false;
            continue;
        }
        if c == b'@' || c == b'$' {
            let mut k = i + 1;
            let mut kind = if c == b'$' { K::GVar } else { K::IVar };
            if c == b'@' && k < n && b[k] == b'@' {
                k += 1;
                kind = K::CVar;
            }
            while k < n && (b[k].is_ascii_alphanumeric() || b[k] == b'_') {
                k += 1;
            }
            if k == i + 1 && c == b'$' && k < n {
                k += 1;
            }
            out.push(Tk { k: kind, s, e: k, sp });
            i = k;
            sp = false;
            continue;
        }
        let ch = src[i..].chars().next().unwrap();
        if ch == '_' || ch.is_alphabetic() {
            let mut k = i;
            for (o, c2) in src[i..].char_indices() {
                if !(c2 == '_' || c2.is_alphanumeric()) {
                    k = i + o;
                    break;
                }
                k = i + o + c2.len_utf8();
            }
            if k < n && matches!(b[k], b'?' | b'!') && !(k + 1 < n && b[k + 1] == b'=') {
                k += 1;
            }
            let word = &src[i..k];
            let kind = if ch.is_uppercase() { K::Const } else { K::Ident };
            let _ = word;
            out.push(Tk { k: kind, s, e: k, sp });
            i = k;
            sp = false;
            continue;
        }
        let r = &src[i..];
        let mut l = ch.len_utf8();
        for o in OPS {
            if r.starts_with(o) {
                l = o.len();
                break;
            }
        }
        match c {
            b'(' | b'[' => paren_depth.push(c),
            b'{' => paren_depth.push(c),
            b')' | b']' | b'}' => {
                paren_depth.pop();
            }
            _ => {}
        }
        out.push(Tk { k: K::Op, s, e: i + l, sp });
        i += l;
        sp = false;
    }
    out.push(Tk { k: K::Eof, s: n, e: n, sp: true });
    out
}

fn scan_str(b: &[u8], i: usize, q: u8) -> usize {
    let mut k = i + 1;
    let mut depth = 0;
    while k < b.len() {
        if b[k] == b'\\' {
            k += 2;
            continue;
        }
        if q == b'"' && b[k] == b'#' && k + 1 < b.len() && b[k + 1] == b'{' {
            depth += 1;
            k += 2;
            continue;
        }
        if depth > 0 && b[k] == b'}' {
            depth -= 1;
            k += 1;
            continue;
        }
        if depth == 0 && b[k] == q {
            return k + 1;
        }
        k += 1;
    }
    b.len()
}

struct P<'a> {
    src: &'a str,
    toks: Vec<Tk>,
    i: usize,
    b: Builder,
    depth: usize,
    no_do: bool,
}

pub fn parse(src: &str) -> Tree {
    let toks = tokenize(src);
    let mut p = P { src, toks, i: 0, b: Builder::new(), depth: 0, no_do: false };
    let m = p.b.mark();
    p.statements(&[]);
    p.flush_extras();
    let start = p.b.stack[m..].first().map(|&c| p.b.nodes[c as usize].start).unwrap_or(src.len() - src.trim_start().len());
    let root = p.b.wrap_all(m, "program", start, src.len());
    p.b.finish(root, src)
}

impl<'a> P<'a> {
    fn idx(&self, n: usize) -> usize {
        let mut j = self.i;
        let mut c = 0;
        loop {
            while j < self.toks.len() && self.toks[j].k == K::Comment {
                j += 1;
            }
            if j >= self.toks.len() {
                return self.toks.len() - 1;
            }
            if c == n {
                return j;
            }
            c += 1;
            j += 1;
        }
    }
    fn tok(&self, n: usize) -> Tk {
        self.toks[self.idx(n)]
    }
    fn k(&self) -> K {
        self.tok(0).k
    }
    fn txn(&self, n: usize) -> &'a str {
        let t = self.tok(n);
        if matches!(t.k, K::Eof | K::NL) {
            return "";
        }
        &self.src[t.s..t.e]
    }
    fn tx(&self) -> &'a str {
        self.txn(0)
    }
    fn at(&self, s: &str) -> bool {
        let t = self.tok(0);
        matches!(t.k, K::Op | K::Ident | K::Const) && &self.src[t.s..t.e] == s
    }
    fn flush_extras(&mut self) {
        while self.i < self.toks.len() && self.toks[self.i].k == K::Comment {
            let t = self.toks[self.i];
            self.b.extra("comment", t.s, t.e);
            self.i += 1;
        }
    }
    fn advance(&mut self) -> Tk {
        self.flush_extras();
        let t = self.toks[self.i];
        if t.k != K::Eof {
            self.i += 1;
        }
        t
    }
    fn bump(&mut self) -> u32 {
        let t = self.advance();
        let k = intern(&self.src[t.s..t.e]);
        self.b.leaf(k, false, t.s, t.e)
    }
    fn bump_named(&mut self, kind: &'static str) -> u32 {
        let t = self.advance();
        self.b.leaf(kind, true, t.s, t.e)
    }
    fn eat(&mut self, s: &str) -> bool {
        if self.at(s) {
            self.bump();
            true
        } else {
            false
        }
    }
    fn cur_pos(&self) -> usize {
        self.b.last().map(|l| self.b.nodes[l as usize].end).unwrap_or(0)
    }
    fn expect(&mut self, s: &str) {
        if !self.eat(s) {
            let p = self.cur_pos();
            self.b.missing(intern(s), false, p);
        }
    }
    fn skip_nl(&mut self) {
        while self.k() == K::NL || self.at(";") {
            if self.k() == K::NL {
                let t = self.advance();
                let _ = t;
            } else {
                break;
            }
        }
    }
    fn skip_terms(&mut self) {
        while self.k() == K::NL {
            self.advance();
        }
    }
    fn error_token(&mut self) {
        if self.k() == K::Eof {
            return;
        }
        if self.k() == K::NL {
            self.advance();
            return;
        }
        let m = self.b.mark();
        self.bump();
        self.b.wrap(m, "ERROR", true);
    }
    fn set_field_first(&mut self, m: usize, f: &'static str) {
        for i in m..self.b.stack.len() {
            let id = self.b.stack[i] as usize;
            if !self.b.nodes[id].extra {
                self.b.nodes[id].field = Some(f);
                return;
            }
        }
    }

    /// parse statements until one of the end keywords; returns number parsed
    fn statements(&mut self, ends: &[&str]) -> usize {
        let mut n = 0;
        loop {
            self.skip_terms();
            if self.k() == K::Eof {
                break;
            }
            if ends.iter().any(|e| self.at(e)) {
                break;
            }
            if self.at(";") {
                self.bump();
                continue;
            }
            let before = self.i;
            self.statement();
            n += 1;
            if self.i == before {
                self.error_token();
            }
            if self.at(";") {
                self.bump();
            }
        }
        n
    }

    fn body(&mut self, ends: &[&str], kind: &'static str) -> bool {
        // body_statement wrapper (may include rescue/else/ensure)
        self.skip_terms();
        let m = self.b.mark();
        let mut all_ends: Vec<&str> = ends.to_vec();
        all_ends.extend_from_slice(&["rescue", "ensure"]);
        if ends.contains(&"end") {
            all_ends.push("else");
        }
        let n = self.statements(&all_ends);
        let mut has = n > 0;
        while self.at("rescue") || self.at("ensure") || (self.at("else") && has_rescue(&self.b, m)) {
            if self.at("rescue") {
                self.rescue_clause();
            } else if self.at("else") {
                let me = self.b.mark();
                self.bump();
                self.statements(&["ensure", "end"]);
                self.b.wrap(me, "else", true);
            } else {
                let me = self.b.mark();
                self.bump();
                self.statements(&["end"]);
                self.b.wrap(me, "ensure", true);
            }
            has = true;
        }
        if has {
            self.b.wrap(m, kind, true);
        }
        has
    }

    fn rescue_clause(&mut self) {
        let m = self.b.mark();
        self.bump(); // rescue
        if !matches!(self.k(), K::NL) && !self.at("then") && !self.at("=>") && !self.at(";") {
            let me = self.b.mark();
            loop {
                self.arg();
                if !self.eat(",") {
                    break;
                }
            }
            self.b.wrap(me, "exceptions", true);
            self.b.field_last("exceptions");
        }
        if self.at("=>") {
            let mv = self.b.mark();
            self.bump();
            self.primary();
            self.b.wrap(mv, "exception_variable", true);
            self.b.field_last("variable");
        }
        let mt = self.b.mark();
        let had_then = self.eat("then");
        self.skip_terms();
        let n = self.statements(&["rescue", "else", "ensure", "end"]);
        if n > 0 || had_then {
            self.b.wrap(mt, "then", true);
            self.b.field_last("body");
        }
        self.b.wrap(m, "rescue", true);
    }

    fn statement(&mut self) {
        let m = self.b.mark();
        self.expression_statement();
        // modifiers
        loop {
            let tx = self.tx();
            let k = match tx {
                "if" => "if_modifier",
                "unless" => "unless_modifier",
                "while" => "while_modifier",
                "until" => "until_modifier",
                "rescue" => "rescue_modifier",
                _ => break,
            };
            if self.k() != K::Ident {
                break;
            }
            self.set_field_first(m, "body");
            self.bump();
            self.expression_statement();
            self.b.field_last(if k == "rescue_modifier" { "handler" } else { "condition" });
            self.b.wrap(m, k, true);
        }
    }

    fn expression_statement(&mut self) {
        let m = self.b.mark();
        self.not_expr();
        while (self.at("and") || self.at("or")) && self.k() == K::Ident {
            self.b.field_last("left");
            self.bump();
            self.b.field_last("operator");
            self.skip_terms();
            self.not_expr();
            self.b.field_last("right");
            self.b.wrap(m, "binary", true);
        }
    }

    fn not_expr(&mut self) {
        let m = self.b.mark();
        if self.at("not") && self.k() == K::Ident {
            self.bump();
            self.not_expr();
            self.b.wrap(m, "unary", true);
            return;
        }
        self.expression();
    }

    fn expression(&mut self) {
        self.depth += 1;
        if self.depth > 300 {
            self.error_token();
            self.depth -= 1;
            return;
        }
        let m = self.b.mark();
        // multiple assignment lhs / splat
        self.arg();
        if self.at(",") && self.is_mlhs_ahead() {
            while self.eat(",") {
                if self.at("*") {
                    let ms = self.b.mark();
                    self.bump();
                    self.primary_postfix();
                    self.b.wrap(ms, "rest_assignment", true);
                } else {
                    self.primary_postfix();
                }
            }
            self.b.wrap(m, "left_assignment_list", true);
        }
        let tx = self.tx();
        if self.k() == K::Op {
            if tx == "=" {
                self.b.field_last("left");
                self.bump();
                self.skip_terms();
                let mr = self.b.mark();
                self.expression_rhs();
                if self.at(",") {
                    while self.eat(",") {
                        self.arg();
                    }
                    self.b.wrap(mr, "right_assignment_list", true);
                }
                self.b.field_last("right");
                self.b.wrap(m, "assignment", true);
            } else if matches!(tx, "+=" | "-=" | "*=" | "/=" | "%=" | "**=" | "||=" | "&&=" | "|=" | "&=" | "^=" | "<<=" | ">>=") {
                self.b.field_last("left");
                self.bump();
                self.b.field_last("operator");
                self.skip_terms();
                self.expression_rhs();
                self.b.field_last("right");
                self.b.wrap(m, "operator_assignment", true);
            }
        }
        self.depth -= 1;
    }

    fn expression_rhs(&mut self) {
        let m = self.b.mark();
        self.expression();
        if self.at("rescue") && self.k() == K::Ident {
            self.b.field_last("body");
            self.bump();
            self.arg();
            self.b.field_last("handler");
            self.b.wrap(m, "rescue_modifier", true);
        }
    }

    fn is_mlhs_ahead(&self) -> bool {
        // a, b = ...
        let mut j = 0;
        loop {
            let x = self.txn(j);
            let t = self.tok(j);
            if t.k == K::NL || t.k == K::Eof {
                return false;
            }
            if x == "=" {
                return true;
            }
            if matches!(x, "(" | "[" | "{" | "do" | "if" | "unless") {
                return false;
            }
            j += 1;
            if j > 50 {
                return false;
            }
        }
    }

    fn arg(&mut self) {
        let m = self.b.mark();
        self.ternary();
        let _ = m;
    }

    fn ternary(&mut self) {
        let m = self.b.mark();
        self.range();
        if self.at("?") && self.k() == K::Op {
            self.b.field_last("condition");
            self.bump();
            self.skip_terms();
            self.ternary();
            self.b.field_last("consequence");
            self.skip_terms();
            self.expect(":");
            self.skip_terms();
            self.ternary();
            self.b.field_last("alternative");
            self.b.wrap(m, "conditional", true);
        }
    }

    fn range(&mut self) {
        let m = self.b.mark();
        if self.at("..") || self.at("...") {
            self.bump();
            self.b.field_last("operator");
            self.binary(1);
            self.b.field_last("end");
            self.b.wrap(m, "range", true);
            return;
        }
        self.binary(1);
        if self.at("..") || self.at("...") {
            self.b.field_last("begin");
            self.bump();
            self.b.field_last("operator");
            if self.can_start_arg() {
                self.binary(1);
                self.b.field_last("end");
            }
            self.b.wrap(m, "range", true);
        }
    }

    fn can_start_arg(&self) -> bool {
        let t = self.tok(0);
        match t.k {
            K::NL | K::Eof => false,
            K::Op => matches!(self.tx(), "(" | "[" | "-" | "!" | "::" | "{" | "->" | "~" | "*" | "&" | ":" | "**") && !(self.tx() == "{" && false),
            K::Ident => !matches!(self.tx(), "if" | "unless" | "while" | "until" | "rescue" | "and" | "or" | "then" | "do" | "end" | "else" | "elsif" | "when" | "in" | "ensure"),
            _ => true,
        }
    }

    fn binop(&self) -> Option<u8> {
        let t = self.tok(0);
        if t.k != K::Op {
            return None;
        }
        Some(match self.tx() {
            "||" => 1,
            "&&" => 2,
            "<=>" | "==" | "===" | "!=" | "=~" | "!~" => 4,
            "<" | "<=" | ">" | ">=" => 5,
            "|" | "^" => 6,
            "&" => 7,
            "<<" | ">>" => 8,
            "+" | "-" => 9,
            "*" | "/" | "%" => 10,
            "**" => 12,
            _ => return None,
        })
    }

    fn binary(&mut self, min: u8) {
        let m = self.b.mark();
        self.unary();
        loop {
            let Some(p) = self.binop() else { break };
            if p < min {
                break;
            }
            // `foo -1` style command args are handled in primary; here treat as binary
            self.b.field_last("left");
            self.bump();
            self.b.field_last("operator");
            self.skip_terms();
            if p == 12 {
                self.binary(p);
            } else {
                self.binary(p + 1);
            }
            self.b.field_last("right");
            self.b.wrap(m, "binary", true);
        }
    }

    fn unary(&mut self) {
        let m = self.b.mark();
        let tx = self.tx();
        if self.k() == K::Op && matches!(tx, "!" | "~" | "-" | "+") {
            if tx == "-" && self.tok(1).k == K::Num && self.tok(1).s == self.tok(0).e {
                // negative number literal
                let t = self.advance();
                let n = self.advance();
                let txt = &self.src[n.s..n.e];
                let kind = if txt.contains('.') || txt.contains('e') { "float" } else { "integer" };
                self.b.leaf(kind, true, t.s, n.e);
                self.postfix_from(m);
                return;
            }
            self.bump();
            self.b.field_last("operator");
            self.unary();
            self.b.field_last("operand");
            self.b.wrap(m, "unary", true);
            return;
        }
        if self.at("defined?") {
            self.bump();
            self.unary();
            self.b.wrap(m, "unary", true);
            return;
        }
        self.primary_postfix();
    }

    fn primary_postfix(&mut self) {
        let m = self.b.mark();
        self.primary();
        self.postfix_from(m);
    }

    fn postfix_from(&mut self, m: usize) {
        loop {
            let tx = self.tx();
            let t = self.tok(0);
            // leading-dot method chain on next line
            if t.k == K::NL {
                let n = self.tok(1);
                let nx = self.txn(1);
                if n.k == K::Op && (nx == "." || nx == "&.") {
                    self.advance();
                    continue;
                }
                break;
            }
            if t.k != K::Op {
                break;
            }
            match tx {
                "." | "&." => {
                    self.set_field_first(m, "receiver");
                    self.bump();
                    self.b.field_last("operator");
                    self.skip_terms();
                    if self.at("(") {
                        // a.() call
                    } else {
                        let t = self.tok(0);
                        let kind = if t.k == K::Const { "constant" } else { "identifier" };
                        self.bump_named(kind);
                        self.b.field_last("method");
                    }
                    self.call_args_and_block(m, true);
                    self.b.wrap(m, "call", true);
                }
                "::" => {
                    let n = self.tok(1);
                    if n.k == K::Const && self.txn(2) != "(" {
                        self.set_field_first(m, "scope");
                        self.bump();
                        self.bump_named("constant");
                        self.b.field_last("name");
                        self.b.wrap(m, "scope_resolution", true);
                    } else {
                        self.set_field_first(m, "receiver");
                        self.bump();
                        self.b.field_last("operator");
                        self.bump_named("identifier");
                        self.b.field_last("method");
                        self.call_args_and_block(m, true);
                        self.b.wrap(m, "call", true);
                    }
                }
                "[" if !t.sp => {
                    self.set_field_first(m, "object");
                    self.bump();
                    self.skip_terms();
                    while !self.at("]") && self.k() != K::Eof {
                        self.call_arg();
                        self.skip_terms();
                        if !self.eat(",") {
                            break;
                        }
                        self.skip_terms();
                    }
                    self.expect("]");
                    self.b.wrap(m, "element_reference", true);
                }
                _ => break,
            }
        }
    }

    /// after method name: (args) / command args / block
    fn call_args_and_block(&mut self, m: usize, _has_receiver: bool) -> bool {
        let t = self.tok(0);
        let mut had = false;
        if self.at("(") && !t.sp {
            self.paren_args();
            self.b.field_last("arguments");
            had = true;
        } else if t.sp && self.command_arg_start() {
            self.command_args();
            self.b.field_last("arguments");
            had = true;
        }
        if self.at("{") {
            self.brace_block();
            self.b.field_last("block");
            had = true;
        } else if self.at("do") && !self.no_do {
            self.do_block();
            self.b.field_last("block");
            had = true;
        }
        let _ = m;
        had
    }

    fn command_arg_start(&self) -> bool {
        let t = self.tok(0);
        let tx = self.tx();
        match t.k {
            K::NL | K::Eof | K::Comment => false,
            K::Op => {
                let n = self.tok(1);
                match tx {
                    "-" | "*" | "&" | "**" | "::" | "[" | ":" => !n.sp && n.k != K::NL,
                    "!" | "->" | "~" | "(" => true,
                    _ => false,
                }
            }
            K::Ident => !matches!(tx, "if" | "unless" | "while" | "until" | "rescue" | "and" | "or" | "then" | "do" | "end" | "else" | "elsif" | "when" | "in" | "ensure"),
            _ => true,
        }
    }

    fn command_args(&mut self) {
        let m = self.b.mark();
        loop {
            self.call_arg();
            if self.at(",") {
                self.bump();
                self.skip_terms();
                continue;
            }
            break;
        }
        self.b.wrap(m, "argument_list", true);
    }

    fn paren_args(&mut self) {
        let m = self.b.mark();
        self.bump(); // (
        self.skip_terms();
        let save = self.no_do;
        self.no_do = false;
        while !self.at(")") && self.k() != K::Eof {
            self.call_arg();
            self.skip_terms();
            if !self.eat(",") {
                break;
            }
            self.skip_terms();
        }
        self.no_do = save;
        self.expect(")");
        self.b.wrap(m, "argument_list", true);
    }

    fn call_arg(&mut self) {
        let m = self.b.mark();
        let tx = self.tx();
        if self.k() == K::Op {
            match tx {
                "*" => {
                    self.bump();
                    self.arg();
                    self.b.wrap(m, "splat_argument", true);
                    return;
                }
                "**" => {
                    self.bump();
                    self.arg();
                    self.b.wrap(m, "hash_splat_argument", true);
                    return;
                }
                "&" => {
                    self.bump();
                    if !self.at(")") && !self.at(",") {
                        self.arg();
                    }
                    self.b.wrap(m, "block_argument", true);
                    return;
                }
                _ => {}
            }
        }
        // keyword pair `key: value`
        if matches!(self.k(), K::Ident | K::Const) && self.txn(1) == ":" && self.tok(1).s == self.tok(0).e {
            self.pair_symbol_key(m);
            return;
        }
        if self.k() == K::Str && self.txn(1) == ":" && self.tok(1).s == self.tok(0).e {
            self.string();
            self.b.field_last("key");
            self.bump();
            self.skip_terms();
            self.arg();
            self.b.field_last("value");
            self.b.wrap(m, "pair", true);
            return;
        }
        self.arg();
        if self.at("=>") {
            self.b.field_last("key");
            self.bump();
            self.skip_terms();
            self.arg();
            self.b.field_last("value");
            self.b.wrap(m, "pair", true);
        }
    }

    fn pair_symbol_key(&mut self, m: usize) {
        self.bump_named("hash_key_symbol");
        self.b.field_last("key");
        self.bump(); // :
        self.skip_terms();
        if !self.at(",") && !self.at(")") && !self.at("}") {
            self.arg();
            self.b.field_last("value");
        }
        self.b.wrap(m, "pair", true);
    }

    fn brace_block(&mut self) {
        let m = self.b.mark();
        self.bump(); // {
        self.skip_terms();
        if self.at("|") {
            self.block_params();
            self.b.field_last("parameters");
        }
        let mb = self.b.mark();
        let n = self.statements(&["}"]);
        if n > 0 {
            self.b.wrap(mb, "block_body", true);
            self.b.field_last("body");
        }
        self.expect("}");
        self.b.wrap(m, "block", true);
    }

    fn do_block(&mut self) {
        let m = self.b.mark();
        self.bump(); // do
        while self.k() == K::NL && self.txn(1) == "|" {
            self.advance();
        }
        if self.at("|") {
            self.block_params();
            self.b.field_last("parameters");
        }
        if self.body(&["end"], "body_statement") {
            self.b.field_last("body");
        }
        self.expect("end");
        self.b.wrap(m, "do_block", true);
    }

    fn block_params(&mut self) {
        let m = self.b.mark();
        self.bump(); // |
        while !self.at("|") && self.k() != K::Eof {
            self.param();
            if !self.eat(",") {
                break;
            }
        }
        self.expect("|");
        self.b.wrap(m, "block_parameters", true);
    }

    fn param(&mut self) {
        let m = self.b.mark();
        let tx = self.tx();
        match tx {
            "*" => {
                self.bump();
                if self.k() == K::Ident {
                    self.bump_named("identifier");
                    self.b.field_last("name");
                }
                self.b.wrap(m, "splat_parameter", true);
            }
            "**" => {
                self.bump();
                if self.k() == K::Ident {
                    self.bump_named("identifier");
                    self.b.field_last("name");
                }
                self.b.wrap(m, "hash_splat_parameter", true);
            }
            "&" => {
                self.bump();
                if self.k() == K::Ident {
                    self.bump_named("identifier");
                    self.b.field_last("name");
                }
                self.b.wrap(m, "block_parameter", true);
            }
            "(" => {
                self.bump();
                while !self.at(")") && self.k() != K::Eof {
                    self.param();
                    if !self.eat(",") {
                        break;
                    }
                }
                self.expect(")");
                self.b.wrap(m, "destructured_parameter", true);
            }
            _ => {
                self.bump_named("identifier");
                if self.at(":") && self.tok(0).s == self.cur_pos() {
                    self.b.field_last("name");
                    self.bump();
                    if !self.at(",") && !self.at(")") && !self.at("|") && self.k() != K::NL {
                        self.arg();
                        self.b.field_last("value");
                    }
                    self.b.wrap(m, "keyword_parameter", true);
                } else if self.at("=") {
                    self.b.field_last("name");
                    self.bump();
                    self.arg();
                    self.b.field_last("value");
                    self.b.wrap(m, "optional_parameter", true);
                }
            }
        }
    }

    fn string(&mut self) {
        let t = self.advance();
        let b = self.src.as_bytes();
        let m = self.b.mark();
        let txt = &self.src[t.s..t.e];
        if txt.starts_with('/') {
            // regex
            self.b.leaf("/", false, t.s, t.s + 1);
            let close = txt.rfind('/').unwrap_or(0);
            if close > 1 {
                self.b.leaf("string_content", true, t.s + 1, t.s + close);
            }
            self.b.leaf("/", false, t.s + close, t.s + close + 1);
            self.b.wrap(m, "regex", true);
            let _ = b;
            return;
        }
        if txt.starts_with('%') {
            let kind = match txt.as_bytes().get(1) {
                Some(b'w') | Some(b'W') => "string_array",
                Some(b'i') | Some(b'I') => "symbol_array",
                Some(b'r') => "regex",
                _ => "string",
            };
            let open_len = if txt.as_bytes()[1].is_ascii_alphabetic() { 3 } else { 2 };
            self.b.leaf(intern(&txt[..open_len]), false, t.s, t.s + open_len);
            let inner_s = t.s + open_len;
            let inner_e = t.e - 1;
            if kind.ends_with("_array") {
                let mut k = inner_s;
                while k < inner_e {
                    while k < inner_e && (b[k] as char).is_whitespace() {
                        k += 1;
                    }
                    let ws = k;
                    while k < inner_e && !(b[k] as char).is_whitespace() {
                        k += 1;
                    }
                    if k > ws {
                        let mb = self.b.mark();
                        self.b.leaf("string_content", true, ws, k);
                        self.b.wrap(mb, if kind == "string_array" { "bare_string" } else { "bare_symbol" }, true);
                    }
                }
            } else if inner_e > inner_s {
                self.b.leaf("string_content", true, inner_s, inner_e);
            }
            self.b.leaf(intern(&txt[txt.len() - 1..]), false, t.e - 1, t.e);
            self.b.wrap(m, kind, true);
            return;
        }
        let q = b[t.s];
        let qk = intern(&txt[..1]);
        self.b.leaf(qk, false, t.s, t.s + 1);
        let close = t.e > t.s + 1 && b[t.e - 1] == q;
        let ce = if close { t.e - 1 } else { t.e };
        let mut i = t.s + 1;
        let mut cs = i;
        while i < ce {
            if b[i] == b'\\' && (q == b'"' || (i + 1 < ce && (b[i + 1] == b'\'' || b[i + 1] == b'\\'))) {
                if cs < i {
                    self.b.leaf("string_content", true, cs, i);
                }
                let e = (i + 2).min(ce);
                self.b.leaf("escape_sequence", true, i, e);
                i = e;
                cs = i;
                continue;
            }
            if q != b'\'' && b[i] == b'#' && i + 1 < ce && b[i + 1] == b'{' {
                if cs < i {
                    self.b.leaf("string_content", true, cs, i);
                }
                let mi = self.b.mark();
                self.b.leaf("#{", false, i, i + 2);
                // find matching }
                let mut depth = 1;
                let mut k = i + 2;
                while k < ce && depth > 0 {
                    if b[k] == b'{' {
                        depth += 1;
                    } else if b[k] == b'}' {
                        depth -= 1;
                        if depth == 0 {
                            break;
                        }
                    }
                    k += 1;
                }
                // parse inner expression
                let inner = tokenize(&self.src[..k]);
                let sub: Vec<Tk> = inner.into_iter().filter(|x| x.s >= i + 2 && x.k != K::Eof).collect();
                let mut sub = sub;
                sub.push(Tk { k: K::Eof, s: k, e: k, sp: true });
                let saved = std::mem::replace(&mut self.toks, sub);
                let saved_i = self.i;
                self.i = 0;
                self.statements(&[]);
                self.flush_extras();
                self.toks = saved;
                self.i = saved_i;
                if k < ce {
                    self.b.leaf("}", false, k, k + 1);
                }
                self.b.wrap(mi, "interpolation", true);
                i = (k + 1).min(ce);
                cs = i;
                continue;
            }
            i += 1;
        }
        if cs < ce {
            self.b.leaf("string_content", true, cs, ce);
        }
        if close {
            self.b.leaf(qk, false, t.e - 1, t.e);
        }
        self.b.wrap(m, if q == b'`' { "subshell" } else { "string" }, true);
    }

    fn primary(&mut self) {
        let m = self.b.mark();
        let t = self.tok(0);
        let tx = self.tx();
        match t.k {
            K::Num => {
                let kind = if tx.contains('.') || (tx.contains('e') && !tx.starts_with("0x")) { "float" } else { "integer" };
                self.bump_named(kind);
            }
            K::Str => {
                self.string();
                // adjacent string literal concatenation
                if self.k() == K::Str && self.tok(0).sp && self.src[self.tok(0).s..].starts_with(['"', '\'']) {
                    while self.k() == K::Str {
                        self.string();
                    }
                    self.b.wrap(m, "chained_string", true);
                }
            }
            K::Sym => {
                let txt = tx;
                if txt.starts_with(":\"") {
                    let t = self.advance();
                    self.b.leaf(":\"", false, t.s, t.s + 2);
                    if t.e > t.s + 3 {
                        self.b.leaf("string_content", true, t.s + 2, t.e - 1);
                    }
                    self.b.leaf("\"", false, t.e - 1, t.e);
                    self.b.wrap(m, "delimited_symbol", true);
                } else {
                    self.bump_named("simple_symbol");
                }
            }
            K::IVar => {
                self.bump_named("instance_variable");
            }
            K::CVar => {
                self.bump_named("class_variable");
            }
            K::GVar => {
                self.bump_named("global_variable");
            }
            K::Const => {
                self.bump_named("constant");
                if self.at("(") && !self.tok(0).sp {
                    self.set_field_first(m, "method");
                    self.call_args_and_block(m, false);
                    self.b.wrap(m, "call", true);
                } else if self.tok(0).sp && self.k() == K::Str {
                    self.set_field_first(m, "method");
                    self.command_args();
                    self.b.field_last("arguments");
                    self.b.wrap(m, "call", true);
                }
            }
            K::Ident => self.keyword_or_ident(m),
            K::Op => match tx {
                "(" => {
                    self.bump();
                    self.skip_terms();
                    let n = self.statements(&[")"]);
                    let _ = n;
                    self.expect(")");
                    self.b.wrap(m, "parenthesized_statements", true);
                }
                "[" => {
                    self.bump();
                    self.skip_terms();
                    while !self.at("]") && self.k() != K::Eof {
                        self.call_arg();
                        self.skip_terms();
                        if !self.eat(",") {
                            break;
                        }
                        self.skip_terms();
                    }
                    self.expect("]");
                    self.b.wrap(m, "array", true);
                }
                "{" => {
                    self.bump();
                    self.skip_terms();
                    while !self.at("}") && self.k() != K::Eof {
                        let mp = self.b.mark();
                        if self.at("**") {
                            self.bump();
                            self.arg();
                            self.b.wrap(mp, "hash_splat_argument", true);
                        } else if matches!(self.k(), K::Ident | K::Const) && self.txn(1) == ":" && self.tok(1).s == self.tok(0).e {
                            self.pair_symbol_key(mp);
                        } else if self.k() == K::Str && self.txn(1) == ":" && self.tok(1).s == self.tok(0).e {
                            self.string();
                            self.b.field_last("key");
                            self.bump();
                            self.skip_terms();
                            self.arg();
                            self.b.field_last("value");
                            self.b.wrap(mp, "pair", true);
                        } else {
                            self.arg();
                            self.b.field_last("key");
                            self.skip_terms();
                            self.expect("=>");
                            self.skip_terms();
                            self.arg();
                            self.b.field_last("value");
                            self.b.wrap(mp, "pair", true);
                        }
                        self.skip_terms();
                        if !self.eat(",") {
                            break;
                        }
                        self.skip_terms();
                    }
                    self.expect("}");
                    self.b.wrap(m, "hash", true);
                }
                "->" => {
                    self.bump();
                    if self.at("(") {
                        let mp = self.b.mark();
                        self.bump();
                        while !self.at(")") && self.k() != K::Eof {
                            self.param();
                            if !self.eat(",") {
                                break;
                            }
                        }
                        self.expect(")");
                        self.b.wrap(mp, "lambda_parameters", true);
                        self.b.field_last("parameters");
                    } else if self.k() == K::Ident {
                        let mp = self.b.mark();
                        while self.k() == K::Ident {
                            self.param();
                            if !self.eat(",") {
                                break;
                            }
                        }
                        self.b.wrap(mp, "lambda_parameters", true);
                        self.b.field_last("parameters");
                    }
                    if self.at("{") {
                        self.brace_block();
                    } else {
                        self.do_block();
                    }
                    self.b.field_last("body");
                    self.b.wrap(m, "lambda", true);
                }
                "::" => {
                    self.bump();
                    self.bump_named("constant");
                    self.b.field_last("name");
                    self.b.wrap(m, "scope_resolution", true);
                }
                _ => self.error_token(),
            },
            _ => {
                let p = self.cur_pos();
                self.b.missing("identifier", true, p);
            }
        }
    }

    fn keyword_or_ident(&mut self, m: usize) {
        let tx = self.tx();
        match tx {
            "nil" => {
                self.bump_named("nil");
            }
            "true" => {
                self.bump_named("true");
            }
            "false" => {
                self.bump_named("false");
            }
            "self" => {
                self.bump_named("self");
            }
            "def" => self.method_def(m),
            "class" => {
                self.bump();
                if self.at("<<") {
                    self.bump();
                    self.arg();
                    self.b.field_last("value");
                    if self.body(&["end"], "body_statement") {
                        self.b.field_last("body");
                    }
                    self.expect("end");
                    self.b.wrap(m, "singleton_class", true);
                    return;
                }
                self.const_path();
                self.b.field_last("name");
                if self.at("<") {
                    let ms = self.b.mark();
                    self.bump();
                    self.arg();
                    self.b.wrap(ms, "superclass", true);
                    self.b.field_last("superclass");
                }
                if self.body(&["end"], "body_statement") {
                    self.b.field_last("body");
                }
                self.expect("end");
                self.b.wrap(m, "class", true);
            }
            "module" => {
                self.bump();
                self.const_path();
                self.b.field_last("name");
                if self.body(&["end"], "body_statement") {
                    self.b.field_last("body");
                }
                self.expect("end");
                self.b.wrap(m, "module", true);
            }
            "if" | "unless" => {
                self.bump();
                self.cond_expr();
                self.b.field_last("condition");
                self.then_part(&["elsif", "else", "end"]);
                self.if_tail(tx == "if");
                self.expect("end");
                self.b.wrap(m, tx, true);
            }
            "while" | "until" => {
                self.bump();
                self.cond_expr();
                self.b.field_last("condition");
                let md = self.b.mark();
                if self.at("do") {
                    self.bump();
                }
                self.skip_terms();
                self.statements(&["end"]);
                self.expect("end");
                self.b.wrap(md, "do", true);
                self.b.field_last("body");
                self.b.wrap(m, tx, true);
            }
            "for" => {
                self.bump();
                let ml = self.b.mark();
                self.primary();
                if self.at(",") {
                    while self.eat(",") {
                        self.primary();
                    }
                    self.b.wrap(ml, "left_assignment_list", true);
                }
                self.b.field_last("pattern");
                let mi = self.b.mark();
                self.expect("in");
                self.cond_expr();
                self.b.wrap(mi, "in", true);
                self.b.field_last("value");
                let md = self.b.mark();
                if self.at("do") {
                    self.bump();
                }
                self.skip_terms();
                self.statements(&["end"]);
                self.expect("end");
                self.b.wrap(md, "do", true);
                self.b.field_last("body");
                self.b.wrap(m, "for", true);
            }
            "case" => {
                self.bump();
                if self.k() != K::NL {
                    self.arg();
                    self.b.field_last("value");
                }
                self.skip_terms();
                while self.at("when") || self.at("in") {
                    let mw = self.b.mark();
                    let is_in = self.at("in");
                    self.bump();
                    loop {
                        let mp = self.b.mark();
                        if self.at("*") {
                            let ms = self.b.mark();
                            self.bump();
                            self.arg();
                            self.b.wrap(ms, "splat_argument", true);
                        } else {
                            self.arg();
                        }
                        if !is_in {
                            self.b.wrap(mp, "pattern", true);
                            self.b.field_last("pattern");
                        } else {
                            self.b.field_last("pattern");
                        }
                        if !self.eat(",") {
                            break;
                        }
                        self.skip_terms();
                    }
                    self.then_part(&["when", "in", "else", "end"]);
                    self.b.wrap(mw, if is_in { "in_clause" } else { "when" }, true);
                    self.skip_terms();
                }
                if self.at("else") {
                    let me = self.b.mark();
                    self.bump();
                    self.skip_terms();
                    self.statements(&["end"]);
                    self.b.wrap(me, "else", true);
                }
                self.expect("end");
                self.b.wrap(m, "case", true);
            }
            "begin" => {
                self.bump();
                self.skip_terms();
                self.statements(&["rescue", "else", "ensure", "end"]);
                while self.at("rescue") || self.at("else") || self.at("ensure") {
                    if self.at("rescue") {
                        self.rescue_clause();
                    } else if self.at("else") {
                        let me = self.b.mark();
                        self.bump();
                        self.statements(&["ensure", "end"]);
                        self.b.wrap(me, "else", true);
                    } else {
                        let me = self.b.mark();
                        self.bump();
                        self.statements(&["end"]);
                        self.b.wrap(me, "ensure", true);
                    }
                }
                self.expect("end");
                self.b.wrap(m, "begin", true);
            }
            "return" | "break" | "next" | "yield" | "super" | "redo" | "retry" => {
                self.bump();
                if tx == "redo" || tx == "retry" {
                    self.b.wrap(m, tx, true);
                    return;
                }
                if tx == "super" && self.at("(") && !self.tok(0).sp {
                    self.paren_args();
                    self.b.field_last("arguments");
                    self.call_args_and_block(m, false);
                    self.b.wrap(m, "call", true);
                    return;
                }
                if self.tok(0).sp && self.command_arg_start() {
                    self.command_args();
                } else if self.at("(") && tx == "yield" {
                    self.paren_args();
                }
                if tx == "super" {
                    self.b.wrap(m, "super", true);
                    return;
                }
                self.b.wrap(m, tx, true);
            }
            "alias" => {
                self.bump();
                self.method_name();
                self.b.field_last("name");
                self.method_name();
                self.b.field_last("alias");
                self.b.wrap(m, "alias", true);
            }
            "__FILE__" | "__LINE__" | "__dir__" => {
                self.bump_named(if tx == "__FILE__" { "file" } else { "line" });
            }
            _ => {
                // identifier: maybe call
                self.bump_named("identifier");
                let t = self.tok(0);
                if self.at("(") && !t.sp {
                    self.set_field_first(m, "method");
                    self.call_args_and_block(m, false);
                    self.b.wrap(m, "call", true);
                } else if t.sp && self.command_arg_start() && !self.is_local_assign_ahead() {
                    self.set_field_first(m, "method");
                    self.call_args_and_block(m, false);
                    self.b.wrap(m, "call", true);
                } else if self.at("{") || (self.at("do") && !self.no_do) {
                    self.set_field_first(m, "method");
                    self.call_args_and_block(m, false);
                    self.b.wrap(m, "call", true);
                }
            }
        }
    }

    fn is_local_assign_ahead(&self) -> bool {
        false
    }

    fn method_name(&mut self) {
        let t = self.tok(0);
        match t.k {
            K::Sym => {
                self.bump_named("simple_symbol");
            }
            K::Const => {
                self.bump_named("constant");
            }
            K::Op => {
                let m = self.b.mark();
                self.bump();
                if self.at("]") {
                    self.bump();
                }
                self.b.wrap(m, "operator", true);
            }
            _ => {
                let e = self.tok(0).e;
                let tk = self.advance();
                let mut end = tk.e;
                // setter name foo=
                if self.at("=") && self.tok(0).s == e && self.tok(1).k != K::Op {
                    end = self.advance().e;
                }
                self.b.leaf(if end > tk.e { "setter" } else { "identifier" }, true, tk.s, end);
            }
        }
    }

    fn const_path(&mut self) {
        let m = self.b.mark();
        if self.at("::") {
            self.bump();
        }
        self.bump_named("constant");
        while self.at("::") {
            self.set_field_first(m, "scope");
            self.bump();
            self.bump_named("constant");
            self.b.field_last("name");
            self.b.wrap(m, "scope_resolution", true);
        }
    }

    fn cond_expr(&mut self) {
        let save = self.no_do;
        self.no_do = true;
        self.expression_statement();
        self.no_do = save;
    }

    fn then_part(&mut self, ends: &[&str]) {
        let mt = self.b.mark();
        let had_then = self.at("then");
        if had_then {
            self.bump();
        }
        self.skip_terms();
        let n = self.statements(ends);
        if n > 0 || had_then {
            self.b.wrap(mt, "then", true);
            self.b.field_last(if ends.contains(&"when") { "body" } else { "consequence" });
        }
    }

    fn if_tail(&mut self, _is_if: bool) {
        if self.at("elsif") {
            let me = self.b.mark();
            self.bump();
            self.cond_expr();
            self.b.field_last("condition");
            self.then_part(&["elsif", "else", "end"]);
            self.if_tail(true);
            self.b.wrap(me, "elsif", true);
            self.b.field_last("alternative");
        } else if self.at("else") {
            let me = self.b.mark();
            self.bump();
            self.skip_terms();
            self.statements(&["end"]);
            self.b.wrap(me, "else", true);
            self.b.field_last("alternative");
        }
    }

    fn method_def(&mut self, m: usize) {
        self.bump(); // def
        let singleton = (self.at("self") || self.k() == K::Ident || self.k() == K::Const) && self.txn(1) == "." && self.tok(1).s == self.tok(0).e;
        if singleton {
            if self.at("self") {
                self.bump_named("self");
            } else if self.k() == K::Const {
                self.bump_named("constant");
            } else {
                self.bump_named("identifier");
            }
            self.b.field_last("object");
            self.bump();
        }
        self.method_name();
        self.b.field_last("name");
        if self.at("(") {
            let mp = self.b.mark();
            self.bump();
            self.skip_terms();
            while !self.at(")") && self.k() != K::Eof {
                self.param();
                self.skip_terms();
                if !self.eat(",") {
                    break;
                }
                self.skip_terms();
            }
            self.expect(")");
            self.b.wrap(mp, "method_parameters", true);
            self.b.field_last("parameters");
        } else if self.k() != K::NL && !self.at(";") && !self.at("=") {
            let mp = self.b.mark();
            while self.k() != K::NL && !self.at(";") && self.k() != K::Eof {
                self.param();
                if !self.eat(",") {
                    break;
                }
            }
            self.b.wrap(mp, "method_parameters", true);
            self.b.field_last("parameters");
        }
        if self.at("=") {
            // endless method
            self.bump();
            self.skip_terms();
            self.arg();
            self.b.field_last("body");
            self.b.wrap(m, if singleton { "singleton_method" } else { "method" }, true);
            return;
        }
        if self.at(";") {
            self.bump();
        }
        if self.body(&["end"], "body_statement") {
            self.b.field_last("body");
        }
        self.expect("end");
        self.b.wrap(m, if singleton { "singleton_method" } else { "method" }, true);
    }
}

fn has_rescue(b: &Builder, m: usize) -> bool {
    b.stack[m.min(b.stack.len())..].iter().any(|&c| b.nodes[c as usize].kind == "rescue")
}

#[allow(dead_code)]
fn is_kw(s: &str) -> bool {
    KW.contains(&s)
