{"command":"cat > /workspace/src/lang/bash.rs <<'EOF'
// Bash parser (common subset of tree-sitter-bash)
use super::js::intern;
use crate::tree::{Builder, Tree};

struct P<'a> {
    s: &'a [u8],
    src: &'a str,
    i: usize,
    b: Builder,
    depth: usize,
}

pub fn parse(src: &str) -> Tree {
    let mut p = P { s: src.as_bytes(), src, i: 0, b: Builder::new(), depth: 0 };
    let m = p.b.mark();
    p.statements(&[], false);
    p.ws_nl();
    let start = p.b.stack[m..].first().map(|&c| p.b.nodes[c as usize].start).unwrap_or(src.len() - src.trim_start().len());
    let root = p.b.wrap_all(m, "program", start, src.len());
    p.b.finish(root, src)
}

fn is_word_char(c: u8) -> bool {
    !matches!(c, b' ' | b'\t' | b'\n' | b'\r' | b';' | b'&' | b'|' | b'<' | b'>' | b'(' | b')' | b'"' | b'\'' | b'`' | b'$')
}

impl<'a> P<'a> {
    fn peek(&self) -> u8 {
        *self.s.get(self.i).unwrap_or(&0)
    }
    fn peek_at(&self, k: usize) -> u8 {
        *self.s.get(self.i + k).unwrap_or(&0)
    }
    fn starts(&self, t: &str) -> bool {
        self.src[self.i..].starts_with(t)
    }
    /// skip spaces/tabs and line continuations; comments become extras
    fn ws(&mut self) {
        loop {
            let c = self.peek();
            if c == b' ' || c == b'\t' || c == b'\r' {
                self.i += 1;
            } else if c == b'\\' && self.peek_at(1) == b'\n' {
                self.i += 2;
            } else if c == b'#' && (self.i == 0 || matches!(self.s[self.i - 1], b' ' | b'\t' | b'\n' | b';')) {
                let st = self.i;
                while self.i < self.s.len() && self.s[self.i] != b'\n' {
                    self.i += 1;
                }
                self.b.extra("comment", st, self.i);
            } else {
                break;
            }
        }
    }
    fn ws_nl(&mut self) {
        loop {
            self.ws();
            if self.peek() == b'\n' {
                self.i += 1;
                continue;
            }
            break;
        }
    }
    fn tok(&mut self, t: &'static str) {
        self.b.leaf(t, false, self.i, self.i + t.len());
        self.i += t.len();
    }
    fn word_at(&self) -> &'a str {
        let mut k = self.i;
        while k < self.s.len() && is_word_char(self.s[k]) {
            k += 1;
        }
        &self.src[self.i..k]
    }
    fn at_kw(&self, kw: &str) -> bool {
        self.word_at() == kw
    }

    fn statements(&mut self, ends: &[&str], in_paren: bool) -> usize {
        let mut n = 0;
        loop {
            self.ws_nl();
            if self.i >= self.s.len() {
                break;
            }
            if ends.iter().any(|e| self.at_kw(e) || (e.len() <= 2 && !e.chars().any(|c| c.is_alphabetic()) && self.starts(e))) {
                break;
            }
            if in_paren && self.peek() == b')' {
                break;
            }
            if self.peek() == b'}' && ends.contains(&"}") {
                break;
            }
            let before = self.i;
            self.list();
            n += 1;
            self.ws();
            if self.peek() == b';' && self.peek_at(1) != b';' {
                self.tok(";");
            } else if self.peek() == b'&' && self.peek_at(1) != b'&' && self.peek_at(1) != b'>' {
                self.tok("&");
            }
            if self.i == before {
                let m = self.b.mark();
                self.b.leaf(intern(&self.src[self.i..self.i + 1]), false, self.i, self.i + 1);
                self.i += 1;
                self.b.wrap(m, "ERROR", true);
            }
        }
        n
    }

    fn list(&mut self) {
        let m = self.b.mark();
        self.pipeline();
        loop {
            self.ws();
            if self.starts("&&") || self.starts("||") {
                let t = if self.starts("&&") { "&&" } else { "||" };
                self.tok(t);
                self.ws_nl();
                self.pipeline();
                self.b.wrap(m, "list", true);
            } else {
                break;
            }
        }
    }

    fn pipeline(&mut self) {
        let m = self.b.mark();
        let neg = self.peek() == b'!' && matches!(self.peek_at(1), b' ' | b'\t');
        if neg {
            self.tok("!");
            self.ws();
        }
        self.statement();
        let mut piped = false;
        loop {
            self.ws();
            if self.peek() == b'|' && self.peek_at(1) != b'|' {
                if self.peek_at(1) == b'&' {
                    self.tok("|&");
                } else {
                    self.tok("|");
                }
                self.ws_nl();
                self.statement();
                piped = true;
            } else {
                break;
            }
        }
        if piped {
            self.b.wrap(m, "pipeline", true);
        }
        if neg {
            self.b.wrap(m, "negated_command", true);
        }
    }

    fn statement(&mut self) {
        self.depth += 1;
        if self.depth > 200 {
            self.depth -= 1;
            return;
        }
        let m = self.b.mark();
        let w = self.word_at();
        match w {
            "if" => self.if_stmt(),
            "for" | "select" => self.for_stmt(),
            "while" | "until" => {
                let mw = self.b.mark();
                self.tok(if w == "while" { "while" } else { "until" });
                self.ws();
                let mc = self.b.mark();
                self.statements(&["do"], false);
                self.b.field_from(mc, "condition");
                self.do_group();
                self.b.field_last("body");
                self.b.wrap(mw, "while_statement", true);
            }
            "case" => self.case_stmt(),
            "function" => {
                let mf = self.b.mark();
                self.tok("function");
                self.ws();
                let ws = self.i;
                let w2 = self.word_at();
                self.i += w2.len();
                self.b.leaf("word", true, ws, self.i);
                self.b.field_last("name");
                self.ws();
                if self.peek() == b'(' {
                    self.tok("(");
                    self.ws();
                    if self.peek() == b')' {
                        self.tok(")");
                    }
                }
                self.ws_nl();
                self.compound_body();
                self.b.field_last("body");
                self.b.wrap(mf, "function_definition", true);
            }
            "local" | "export" | "declare" | "readonly" | "typeset" => {
                let md = self.b.mark();
                let k = intern(w);
                self.tok(k);
                loop {
                    self.ws();
                    if self.at_end_of_command() {
                        break;
                    }
                    if self.is_assignment_ahead() {
                        self.assignment();
                    } else {
                        self.word_like(false);
                    }
                }
                self.b.wrap(md, "declaration_command", true);
            }
            "unset" | "unsetenv" => {
                let md = self.b.mark();
                let k = intern(w);
                self.tok(k);
                loop {
                    self.ws();
                    if self.at_end_of_command() {
                        break;
                    }
                    self.word_like(false);
                }
                self.b.wrap(md, "unset_command", true);
            }
            _ => {
                if self.peek() == b'{' && matches!(self.peek_at(1), b' ' | b'\n' | b'\t') {
                    self.compound_body();
                } else if self.peek() == b'(' && self.peek_at(1) == b'(' {
                    // arithmetic command
                    let ma = self.b.mark();
                    self.tok("((");
                    let st = self.i;
                    let mut depth = 0;
                    while self.i < self.s.len() {
                        if self.peek() == b'(' {
                            depth += 1;
                        } else if self.peek() == b')' {
                            if depth == 0 {
                                break;
                            }
                            depth -= 1;
                        }
                        self.i += 1;
                    }
                    let txt = self.src[st..self.i].trim();
                    if !txt.is_empty() {
                        let off = st + self.src[st..].find(txt).unwrap_or(0);
                        self.b.leaf("word", true, off, off + txt.len());
                    }
                    if self.starts("))") {
                        self.tok("))");
                    }
                    self.b.wrap(ma, "compound_statement", true);
                } else if self.peek() == b'(' {
                    let ms = self.b.mark();
                    self.tok("(");
                    self.statements(&[], true);
                    if self.peek() == b')' {
                        self.tok(")");
                    }
                    self.b.wrap(ms, "subshell", true);
                } else if self.peek() == b'[' {
                    self.test_command();
                } else if self.is_func_def_ahead() {
                    let mf = self.b.mark();
                    let ws = self.i;
                    let w2 = self.word_at();
                    self.i += w2.len();
                    self.b.leaf("word", true, ws, self.i);
                    self.b.field_last("name");
                    self.ws();
                    self.tok("(");
                    self.ws();
                    self.tok(")");
                    self.ws_nl();
                    self.compound_body();
                    self.b.field_last("body");
                    self.b.wrap(mf, "function_definition", true);
                } else {
                    self.command();
                }
            }
        }
        // redirects
        let mut redirected = false;
        loop {
            self.ws();
            if self.at_redirect() {
                self.redirect();
                self.b.field_last("redirect");
                redirected = true;
            } else {
                break;
            }
        }
        if redirected {
            self.set_field_first(m, "body");
            self.b.wrap(m, "redirected_statement", true);
        }
        self.depth -= 1;
    }

    fn set_field_first(&mut self, m: usize, f: &'static str) {
        for i in m..self.b.stack.len() {
            let id = self.b.stack[i] as usize;
            if !self.b.nodes[id].extra {
                self.b.nodes[id].field = Some(f);
                return;
            }
        }
    }

    fn is_func_def_ahead(&self) -> bool {
        let w = self.word_at();
        if w.is_empty() {
            return false;
        }
        let mut k = self.i + w.len();
        while k < self.s.len() && matches!(self.s[k], b' ' | b'\t') {
            k += 1;
        }
        k + 1 < self.s.len() && self.s[k] == b'(' && {
            let mut j = k + 1;
            while j < self.s.len() && matches!(self.s[j], b' ' | b'\t') {
                j += 1;
            }
            j < self.s.len() && self.s[j] == b')'
        }
    }

    fn compound_body(&mut self) {
        let m = self.b.mark();
        if self.peek() == b'{' {
            self.tok("{");
            self.statements(&["}"], false);
            self.ws_nl();
            if self.peek() == b'}' {
                self.tok("}");
            }
            self.b.wrap(m, "compound_statement", true);
        } else if self.peek() == b'(' {
            self.tok("(");
            self.statements(&[], true);
            if self.peek() == b')' {
                self.tok(")");
            }
            self.b.wrap(m, "subshell", true);
        } else {
            self.statement();
        }
    }

    fn at_end_of_command(&self) -> bool {
        let c = self.peek();
        c == 0 || matches!(c, b'\n' | b';' | b'&' | b'|' | b')' | b'`') || (c == b'}' && false) || (c == b'#')
    }

    fn at_redirect(&self) -> bool {
        let c = self.peek();
        if c == b'>' || c == b'<' {
            return !(c == b'<' && self.peek_at(1) == b'(') && !(c == b'>' && self.peek_at(1) == b'(');
        }
        if c == b'&' && self.peek_at(1) == b'>' {
            return true;
        }
        if c.is_ascii_digit() {
            let n = self.peek_at(1);
            return n == b'>' || n == b'<';
        }
        false
    }

    fn redirect(&mut self) {
