            let t = if self.starts("<<-") { "<<-" } else { "<<" };
            self.tok(t);
            self.ws();
            let st = self.i;
            let w = self.word_at();
            self.i += w.len();
            self.b.leaf("heredoc_start", true, st, self.i);
            let delim = w.trim_matches(|c| c == '\'' || c == '"').to_string();
            // body: from next line to delimiter line
            let rest = &self.src[self.i..];
            if let Some(nl) = rest.find('\n') {
                let body_start = self.i + nl + 1;
                let mut k = body_start;
                let mut end_line = None;
                while k < self.s.len() {
                    let le = self.src[k..].find('\n').map(|x| k + x).unwrap_or(self.s.len());
                    if self.src[k..le].trim() == delim {
                        end_line = Some((k, le));
                        break;
                    }
                    k = le + 1;
                }
                if let Some((ls, le)) = end_line {
                    // rest of current line after heredoc start remains for parsing; simplify: skip
                    let _ = body_start;
                    let mb = self.b.mark();
                    if ls > body_start {
                        self.b.leaf("heredoc_content", true, body_start, ls);
                    }
                    self.b.wrap_at(mb, "heredoc_body", true, body_start);
                    let id = self.b.last().unwrap() as usize;
                    self.b.nodes[id].start = body_start;
                    self.b.nodes[id].end = ls;
                    let es = ls + (self.src[ls..le].len() - self.src[ls..le].trim_start().len());
                    self.b.leaf("heredoc_end", true, es, le);
                    self.i = le;
                }
            }
            self.b.wrap(m, "heredoc_redirect", true);
            return;
        }
        let ops = [">>", "&>>", "&>", ">&", "<&", ">|", "<>", ">", "<"];
        for o in ops {
            if self.starts(o) {
                self.tok(o);
                break;
            }
        }
        self.ws();
        self.word_like(false);
        self.b.field_last("destination");
        self.b.wrap(m, "file_redirect", true);
    }

    fn is_assignment_ahead(&self) -> bool {
        let mut k = self.i;
        if k < self.s.len() && (self.s[k].is_ascii_alphabetic() || self.s[k] == b'_') {
            while k < self.s.len() && (self.s[k].is_ascii_alphanumeric() || self.s[k] == b'_') {
                k += 1;
            }
            if k < self.s.len() && self.s[k] == b'[' {
                while k < self.s.len() && self.s[k] != b']' {
                    k += 1;
                }
                k += 1;
            }
            if k < self.s.len() && self.s[k] == b'+' {
                k += 1;
            }
            return k < self.s.len() && self.s[k] == b'=';
        }
        false
    }

    fn assignment(&mut self) {
        let m = self.b.mark();
        let st = self.i;
        while self.i < self.s.len() && (self.s[self.i].is_ascii_alphanumeric() || self.s[self.i] == b'_') {
            self.i += 1;
        }
        if self.peek() == b'[' {
            let mi = self.b.mark();
            self.b.leaf("variable_name", true, st, self.i);
            self.b.field_last("name");
            self.tok("[");
            let is = self.i;
            while self.i < self.s.len() && self.s[self.i] != b']' {
                self.i += 1;
            }
            self.b.leaf("word", true, is, self.i);
            self.b.field_last("index");
            if self.peek() == b']' {
                self.tok("]");
            }
            self.b.wrap(mi, "subscript", true);
            self.b.field_last("name");
        } else {
            self.b.leaf("variable_name", true, st, self.i);
            self.b.field_last("name");
        }
        if self.starts("+=") {
            self.tok("+=");
        } else {
            self.tok("=");
        }
        if self.peek() == b'(' {
            let ma = self.b.mark();
            self.tok("(");
            loop {
                self.ws_nl();
                if self.peek() == b')' || self.i >= self.s.len() {
                    break;
                }
                self.word_like(false);
            }
            if self.peek() == b')' {
                self.tok(")");
            }
            self.b.wrap(ma, "array", true);
            self.b.field_last("value");
        } else if !self.at_end_of_command() && !matches!(self.peek(), b' ' | b'\t') {
            self.word_like(false);
            self.b.field_last("value");
        }
        self.b.wrap(m, "variable_assignment", true);
    }

    fn command(&mut self) {
        let m = self.b.mark();
        // prefix assignments
        let mut n_assign = 0;
        while self.is_assignment_ahead() {
            self.assignment();
            n_assign += 1;
            self.ws();
        }
        if n_assign > 0 && self.at_end_of_command() {
            if n_assign > 1 {
                self.b.wrap(m, "variable_assignments", true);
            }
            return;
        }
        if self.at_end_of_command() {
            return;
        }
        let mn = self.b.mark();
        self.word_like(true);
        self.b.wrap(mn, "command_name", true);
        self.b.field_last("name");
        loop {
            self.ws();
            if self.at_end_of_command() || self.at_redirect() {
                if self.at_redirect() {
                    // redirect inside command args
                    let save = self.i;
                    let _ = save;
                    break;
                }
                break;
            }
            if self.peek() == b'}' {
                break;
            }
            let before = self.i;
            self.word_like(false);
            self.b.field_last("argument");
            if self.i == before {
                break;
            }
        }
        self.b.wrap(m, "command", true);
    }

    /// a shell word possibly composed of multiple parts (concatenation)
    fn word_like(&mut self, _is_name: bool) {
        let m = self.b.mark();
        let mut parts = 0;
        loop {
            let c = self.peek();
            if c == 0 || matches!(c, b' ' | b'\t' | b'\n' | b'\r' | b';' | b'&' | b'|' | b'<' | b'>' | b')') {
                if (c == b'<' || c == b'>') && self.peek_at(1) == b'(' {
                    // process substitution
                } else {
                    break;
                }
            }
            if c == b'(' && parts > 0 {
                break;
            }
            let before = self.i;
            self.word_part();
            if self.i == before {
                break;
            }
            parts += 1;
        }
        if parts > 1 {
            self.b.wrap(m, "concatenation", true);
        }
    }

    fn word_part(&mut self) {
        let c = self.peek();
        match c {
            b'"' => self.dq_string(),
            b'\'' => {
                let st = self.i;
                self.i += 1;
                while self.i < self.s.len() && self.s[self.i] != b'\'' {
                    self.i += 1;
                }
                self.i = (self.i + 1).min(self.s.len());
                self.b.leaf("raw_string", true, st, self.i);
            }
            b'$' => self.dollar(),
            b'`' => {
                let m = self.b.mark();
                self.tok("`");
                let st = self.i;
                while self.i < self.s.len() && self.s[self.i] != b'`' {
                    self.i += 1;
                }
                let end = self.i;
                self.sub_parse(st, end);
                self.i = end;
                if self.peek() == b'`' {
                    self.tok("`");
                }
                self.b.wrap(m, "command_substitution", true);
            }
            b'<' | b'>' if self.peek_at(1) == b'(' => {
                let m = self.b.mark();
                let t = if c == b'<' { "<(" } else { ">(" };
                self.tok(t);
                self.statements(&[], true);
                if self.peek() == b')' {
                    self.tok(")");
                }
                self.b.wrap(m, "process_substitution", true);
            }
            _ => {
                let st = self.i;
                while self.i < self.s.len() {
                    let ch = self.s[self.i];
                    if ch == b'\\' && self.i + 1 < self.s.len() {
                        self.i += 2;
                        continue;
                    }
                    if !is_word_char(ch) {
                        break;
                    }
                    self.i += 1;
                }
                if self.i > st {
                    let t = &self.src[st..self.i];
                    let kind = if t.chars().all(|c| c.is_ascii_digit()) { "number" } else { "word" };
                    self.b.leaf(kind, true, st, self.i);
                }
            }
        }
    }

    fn sub_parse(&mut self, st: usize, end: usize) {
        // parse commands inside [st, end)
        let sub = &self.src[..end];
        let mut q = P { s: sub.as_bytes(), src: sub, i: st, b: Builder::new(), depth: self.depth + 1 };
        let m = q.b.mark();
        q.statements(&[], false);
        q.ws_nl();
        let ids: Vec<u32> = q.b.stack[m..].to_vec();
        // transplant nodes
        let base = self.b.nodes.len() as u32;
        for n in q.b.nodes.iter() {
            let mut nn = n.clone();
            nn.children = nn.children.iter().map(|c| c + base).collect();
            self.b.nodes.push(nn);
        }
        for id in ids {
            self.b.stack.push(id + base);
        }
    }

    fn dollar(&mut self) {
        let m = self.b.mark();
        let n = self.peek_at(1);
        if n == b'(' && self.peek_at(2) == b'(' {
            self.tok("$((");
            let st = self.i;
            let mut depth = 0;
            while self.i < self.s.len() {
                if self.peek() == b'(' {
                    depth += 1;
                } else if self.peek() == b')' {
                    if depth == 0 {
                        break;
                    }
                    depth -= 1;
                }
                self.i += 1;
            }
            let txt = &self.src[st..self.i];
            let t = txt.trim();
            if !t.is_empty() {
                let off = st + txt.find(t).unwrap_or(0);
                self.b.leaf("word", true, off, off + t.len());
            }
            if self.starts("))") {
                self.tok("))");
            }
            self.b.wrap(m, "arithmetic_expansion", true);
            return;
        }
        if n == b'(' {
            self.tok("$(");
            self.statements(&[], true);
            if self.peek() == b')' {
                self.tok(")");
            }
            self.b.wrap(m, "command_substitution", true);
            return;
        }
        if n == b'{' {
            self.tok("${");
            if self.peek() == b'#' {
                self.tok("#");
            } else if self.peek() == b'!' {
                self.tok("!");
            }
            let st = self.i;
            while self.i < self.s.len() && (self.s[self.i].is_ascii_alphanumeric() || self.s[self.i] == b'_' || (self.i == st && matches!(self.s[self.i], b'@' | b'*' | b'#' | b'?'))) {
                self.i += 1;
            }
            if self.i > st {
                let t = &self.src[st..self.i];
                let k = if t.len() == 1 && matches!(t, "@" | "*" | "#" | "?" | "$" | "!") || t.chars().all(|c| c.is_ascii_digit()) { "special_variable_name" } else { "variable_name" };
                self.b.leaf(if t.chars().all(|c| c.is_ascii_digit()) { "variable_name" } else { k }, true, st, self.i);
            }
            if self.peek() == b'[' {
                let ms = self.b.mark();
                let _ = ms;
                self.tok("[");
                let is = self.i;
                while self.i < self.s.len() && self.s[self.i] != b']' {
                    self.i += 1;
                }
                self.b.leaf("word", true, is, self.i);
                if self.peek() == b']' {
                    self.tok("]");
                }
            }
            // operator
            let ops = [":-", ":=", ":+", ":?", "##", "%%", "//", "-", "=", "+", "?", "#", "%", "/", ":", ",,", "^^", ",", "^"];
            for o in ops {
                if self.starts(o) {
                    self.tok(o);
                    self.b.field_last("operator");
                    // value up to }
                    let st2 = self.i;
                    let mut depth = 0;
                    let mv = self.b.mark();
                    while self.i < self.s.len() {
                        let ch = self.s[self.i];
                        if ch == b'{' {
                            depth += 1;
                        }
                        if ch == b'}' {
                            if depth == 0 {
                                break;
                            }
                            depth -= 1;
                        }
                        if ch == b'$' {
                            if self.i > st2 {
                            }
                            self.dollar();
                            continue;
                        }
                        if ch == b'"' {
                            self.dq_string();
                            continue;
                        }
                        let ws = self.i;
                        while self.i < self.s.len() && !matches!(self.s[self.i], b'}' | b'$' | b'"' | b'{') {
                            self.i += 1;
                        }
                        if self.i > ws {
                            self.b.leaf("word", true, ws, self.i);
                        }
                    }
                    let _ = mv;
                    break;
                }
            }
            if self.peek() == b'}' {
                self.tok("}");
            }
            self.b.wrap(m, "expansion", true);
            return;
        }
        // simple expansion
        self.tok("$");
        let st = self.i;
        if matches!(self.peek(), b'@' | b'*' | b'#' | b'?' | b'$' | b'!' | b'-' | b'0'..=b'9') {
            self.i += 1;
            let t = &self.src[st..self.i];
            let k = if t.chars().all(|c| c.is_ascii_digit()) { "variable_name" } else { "special_variable_name" };
            self.b.leaf(k, true, st, self.i);
        } else {
            while self.i < self.s.len() && (self.s[self.i].is_ascii_alphanumeric() || self.s[self.i] == b'_') {
                self.i += 1;
            }
            if self.i > st {
                self.b.leaf("variable_name", true, st, self.i);
            }
        }
        self.b.wrap(m, "simple_expansion", true);
    }

    fn dq_string(&mut self) {
        let m = self.b.mark();
        self.tok("\"");
        let mut cs = self.i;
        while self.i < self.s.len() && self.s[self.i] != b'"' {
            let c = self.s[self.i];
            if c == b'\\' {
                self.i += 2;
                continue;
            }
            if c == b'$' && (self.peek_at(1).is_ascii_alphanumeric() || matches!(self.peek_at(1), b'_' | b'{' | b'(' | b'@' | b'*' | b'#' | b'?')) || c == b'`' {
                if cs < self.i {
                    self.b.leaf("string_content", true, cs, self.i);
                }
                self.word_part();
                cs = self.i;
                continue;
            }
            self.i += 1;
        }
        if cs < self.i {
            self.b.leaf("string_content", true, cs, self.i);
        }
        if self.peek() == b'"' {
            self.tok("\"");
        }
        self.b.wrap(m, "string", true);
    }

    fn test_command(&mut self) {
        let m = self.b.mark();
        let dbl = self.starts("[[");
        self.tok(if dbl { "[[" } else { "[" });
        self.ws();
        self.test_expr(dbl);
        self.ws();
        if dbl && self.starts("]]") {
            self.tok("]]");
        } else if self.peek() == b']' {
            self.tok("]");
        }
        self.b.wrap(m, "test_command", true);
    }

    fn test_expr(&mut self, dbl: bool) {
        let m = self.b.mark();
        if self.peek() == b'!' && matches!(self.peek_at(1), b' ') {
            self.tok("!");
            self.ws();
            self.test_expr(dbl);
            self.b.wrap(m, "unary_expression", true);
            return;
        }
        if self.peek() == b'-' && self.peek_at(1).is_ascii_alphabetic() && matches!(self.peek_at(2), b' ') {
            let st = self.i;
            self.i += 2;
            self.b.leaf("test_operator", true, st, self.i);
            self.b.field_last("operator");
            self.ws();
            self.word_like(false);
            self.b.wrap(m, "unary_expression", true);
        } else {
            self.word_like(false);
            self.ws();
            let ops = ["==", "!=", "=~", "-eq", "-ne", "-lt", "-le", "-gt", "-ge", "-nt", "-ot", "=", "<", ">"];
            for o in ops {
                if self.starts(o) && matches!(self.peek_at(o.len()), b' ') {
                    self.b.field_last("left");
                    let st = self.i;
                    self.i += o.len();
                    if o.starts_with('-') {
                        self.b.leaf("test_operator", true, st, self.i);
                    } else {
                        self.b.leaf(intern(o), false, st, self.i);
                    }
                    self.b.field_last("operator");
                    self.ws();
                    if dbl && (o == "==" || o == "!=" || o == "=") {
                        // right side is a pattern
                        let st = self.i;
                        let w = self.word_at();
                        if !w.is_empty() && !self.starts("\"") && !self.starts("$") {
                            self.i += w.len();
                            self.b.leaf("extglob_pattern", true, st, self.i);
                        } else {
                            self.word_like(false);
                        }
                    } else if o == "=~" {
                        let st = self.i;
                        while self.i < self.s.len() && !matches!(self.s[self.i], b' ' | b'\n') {
                            self.i += 1;
                        }
                        self.b.leaf("regex", true, st, self.i);
                    } else {
                        self.word_like(false);
                    }
                    self.b.field_last("right");
                    self.b.wrap(m, "binary_expression", true);
                    break;
                }
            }
        }
        self.ws();
        if dbl && (self.starts("&&") || self.starts("||")) {
            self.b.field_last("left");
            let t = if self.starts("&&") { "&&" } else { "||" };
            self.tok(t);
            self.b.field_last("operator");
            self.ws();
            self.test_expr(dbl);
            self.b.field_last("right");
            self.b.wrap(m, "binary_expression", true);
        }
    }

    fn if_stmt(&mut self) {
        let m = self.b.mark();
        self.tok("if");
        self.ws();
        let mc = self.b.mark();
        self.statements(&["then"], false);
        self.b.field_from(mc, "condition");
        self.ws_nl();
        if self.at_kw("then") {
            self.tok("then");
        }
        self.statements(&["elif", "else", "fi"], false);
        loop {
            self.ws_nl();
            if self.at_kw("elif") {
                let me = self.b.mark();
                self.tok("elif");
                self.statements(&["then"], false);
                self.ws_nl();
                if self.at_kw("then") {
                    self.tok("then");
                }
                self.statements(&["elif", "else", "fi"], false);
                self.b.wrap(me, "elif_clause", true);
                continue;
            }
            if self.at_kw("else") {
                let me = self.b.mark();
                self.tok("else");
                self.statements(&["fi"], false);
                self.b.wrap(me, "else_clause", true);
                continue;
            }
            break;
        }
        self.ws_nl();
        if self.at_kw("fi") {
            self.tok("fi");
        }
        self.b.wrap(m, "if_statement", true);
    }

    fn do_group(&mut self) {
        self.ws_nl();
        let m = self.b.mark();
        if self.at_kw("do") {
            self.tok("do");
        }
        self.statements(&["done"], false);
        self.ws_nl();
        if self.at_kw("done") {
            self.tok("done");
        }
        self.b.wrap(m, "do_group", true);
    }

    fn for_stmt(&mut self) {
        let m = self.b.mark();
        let kw = if self.at_kw("for") { "for" } else { "select" };
        self.tok(kw);
        self.ws();
        if self.starts("((") {
            self.tok("((");
            let st = self.i;
            while self.i < self.s.len() && !self.starts("))") {
                self.i += 1;
            }
            let _ = st;
            if self.starts("))") {
                self.tok("))");
            }
            self.ws();
            if self.peek() == b';' {
                self.tok(";");
            }
            self.do_group();
            self.b.field_last("body");
            self.b.wrap(m, "c_style_for_statement", true);
            return;
        }
        let st = self.i;
        let w = self.word_at();
        self.i += w.len();
        self.b.leaf("variable_name", true, st, self.i);
        self.b.field_last("variable");
        self.ws();
        if self.at_kw("in") {
            self.tok("in");
            loop {
                self.ws();
                if self.at_end_of_command() {
                    break;
                }
                self.word_like(false);
                self.b.field_last("value");
            }
        }
        self.ws();
        if self.peek() == b';' {
            self.tok(";");
        }
        self.do_group();
        self.b.field_last("body");
        self.b.wrap(m, "for_statement", true);
    }

    fn case_stmt(&mut self) {
        let m = self.b.mark();
        self.tok("case");
        self.ws();
        self.word_like(false);
        self.b.field_last("value");
        self.ws_nl();
        if self.at_kw("in") {
            self.tok("in");
        }
        loop {
            self.ws_nl();
            if self.at_kw("esac") || self.i >= self.s.len() {
                break;
            }
            let mi = self.b.mark();
            if self.peek() == b'(' {
                self.tok("(");
            }
            let mut first = true;
            loop {
                self.ws();
                let st = self.i;
                if first && !matches!(self.peek(), b'"' | b'\'' | b'$') {
                    while self.i < self.s.len() && !matches!(self.s[self.i], b'|' | b')' | b' ' | b'\n') {
                        self.i += 1;
                    }
                    self.b.leaf("extglob_pattern", true, st, self.i);
                } else {
                    self.word_like(false);
                }
                first = false;
                self.b.field_last("value");
                self.ws();
                if self.peek() == b'|' {
                    self.tok("|");
                    continue;
                }
                break;
            }
            if self.peek() == b')' {
                self.tok(")");
            }
            self.statements(&[";;", ";&", ";;&", "esac"], false);
            self.ws_nl();
            for t in [";;&", ";;", ";&"] {
                if self.starts(t) {
                    self.tok(t);
                    self.b.field_last("termination");
                    break;
                }
            }
            self.b.wrap(mi, "case_item", true);
        }
        if self.at_kw("esac") {
            self.tok("esac");
        }
        self.b.wrap(m, "case_statement", true);
    }
}
