use super::js::intern;
use crate::tree::{Builder, Tree};

#[derive(Clone, Copy, PartialEq, Debug)]
enum K {
    Ident,
    Num,
    Str,
    Op,
    Comment,
    Eof,
}

#[derive(Clone, Copy, Debug)]
struct Tk {
    k: K,
    s: usize,
    e: usize,
}

const OPS: &[&str] = &["...", "==", "~=", "<=", ">=", "//", "::", "<<", ">>", ".."];

fn long_bracket(b: &[u8], i: usize) -> Option<(usize, usize)> {
    // returns (level, end) for [[ / [=[ starting at i
    if i >= b.len() || b[i] != b'[' {
        return None;
    }
    let mut k = i + 1;
    let mut lvl = 0;
    while k < b.len() && b[k] == b'=' {
        lvl += 1;
        k += 1;
    }
    if k >= b.len() || b[k] != b'[' {
        return None;
    }
    let close: Vec<u8> = std::iter::once(b']').chain(std::iter::repeat(b'=').take(lvl)).chain(std::iter::once(b']')).collect();
    let mut j = k + 1;
    while j + close.len() <= b.len() {
        if &b[j..j + close.len()] == close.as_slice() {
            return Some((lvl, j + close.len()));
        }
        j += 1;
    }
    Some((lvl, b.len()))
}

fn tokenize(src: &str) -> Vec<Tk> {
    let b = src.as_bytes();
    let n = b.len();
    let mut out = Vec::new();
    let mut i = 0;
    if src.starts_with("#!") {
        i = src.find('\n').unwrap_or(n);
    }
    while i < n {
        let c = b[i];
        if c.is_ascii_whitespace() {
            i += 1;
            continue;
        }
        let s = i;
        if c == b'-' && i + 1 < n && b[i + 1] == b'-' {
            if let Some((_, e)) = long_bracket(b, i + 2) {
                out.push(Tk { k: K::Comment, s, e });
                i = e;
                continue;
            }
            while i < n && b[i] != b'\n' {
                i += 1;
            }
            out.push(Tk { k: K::Comment, s, e: i });
            continue;
        }
        if c == b'"' || c == b'\'' {
            let mut k = i + 1;
            while k < n && b[k] != c && b[k] != b'\n' {
                if b[k] == b'\\' {
                    k += 1;
                }
                k += 1;
            }
            i = (k + 1).min(n);
            out.push(Tk { k: K::Str, s, e: i });
            continue;
        }
        if c == b'[' {
            if let Some((_, e)) = long_bracket(b, i) {
                out.push(Tk { k: K::Str, s, e });
                i = e;
                continue;
            }
        }
        if c.is_ascii_digit() || (c == b'.' && i + 1 < n && b[i + 1].is_ascii_digit()) {
            let mut k = i;
            while k < n && (b[k].is_ascii_alphanumeric() || b[k] == b'.' || ((b[k] == b'-' || b[k] == b'+') && matches!(b[k - 1], b'e' | b'E' | b'p' | b'P'))) {
                if b[k] == b'.' && k + 1 < n && b[k + 1] == b'.' {
                    break;
                }
                k += 1;
            }
            i = k;
            out.push(Tk { k: K::Num, s, e: i });
            continue;
        }
        let ch = src[i..].chars().next().unwrap();
        if ch == '_' || ch.is_alphabetic() {
            let mut e = i;
            for (o, c2) in src[i..].char_indices() {
                if !(c2 == '_' || c2.is_alphanumeric()) {
                    e = i + o;
                    break;
                }
                e = i + o + c2.len_utf8();
            }
            i = e;
            out.push(Tk { k: K::Ident, s, e: i });
            continue;
        }
        let r = &src[i..];
        let mut l = ch.len_utf8();
        for o in OPS {
            if r.starts_with(o) {
                l = o.len();
                break;
            }
        }
        i += l;
        out.push(Tk { k: K::Op, s, e: i });
    }
    out.push(Tk { k: K::Eof, s: n, e: n });
    out
}

struct P<'a> {
    src: &'a str,
    toks: Vec<Tk>,
    i: usize,
    b: Builder,
    depth: usize,
}

pub fn parse(src: &str) -> Tree {
    let toks = tokenize(src);
    let mut p = P { src, toks, i: 0, b: Builder::new(), depth: 0 };
    let m = p.b.mark();
    if src.starts_with("#!") {
        let e = src.find('\n').unwrap_or(src.len());
        p.b.leaf("hash_bang_line", true, 0, e);
    }
    p.block_stmts(&[]);
    p.flush_extras();
    let start = p.b.stack[m..].first().map(|&c| p.b.nodes[c as usize].start).unwrap_or(src.len() - src.trim_start().len());
    let root = p.b.wrap_all(m, "chunk", start, src.len());
    p.b.finish(root, src)
}

impl<'a> P<'a> {
    fn idx(&self, n: usize) -> usize {
        let mut j = self.i;
        let mut c = 0;
        loop {
            while j < self.toks.len() && self.toks[j].k == K::Comment {
                j += 1;
            }
            if j >= self.toks.len() {
                return self.toks.len() - 1;
            }
            if c == n {
                return j;
            }
            c += 1;
            j += 1;
        }
    }
    fn tok(&self, n: usize) -> Tk {
        self.toks[self.idx(n)]
    }
    fn k(&self) -> K {
        self.tok(0).k
    }
    fn txn(&self, n: usize) -> &'a str {
        let t = self.tok(n);
        if t.k == K::Eof {
            return "";
        }
        &self.src[t.s..t.e]
    }
    fn tx(&self) -> &'a str {
        self.txn(0)
    }
    fn at(&self, s: &str) -> bool {
        let t = self.tok(0);
        matches!(t.k, K::Op | K::Ident) && &self.src[t.s..t.e] == s
    }
    fn flush_extras(&mut self) {
        while self.i < self.toks.len() && self.toks[self.i].k == K::Comment {
            let t = self.toks[self.i];
            let m = self.b.mark();
            self.b.leaf("--", false, t.s, t.s + 2);
            self.b.field_last("start");
            let b = self.src.as_bytes();
            if let Some((lvl, e)) = long_bracket(b, t.s + 2) {
                let open = 2 + lvl;
                self.b.leaf(intern(&self.src[t.s + 2..t.s + 2 + open]), false, t.s + 2, t.s + 2 + open);
                let ce = e.saturating_sub(open).max(t.s + 2 + open);
                if ce > t.s + 2 + open {
                    self.b.leaf("comment_content", true, t.s + 2 + open, ce);
                    self.b.field_last("content");
                }
                self.b.leaf(intern(&self.src[ce..e]), false, ce, e);
                self.b.field_last("end");
            } else if t.e > t.s + 2 {
                self.b.leaf("comment_content", true, t.s + 2, t.e);
                self.b.field_last("content");
            }
            let id = self.b.wrap(m, "comment", true);
            self.b.nodes[id as usize].extra = true;
            self.i += 1;
        }
    }
    fn advance(&mut self) -> Tk {
        self.flush_extras();
        let t = self.toks[self.i];
        if t.k != K::Eof {
            self.i += 1;
        }
        t
    }
    fn bump(&mut self) -> u32 {
        let t = self.advance();
        let k = intern(&self.src[t.s..t.e]);
        self.b.leaf(k, false, t.s, t.e)
    }
    fn bump_named(&mut self, kind: &'static str) -> u32 {
        let t = self.advance();
        self.b.leaf(kind, true, t.s, t.e)
    }
    fn eat(&mut self, s: &str) -> bool {
        if self.at(s) {
            self.bump();
            true
        } else {
            false
        }
    }
    fn cur_pos(&self) -> usize {
        self.b.last().map(|l| self.b.nodes[l as usize].end).unwrap_or(0)
    }
    fn expect(&mut self, s: &str) {
        if !self.eat(s) {
            let p = self.cur_pos();
            self.b.missing(intern(s), false, p);
        }
    }
    fn set_field_first(&mut self, m: usize, f: &'static str) {
        for i in m..self.b.stack.len() {
            let id = self.b.stack[i] as usize;
            if !self.b.nodes[id].extra {
                self.b.nodes[id].field = Some(f);
                return;
            }
        }
    }

    fn block_stmts(&mut self, ends: &[&str]) -> usize {
        let mut n = 0;
        loop {
            if self.k() == K::Eof || ends.iter().any(|e| self.at(e)) {
                break;
            }
            let before = self.i;
            self.statement();
            n += 1;
            if self.i == before {
                let m = self.b.mark();
                self.bump();
                self.b.wrap(m, "ERROR", true);
            }
        }
        n
    }

    fn block(&mut self, ends: &[&str], field: &'static str) {
        let m = self.b.mark();
        let n = self.block_stmts(ends);
        if n > 0 {
            self.b.wrap(m, "block", true);
            self.b.field_last(field);
        }
    }

    fn statement(&mut self) {
        let m = self.b.mark();
        let tx = self.tx();
        match tx {
            ";" => {
                self.bump();
                self.b.wrap(m, "empty_statement", true);
            }
            "local" => {
                self.bump();
                if self.at("function") {
                    self.bump();
                    self.bump_named("identifier");
                    self.b.field_last("name");
                    self.funcbody();
                    self.b.wrap(m, "function_declaration", true);
                } else {
                    let ma = self.b.mark();
                    let ml = self.b.mark();
                    loop {
                        self.bump_named("identifier");
                        self.b.field_last("name");
                        if self.at("<") {
                            let mt = self.b.mark();
                            self.bump();
                            self.bump_named("identifier");
                            self.expect(">");
                            self.b.wrap(mt, "attribute", true);
                            self.b.field_last("attribute");
                        }
                        if !self.eat(",") {
                            break;
                        }
                    }
                    self.b.wrap(ml, "variable_list", true);
                    if self.at("=") {
                        self.bump();
                        self.b.field_last("operator");
                        self.expr_list();
                        self.b.wrap(ma, "assignment_statement", true);
                    }
                    self.b.wrap(m, "variable_declaration", true);
                }
                self.b.field_last("local_declaration");
            }
            "function" => {
                self.bump();
                let mn = self.b.mark();
                self.bump_named("identifier");
                loop {
                    if self.at(".") {
                        self.set_field_first(mn, "table");
                        self.bump();
                        self.bump_named("identifier");
                        self.b.field_last("field");
                        self.b.wrap(mn, "dot_index_expression", true);
                    } else if self.at(":") {
                        self.set_field_first(mn, "table");
                        self.bump();
                        self.bump_named("identifier");
                        self.b.field_last("method");
                        self.b.wrap(mn, "method_index_expression", true);
                        break;
                    } else {
                        break;
                    }
                }
                self.b.field_last("name");
                self.funcbody();
                self.b.wrap(m, "function_declaration", true);
            }
            "if" => {
                self.bump();
                self.expression();
                self.b.field_last("condition");
                self.expect("then");
                self.block(&["elseif", "else", "end"], "consequence");
                while self.at("elseif") {
                    let me = self.b.mark();
                    self.bump();
                    self.expression();
                    self.b.field_last("condition");
                    self.expect("then");
                    self.block(&["elseif", "else", "end"], "consequence");
                    self.b.wrap(me, "elseif_statement", true);
                    self.b.field_last("alternative");
                }
                if self.at("else") {
                    let me = self.b.mark();
                    self.bump();
                    self.block(&["end"], "body");
                    self.b.wrap(me, "else_statement", true);
                    self.b.field_last("alternative");
                }
                self.expect("end");
                self.b.wrap(m, "if_statement", true);
            }
            "while" => {
                self.bump();
                self.expression();
                self.b.field_last("condition");
                self.expect("do");
                self.block(&["end"], "body");
                self.expect("end");
                self.b.wrap(m, "while_statement", true);
            }
            "repeat" => {
                self.bump();
                self.block(&["until"], "body");
                self.expect("until");
                self.expression();
                self.b.field_last("condition");
                self.b.wrap(m, "repeat_statement", true);
            }
            "for" => {
                self.bump();
                let mc = self.b.mark();
                if self.txn(1) == "=" {
                    self.bump_named("identifier");
                    self.b.field_last("name");
                    self.bump();
                    self.b.field_last("operator");
                    self.expression();
                    self.b.field_last("start");
                    self.expect(",");
                    self.expression();
                    self.b.field_last("end");
                    if self.eat(",") {
                        self.expression();
                        self.b.field_last("step");
                    }
                    self.b.wrap(mc, "for_numeric_clause", true);
                } else {
                    let ml = self.b.mark();
                    loop {
                        self.bump_named("identifier");
                        self.b.field_last("name");
                        if !self.eat(",") {
                            break;
                        }
                    }
                    self.b.wrap(ml, "variable_list", true);
                    self.expect("in");
                    self.expr_list();
                    self.b.wrap(mc, "for_generic_clause", true);
                }
                self.b.field_last("clause");
                self.expect("do");
                self.block(&["end"], "body");
                self.expect("end");
                self.b.wrap(m, "for_statement", true);
            }
            "do" => {
                self.bump();
                self.block(&["end"], "body");
                self.expect("end");
                self.b.wrap(m, "do_statement", true);
            }
            "return" => {
                self.bump();
                if !matches!(self.tx(), "end" | "else" | "elseif" | "until" | ";" | "") {
                    self.expr_list_plain();
                }
                self.eat(";");
                self.b.wrap(m, "return_statement", true);
            }
            "break" => {
                self.bump();
                self.b.wrap(m, "break_statement", true);
            }
            "goto" => {
                self.bump();
                self.bump_named("identifier");
                self.b.wrap(m, "goto_statement", true);
            }
            "::" => {
                self.bump();
                self.bump_named("identifier");
                self.expect("::");
                self.b.wrap(m, "label_statement", true);
            }
            _ => {
                // assignment or call
                let ml = self.b.mark();
                self.suffixed();
                if self.at("=") || self.at(",") {
                    while self.eat(",") {
                        self.suffixed();
                    }
                    self.name_fields(ml);
                    self.b.wrap(ml, "variable_list", true);
                    self.expect("=");
                    self.b.field_last("operator");
                    self.expr_list();
                    self.b.wrap(m, "assignment_statement", true);
                }
            }
        }
    }

    fn name_fields(&mut self, ml: usize) {
        for i in ml..self.b.stack.len() {
            let id = self.b.stack[i] as usize;
            if self.b.nodes[id].named && !self.b.nodes[id].extra {
                self.b.nodes[id].field = Some("name");
            }
        }
    }

    fn expr_list(&mut self) {
        let m = self.b.mark();
        loop {
            self.expression();
            self.b.field_last("value");
            if !self.eat(",") {
                break;
            }
        }
        self.b.wrap(m, "expression_list", true);
    }

    fn expr_list_plain(&mut self) {
        let m = self.b.mark();
        loop {
            self.expression();
            if !self.eat(",") {
                break;
            }
        }
        self.b.wrap(m, "expression_list", true);
    }

    fn funcbody(&mut self) {
        let mp = self.b.mark();
        self.expect("(");
        while !self.at(")") && self.k() != K::Eof {
            if self.at("...") {
                let mv = self.b.mark();
                self.bump();
                self.b.wrap(mv, "vararg_expression", true);
            } else {
                self.bump_named("identifier");
                self.b.field_last("name");
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect(")");
        self.b.wrap(mp, "parameters", true);
        self.b.field_last("parameters");
        self.block(&["end"], "body");
        self.expect("end");
    }

    fn binop(&self) -> Option<(u8, bool)> {
        let t = self.tok(0);
        let tx = self.tx();
        if t.k == K::Ident {
            return match tx {
                "or" => Some((1, false)),
                "and" => Some((2, false)),
                _ => None,
            };
        }
        if t.k != K::Op {
            return None;
        }
        Some(match tx {
            "<" | ">" | "<=" | ">=" | "~=" | "==" => (3, false),
            "|" => (4, false),
            "~" => (5, false),
            "&" => (6, false),
            "<<" | ">>" => (7, false),
            ".." => (8, true),
            "+" | "-" => (9, false),
            "*" | "/" | "//" | "%" => (10, false),
            "^" => (12, true),
            _ => return None,
        })
    }

    fn expression(&mut self) {
        self.depth += 1;
        if self.depth > 300 {
            self.depth -= 1;
            return;
        }
        self.binary(1);
        self.depth -= 1;
    }

    fn binary(&mut self, min: u8) {
        let m = self.b.mark();
        if (self.at("not") || (self.k() == K::Op && matches!(self.tx(), "-" | "#" | "~"))) && min <= 11 {
            self.bump();
            self.b.field_last("operator");
            self.binary(11);
            self.b.field_last("operand");
            self.b.wrap(m, "unary_expression", true);
        } else {
            self.simple();
        }
        loop {
            let Some((p, right)) = self.binop() else { break };
            if p < min {
                break;
            }
            self.b.field_last("left");
            self.bump();
            self.b.field_last("operator");
            self.binary(if right { p } else { p + 1 });
            self.b.field_last("right");
            self.b.wrap(m, "binary_expression", true);
        }
    }

    fn simple(&mut self) {
        let m = self.b.mark();
        let t = self.tok(0);
        let tx = self.tx();
        match t.k {
            K::Num => {
                self.bump_named("number");
            }
            K::Str => self.string(),
            K::Ident => match tx {
                "nil" => {
                    self.bump_named("nil");
                }
                "true" => {
                    self.bump_named("true");
                }
                "false" => {
                    self.bump_named("false");
                }
                "function" => {
                    self.bump();
                    self.funcbody();
                    self.b.wrap(m, "function_definition", true);
                }
                _ => self.suffixed(),
            },
            K::Op => match tx {
                "..." => {
                    self.bump();
                    self.b.wrap(m, "vararg_expression", true);
                }
                "{" => self.table(),
                "(" => self.suffixed(),
                _ => {
                    let mm = self.b.mark();
                    self.bump();
                    self.b.wrap(mm, "ERROR", true);
                }
            },
            _ => {
                let p = self.cur_pos();
                self.b.missing("identifier", true, p);
            }
        }
    }

    fn suffixed(&mut self) {
        let m = self.b.mark();
        if self.at("(") {
            self.bump();
            self.expression();
            self.expect(")");
            self.b.wrap(m, "parenthesized_expression", true);
        } else if self.k() == K::Ident {
            self.bump_named("identifier");
        } else {
            let p = self.cur_pos();
            self.b.missing("identifier", true, p);
            return;
        }
        loop {
            let tx = self.tx();
            let t = self.tok(0);
            match tx {
                "." => {
                    self.set_field_first(m, "table");
                    self.bump();
                    self.bump_named("identifier");
                    self.b.field_last("field");
                    self.b.wrap(m, "dot_index_expression", true);
                }
                "[" if t.k == K::Op => {
                    self.set_field_first(m, "table");
                    self.bump();
                    self.expression();
                    self.b.field_last("field");
                    self.expect("]");
                    self.b.wrap(m, "bracket_index_expression", true);
                }
                ":" => {
                    self.set_field_first(m, "table");
                    self.bump();
                    self.bump_named("identifier");
                    self.b.field_last("method");
                    self.b.wrap(m, "method_index_expression", true);
                    self.set_field_first(m, "name");
                    self.call_args();
                    self.b.field_last("arguments");
                    self.b.wrap(m, "function_call", true);
                }
                "(" | "{" => {
                    self.set_field_first(m, "name");
                    self.call_args();
                    self.b.field_last("arguments");
                    self.b.wrap(m, "function_call", true);
                }
                _ => {
                    if t.k == K::Str {
                        self.set_field_first(m, "name");
                        self.call_args();
                        self.b.field_last("arguments");
                        self.b.wrap(m, "function_call", true);
                        continue;
                    }
                    break;
                }
            }
        }
    }

    fn call_args(&mut self) {
        let m = self.b.mark();
        if self.at("(") {
            self.bump();
            while !self.at(")") && self.k() != K::Eof {
                self.expression();
                if !self.eat(",") {
                    break;
                }
            }
            self.expect(")");
        } else if self.at("{") {
            self.table();
        } else if self.k() == K::Str {
            self.string();
        }
        self.b.wrap(m, "arguments", true);
    }

    fn table(&mut self) {
        let m = self.b.mark();
        self.bump(); // {
        while !self.at("}") && self.k() != K::Eof {
            let mf = self.b.mark();
            if self.at("[") {
                self.bump();
                self.expression();
                self.b.field_last("name");
                self.expect("]");
                self.expect("=");
                self.b.field_last("operator");
                self.expression();
                self.b.field_last("value");
            } else if self.k() == K::Ident && self.txn(1) == "=" {
                self.bump_named("identifier");
                self.b.field_last("name");
                self.bump();
                self.expression();
                self.b.field_last("value");
            } else {
                self.expression();
                self.b.field_last("value");
            }
            self.b.wrap(mf, "field", true);
            if !(self.eat(",") || self.eat(";")) {
                break;
            }
        }
        self.expect("}");
        self.b.wrap(m, "table_constructor", true);
    }

    fn string(&mut self) {
        let t = self.advance();
        let m = self.b.mark();
        let b = self.src.as_bytes();
        let txt = &self.src[t.s..t.e];
        if txt.starts_with('[') {
            let (lvl, _) = long_bracket(b, t.s).unwrap_or((0, t.e));
            let ol = 2 + lvl;
            self.b.leaf(intern(&txt[..ol]), false, t.s, t.s + ol);
            self.b.field_last("start");
            if t.e - ol > t.s + ol {
                self.b.leaf("string_content", true, t.s + ol, t.e - ol);
                self.b.field_last("content");
            }
            self.b.leaf(intern(&txt[txt.len() - ol..]), false, t.e - ol, t.e);
            self.b.field_last("end");
            self.b.wrap(m, "string", true);
            return;
        }
        let q = intern(&txt[..1]);
        self.b.leaf(q, false, t.s, t.s + 1);
        self.b.field_last("start");
        let close = t.e > t.s + 1 && b[t.e - 1] == b[t.s];
        let ce = if close { t.e - 1 } else { t.e };
        if ce > t.s + 1 {
            let mc = self.b.mark();
            let mut i = t.s + 1;
            while i < ce {
                if b[i] == b'\\' {
                    let e = (i + 2).min(ce);
                    self.b.leaf("escape_sequence", true, i, e);
                    i = e;
                } else {
                    i += 1;
                }
            }
            self.b.wrap_at(mc, "string_content", true, t.s + 1);
            let id = self.b.last().unwrap() as usize;
            self.b.nodes[id].start = t.s + 1;
            self.b.nodes[id].end = ce;
            self.b.field_last("content");
        }
        if close {
            self.b.leaf(q, false, t.e - 1, t.e);
            self.b.field_last("end");
        }
        self.b.wrap(m, "string", true);
    }
}
