            self.ident();
            self.b.wrap(m, "color_value", true);
            let id = self.b.last().unwrap() as usize;
            self.b.nodes[id].end = self.i;
            return;
        }
        if c.is_ascii_digit() || ((c == b'-' || c == b'+' || c == b'.') && self.s.get(self.i + 1).map_or(false, |x| x.is_ascii_digit() || *x == b'.')) {
            let m = self.b.mark();
            self.i += 1;
            while self.i < self.s.len() && (self.s[self.i].is_ascii_digit() || self.s[self.i] == b'.') {
                self.i += 1;
            }
            let is_float = self.src[st..self.i].contains('.');
            let us = self.i;
            while self.i < self.s.len() && (self.s[self.i].is_ascii_alphabetic() || self.s[self.i] == b'%') {
                self.i += 1;
            }
            if self.i > us {
                self.b.leaf("unit", true, us, self.i);
            }
            self.b.wrap_at(m, if is_float { "float_value" } else { "integer_value" }, true, st);
            let id = self.b.last().unwrap() as usize;
            self.b.nodes[id].start = st;
            self.b.nodes[id].end = self.i;
            return;
        }
        if css_ident_char(c) {
            self.ident();
            if self.peek() == b'(' {
                let m = self.b.mark();
                self.b.leaf("function_name", true, st, self.i);
                let ma = self.b.mark();
                self.tok("(");
                loop {
                    self.ws();
                    let ch = self.peek();
                    if ch == b')' || ch == 0 {
                        break;
                    }
                    let before = self.i;
                    if ch == b',' {
                        self.tok(",");
                    } else {
                        self.value();
                    }
                    if self.i == before {
                        self.i += 1;
                    }
                }
                if self.peek() == b')' {
                    self.tok(")");
                }
                self.b.wrap(ma, "arguments", true);
                self.b.wrap(m, "call_expression", true);
                return;
            }
            self.b.leaf("plain_value", true, st, self.i);
            return;
        }
        if c == b'(' {
            let m = self.b.mark();
            self.tok("(");
            self.ws();
            self.value();
            self.ws();
            if self.peek() == b')' {
                self.tok(")");
            }
            self.b.wrap(m, "parenthesized_value", true);
            return;
        }
        // other char: plain value
        self.i += 1;
        while self.i < self.s.len() && !matches!(self.s[self.i], b' ' | b';' | b'}' | b',' | b')' | b'\n') {
            self.i += 1;
        }
        self.b.leaf("plain_value", true, st, self.i);
    }
}

// ---------------- HTML ----------------
const VOID: &[&str] = &["area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"];

struct H<'a> {
    s: &'a [u8],
    src: &'a str,
    i: usize,
    b: Builder,
}

pub fn parse_html(src: &str) -> Tree {
    let mut p = H { s: src.as_bytes(), src, i: 0, b: Builder::new() };
    let m = p.b.mark();
    p.nodes(&mut vec![]);
    let start = p.b.stack[m..].first().map(|&c| p.b.nodes[c as usize].start).unwrap_or(src.len() - src.trim_start().len());
    let root = p.b.wrap_all(m, "document", start, src.len());
    p.b.finish(root, src)
}

impl<'a> H<'a> {
    fn starts(&self, t: &str) -> bool {
        self.src[self.i..].starts_with(t)
    }
    fn tok(&mut self, t: &'static str) {
        self.b.leaf(t, false, self.i, self.i + t.len());
        self.i += t.len();
    }
    fn ws(&mut self) {
        while self.i < self.s.len() && (self.s[self.i] as char).is_ascii_whitespace() {
            self.i += 1;
        }
    }
    fn tag_name_at(&self, k: usize) -> &'a str {
        let mut e = k;
        while e < self.s.len() && (self.s[e].is_ascii_alphanumeric() || self.s[e] == b'-' || self.s[e] == b':' || self.s[e] == b'_') {
            e += 1;
        }
        &self.src[k..e]
    }
    /// parse children until a closing tag that matches something in the open stack
    fn nodes(&mut self, open: &mut Vec<String>) {
        loop {
            if self.i >= self.s.len() {
                return;
            }
            if self.starts("</") {
                let name = self.tag_name_at(self.i + 2).to_ascii_lowercase();
                if open.iter().any(|o| *o == name) {
                    return;
                }
                // stray end tag -> erroneous_end_tag
                let m = self.b.mark();
                self.tok("</");
                let st = self.i;
                self.i += name.len();
                self.b.leaf("erroneous_end_tag_name", true, st, self.i);
                self.ws();
                if self.starts(">") {
                    self.tok(">");
                }
                self.b.wrap(m, "erroneous_end_tag", true);
                continue;
            }
            if self.starts("<!--") {
                let st = self.i;
                let e = self.src[self.i + 4..].find("-->").map(|x| self.i + 4 + x + 3).unwrap_or(self.s.len());
                self.b.leaf("comment", true, st, e);
                self.i = e;
                continue;
            }
            if self.starts("<!") {
                let m = self.b.mark();
                self.tok("<!");
                let st = self.i;
                while self.i < self.s.len() && self.s[self.i].is_ascii_alphabetic() {
                    self.i += 1;
                }
                self.b.leaf("doctype", false, st, self.i);
                self.ws();
                while self.i < self.s.len() && self.s[self.i] != b'>' {
                    self.i += 1;
                }
                if self.starts(">") {
                    self.tok(">");
                }
                self.b.wrap(m, "doctype", true);
                continue;
            }
            if self.starts("<") && self.s.get(self.i + 1).map_or(false, |c| c.is_ascii_alphabetic()) {
                self.element(open);
                continue;
            }
            // text
            let st = self.i;
            while self.i < self.s.len() && !(self.s[self.i] == b'<' && (self.starts("</") || self.starts("<!") || self.s.get(self.i + 1).map_or(false, |c| c.is_ascii_alphabetic()))) {
                if self.s[self.i] == b'&' {
                    break;
                }
                self.i += 1;
            }
            if self.i < self.s.len() && self.s[self.i] == b'&' && self.i == st {
                // entity
                let mut k = self.i + 1;
                while k < self.s.len() && k - self.i < 32 && (self.s[k].is_ascii_alphanumeric() || self.s[k] == b'#') {
                    k += 1;
                }
                if k < self.s.len() && self.s[k] == b';' {
                    self.b.leaf("entity", true, self.i, k + 1);
                    self.i = k + 1;
                    continue;
                }
                self.i += 1;
                while self.i < self.s.len() && !matches!(self.s[self.i], b'<' | b'&') {
                    self.i += 1;
                }
            }
            let txt = &self.src[st..self.i];
            let t = txt.trim();
            if !t.is_empty() {
                let off = st + (txt.len() - txt.trim_start().len());
                self.b.leaf("text", true, off, off + t.len());
            }
            if self.i == st {
                self.i += 1;
            }
        }
    }
    fn attributes(&mut self) {
        loop {
            self.ws();
            if self.i >= self.s.len() || self.starts(">") || self.starts("/>") {
                break;
            }
            let m = self.b.mark();
            let st = self.i;
            while self.i < self.s.len() && !matches!(self.s[self.i], b' ' | b'\t' | b'\n' | b'\r' | b'=' | b'>' | b'/' | b'"' | b'\'') {
                self.i += 1;
            }
            if self.i == st {
                self.i += 1;
                continue;
            }
            self.b.leaf("attribute_name", true, st, self.i);
            self.ws();
            if self.starts("=") {
                self.tok("=");
                self.ws();
                let c = self.s.get(self.i).copied().unwrap_or(0);
                if c == b'"' || c == b'\'' {
                    let mq = self.b.mark();
                    let q = if c == b'"' { "\"" } else { "'" };
                    self.tok(q);
                    let vs = self.i;
                    while self.i < self.s.len() && self.s[self.i] != c {
                        self.i += 1;
                    }
                    if self.i > vs {
                        self.b.leaf("attribute_value", true, vs, self.i);
                    }
                    if self.i < self.s.len() {
                        self.tok(q);
                    }
                    self.b.wrap(mq, "quoted_attribute_value", true);
                } else {
                    let vs = self.i;
                    while self.i < self.s.len() && !matches!(self.s[self.i], b' ' | b'\t' | b'\n' | b'>') {
                        self.i += 1;
                    }
                    self.b.leaf("attribute_value", true, vs, self.i);
                }
            }
            self.b.wrap(m, "attribute", true);
        }
    }
    fn element(&mut self, open: &mut Vec<String>) {
        let m = self.b.mark();
        let ms = self.b.mark();
        self.tok("<");
        let name = self.tag_name_at(self.i).to_string();
        let lname = name.to_ascii_lowercase();
        let st = self.i;
        self.i += name.len();
        self.b.leaf("tag_name", true, st, self.i);
        self.attributes();
        if self.starts("/>") {
            self.tok("/>");
            self.b.wrap(ms, "self_closing_tag", true);
            self.b.wrap(m, "element", true);
            return;
        }
        if self.starts(">") {
            self.tok(">");
        }
        self.b.wrap(ms, "start_tag", true);
        if VOID.contains(&lname.as_str()) {
            self.b.wrap(m, "element", true);
            return;
        }
        let kind = if lname == "script" {
            "script_element"
        } else if lname == "style" {
            "style_element"
        } else {
            "element"
        };
        if kind != "element" {
            let close = format!("</{}", lname);
            let rest_lower = self.src[self.i..].to_ascii_lowercase();
            let e = rest_lower.find(&close).map(|x| self.i + x).unwrap_or(self.s.len());
            if e > self.i {
                self.b.leaf("raw_text", true, self.i, e);
            }
            self.i = e;
        } else {
            open.push(lname.clone());
            self.nodes(open);
            open.pop();
        }
        if self.starts("</") && self.tag_name_at(self.i + 2).eq_ignore_ascii_case(&lname) {
            let me = self.b.mark();
            self.tok("</");
            let st = self.i;
            self.i += lname.len();
            self.b.leaf("tag_name", true, st, self.i);
            self.ws();
            if self.starts(">") {
                self.tok(">");
            }
            self.b.wrap(me, "end_tag", true);
        }
        self.b.wrap(m, kind, true);
    }
}
