// CSS and HTML parsers
use super::js::intern;
use crate::tree::{Builder, Tree};

// ---------------- CSS ----------------
struct C<'a> {
    s: &'a [u8],
    src: &'a str,
    i: usize,
    b: Builder,
    depth: usize,
}

pub fn parse_css(src: &str) -> Tree {
    let mut p = C { s: src.as_bytes(), src, i: 0, b: Builder::new(), depth: 0 };
    let m = p.b.mark();
    p.items(false);
    p.ws();
    let start = p.b.stack[m..].first().map(|&c| p.b.nodes[c as usize].start).unwrap_or(src.len() - src.trim_start().len());
    let root = p.b.wrap_all(m, "stylesheet", start, src.len());
    p.b.finish(root, src)
}

fn css_ident_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'-' || c == b'_' || c >= 0x80
}

impl<'a> C<'a> {
    fn peek(&self) -> u8 {
        *self.s.get(self.i).unwrap_or(&0)
    }
    fn ws(&mut self) {
        loop {
            while self.i < self.s.len() && (self.s[self.i] as char).is_ascii_whitespace() {
                self.i += 1;
            }
            if self.src[self.i..].starts_with("/*") {
                let st = self.i;
                let e = self.src[self.i + 2..].find("*/").map(|x| self.i + 2 + x + 2).unwrap_or(self.s.len());
                self.b.extra("comment", st, e);
                self.i = e;
                continue;
            }
            if self.src[self.i..].starts_with("//") {
                let st = self.i;
                while self.i < self.s.len() && self.s[self.i] != b'\n' {
                    self.i += 1;
                }
                self.b.extra("js_comment", st, self.i);
                continue;
            }
            break;
        }
    }
    fn tok(&mut self, t: &'static str) {
        self.b.leaf(t, false, self.i, self.i + t.len());
        self.i += t.len();
    }
    fn ident(&mut self) -> usize {
        let st = self.i;
        while self.i < self.s.len() && css_ident_char(self.s[self.i]) {
            self.i += 1;
        }
        self.i - st
    }
    fn items(&mut self, in_block: bool) {
        loop {
            self.ws();
            if self.i >= self.s.len() || (in_block && self.peek() == b'}') {
                break;
            }
            let before = self.i;
            self.item(in_block);
            if self.i == before {
                let m = self.b.mark();
                self.b.leaf(intern(&self.src[self.i..self.i + 1]), false, self.i, self.i + 1);
                self.i += 1;
                self.b.wrap(m, "ERROR", true);
            }
        }
    }
    fn item(&mut self, in_block: bool) {
        if self.peek() == b'@' {
            self.at_rule();
            return;
        }
        if in_block && self.is_declaration_ahead() {
            self.declaration();
            return;
        }
        self.rule_set();
    }
    fn is_declaration_ahead(&self) -> bool {
        // ident followed by ':' then not a selector-ish before '{'
        let mut k = self.i;
        while k < self.s.len() && (css_ident_char(self.s[k]) || self.s[k] == b'*') {
            k += 1;
        }
        if k == self.i {
            return false;
        }
        while k < self.s.len() && self.s[k] == b' ' {
            k += 1;
        }
        if k >= self.s.len() || self.s[k] != b':' {
            return false;
        }
        // scan to ; or { or }
        let mut j = k;
        while j < self.s.len() {
            match self.s[j] {
                b';' | b'}' => return true,
                b'{' => return false,
                _ => j += 1,
            }
        }
        true
    }
    fn at_rule(&mut self) {
        let m = self.b.mark();
        let st = self.i;
        self.i += 1;
        self.ident();
        let kw = &self.src[st..self.i];
        let kind = match kw {
            "@import" => "import_statement",
            "@media" => "media_statement",
            "@charset" => "charset_statement",
            "@namespace" => "namespace_statement",
            "@keyframes" | "@-webkit-keyframes" => "keyframes_statement",
            "@supports" => "supports_statement",
            "@scope" => "scope_statement",
            _ => "at_rule",
        };
        let id = self.b.leaf(intern(kw), false, st, self.i);
        if kind == "at_rule" {
            self.b.rename(id, "at_keyword");
            self.b.nodes[id as usize].named = true;
        }
        self.ws();
        if kind == "keyframes_statement" {
            let ns = self.i;
            self.ident();
            self.b.leaf("keyframes_name", true, ns, self.i);
            self.b.field_last("name");
            self.ws();
            let mb = self.b.mark();
            self.tok("{");
            loop {
                self.ws();
                if self.peek() == b'}' || self.i >= self.s.len() {
                    break;
                }
                let mk = self.b.mark();
                let ks = self.i;
                while self.i < self.s.len() && !matches!(self.s[self.i], b'{' | b' ' | b',') {
                    self.i += 1;
                }
                let t = &self.src[ks..self.i];
                if t.ends_with('%') {
                    let mi = self.b.mark();
                    self.b.leaf("unit", true, self.i - 1, self.i);
                    self.b.wrap_at(mi, "integer_value", true, ks);
                    let idn = self.b.last().unwrap() as usize;
                    self.b.nodes[idn].start = ks;
                } else {
                    self.b.leaf("from", false, ks, self.i);
                }
                self.ws();
                self.block();
                self.b.wrap(mk, "keyframe_block", true);
            }
            if self.peek() == b'}' {
                self.tok("}");
            }
            self.b.wrap(mb, "keyframe_block_list", true);
            self.b.field_last("blocks");
            self.b.wrap(m, kind, true);
            return;
        }
        // prelude until ; or {
        self.prelude(kind);
        self.ws();
        if self.peek() == b'{' {
            self.block();
        } else if self.peek() == b';' {
            self.tok(";");
        }
        self.b.wrap(m, kind, true);
    }
    fn prelude(&mut self, kind: &str) {
        loop {
            self.ws();
            let c = self.peek();
            if c == 0 || c == b';' || c == b'{' || c == b'}' {
                break;
            }
            let before = self.i;
            if c == b'(' && (kind == "media_statement" || kind == "supports_statement") {
                let m = self.b.mark();
                self.tok("(");
                self.ws();
                let fs = self.i;
                self.ident();
                self.b.leaf("feature_name", true, fs, self.i);
                self.ws();
                if self.peek() == b':' {
                    self.tok(":");
                    self.ws();
                    self.value();
                    self.ws();
                }
                if self.peek() == b')' {
                    self.tok(")");
                }
                self.b.wrap(m, "feature_query", true);
            } else if c == b',' {
                self.tok(",");
            } else if kind == "media_statement" && css_ident_char(c) {
                let st = self.i;
                self.ident();
                let w = &self.src[st..self.i];
                if w == "and" || w == "or" || w == "not" || w == "only" {
                    self.b.leaf(intern(w), false, st, self.i);
                } else {
                    self.b.leaf("keyword_query", true, st, self.i);
                }
            } else {
                self.value();
            }
            if self.i == before {
                self.i += 1;
            }
        }
    }
    fn rule_set(&mut self) {
        let m = self.b.mark();
        let ms = self.b.mark();
        loop {
            self.ws();
            self.selector();
            self.ws();
            if self.peek() == b',' {
                self.tok(",");
                continue;
            }
            break;
        }
        self.b.wrap(ms, "selectors", true);
        self.ws();
        if self.peek() == b'{' {
            self.block();
        }
        self.b.wrap(m, "rule_set", true);
    }
    fn block(&mut self) {
        let m = self.b.mark();
        self.tok("{");
        self.items(true);
        if self.peek() == b'}' {
            self.tok("}");
        }
        self.b.wrap(m, "block", true);
    }
    fn simple_suffix(&mut self, m: usize) -> bool {
        let c = self.peek();
        match c {
            b'.' => {
                self.tok(".");
                let mc = self.b.mark();
                let st = self.i;
                self.ident();
                self.b.leaf("identifier", true, st, self.i);
                self.b.wrap(mc, "class_name", true);
                self.b.wrap(m, "class_selector", true);
                true
            }
            b'#' => {
                self.tok("#");
                let st = self.i;
                self.ident();
                self.b.leaf("id_name", true, st, self.i);
                self.b.wrap(m, "id_selector", true);
                true
            }
            b'[' => {
                self.tok("[");
                self.ws();
                let st = self.i;
                self.ident();
                self.b.leaf("attribute_name", true, st, self.i);
                self.ws();
                for op in ["~=", "|=", "^=", "$=", "*=", "="] {
                    if self.src[self.i..].starts_with(op) {
                        self.tok(op);
                        self.ws();
                        self.value();
                        self.ws();
                        break;
                    }
                }
                if self.peek() == b']' {
                    self.tok("]");
                }
                self.b.wrap(m, "attribute_selector", true);
                true
            }
            b':' => {
                if self.src[self.i..].starts_with("::") {
                    self.tok("::");
                    let st = self.i;
                    self.ident();
                    self.b.leaf("tag_name", true, st, self.i);
                    self.b.wrap(m, "pseudo_element_selector", true);
                } else {
                    self.tok(":");
                    let mc = self.b.mark();
                    let st = self.i;
                    self.ident();
                    self.b.leaf("identifier", true, st, self.i);
                    self.b.wrap(mc, "class_name", true);
                    if self.peek() == b'(' {
                        let ma = self.b.mark();
                        self.tok("(");
                        loop {
                            self.ws();
                            if self.peek() == b')' || self.i >= self.s.len() {
                                break;
                            }
                            let before = self.i;
                            self.selector();
                            self.ws();
