            self.ws();
            let c = self.peek();
            if c == b'>' || c == b'~' || c == b'+' {
                let t = intern(&self.src[self.i..self.i + 1]);
                self.b.leaf(t, false, self.i, self.i + 1);
                self.i += 1;
                self.ws();
                let mc = self.b.mark();
                self.compound(mc);
                let k = match c {
                    b'>' => "child_selector",
                    b'~' => "sibling_selector",
                    _ => "adjacent_sibling_selector",
                };
                self.b.wrap(m, k, true);
                continue;
            }
            if had_ws && c != 0 && !matches!(c, b',' | b'{' | b')' | b'}') {
