        } else if c == b'&' {
            self.tok("&");
            self.b.wrap(m, "nesting_selector", true);
        } else if css_ident_char(c) && !c.is_ascii_digit() {
            let st = self.i;
            self.ident();
            self.b.leaf("tag_name", true, st, self.i);
        }
