        let mut k = self.b.stack.len();
        while k > 0 {
            let id = self.b.stack[k - 1] as usize;
            let n = &self.b.nodes[id];
            if n.extra {
                k -= 1;
                continue;
            }
            if !n.named && (n.kind == "," || n.kind == "(" || n.kind == "{") {
                break;
            }
            if n.named && matches!(n.kind, "selectors" | "block" | "arguments") {
                break;
            }
            k -= 1;
        }
        k
    }
    fn declaration(&mut self) {
        let m = self.b.mark();
        let st = self.i;
        while self.i < self.s.len() && (css_ident_char(self.s[self.i]) || self.s[self.i] == b'*') {
