            self.tok(";");
        }
        self.b.wrap(m, "declaration", true);
    }
    fn value(&mut self) {
        let m = self.b.mark();
        self.value_primary();
        // binary expression (calc)
        loop {
            let save = self.i;
            self.ws();
            let c = self.peek();
