// PHP parser (tree-sitter-php php_only subset)
use super::js::intern;
use crate::tree::{Builder, Tree};

#[derive(Clone, Copy, PartialEq, Debug)]
enum K {
    Var,
    Ident,
    Num,
    Str,
    DStr,
    Op,
    Comment,
    Tag,
    Eof,
}

#[derive(Clone, Copy, Debug)]
struct Tk {
    k: K,
    s: usize,
    e: usize,
}

const OPS: &[&str] = &[
    "<=>", "===", "!==", "**=", "...", "<<=", ">>=", "??=", "?->", "->", "=>", "::", "++", "--", "==", "!=", "<>", "<=",
    ">=", "&&", "||", "??", "+=", "-=", "*=", "/=", ".=", "%=", "&=", "|=", "^=", "<<", ">>", "**",
];

fn tokenize(src: &str) -> Vec<Tk> {
    let b = src.as_bytes();
    let n = b.len();
    let mut out = Vec::new();
    let mut i = 0;
    while i < n {
        let c = b[i];
        if c.is_ascii_whitespace() {
            i += 1;
            continue;
        }
        let s = i;
        if src[i..].starts_with("<?php") {
            out.push(Tk { k: K::Tag, s, e: i + 5 });
            i += 5;
            continue;
        }
        if src[i..].starts_with("?>") {
            out.push(Tk { k: K::Tag, s, e: i + 2 });
            i += 2;
            continue;
        }
        if (c == b'/' && i + 1 < n && b[i + 1] == b'/') || c == b'#' && !(i + 1 < n && b[i + 1] == b'[') {
            while i < n && b[i] != b'\n' {
                i += 1;
            }
            out.push(Tk { k: K::Comment, s, e: i });
            continue;
        }
        if c == b'/' && i + 1 < n && b[i + 1] == b'*' {
            i += 2;
            while i + 1 < n && !(b[i] == b'*' && b[i + 1] == b'/') {
                i += 1;
            }
            i = (i + 2).min(n);
            out.push(Tk { k: K::Comment, s, e: i });
            continue;
        }
        if c == b'\'' || c == b'"' {
            let mut k = i + 1;
            while k < n && b[k] != c {
                if b[k] == b'\\' {
                    k += 1;
                }
                k += 1;
            }
            i = (k + 1).min(n);
            out.push(Tk { k: if c == b'"' { K::DStr } else { K::Str }, s, e: i });
            continue;
        }
        if c == b'$' && i + 1 < n && (b[i + 1].is_ascii_alphabetic() || b[i + 1] == b'_' || b[i + 1] >= 0x80) {
            let mut k = i + 1;
            while k < n && (b[k].is_ascii_alphanumeric() || b[k] == b'_' || b[k] >= 0x80) {
                k += 1;
            }
            out.push(Tk { k: K::Var, s, e: k });
            i = k;
            continue;
        }
        if c.is_ascii_digit() || (c == b'.' && i + 1 < n && b[i + 1].is_ascii_digit()) {
            let mut k = i;
            while k < n && (b[k].is_ascii_alphanumeric() || b[k] == b'_' || (b[k] == b'.' && k + 1 < n && b[k + 1].is_ascii_digit())) {
                k += 1;
            }
            out.push(Tk { k: K::Num, s, e: k });
            i = k;
            continue;
        }
        let ch = src[i..].chars().next().unwrap();
        if ch == '_' || ch.is_alphabetic() || ch == '\\' {
            let mut k = i;
            for (o, c2) in src[i..].char_indices() {
                if !(c2 == '_' || c2.is_alphanumeric() || c2 == '\\') {
                    k = i + o;
                    break;
                }
                k = i + o + c2.len_utf8();
            }
            out.push(Tk { k: K::Ident, s, e: k });
            i = k;
            continue;
        }
        let r = &src[i..];
        let mut l = ch.len_utf8();
        for o in OPS {
            if r.starts_with(o) {
                l = o.len();
                break;
            }
        }
        i += l;
        out.push(Tk { k: K::Op, s, e: i });
    }
    out.push(Tk { k: K::Eof, s: n, e: n });
    out
}

struct P<'a> {
    src: &'a str,
    toks: Vec<Tk>,
    i: usize,
    b: Builder,
    depth: usize,
}

pub fn parse(src: &str) -> Tree {
    let toks = tokenize(src);
    let mut p = P { src, toks, i: 0, b: Builder::new(), depth: 0 };
    let m = p.b.mark();
    loop {
        if p.k() == K::Eof {
            break;
        }
        if p.k() == K::Tag {
            let t = p.advance();
            if &src[t.s..t.e] == "<?php" {
                p.b.leaf("php_tag", true, t.s, t.e);
            } else {
                p.b.leaf("?>", false, t.s, t.e);
            }
            continue;
        }
        let before = p.i;
        p.statement();
        if p.i == before {
            p.error_token();
        }
    }
    p.flush_extras();
    let start = p.b.stack[m..].first().map(|&c| p.b.nodes[c as usize].start).unwrap_or(src.len() - src.trim_start().len());
    let root = p.b.wrap_all(m, "program", start, src.len());
    p.b.finish(root, src)
}

impl<'a> P<'a> {
    fn idx(&self, n: usize) -> usize {
        let mut j = self.i;
        let mut c = 0;
        loop {
            while j < self.toks.len() && self.toks[j].k == K::Comment {
                j += 1;
            }
            if j >= self.toks.len() {
                return self.toks.len() - 1;
            }
            if c == n {
                return j;
            }
            c += 1;
            j += 1;
        }
    }
    fn tok(&self, n: usize) -> Tk {
        self.toks[self.idx(n)]
    }
    fn k(&self) -> K {
        self.tok(0).k
    }
    fn txn(&self, n: usize) -> &'a str {
        let t = self.tok(n);
        if t.k == K::Eof {
            return "";
        }
        &self.src[t.s..t.e]
    }
    fn tx(&self) -> &'a str {
        self.txn(0)
    }
    fn at(&self, s: &str) -> bool {
        let t = self.tok(0);
        matches!(t.k, K::Op | K::Ident) && self.src[t.s..t.e].eq_ignore_ascii_case(s)
    }
    fn flush_extras(&mut self) {
        while self.i < self.toks.len() && self.toks[self.i].k == K::Comment {
            let t = self.toks[self.i];
            self.b.extra("comment", t.s, t.e);
            self.i += 1;
        }
    }
    fn advance(&mut self) -> Tk {
        self.flush_extras();
        let t = self.toks[self.i];
        if t.k != K::Eof {
            self.i += 1;
        }
        t
    }
    fn bump(&mut self) -> u32 {
        let t = self.advance();
        let k = intern(&self.src[t.s..t.e].to_ascii_lowercase());
        self.b.leaf(k, false, t.s, t.e)
    }
    fn bump_named(&mut self, kind: &'static str) -> u32 {
        let t = self.advance();
        self.b.leaf(kind, true, t.s, t.e)
    }
    fn eat(&mut self, s: &str) -> bool {
        if self.at(s) {
            self.bump();
            true
        } else {
            false
        }
    }
    fn cur_pos(&self) -> usize {
        self.b.last().map(|l| self.b.nodes[l as usize].end).unwrap_or(0)
    }
    fn expect(&mut self, s: &str) {
        if !self.eat(s) {
            let p = self.cur_pos();
            self.b.missing(intern(s), false, p);
        }
    }
    fn error_token(&mut self) {
        if self.k() == K::Eof {
            return;
        }
        let m = self.b.mark();
        self.bump();
        self.b.wrap(m, "ERROR", true);
    }
    fn set_field_first(&mut self, m: usize, f: &'static str) {
        for i in m..self.b.stack.len() {
            let id = self.b.stack[i] as usize;
            if !self.b.nodes[id].extra {
                self.b.nodes[id].field = Some(f);
                return;
            }
        }
    }
    fn semicolon(&mut self) {
        if self.at(";") {
            self.bump();
        } else if self.k() == K::Tag {
        } else {
            let p = self.cur_pos();
            self.b.missing(";", false, p);
        }
    }

    fn variable(&mut self) {
        let t = self.advance();
        let m = self.b.mark();
        self.b.leaf("$", false, t.s, t.s + 1);
        self.b.leaf("name", true, t.s + 1, t.e);
        self.b.wrap(m, "variable_name", true);
    }

    fn name_or_qualified(&mut self) {
        let t = self.tok(0);
        let txt = &self.src[t.s..t.e];
        if txt.contains('\\') && txt.len() > 1 {
            let t = self.advance();
            let m = self.b.mark();
            let parts: Vec<(usize, usize)> = {
                let mut v = Vec::new();
                let mut st = t.s;
                for (o, ch) in txt.char_indices() {
                    if ch == '\\' {
                        if t.s + o > st {
                            v.push((st, t.s + o));
                        }
                        st = t.s + o + 1;
                    }
                }
                if st < t.e {
                    v.push((st, t.e));
                }
                v
            };
            if parts.len() > 1 {
                let mp = self.b.mark();
                if txt.starts_with('\\') {
                    self.b.leaf("\\", false, t.s, t.s + 1);
                }
                for (k, &(a, e)) in parts[..parts.len() - 1].iter().enumerate() {
                    if k > 0 {
                        self.b.leaf("\\", false, a - 1, a);
                    }
                    self.b.leaf("name", true, a, e);
                }
                let (la, le) = *parts.last().unwrap();
                self.b.leaf("\\", false, la - 1, la);
                self.b.wrap(mp, "namespace_name", true);
                self.b.field_last("prefix");
                // prefix includes trailing backslash in tree-sitter-php
                self.b.leaf("name", true, la, le);
                self.b.wrap(m, "qualified_name", true);
            } else {
                self.b.leaf("name", true, parts[0].0, parts[0].1);
            }
            return;
        }
        self.bump_named("name");
    }

    fn statement(&mut self) {
        let m = self.b.mark();
        let tx = self.tx().to_ascii_lowercase();
        if self.k() == K::Ident {
            match tx.as_str() {
                "echo" | "print" if tx == "echo" => {
                    self.bump();
                    loop {
                        self.expression();
                        if !self.eat(",") {
                            break;
                        }
                    }
                    self.semicolon();
                    self.b.wrap(m, "echo_statement", true);
                    return;
                }
                "return" => {
                    self.bump();
                    if !self.at(";") {
                        self.expression();
                    }
                    self.semicolon();
                    self.b.wrap(m, "return_statement", true);
                    return;
                }
                "if" => return self.if_stmt(m),
                "while" => {
                    self.bump();
                    self.paren_expr();
                    self.b.field_last("condition");
                    self.statement();
                    self.b.field_last("body");
                    self.b.wrap(m, "while_statement", true);
                    return;
                }
                "foreach" => {
                    self.bump();
                    self.expect("(");
                    self.expression();
                    self.expect("as");
                    let mp = self.b.mark();
                    self.expression();
                    if self.at("=>") {
                        self.bump();
                        self.expression();
                        self.b.wrap(mp, "pair", true);
                    }
                    self.expect(")");
                    self.statement();
                    self.b.field_last("body");
                    self.b.wrap(m, "foreach_statement", true);
                    return;
                }
                "for" => {
                    self.bump();
                    self.expect("(");
                    for f in ["initialize", "condition"] {
                        if !self.at(";") {
                            self.expression();
                            self.b.field_last(f);
                        }
                        self.expect(";");
                    }
                    if !self.at(")") {
                        self.expression();
                        self.b.field_last("update");
                    }
                    self.expect(")");
                    self.statement();
                    self.b.field_last("body");
                    self.b.wrap(m, "for_statement", true);
                    return;
                }
                "function" if self.tok(1).k == K::Ident => {
                    self.bump();
                    self.bump_named("name");
                    self.b.field_last("name");
                    self.func_rest();
                    self.b.wrap(m, "function_definition", true);
                    return;
                }
                "abstract" | "final" | "class" | "interface" | "trait" | "readonly" if tx != "readonly" || self.txn(1).eq_ignore_ascii_case("class") => {
                    if self.class_like(m) {
                        return;
                    }
                }
                "namespace" => {
                    self.bump();
                    let mn = self.b.mark();
                    let t = self.advance();
                    let txt = &self.src[t.s..t.e];
                    let mut st = t.s;
                    for (o, ch) in txt.char_indices() {
                        if ch == '\\' {
                            self.b.leaf("name", true, st, t.s + o);
                            self.b.leaf("\\", false, t.s + o, t.s + o + 1);
                            st = t.s + o + 1;
                        }
                    }
                    self.b.leaf("name", true, st, t.e);
                    self.b.wrap(mn, "namespace_name", true);
                    self.b.field_last("name");
                    if self.at("{") {
                        self.compound();
                        self.b.field_last("body");
                    } else {
                        self.semicolon();
                    }
                    self.b.wrap(m, "namespace_definition", true);
                    return;
                }
                "use" => {
                    self.bump();
                    loop {
                        let mc = self.b.mark();
                        self.name_or_qualified();
                        if self.eat("as") {
                            self.bump_named("name");
                        }
                        self.b.wrap(mc, "namespace_use_clause", true);
                        if !self.eat(",") {
                            break;
                        }
                    }
                    self.semicolon();
                    self.b.wrap(m, "namespace_use_declaration", true);
                    return;
                }
                "try" => {
                    self.bump();
                    self.compound();
                    self.b.field_last("body");
                    while self.at("catch") {
                        let mc = self.b.mark();
                        self.bump();
                        self.expect("(");
                        let mt = self.b.mark();
                        self.name_or_qualified();
                        while self.eat("|") {
                            self.name_or_qualified();
                        }
                        self.b.wrap(mt, "type_list", true);
                        self.b.field_last("type");
                        if self.k() == K::Var {
                            self.variable();
                            self.b.field_last("name");
                        }
                        self.expect(")");
                        self.compound();
                        self.b.field_last("body");
                        self.b.wrap(mc, "catch_clause", true);
                    }
                    if self.at("finally") {
                        let mf = self.b.mark();
                        self.bump();
                        self.compound();
                        self.b.field_last("body");
                        self.b.wrap(mf, "finally_clause", true);
                    }
                    self.b.wrap(m, "try_statement", true);
                    return;
                }
                "break" | "continue" => {
                    self.bump();
                    if self.k() == K::Num {
                        self.bump_named("integer");
                    }
                    self.semicolon();
                    self.b.wrap(m, if tx == "break" { "break_statement" } else { "continue_statement" }, true);
                    return;
                }
                _ => {}
            }
        }
        if self.at("{") {
            self.compound();
            return;
        }
        if self.at(";") {
            self.bump();
            self.b.wrap(m, "empty_statement", true);
            return;
        }
        self.expression();
        self.semicolon();
        self.b.wrap(m, "expression_statement", true);
    }

    fn compound(&mut self) {
        let m = self.b.mark();
        self.expect("{");
        while !self.at("}") && self.k() != K::Eof {
            let before = self.i;
            self.statement();
            if self.i == before {
                self.error_token();
            }
        }
        self.expect("}");
        self.b.wrap(m, "compound_statement", true);
    }

    fn paren_expr(&mut self) {
        let m = self.b.mark();
        self.expect("(");
        self.expression();
        self.expect(")");
        self.b.wrap(m, "parenthesized_expression", true);
    }

    fn if_stmt(&mut self, m: usize) {
        self.bump();
        self.paren_expr();
        self.b.field_last("condition");
        self.statement();
        self.b.field_last("body");
        loop {
            if self.at("elseif") || (self.at("else") && self.txn(1).eq_ignore_ascii_case("if")) {
                let me = self.b.mark();
                if self.at("else") {
                    self.bump();
                    self.bump();
                } else {
                    self.bump();
                }
                self.paren_expr();
                self.b.field_last("condition");
                self.statement();
                self.b.field_last("body");
                self.b.wrap(me, "else_if_clause", true);
                self.b.field_last("alternative");
                continue;
            }
            if self.at("else") {
                let me = self.b.mark();
                self.bump();
                self.statement();
                self.b.field_last("body");
                self.b.wrap(me, "else_clause", true);
                self.b.field_last("alternative");
            }
            break;
        }
        self.b.wrap(m, "if_statement", true);
    }

    fn func_rest(&mut self) {
        self.formal_parameters();
        self.b.field_last("parameters");
        if self.at(":") {
            self.bump();
            self.php_type();
            self.b.field_last("return_type");
        }
        if self.at("{") {
            self.compound();
            self.b.field_last("body");
        } else {
            self.semicolon();
        }
    }

    fn php_type(&mut self) {
        let m = self.b.mark();
        if self.at("?") {
            self.bump();
            self.php_type();
            self.b.wrap(m, "optional_type", true);
            return;
        }
        let tx = self.tx().to_ascii_lowercase();
        if matches!(tx.as_str(), "int" | "float" | "bool" | "string" | "array" | "void" | "mixed" | "callable" | "iterable" | "object" | "null" | "false" | "true" | "never" | "self" | "static") {
            self.bump();
            self.b.wrap(m, "primitive_type", true);
        } else {
            self.name_or_qualified();
            self.b.wrap(m, "named_type", true);
        }
        if self.at("|") {
            while self.eat("|") {
                self.php_type();
            }
            self.b.wrap(m, "union_type", true);
        }
    }

    fn formal_parameters(&mut self) {
        let m = self.b.mark();
        self.expect("(");
        while !self.at(")") && self.k() != K::Eof {
            let mp = self.b.mark();
            let mut promo = false;
            if matches!(self.tx().to_ascii_lowercase().as_str(), "public" | "private" | "protected") {
                let mv = self.b.mark();
                self.bump();
                self.b.wrap(mv, "visibility_modifier", true);
                self.b.field_last("visibility");
                promo = true;
            }
            if self.at("readonly") {
                let mr = self.b.mark();
                self.bump();
                self.b.wrap(mr, "readonly_modifier", true);
                promo = true;
            }
            if self.k() != K::Var && !self.at("...") && !self.at("&") {
                self.php_type();
                self.b.field_last("type");
            }
            let variadic = self.eat("...");
            self.eat("&");
            if self.k() == K::Var {
                self.variable();
                self.b.field_last("name");
            }
            if self.eat("=") {
                self.expression();
                self.b.field_last("default_value");
            }
            let k = if promo { "property_promotion_parameter" } else if variadic { "variadic_parameter" } else { "simple_parameter" };
            self.b.wrap(mp, k, true);
            if !self.eat(",") {
                break;
            }
        }
        self.expect(")");
        self.b.wrap(m, "formal_parameters", true);
    }

    fn class_like(&mut self, m: usize) -> bool {
        while matches!(self.tx().to_ascii_lowercase().as_str(), "abstract" | "final" | "readonly") {
            let mm = self.b.mark();
            let t = self.tx().to_ascii_lowercase();
            self.bump();
            self.b.wrap(mm, if t == "abstract" { "abstract_modifier" } else if t == "final" { "final_modifier" } else { "readonly_modifier" }, true);
        }
        let kw = self.tx().to_ascii_lowercase();
        let kind = match kw.as_str() {
            "class" => "class_declaration",
            "interface" => "interface_declaration",
            "trait" => "trait_declaration",
            _ => return false,
        };
        self.bump();
        self.bump_named("name");
        self.b.field_last("name");
        if self.at("extends") {
            let mb = self.b.mark();
            self.bump();
            loop {
                self.name_or_qualified();
                if !self.eat(",") {
                    break;
                }
            }
            self.b.wrap(mb, "base_clause", true);
        }
        if self.at("implements") {
            let mb = self.b.mark();
            self.bump();
            loop {
                self.name_or_qualified();
                if !self.eat(",") {
                    break;
                }
            }
            self.b.wrap(mb, "class_interface_clause", true);
        }
        let md = self.b.mark();
        self.expect("{");
        while !self.at("}") && self.k() != K::Eof {
            let before = self.i;
            self.member();
            if self.i == before {
                self.error_token();
            }
        }
        self.expect("}");
        self.b.wrap(md, "declaration_list", true);
        self.b.field_last("body");
        self.b.wrap(m, kind, true);
        true
    }

    fn member(&mut self) {
        let m = self.b.mark();
        loop {
            let t = self.tx().to_ascii_lowercase();
            match t.as_str() {
                "public" | "private" | "protected" => {
                    let mv = self.b.mark();
                    self.bump();
                    self.b.wrap(mv, "visibility_modifier", true);
                }
                "static" => {
                    let mv = self.b.mark();
                    self.bump();
                    self.b.wrap(mv, "static_modifier", true);
                }
                "abstract" => {
                    let mv = self.b.mark();
                    self.bump();
                    self.b.wrap(mv, "abstract_modifier", true);
                }
                "final" => {
                    let mv = self.b.mark();
                    self.bump();
                    self.b.wrap(mv, "final_modifier", true);
                }
                "readonly" => {
                    let mv = self.b.mark();
                    self.bump();
                    self.b.wrap(mv, "readonly_modifier", true);
                }
                "var" => {
                    self.bump();
                }
                _ => break,
            }
        }
        let t = self.tx().to_ascii_lowercase();
        if t == "function" {
            self.bump();
            self.bump_named("name");
            self.b.field_last("name");
            self.func_rest();
            self.b.wrap(m, "method_declaration", true);
            return;
        }
        if t == "const" {
            self.bump();
            loop {
                let mc = self.b.mark();
                self.bump_named("name");
                self.expect("=");
                self.expression();
                self.b.wrap(mc, "const_element", true);
                if !self.eat(",") {
                    break;
                }
            }
            self.semicolon();
            self.b.wrap(m, "const_declaration", true);
            return;
        }
        if t == "use" {
            self.bump();
            loop {
                self.name_or_qualified();
                if !self.eat(",") {
                    break;
                }
            }
            self.semicolon();
            self.b.wrap(m, "use_declaration", true);
            return;
        }
        if self.k() != K::Var {
            self.php_type();
            self.b.field_last("type");
        }
        loop {
            let me = self.b.mark();
            if self.k() == K::Var {
                self.variable();
                self.b.field_last("name");
            }
            if self.eat("=") {
                self.expression();
                self.b.field_last("default_value");
            }
