    fn binop(&self) -> Option<u8> {
        let t = self.tok(0);
        let tx = self.tx();
        if t.k == K::Ident {
            return match tx.to_ascii_lowercase().as_str() {
                "or" => Some(1),
                "xor" => Some(2),
                "and" => Some(3),
                "instanceof" => Some(16),
                _ => None,
            };
