                        self.bump();
                        let mc = self.b.mark();
                        self.bump();
                        self.b.wrap(mc, "cast_type", true);
                        self.b.field_last("type");
                        self.bump();
                        self.unary();
                        self.b.field_last("value");
                        self.b.wrap(m, "cast_expression", true);
                        return;
                    }
                }
                _ => {}
            }
        }
        self.postfix();
    }

    fn arguments(&mut self) {
        let m = self.b.mark();
        self.bump(); // (
        while !self.at(")") && self.k() != K::Eof {
            let ma = self.b.mark();
            if self.at("...") {
                self.bump();
                if self.at(")") {
                    self.b.wrap(ma, "variadic_placeholder", true);
                    break;
                }
                self.expression();
                self.b.wrap(ma, "variadic_unpacking", true);
            } else {
                if self.k() == K::Ident && self.txn(1) == ":" && self.txn(2) != ":" {
