                    self.b.field_last("name");
                    self.bump();
                }
                self.expression();
                self.b.wrap(ma, "argument", true);
            }
            if !self.eat(",") {
                break;
            }
        }
        self.expect(")");
        self.b.wrap(m, "arguments", true);
    }

    fn postfix(&mut self) {
        let m = self.b.mark();
        self.primary();
        loop {
            let tx = self.tx();
            match tx {
                "->" | "?->" => {
                    self.set_field_first(m, "object");
                    self.bump();
                    if self.k() == K::Var {
                        self.variable();
                    } else {
                        self.bump_named("name");
                    }
                    self.b.field_last("name");
                    if self.at("(") {
                        self.arguments();
                        self.b.field_last("arguments");
                        self.b.wrap(m, if tx == "->" { "member_call_expression" } else { "nullsafe_member_call_expression" }, true);
                    } else {
                        self.b.wrap(m, if tx == "->" { "member_access_expression" } else { "nullsafe_member_access_expression" }, true);
                    }
                }
                "::" => {
                    self.set_field_first(m, "scope");
                    self.bump();
                    if self.k() == K::Var {
                        self.variable();
                        self.b.field_last("name");
                        self.b.wrap(m, "scoped_property_access_expression", true);
                        continue;
                    }
                    self.bump_named("name");
                    if self.at("(") {
                        self.b.field_last("name");
                        self.arguments();
                        self.b.field_last("arguments");
                        self.b.wrap(m, "scoped_call_expression", true);
                    } else {
                        // class constant: no fields
                        let id = self.b.stack[m] as usize;
                        self.b.nodes[id].field = None;
                        self.b.wrap(m, "class_constant_access_expression", true);
                    }
                }
                "[" => {
                    self.bump();
                    if !self.at("]") {
                        self.expression();
                    }
                    self.expect("]");
                    self.b.wrap(m, "subscript_expression", true);
                }
                "(" => {
                    self.set_field_first(m, "function");
                    self.arguments();
                    self.b.field_last("arguments");
                    self.b.wrap(m, "function_call_expression", true);
                }
                "++" | "--" => {
                    self.b.field_last("argument");
                    self.bump();
                    self.b.field_last("operator");
                    self.b.wrap(m, "update_expression", true);
                }
                _ => break,
            }
        }
    }

    fn string(&mut self) {
        let t = self.advance();
        let m = self.b.mark();
        let b = self.src.as_bytes();
        let dq = b[t.s] == b'"';
        let q = if dq { "\"" } else { "'" };
        self.b.leaf(q, false, t.s, t.s + 1);
        let close = t.e > t.s + 1 && b[t.e - 1] == b[t.s];
        let ce = if close { t.e - 1 } else { t.e };
