                }
                "fn" if self.txn(1) == "(" => {
                    self.bump();
                    self.formal_parameters();
                    self.b.field_last("parameters");
                    if self.at(":") {
                        self.bump();
                        self.php_type();
                        self.b.field_last("return_type");
                    }
                    self.expect("=>");
                    self.expression();
                    self.b.field_last("body");
                    self.b.wrap(m, "arrow_function", true);
                }
                "function" => {
                    self.bump();
                    self.formal_parameters();
                    self.b.field_last("parameters");
                    if self.at("use") {
                        let mu = self.b.mark();
                        self.bump();
                        self.expect("(");
