                            self.variable();
                            if !self.eat(",") {
                                break;
                            }
                        }
                        self.expect(")");
                        self.b.wrap(mu, "anonymous_function_use_clause", true);
                    }
                    if self.at(":") {
                        self.bump();
                        self.php_type();
                        self.b.field_last("return_type");
                    }
                    self.compound();
                    self.b.field_last("body");
                    self.b.wrap(m, "anonymous_function", true);
                }
                "array" if self.txn(1) == "(" => {
                    self.bump();
                    self.bump();
                    self.array_elems(")");
                    self.b.wrap(m, "array_creation_expression", true);
                }
                "throw" => {
                    self.bump();
                    self.expression();
                    self.b.wrap(m, "throw_expression", true);
                }
                "print" => {
                    self.bump();
                    self.expression();
                    self.b.wrap(m, "print_intrinsic", true);
                }
                "match" if self.txn(1) == "(" => {
                    self.bump();
                    self.paren_expr();
                    self.b.field_last("condition");
                    let mb = self.b.mark();
                    self.expect("{");
                    while !self.at("}") && self.k() != K::Eof {
                        let ma = self.b.mark();
                        if self.at("default") {
                            self.bump();
                            self.expect("=>");
                            self.expression();
